@import "tailwindcss";

/* Shared site-wide loading visual: every visual loader resolves to DotsRing. */
.dots-ring {
  --dots-ring-size: 2rem;
  position: relative;
  display: inline-block;
  width: var(--dots-ring-size);
  height: var(--dots-ring-size);
  flex: 0 0 var(--dots-ring-size);
  color: var(--theme-effect-moving-light);
  vertical-align: middle;
}

.dots-ring--inline { --dots-ring-size: 1rem; }
.dots-ring--sm { --dots-ring-size: 1.35rem; }
.dots-ring--md { --dots-ring-size: 2rem; }
.dots-ring--lg { --dots-ring-size: 2.65rem; }
.dots-ring--xl { --dots-ring-size: 3.5rem; }
.dots-ring--custom { --dots-ring-size: 2rem; }

.dots-ring__orbit {
  position: absolute;
  inset: 11%;
  display: block;
  border: max(1px, calc(var(--dots-ring-size) * .07)) solid color-mix(in srgb, var(--theme-effect-moving-light) 24%, transparent);
  border-radius: 50%;
}

.dots-ring__dot {
  position: absolute;
  display: block;
  width: max(3px, calc(var(--dots-ring-size) * .19));
  height: max(3px, calc(var(--dots-ring-size) * .19));
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 calc(var(--dots-ring-size) * .32) color-mix(in srgb, var(--theme-effect-icon-glow) 70%, transparent);
}

.dots-ring__dot--one { top: calc(var(--dots-ring-size) * -.095); left: 50%; transform: translateX(-50%); }
.dots-ring__dot--two { right: calc(var(--dots-ring-size) * .02); bottom: calc(var(--dots-ring-size) * .08); }
.dots-ring__dot--three { bottom: calc(var(--dots-ring-size) * .08); left: calc(var(--dots-ring-size) * .02); }

@media (prefers-reduced-motion: reduce) {
  .dots-ring__orbit { border-color: color-mix(in srgb, var(--theme-effect-moving-light) 52%, transparent); }
}

.dots-ring-loading {
  display: flex;
  min-width: 0;
  min-height: 8rem;
  align-items: center;
  justify-content: center;
  gap: .7rem;
  padding: 1.25rem;
  color: var(--theme-text-color);
  text-align: center;
}

.dots-ring-loading > span:last-child {
  color: var(--theme-mid-tone);
}

.dots-ring-loading.admin-state-card,
.dots-ring-loading.catalog-loading-grid,
.dots-ring-loading.latest-loading-grid,
.dots-ring-loading.store-cosmetics-grid,
.dots-ring-loading.continue-reading-loading,
.dots-ring-loading.hot-week-list,
.dots-ring-loading.comment-loading,
.dots-ring-loading.community-highlight-loading,
.dots-ring-loading.public-discovery-loading,
.dots-ring-loading.settings-loading,
.dots-ring-loading.store-admin-loading,
.dots-ring-loading.commerce-loading {
  display: flex;
  min-height: 10rem;
  align-content: center;
  align-items: center;
  justify-content: center;
  gap: .7rem;
  background: var(--theme-accent);
  background-image: none;
  animation: none;
}

.dots-ring-loading.admin-state-card,
.dots-ring-loading.catalog-loading-grid,
.dots-ring-loading.latest-loading-grid,
.dots-ring-loading.store-cosmetics-grid,
.dots-ring-loading.hot-week-list,
.dots-ring-loading.comment-loading,
.dots-ring-loading.community-highlight-loading {
  grid-template-columns: none;
}

.card-coverflow-desktop { display: none; }

@media (min-width: 1024px) {
  .card-coverflow-desktop { display: block; }
  .v481-pinned-touch-only { display: none !important; }
  .card-coverflow {
    position: relative;
    isolation: isolate;
    width: 100%;
    min-width: 0;
  }
  .card-coverflow__viewport {
    position: relative;
    display: grid;
    min-height: clamp(22rem, 35vw, 31rem);
    place-items: center;
    overflow: hidden;
    padding: 1.2rem clamp(3.8rem, 9vw, 8rem) .5rem;
  }
  .card-coverflow__track {
    position: relative;
    display: grid;
    width: 100%;
    min-height: clamp(20rem, 32vw, 28rem);
    place-items: center;
    outline: none;
  }
  .card-coverflow__slide {
    position: absolute;
    inset: 0;
    display: grid;
    place-items: center;
    pointer-events: auto;
    will-change: transform, opacity;
  }
  .card-coverflow__slide > .v481-pin-card {
    width: min(74%, 54rem);
    min-height: 0;
    aspect-ratio: 2 / 1;
    border-color: color-mix(in srgb, var(--theme-effect-cover-glow) 54%, var(--theme-accent-l3));
    box-shadow: none;
  }
  .card-coverflow__slide[data-coverflow-active="true"] > .v481-pin-card {
    border-color: var(--theme-effect-cover-glow);
    box-shadow: none;
  }
  .card-coverflow__arrow {
    position: absolute;
    z-index: 8;
    display: grid;
    width: 2.8rem;
    height: 2.8rem;
    place-items: center;
    border: 1px solid color-mix(in srgb, var(--theme-effect-button-glow) 62%, var(--theme-accent-l3));
    border-radius: 50%;
    color: var(--theme-effect-button-glow);
    background: color-mix(in srgb, var(--theme-accent) 88%, transparent);
    box-shadow: 0 .7rem 1.8rem color-mix(in srgb, var(--theme-main-background) 42%, transparent), 0 0 .8rem color-mix(in srgb, var(--theme-effect-button-glow) 20%, transparent);
    font-size: 2rem;
    line-height: 1;
    cursor: pointer;
    transition: transform .18s ease, opacity .18s ease, background .18s ease;
  }
  .card-coverflow__arrow:hover:not(:disabled),
  .card-coverflow__arrow:focus-visible {
    background: color-mix(in srgb, var(--theme-effect-button-glow) 15%, var(--theme-accent));
    transform: scale(1.06);
  }
  .card-coverflow__arrow:disabled { cursor: default; opacity: .42; }
  .card-coverflow__arrow--previous { left: 1rem; }
  .card-coverflow__arrow--next { right: 1rem; }
  .card-coverflow__progress {
    display: flex;
    justify-content: center;
    gap: .35rem;
    margin-top: .45rem;
  }
  .card-coverflow__progress button {
    width: 1.35rem;
    height: .28rem;
    padding: 0;
    border: 0;
    border-radius: 999px;
    background: var(--theme-progress-track);
    transition: width .18s ease, background .18s ease, box-shadow .18s ease;
  }
  .card-coverflow__progress button.is-active {
    width: 2.1rem;
    background: var(--theme-progress-fill);
    box-shadow: 0 0 .7rem color-mix(in srgb, var(--theme-progress-fill) 45%, transparent);
  }
}

@media (prefers-reduced-motion: reduce) {
  .card-coverflow__arrow,
  .card-coverflow__progress button { transition: none; }
}

:root {
