  --theme-text-color: var(--site-dark-text, #f7f8fb);
  --theme-main-background: var(--site-dark-bg, #070708);
  --theme-accent: var(--site-dark-surface, #111216);
  --theme-accent-hover: var(--site-dark-surface-2, #17191f);
  --theme-accent-active: var(--site-dark-surface-3, #1f222a);
  --theme-accent-l1: var(--site-dark-surface-2, #17191f);
  --theme-accent-l1-hover: var(--site-dark-surface-3, #1f222a);
  --theme-accent-l1-active: var(--site-dark-line, #2b2f39);
  --theme-accent-l2: var(--site-dark-surface-3, #1f222a);
  --theme-accent-l2-hover: var(--site-dark-line, #2b2f39);
  --theme-accent-l2-active: #343944;
  --theme-accent-l3: var(--site-dark-line, #2b2f39);
  --theme-accent-l3-hover: #343944;
  --theme-accent-l3-active: var(--site-dark-line-strong, #454b59);
  --theme-accent-l4: #343944;
  --theme-accent-l4-hover: var(--site-dark-line-strong, #454b59);
  --theme-accent-l4-active: #646d7e;
  --theme-accent-l5: var(--site-dark-line-strong, #454b59);
  --theme-accent-l5-hover: #646d7e;
  --theme-accent-l5-active: var(--site-dark-muted, #9198a6);
  --theme-mid-tone: var(--site-dark-muted, #9198a6);
  --theme-contrast-l1: #ffffff;
  --theme-scrollbar-color: var(--site-dark-line-strong, #454b59);
  --theme-scrollbar-color-hover: #646d7e;
  --theme-button-accent: var(--site-accent, #39a9ff);
  --theme-button-accent-alternate: var(--site-accent-ink, #03111f);
  --theme-primary: var(--site-accent, #39a9ff);
  --theme-primary-l1: var(--site-accent-strong, #168de2);
  --theme-primary-l2: #0876c5;
  --theme-status-red: var(--site-danger, #ef8175);
  --theme-status-green: var(--site-success, #39c98a);
  --theme-status-yellow: var(--site-warning, #e6bd61);
  --theme-status-blue: #5ab7ff;
  --theme-status-purple: #b39af4;
  --theme-status-grey: var(--site-dark-muted, #9198a6);
  --theme-indication-blue: var(--site-premium, #8ecbff);
  --theme-danger: var(--site-danger, #ef8175);
  --theme-danger-l1: #d95f55;
  --theme-danger-l2: #b94236;
  --theme-logo-color: var(--theme-text-color);
  --theme-logo-accent-color: var(--theme-primary);
  --theme-logo-outline-color: var(--theme-contrast-l1);
  --bg: var(--theme-main-background);
  --bg-soft: var(--theme-accent);
  --surface: var(--theme-accent);
  --surface-2: var(--theme-accent-l1);
  --surface-3: var(--theme-accent-l2);
  --surface-raised: var(--surface-2);
  --surface-strong: var(--surface-3);
  --text: var(--theme-text-color);
  --text-soft: color-mix(in srgb, var(--theme-text-color) 82%, var(--theme-main-background));
  --muted: var(--theme-mid-tone);
  --line: var(--theme-accent-l3);
  --line-strong: var(--theme-accent-l4);
  --accent: var(--theme-primary);
  --accent-strong: var(--theme-primary-l1);
  --accent-ink: var(--theme-button-accent-alternate);
  --accent-contrast: var(--accent-ink);
  --danger: var(--theme-danger);
  --warning: var(--theme-status-yellow);
  --success: var(--theme-status-green);
  --premium: var(--theme-status-purple);
  --indication: var(--theme-indication-blue);
  --brand-gradient: linear-gradient(135deg, var(--theme-primary-l2), var(--theme-primary));
  --shadow: rgba(1, 10, 24, 0.5);
  --header: color-mix(in srgb, var(--bg) 88%, transparent);
  --radius: var(--site-radius, 14px);
  --radius-small: 9px;
  --z-dropdown: 850;
  --z-modal: 800;
  --z-toast: 900;
  --cover-ratio: 2 / 3;
  --page: min(1440px, calc(100vw - 64px));
  --theme-focus-ring: color-mix(in srgb, var(--theme-primary) 48%, transparent);
  --theme-placeholder: color-mix(in srgb, var(--theme-mid-tone) 78%, var(--theme-main-background));
  --theme-disabled-text: color-mix(in srgb, var(--theme-text-color) 48%, var(--theme-main-background));
  --theme-disabled-surface: color-mix(in srgb, var(--theme-accent-l1) 76%, var(--theme-main-background));
  --theme-overlay: color-mix(in srgb, var(--theme-main-background) 78%, transparent);
  --theme-tooltip-background: var(--theme-accent-l4);
  --theme-tooltip-text: var(--theme-text-color);
  --theme-skeleton-base: var(--theme-accent-l1);
  --theme-skeleton-highlight: var(--theme-accent-l2-hover);
}

/* Version 48.2.0 — event campaign, reader seek, and discussion composer */
.event-campaign-backdrop {
  position: fixed;
  inset: 0;
  z-index: 2147483000;
  display: grid;
  place-items: center;
  padding: clamp(1rem, 4vw, 3rem);
  background: rgb(1 6 12 / 78%);
  backdrop-filter: blur(14px) saturate(.8);
  animation: v482-backdrop-in .24s ease both;
}

.event-campaign-modal {
  position: relative;
  isolation: isolate;
  width: min(960px, 94vw);
  min-height: min(580px, 82dvh);
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--accent, #45b8ff) 48%, transparent);
  border-radius: 24px;
  background: var(--surface-strong);
  box-shadow: 0 40px 120px rgb(0 0 0 / 70%);
  animation: v482-modal-in .34s cubic-bezier(.22, 1, .36, 1) both;
}

.event-campaign-art,
.event-campaign-shade {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.event-campaign-art {
  z-index: -3;
  object-fit: cover;
  object-position: 72% center;
}

.event-campaign-placeholder {
  display: grid;
  place-items: center;
  color: var(--accent, #45b8ff);
  background: radial-gradient(circle at 75% 40%, #173e62, #06111e 56%);
}

.event-campaign-shade {
  z-index: -2;
  background: linear-gradient(90deg, #040b14 4%, rgb(4 11 20 / 97%) 38%, rgb(4 11 20 / 54%) 68%, rgb(4 11 20 / 8%));
}

.event-campaign-close {
  position: absolute;
  z-index: 2;
  top: 1rem;
  right: 1rem;
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border: 1px solid rgb(255 255 255 / 32%);
  border-radius: 12px;
  color: #fff;
  background: rgb(3 10 18 / 68%);
  backdrop-filter: blur(10px);
}

.event-campaign-content {
  display: flex;
  min-height: inherit;
  width: min(58%, 560px);
  flex-direction: column;
  justify-content: center;
  align-items: flex-start;
  gap: 1rem;
  padding: clamp(2rem, 5vw, 4.5rem);
  color: #eef7ff;
}

.event-campaign-content > small {
  padding: .45rem .75rem;
  border: 1px solid rgb(104 192 255 / 46%);
  border-radius: 999px;
  color: #a9dcff;
  background: rgb(6 30 50 / 70%);
  font-size: .72rem;
  font-weight: 760;
  letter-spacing: .16em;
  text-transform: uppercase;
}

.event-campaign-content h2 {
  max-width: 12ch;
  margin: 0;
  font-size: clamp(2rem, 4.2vw, 4rem);
  line-height: .98;
  letter-spacing: -.055em;
}

.event-campaign-content > p {
  max-width: 58ch;
  margin: 0;
  color: rgb(224 238 249 / 78%);
  line-height: 1.6;
}

.event-campaign-info {
  display: grid;
  width: 100%;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: .7rem;
}

.event-campaign-info article {
  display: grid;
  min-width: 0;
  grid-template-columns: 38px minmax(0, 1fr);
  gap: .7rem;
  align-items: center;
  padding: .7rem;
  border: 1px solid rgb(137 207 255 / 18%);
  border-radius: 13px;
  background: rgb(5 22 36 / 68%);
  backdrop-filter: blur(8px);
}

.event-campaign-info article > span {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  border-radius: 10px;
  background: rgb(83 174 255 / 16%);
  font-size: 1.25rem;
}

.event-campaign-info article div,
.event-campaign-info article small {
  display: block;
  min-width: 0;
}

.event-campaign-info article small {
  margin-top: .16rem;
  overflow: hidden;
  color: rgb(224 238 249 / 62%);
  font-size: .72rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.event-campaign-action {
  display: inline-flex;
  min-height: 48px;
  align-items: center;
  justify-content: center;
  gap: .5rem;
  padding: .78rem 1.35rem;
  border-radius: 999px;
  color: #03111d;
  background: var(--accent, #62c4ff);
  box-shadow: 0 12px 34px color-mix(in srgb, var(--accent, #62c4ff) 30%, transparent);
  font-weight: 800;
}

.event-campaign-dismiss {
  display: inline-flex;
  align-items: center;
  gap: .55rem;
  color: rgb(224 238 249 / 67%);
  font-size: .8rem;
}

.event-campaign-dismiss input {
  width: 17px;
  height: 17px;
  accent-color: var(--accent, #62c4ff);
}

.reader-footer {
  grid-template-columns: minmax(0, 1fr) !important;
}

.reader-progress-shell {
  width: 100%;
  max-width: none !important;
}

.reader-progress {
  position: relative;
  min-height: 32px;
  cursor: pointer;
  touch-action: none;
  outline: none;
}

.reader-progress::before {
  content: "";
  position: absolute;
  inset: 14px 0;
  border-radius: 999px;
  background: rgb(255 255 255 / 16%);
}

.reader-progress:focus-visible {
  border-radius: 999px;
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent, #55bfff) 42%, transparent);
}

.reader-progress > i {
  position: absolute;
  z-index: 1;
  top: 14px;
  left: 0;
  height: 4px;
  border-radius: 999px;
}

.chapter-reaction-placement {
  margin-bottom: clamp(1.6rem, 4vw, 3rem);
}

.chapter-reactions-box {
  display: grid;
  gap: 1.5rem;
  padding: clamp(1.25rem, 3vw, 2.25rem);
  border: 1px solid var(--line, rgb(255 255 255 / 12%));
  border-radius: 22px;
  background: color-mix(in srgb, var(--surface, #101722) 92%, transparent);
  text-align: center;
}

.chapter-reactions-box > div:last-child {
  display: grid;
  grid-template-columns: repeat(6, minmax(74px, 1fr));
  gap: .6rem;
}

.chapter-reactions-box button {
  display: flex;
  min-width: 0;
  min-height: 112px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: .25rem;
  border: 1px solid transparent;
  border-radius: 16px;
  color: inherit;
  background: transparent;
}

.chapter-reactions-box button:hover,
.chapter-reactions-box button[aria-pressed="true"] {
  border-color: color-mix(in srgb, var(--accent, #55bfff) 50%, transparent);
  background: color-mix(in srgb, var(--accent, #55bfff) 11%, transparent);
}

.chapter-reactions-box button > span {
  font-size: clamp(1.9rem, 4vw, 2.55rem);
  line-height: 1;
}

.chapter-reactions-box button small {
  color: var(--text, #fff);
  font-size: .92rem;
  font-weight: 750;
}

.chapter-reactions-box button strong {
  overflow: hidden;
  color: var(--muted, #91a0b0);
  font-size: .74rem;
  font-weight: 560;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.comment-format-toolbar {
  display: flex;
  gap: .35rem;
  padding: .45rem .55rem;
  border: 1px solid var(--line, rgb(255 255 255 / 12%));
  border-top: 0;
  border-radius: 0 0 12px 12px;
}

.comment-field textarea {
  border-radius: 12px 12px 0 0 !important;
}

.comment-format-toolbar button {
  display: inline-grid;
  min-width: 38px;
  min-height: 36px;
  place-items: center;
  padding: .35rem .6rem;
  border: 0;
  border-radius: 8px;
  color: var(--text-soft, #dce7ef);
  background: transparent;
}

.comment-format-toolbar button:hover,
.comment-format-toolbar button:focus-visible {
  background: color-mix(in srgb, var(--accent, #55bfff) 13%, transparent);
}

.comment-formatted-text > p {
  margin: 0 0 .35rem;
  white-space: pre-wrap;
}

.comment-formatted-text > ul {
  margin: .35rem 0 .5rem 1.25rem;
}

.ad-admin-info-editor {
  display: grid;
  gap: .7rem;
}

.ad-admin-info-row {
  display: grid;
  grid-template-columns: 70px minmax(120px, .8fr) minmax(160px, 1.4fr) 40px;
  gap: .5rem;
}

.ad-admin-block-preview {
  display: flex;
  flex-wrap: wrap;
  gap: .45rem;
}

.ad-admin-block-preview span {
  display: inline-flex;
  gap: .3rem;
  align-items: center;
}

@keyframes v482-backdrop-in {
  from { opacity: 0; }
}

@keyframes v482-modal-in {
  from { opacity: 0; transform: translateY(18px) scale(.97); }
}

@media (max-width: 760px) {
  .event-campaign-backdrop { align-items: end; padding: .7rem; }
  .event-campaign-modal { width: 100%; min-height: min(690px, 92dvh); border-radius: 22px; }
  .event-campaign-art { object-position: 70% top; height: 47%; }
  .event-campaign-shade { background: linear-gradient(0deg, #040b14 3%, rgb(4 11 20 / 98%) 58%, rgb(4 11 20 / 8%) 100%); }
  .event-campaign-content { width: 100%; min-height: inherit; justify-content: flex-end; padding: 7rem 1.25rem 1.25rem; }
  .event-campaign-content h2 { font-size: clamp(2rem, 10vw, 3rem); }
  .event-campaign-info { grid-template-columns: 1fr 1fr; }
  .event-campaign-info article { grid-template-columns: 34px minmax(0, 1fr); padding: .55rem; }
  .event-campaign-info article > span { width: 34px; height: 34px; }
  .chapter-reactions-box > div:last-child { grid-template-columns: repeat(3, minmax(74px, 1fr)); }
  .ad-admin-info-row { grid-template-columns: 58px minmax(0, 1fr) 40px; }
  .ad-admin-info-row input:nth-of-type(3) { grid-column: 1 / -1; grid-row: 2; }
}

@media (prefers-reduced-motion: reduce) {
  .event-campaign-backdrop,
  .event-campaign-modal { animation: none; }
}

/* Version 48 admin finance, permissions, and activity completion */
.users-control-metrics > article {
  min-width: 0;
  overflow: hidden;
}

.users-control-metrics > article > strong {
  min-width: 0;
  max-width: 100%;
  overflow-wrap: anywhere;
  font-variant-numeric: tabular-nums;
  line-height: 1.12;
}

.user-effective-permissions,
.user-recent-activity {
  display: grid;
  min-width: 0;
  gap: .55rem;
}

.user-effective-permissions > span,
.user-recent-activity > span {
  color: var(--muted);
  font-size: .66rem;
  font-weight: 700;
  letter-spacing: .045em;
  text-transform: uppercase;
}

.user-effective-permissions > div {
  display: flex;
  min-width: 0;
  flex-wrap: wrap;
  gap: .4rem;
}

.user-effective-permissions i {
  display: inline-flex;
  min-height: 1.8rem;
  align-items: center;
  gap: .35rem;
  padding: .3rem .5rem;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--surface);
  color: var(--text-soft);
  font-size: .68rem;
  font-style: normal;
}

.user-effective-permissions i > svg {
  flex: 0 0 auto;
  color: var(--accent);
}

.user-recent-activity {
  grid-column: 1 / -1;
  padding-top: .75rem;
  border-top: 1px solid var(--line);
}

.user-recent-activity ol {
  display: grid;
  gap: .45rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.user-recent-activity li {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: .55rem;
  padding: .6rem .7rem;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface);
}

.user-recent-activity li > svg {
  flex: 0 0 auto;
  color: var(--accent);
}

.user-recent-activity li > span {
  display: grid;
  min-width: 0;
  gap: .15rem;
}

.user-recent-activity li :is(strong, time) {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.user-recent-activity li strong {
  font-size: .76rem;
}

.user-recent-activity li time,
.user-recent-activity > small {
  color: var(--muted);
  font-size: .68rem;
}

.payout-summary-metrics {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.payout-summary-metrics article > small {
  color: var(--muted);
  font-size: .68rem;
}

.payout-report-note {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: .65rem;
  margin-bottom: 1rem;
  padding: .75rem;
  border: 1px solid var(--line);
  border-radius: var(--site-card-radius, var(--radius));
  background: var(--bg-soft);
}

.payout-report-note[data-enabled="true"] {
  border-color: color-mix(in srgb, var(--theme-status-green) 42%, var(--line));
}

.payout-report-note > svg {
  flex: 0 0 auto;
  color: var(--accent);
}

.payout-report-note > span {
  display: grid;
  min-width: 0;
  gap: .2rem;
}

.payout-report-note small {
  color: var(--muted);
}

.payout-team-table td:not(:first-child) {
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.payout-records-section {
  display: grid;
  gap: .75rem;
  margin-top: 1rem;
  padding: 1rem;
  border: 1px solid var(--line);
  border-radius: var(--site-card-radius, var(--radius));
  background: var(--bg-soft);
}

.payout-records-section > header {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: .75rem;
}

.payout-records-section > header > div {
  display: grid;
  gap: .2rem;
}

.payout-records-section > header span {
  color: var(--muted);
  font-size: .66rem;
  font-weight: 700;
  letter-spacing: .045em;
  text-transform: uppercase;
}

.payout-records-section :is(h3, p) {
  margin: 0;
}

.payout-record-list {
  display: grid;
  gap: .45rem;
}

.payout-record-list > article {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  align-items: center;
  gap: .75rem;
  padding: .7rem;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface);
}

.payout-record-list > article > span {
  display: grid;
  min-width: 0;
  gap: .2rem;
}

.payout-record-list > article small,
.payout-records-empty {
  color: var(--muted);
}

.payout-record-list > article > b {
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

@media (max-width: 920px) {
  .payout-summary-metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

/* Version 48.1.0 — local authentication and discounted chapter pricing. */
.auth-local-form {
  display: grid;
  width: min(100%, 480px);
  gap: .85rem;
  padding: clamp(1rem, 2.5vw, 1.35rem);
  border: 1px solid var(--line);
  border-radius: var(--site-card-radius, var(--radius));
  background: var(--surface);
}

.auth-local-form > label {
  display: grid;
  gap: .4rem;
  color: var(--text-soft);
  font-size: .76rem;
  font-weight: 650;
}

.auth-local-form input {
  width: 100%;
  min-height: 3rem;
  padding: 0 .85rem;
  border: 1px solid var(--line);
  border-radius: var(--site-button-radius, var(--radius-small));
  outline: none;
  background: var(--surface-strong);
  color: var(--text);
  font: inherit;
  font-size: .9rem;
  font-weight: 500;
}

.auth-local-form input:focus-visible {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 18%, transparent);
}

.auth-local-form label small {
  color: var(--muted);
  font-size: .68rem;
  font-weight: 500;
  line-height: 1.5;
}

.auth-local-actions {
  display: flex;
  flex-wrap: wrap;
  gap: .65rem;
}

.auth-local-actions .button {
  min-height: 2.8rem;
}

.auth-local-feedback,
.auth-local-status {
  display: flex;
  align-items: flex-start;
  gap: .5rem;
  margin: 0;
  padding: .72rem .8rem;
  border: 1px solid var(--line);
  border-radius: var(--site-button-radius, var(--radius-small));
  background: var(--surface-2);
  color: var(--text-soft);
  font-size: .74rem;
  line-height: 1.5;
}

.auth-local-feedback svg,
.auth-local-status svg {
  flex: 0 0 auto;
  margin-top: .08rem;
}

.auth-local-feedback.is-error {
  border-color: color-mix(in srgb, var(--danger) 50%, var(--line));
  color: var(--danger);
}

.auth-local-feedback.is-success {
  border-color: color-mix(in srgb, var(--success) 50%, var(--line));
  color: var(--success);
}

.auth-provider-divider {
  display: flex;
  width: min(100%, 480px);
  align-items: center;
  gap: .75rem;
  color: var(--muted);
  font-size: .7rem;
  text-transform: uppercase;
}

.auth-provider-divider::before,
.auth-provider-divider::after {
  height: 1px;
  flex: 1;
  background: var(--line);
  content: "";
}

.chapter-discount-price {
  display: inline-flex;
  align-items: center;
  gap: .3rem;
}

.chapter-discount-price s,
.reader-lock-original-price {
  color: var(--muted);
  font-size: .82em;
}

.chapter-discount-price b,
.reader-lock-discount-badge {
  padding: .12rem .32rem;
  border-radius: 999px;
  background: color-mix(in srgb, var(--danger) 16%, transparent);
  color: var(--danger);
  font-size: .65rem;
  font-weight: 800;
  text-decoration: none;
}

.reader-lock-discount-badge {
  margin-left: .35rem;
}

.ops-account-menu > div button {
  display: flex;
  width: 100%;
  min-height: 40px;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--text-soft);
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.ops-account-menu > div button:is(:hover, :focus-visible) {
  background: var(--surface-2);
  color: var(--text);
}

@media (max-width: 600px) {
  .auth-local-actions {
    display: grid;
  }

  .auth-local-actions .button {
    width: 100%;
  }
}

@media (max-width: 760px) {
  .user-effective-permissions,
  .user-recent-activity {
    grid-column: 1;
  }

  .payout-summary-metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .users-control-table[data-view="payouts"] td:nth-child(1)::before { content: "Team"; }
  .users-control-table[data-view="payouts"] td:nth-child(2)::before { content: "Total received"; }
  .users-control-table[data-view="payouts"] td:nth-child(3)::before { content: "Posted balance"; }
  .users-control-table[data-view="payouts"] td:nth-child(4)::before { content: "Pending"; }
  .users-control-table[data-view="payouts"] td:nth-child(5)::before { content: "Withdrawn"; }
  .users-control-table[data-view="payouts"] td:nth-child(6)::before { content: "Last earning"; }

  .payout-team-table td:not(:first-child) {
    white-space: normal;
    text-align: right;
  }

  .payout-record-list > article {
    grid-template-columns: minmax(0, 1fr) auto;
  }

  .payout-record-list .technical-reference {
    grid-column: 1 / -1;
  }
}

/* Administrator new-series approval workspace */
.nsq-filter-panel {
  display: grid;
  grid-template-columns: minmax(260px, 1.8fr) repeat(4, minmax(135px, 1fr));
  gap: 12px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: calc(var(--radius) + 2px);
  background: var(--surface);
}

.nsq-filter-panel label {
  display: grid;
  min-width: 0;
  align-content: start;
  gap: 7px;
  color: var(--text-soft);
  font-size: 10px;
  font-weight: 700;
}

.nsq-filter-panel :is(input, select) {
  width: 100%;
  min-width: 0;
  min-height: 42px;
  padding: 9px 11px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  outline: 0;
  background: var(--bg-soft);
  color: var(--text);
}

.nsq-filter-panel :is(input, select):focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 12%, transparent);
}

.nsq-query-field {
  grid-row: span 2;
}

.nsq-query-field > div {
  display: grid;
  min-height: 96px;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 9px;
  padding: 0 14px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--bg-soft);
}

.nsq-query-field > div:focus-within {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 12%, transparent);
}

.nsq-query-field > div > input {
  min-height: 50px;
  padding: 0;
  border: 0;
  box-shadow: none !important;
  background: transparent;
}

.nsq-filter-actions {
  display: flex;
  grid-column: -3 / -1;
  align-items: end;
  justify-content: flex-end;
  gap: 8px;
}

.nsq-queue-summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  color: var(--muted);
  font-size: 10px;
}

.nsq-queue-summary > span {
  display: flex;
  align-items: center;
  gap: 6px;
}

.nsq-queue-summary strong {
  color: var(--text);
}

.nsq-master-detail {
  grid-template-columns: minmax(300px, 0.34fr) minmax(0, 1fr);
}

.nsq-request-list {
  align-content: start;
  max-height: min(840px, calc(100vh - 100px));
}

.nsq-request-list > button:not(.button) {
  display: grid;
  min-height: 104px;
  grid-template-columns: 42px minmax(0, 1fr) auto;
  align-items: center;
  position: relative;
}

.nsq-list-cover {
  height: 54px;
  border-radius: 7px;
}

.nsq-request-list > button > span:nth-child(2) {
  gap: 4px;
}

.nsq-request-list > button > span:nth-child(2) :is(small, em) {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.nsq-status {
  display: inline-flex;
  min-height: 24px;
  align-items: center;
  justify-content: center;
  padding: 4px 8px;
  border: 1px solid var(--line-strong);
  border-radius: 999px;
  background: var(--surface-2);
  color: var(--text-soft);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.035em;
  line-height: 1;
  text-align: center;
  text-transform: uppercase;
}

.nsq-status[data-status="SUBMITTED"] {
  border-color: color-mix(in srgb, #e2a72f 52%, var(--line));
  background: color-mix(in srgb, #e2a72f 10%, var(--surface));
  color: color-mix(in srgb, #e2a72f 75%, var(--text));
}

.nsq-status[data-status="UNDER_REVIEW"] {
  border-color: color-mix(in srgb, var(--accent) 52%, var(--line));
  background: color-mix(in srgb, var(--accent) 10%, var(--surface));
  color: var(--accent);
}

.nsq-status[data-status="CHANGES_REQUESTED"] {
  border-color: color-mix(in srgb, var(--theme-status-yellow) 50%, var(--line));
  background: color-mix(in srgb, var(--theme-status-yellow) 9%, var(--surface));
  color: var(--theme-status-yellow);
}

.nsq-status[data-status="APPROVED"] {
  border-color: color-mix(in srgb, var(--theme-status-green) 45%, var(--line));
  background: color-mix(in srgb, var(--theme-status-green) 9%, var(--surface));
  color: var(--theme-status-green);
}

.nsq-status[data-status="REJECTED"],
.nsq-status[data-status="WITHDRAWN"] {
  border-color: color-mix(in srgb, var(--theme-status-red) 42%, var(--line));
  background: color-mix(in srgb, var(--theme-status-red) 8%, var(--surface));
  color: var(--theme-status-red);
}

.nsq-risk-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--theme-status-yellow);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--theme-status-yellow) 14%, transparent);
  position: absolute;
  top: 8px;
  right: 8px;
}

.nsq-list-loading,
.nsq-list-empty {
  display: grid;
  min-height: 180px;
  place-items: center;
  align-content: center;
  gap: 8px;
  padding: 20px;
  color: var(--muted);
  font-size: 10px;
  text-align: center;
}


.nsq-list-empty strong {
  color: var(--text);
  font-size: 13px;
}

.nsq-list-empty p {
  margin: 0;
  line-height: 1.5;
}

.nsq-pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  padding-top: 6px;
  border-top: 1px solid var(--line);
}

.nsq-pagination .button {
  width: 38px;
  min-height: 34px;
  padding: 0;
}

.nsq-pagination span {
  min-width: 62px;
  color: var(--muted);
  font-size: 9px;
  text-align: center;
}

.nsq-detail-shell {
  display: grid;
  min-width: 0;
  gap: 16px;
}

.nsq-detail-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
  padding: clamp(18px, 2.5vw, 30px);
  border: 1px solid var(--line);
  border-radius: calc(var(--radius) + 3px);
  background:
    radial-gradient(
      circle at 100% 0,
      color-mix(in srgb, var(--accent) 11%, transparent),
      transparent 22rem
    ),
    var(--surface);
}

.nsq-detail-header h3 {
  margin: 5px 0 7px;
  font-size: clamp(23px, 3vw, 34px);
  letter-spacing: -0.045em;
}

.nsq-detail-header p,
.nsq-detail-header small {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.55;
}

.nsq-detail-header > div:last-child {
  display: grid;
  max-width: 220px;
  justify-items: end;
  gap: 8px;
  text-align: right;
}

.nsq-detail-tabs {
  overflow-x: auto;
}

.nsq-detail-content {
  display: grid;
  min-width: 0;
  gap: 18px;
}

.nsq-media-review {
  overflow: hidden;
}

.nsq-artwork-grid {
  display: grid;
  min-width: 0;
  gap: 18px;
}

.nsq-banner-preview {
  display: grid;
  min-height: 180px;
  margin: 0;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background:
    linear-gradient(135deg, var(--surface-2), var(--surface-3));
  position: relative;
}

.nsq-banner-preview img {
  width: 100%;
  height: 100%;
  min-height: 180px;
  max-height: 280px;
  object-fit: cover;
}

.nsq-banner-preview > span {
  display: grid;
  min-height: 180px;
  place-items: center;
  color: var(--muted);
  font-size: 10px;
}

.nsq-banner-preview figcaption {
  padding: 8px 11px;
  background: color-mix(in srgb, var(--surface) 88%, transparent);
  color: var(--muted);
  font-size: 9px;
  position: absolute;
  right: 8px;
  bottom: 8px;
  border-radius: 999px;
  backdrop-filter: blur(10px);
}

.nsq-public-preview {
  display: grid;
  grid-template-columns: minmax(110px, 0.22fr) minmax(0, 1fr);
  align-items: start;
  gap: 20px;
}

.nsq-cover-preview {
  display: grid;
  width: 100%;
  aspect-ratio: 2 / 3;
  place-items: center;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface-3);
  color: var(--accent);
}

.nsq-cover-preview img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.nsq-public-preview > div:last-child {
  min-width: 0;
}

.nsq-public-preview > div > span {
  color: var(--accent);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.06em;
}

.nsq-public-preview h4 {
  margin: 7px 0 10px;
  font-size: clamp(22px, 3vw, 36px);
  letter-spacing: -0.04em;
}

.nsq-public-preview p {
  display: -webkit-box;
  max-width: 72ch;
  margin: 0;
  overflow: hidden;
  color: var(--text-soft);
  font-size: 11px;
  line-height: 1.7;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 5;
}

.nsq-chip-row {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-top: 14px;
}

.nsq-chip-row span {
  padding: 5px 8px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--surface-2);
  color: var(--text-soft) !important;
  font-size: 8px !important;
}

.nsq-long-copy {
  display: grid;
  gap: 7px;
  padding: 15px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface-2);
}

.nsq-long-copy > span {
  color: var(--muted);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.nsq-long-copy p {
  max-width: 82ch;
  margin: 0;
  white-space: pre-wrap;
  color: var(--text-soft);
  font-size: 11px;
  line-height: 1.7;
}

.nsq-team-cards,
.nsq-source-list,
.nsq-rights-list,
.nsq-feedback-timeline,
.nsq-revision-timeline,
.nsq-series-results {
  display: grid;
  gap: 10px;
}

.nsq-team-cards {
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
}

.nsq-team-cards article,
.nsq-source-list article {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 11px;
  padding: 13px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface-2);
}

.nsq-team-cards article > svg,
.nsq-source-list article > svg {
  flex: 0 0 auto;
  color: var(--accent);
}

.nsq-team-cards article > div,
.nsq-source-list article > div {
  display: grid;
  min-width: 0;
  flex: 1;
  gap: 3px;
}

.nsq-team-cards strong,
.nsq-source-list strong {
  font-size: 11px;
}

.nsq-team-cards span,
.nsq-team-cards small,
.nsq-source-list span {
  color: var(--muted);
  font-size: 9px;
}

.nsq-source-list > p {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
}

.nsq-risk-score {
  flex: 0 0 auto;
  padding: 7px 10px;
  border: 1px solid color-mix(in srgb, var(--theme-status-yellow) 45%, var(--line));
  border-radius: 999px;
  background: color-mix(in srgb, var(--theme-status-yellow) 9%, var(--surface));
  color: var(--theme-status-yellow);
  font-size: 9px;
  font-weight: 800;
}

.nsq-comparison-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.nsq-comparison-grid > article,
.nsq-no-duplicates {
  display: grid;
  min-width: 0;
  align-content: start;
  gap: 9px;
  padding: 17px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface-2);
}

.nsq-comparison-request {
  border-color: color-mix(in srgb, var(--accent) 32%, var(--line)) !important;
  background:
    radial-gradient(
      circle at 100% 0,
      color-mix(in srgb, var(--accent) 8%, transparent),
      transparent 14rem
    ),
    var(--surface-2) !important;
}

.nsq-comparison-grid h4 {
  margin: 0;
  font-size: 18px;
}

.nsq-comparison-grid p,
.nsq-comparison-grid small,
.nsq-comparison-grid > article > span {
  margin: 0;
  color: var(--muted);
  font-size: 9px;
  line-height: 1.5;
}

.nsq-duplicate-card header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: var(--muted);
  font-size: 9px;
  font-weight: 800;
  text-transform: uppercase;
}

.nsq-duplicate-card header strong {
  color: var(--theme-status-yellow);
  font-size: 13px;
}

.nsq-duplicate-card ul {
  display: grid;
  gap: 5px;
  margin: 0;
  padding-left: 18px;
  color: var(--text-soft);
  font-size: 10px;
  line-height: 1.5;
}

.nsq-duplicate-card > div {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin-top: auto;
  padding-top: 5px;
}

.nsq-no-duplicates {
  place-items: center;
  align-content: center;
  color: var(--theme-status-green);
  text-align: center;
}

.nsq-no-duplicates p {
  max-width: 42ch;
}

.nsq-assignment-form,
.nsq-feedback-composer {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr)) auto;
  align-items: end;
  gap: 12px;
}

.nsq-feedback-composer .nsq-span-all {
  grid-column: 1 / -1;
}

.nsq-feedback-composer textarea {
  min-height: 110px;
}

.nsq-feedback-composer > .button {
  justify-self: start;
}

.nsq-feedback-timeline article {
  display: grid;
  gap: 7px;
  padding: 14px;
  border: 1px solid var(--line);
  border-left: 3px solid var(--accent);
  border-radius: var(--radius-small);
  background: var(--surface-2);
}

.nsq-feedback-timeline article[data-visibility="INTERNAL"] {
  border-left-color: var(--theme-status-yellow);
}

.nsq-feedback-timeline article > span {
  width: fit-content;
  padding: 3px 6px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--accent) 10%, var(--surface));
  color: var(--accent);
  font-size: 8px;
  font-weight: 800;
  text-transform: uppercase;
}

.nsq-feedback-timeline article[data-visibility="INTERNAL"] > span {
  background: color-mix(in srgb, var(--theme-status-yellow) 10%, var(--surface));
  color: var(--theme-status-yellow);
}

.nsq-feedback-timeline article > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.nsq-feedback-timeline time,
.nsq-feedback-timeline small {
  color: var(--muted);
  font-size: 9px;
}

.nsq-feedback-timeline p,
.nsq-readonly-note {
  margin: 0;
  color: var(--text-soft);
  font-size: 10px;
  line-height: 1.65;
  white-space: pre-wrap;
}

.nsq-revision-timeline article {
  display: grid;
  grid-template-columns: 32px minmax(0, 1fr);
  gap: 11px;
  align-items: start;
}

.nsq-revision-timeline article > span {
  display: grid;
  width: 32px;
  height: 32px;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: var(--surface-2);
  color: var(--accent);
  font-size: 9px;
  font-weight: 800;
}

.nsq-revision-timeline article > div {
  display: grid;
  gap: 4px;
  padding: 8px 0 15px;
  border-bottom: 1px solid var(--line);
}

.nsq-revision-timeline small,
.nsq-revision-timeline p {
  margin: 0;
  color: var(--muted);
  font-size: 9px;
  line-height: 1.5;
}

.nsq-start-review {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 18px;
  border: 1px solid color-mix(in srgb, var(--accent) 35%, var(--line));
  border-radius: var(--radius);
  background: color-mix(in srgb, var(--accent) 7%, var(--surface));
}

.nsq-start-review > div {
  display: flex;
  align-items: center;
  gap: 12px;
}

.nsq-start-review svg {
  flex: 0 0 auto;
  color: var(--accent);
}

.nsq-start-review p {
  margin: 4px 0 0;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.5;
}

.nsq-rights-list > article {
  display: grid;
  gap: 13px;
  padding: 15px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface-2);
}

.nsq-rights-list > article > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.nsq-rights-list > article > header > div {
  display: grid;
  gap: 3px;
}

.nsq-rights-list small {
  color: var(--muted);
  font-size: 9px;
}

.nsq-rights-list > article > div {
  display: grid;
  grid-template-columns: repeat(3, minmax(130px, 1fr)) minmax(170px, 1.4fr);
  gap: 8px;
}

.nsq-validation-error {
  margin: 0;
  color: var(--theme-danger);
  font-size: 10px;
  line-height: 1.5;
}

.nsq-decision-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  align-items: start;
  gap: 18px;
}

.nsq-series-search {
  display: flex;
  align-items: end;
  gap: 8px;
}

.nsq-series-search label {
  flex: 1;
}

.nsq-series-results {
  max-height: 260px;
  overflow: auto;
}

.nsq-series-results > button {
  display: flex;
  width: 100%;
  min-height: 54px;
  align-items: center;
  gap: 10px;
  padding: 8px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface-2);
  color: var(--text);
  cursor: pointer;
  text-align: left;
}

.nsq-series-results > button[aria-pressed="true"] {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 8%, var(--surface));
}

.nsq-series-results > button > span {
  display: grid;
  width: 34px;
  height: 42px;
  flex: 0 0 auto;
  place-items: center;
  overflow: hidden;
  border-radius: 5px;
  background: var(--surface-3);
  color: var(--accent);
}

.nsq-series-results img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.nsq-series-results > button > div {
  display: grid;
  min-width: 0;
  gap: 4px;
}

.nsq-series-results strong {
  overflow: hidden;
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.nsq-series-results small {
  color: var(--muted);
  font-size: 8px;
}

.nsq-selected-series {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px;
  border: 1px solid color-mix(in srgb, var(--theme-status-green) 40%, var(--line));
  border-radius: var(--radius-small);
  background: color-mix(in srgb, var(--theme-status-green) 7%, var(--surface));
  color: var(--theme-status-green);
  font-size: 10px;
}

.nsq-change-fields {
  display: grid;
  gap: 10px;
}

.nsq-change-fields > div {
  display: grid;
  grid-template-columns: minmax(150px, 0.65fr) minmax(240px, 1.35fr) auto;
  align-items: end;
  gap: 8px;
}

.nsq-change-fields > div > .button {
  width: 42px;
  min-height: 44px;
  padding: 0;
}

.nsq-change-fields > .button,
.nsq-change-request > .button,
.nsq-reject-section > .button {
  justify-self: start;
}

.nsq-reject-section {
  border-color: color-mix(in srgb, var(--theme-danger) 25%, var(--line));
}

.nsq-approved-series {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 14px;
  border: 1px solid color-mix(in srgb, var(--theme-status-green) 40%, var(--line));
  border-radius: var(--radius-small);
  background: color-mix(in srgb, var(--theme-status-green) 7%, var(--surface));
  color: var(--theme-status-green);
  text-decoration: none;
}

.nsq-approved-series > span {
  display: grid;
  flex: 1;
  gap: 3px;
  font-size: 9px;
}

.nsq-approved-series strong {
  color: var(--text);
  font-size: 13px;
}

@media (max-width: 1280px) {
  .nsq-filter-panel {
    grid-template-columns: repeat(3, minmax(150px, 1fr));
  }

  .nsq-query-field {
    grid-column: 1 / -1;
    grid-row: auto;
  }

  .nsq-query-field > div {
    min-height: 48px;
  }

  .nsq-filter-actions {
    grid-column: auto;
  }

  .nsq-rights-list > article > div {
    grid-template-columns: repeat(2, minmax(150px, 1fr));
  }
}

@media (max-width: 1000px) {
  .nsq-master-detail {
    grid-template-columns: 1fr;
  }

  .nsq-request-list {
    max-height: 390px;
    position: static;
  }

  .nsq-decision-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 720px) {
  .nsq-filter-panel {
    grid-template-columns: 1fr;
  }

  .nsq-query-field,
  .nsq-filter-actions {
    grid-column: auto;
  }

  .nsq-filter-actions {
    align-items: stretch;
    flex-direction: column;
  }

  .nsq-filter-actions .button {
    width: 100%;
  }

  .nsq-queue-summary,
  .nsq-detail-header,
  .nsq-start-review {
    align-items: stretch;
    flex-direction: column;
  }

  .nsq-detail-header > div:last-child {
    max-width: none;
    justify-items: start;
    text-align: left;
  }

  .nsq-detail-tabs {
    display: flex;
    flex-wrap: nowrap;
  }

  .nsq-detail-tabs button {
    flex: 0 0 auto;
  }

  .nsq-public-preview,
  .nsq-comparison-grid {
    grid-template-columns: 1fr;
  }

  .nsq-cover-preview {
    width: min(180px, 55vw);
  }

  .nsq-assignment-form,
  .nsq-feedback-composer {
    grid-template-columns: 1fr;
  }

  .nsq-feedback-composer .nsq-span-all {
    grid-column: auto;
  }

  .nsq-rights-list > article > header {
    align-items: stretch;
    flex-direction: column;
  }

  .nsq-rights-list > article > div {
    grid-template-columns: 1fr;
  }

  .nsq-series-search,
  .nsq-change-fields > div {
    display: grid;
    grid-template-columns: 1fr;
  }

  .nsq-change-fields > div > .button {
    width: 100%;
  }

  .nsq-source-list article {
    align-items: flex-start;
    flex-wrap: wrap;
  }

  .nsq-source-list article .button {
    width: 100%;
  }
}

:root[data-theme="light"] {
  color-scheme: light;
  --shadow: rgba(21, 66, 97, 0.16);
  --header: color-mix(in srgb, var(--theme-main-background) 92%, transparent);
}

* {
  box-sizing: border-box;
}

html {
  background: var(--bg);
  color: var(--text);
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-width: 320px;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-geist-sans), system-ui, sans-serif;
  text-rendering: optimizeLegibility;
}

button,
input,
select,
textarea {
  color: inherit;
  font: inherit;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

button {
  border: 0;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  display: block;
  max-width: 100%;
}

::selection {
  background: var(--accent);
  color: var(--accent-ink);
}

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}

.sr-only,
.sr-only-focusable:not(:focus):not(:focus-within) {
  position: absolute !important;
  width: 1px !important;
  height: 1px !important;
  padding: 0 !important;
  margin: -1px !important;
  overflow: hidden !important;
  clip: rect(0, 0, 0, 0) !important;
  white-space: nowrap !important;
  border: 0 !important;
}

.page-wrap {
  width: var(--page);
  margin-inline: auto;
}

.advanced-filter-bar,
.chapter-search {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 12px 0 22px;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface);
}

.advanced-filter-bar button {
  padding: 9px 13px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--surface-2);
  cursor: pointer;
}

.advanced-filter-bar button:last-child {
  margin-left: auto;
  color: var(--accent);
}

.chapter-search input {
  width: 100%;
  border: 0;
  outline: 0;
  background: transparent;
}

.account-admin-link {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 18px;
  padding: 13px 14px;
  border: 1px solid color-mix(in srgb, var(--accent) 55%, var(--line));
  border-radius: var(--radius-small);
  background: color-mix(in srgb, var(--accent) 10%, var(--surface));
  color: var(--accent);
  font-size: 14px;
  font-weight: 700;
}

.account-admin-link svg:last-child {
  margin-left: auto;
}

.account-logout-link {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 9px;
  padding: 13px 14px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface);
  color: var(--text-soft);
  font-size: 14px;
  font-weight: 700;
}

.account-logout-link:hover {
  border-color: color-mix(in srgb, var(--danger) 48%, var(--line));
  color: var(--danger);
}

.account-logout-link svg:last-child {
  margin-left: auto;
}

.release-wizard {
  margin: 0 0 24px;
  padding: 24px;
  border: 1px solid color-mix(in srgb, var(--accent) 35%, var(--line));
  border-radius: var(--radius);
  background: var(--surface);
  box-shadow: 0 24px 70px var(--shadow);
}

.release-wizard-head,
.release-actions,
.release-review {
  display: flex;
  align-items: center;
}

.release-wizard-head {
  justify-content: space-between;
}

.release-wizard-head p {
  margin: 0 0 5px;
  color: var(--accent);
  font-size: 12px;
  font-weight: 750;
  text-transform: uppercase;
  letter-spacing: .12em;
}

.release-wizard-head h2 {
  margin: 0;
  font-size: 24px;
}

.release-wizard-head > button {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  border-radius: var(--radius-small);
  background: var(--surface-2);
  cursor: pointer;
}

.release-steps {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 8px;
  margin: 24px 0;
  padding: 0;
  list-style: none;
}

.release-steps li {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 11px;
  border-bottom: 2px solid var(--line);
  color: var(--muted);
  font-size: 13px;
  font-weight: 650;
}

.release-steps li span {
  display: grid;
  width: 24px;
  height: 24px;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 50%;
}

.release-steps li[aria-current="step"],
.release-steps li.is-complete {
  border-color: var(--accent);
  color: var(--text);
}

.release-steps li.is-complete span,
.release-steps li[aria-current="step"] span {
  border-color: var(--accent);
  background: var(--accent);
  color: var(--accent-ink);
}

.release-fields {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.release-fields label {
  display: grid;
  gap: 8px;
}

.release-fields label > span {
  color: var(--text-soft);
  font-size: 13px;
  font-weight: 650;
}

.release-fields input,
.release-fields select {
  min-height: 46px;
  padding: 0 13px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface-2);
}

.release-wide {
  grid-column: 1 / -1;
}

.release-dropzone {
  display: grid;
  min-height: 220px;
  place-items: center;
  align-content: center;
  gap: 9px;
  border: 1px dashed var(--line-strong);
  border-radius: var(--radius);
  background: var(--surface-2);
  text-align: center;
  cursor: pointer;
}

.release-dropzone svg {
  color: var(--accent);
}

.release-dropzone span {
  color: var(--muted);
  font-size: 13px;
}

.release-dropzone input {
  margin-top: 8px;
}

.release-review {
  gap: 14px;
  min-height: 120px;
  padding: 20px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface-2);
}

.release-review > svg {
  color: var(--accent);
}

.release-review p {
  margin: 5px 0 0;
  color: var(--muted);
}

.release-review > span {
  margin-left: auto;
  color: var(--accent);
  font-weight: 700;
}

.release-actions {
  justify-content: flex-end;
  gap: 10px;
  margin-top: 22px;
}

.release-actions button:disabled {
  opacity: .45;
  cursor: not-allowed;
}

.site-shell {
  min-height: 100dvh;
  overflow: clip;
  background:
    radial-gradient(circle at 88% 0%, color-mix(in srgb, var(--accent) 5%, transparent), transparent 24rem),
    var(--bg);
}

.site-header {
  position: sticky;
  top: 0;
  z-index: 40;
  height: 72px;
  border-bottom: 1px solid color-mix(in srgb, var(--line) 76%, transparent);
  background: var(--header);
  backdrop-filter: blur(20px) saturate(130%);
  -webkit-backdrop-filter: blur(20px) saturate(130%);
}

.site-header-inner {
  width: var(--page);
  height: 100%;
  margin-inline: auto;
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 44px;
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 11px;
  width: max-content;
  color: var(--text);
  font-size: 18px;
  font-weight: 730;
  letter-spacing: -0.04em;
}

.brand-mark {
  position: relative;
  width: 29px;
  height: 29px;
  overflow: hidden;
  border-radius: 9px;
  background: var(--brand-gradient);
  color: var(--accent-ink);
}

.brand-mark::before,
.brand-mark::after {
  position: absolute;
  top: 5px;
  width: 8px;
  height: 8px;
  background: var(--accent-ink);
  content: "";
  transform: rotate(45deg);
}

.brand-mark::before {
  left: 5px;
}

.brand-mark::after {
  right: 5px;
}

.brand-mark > span {
  position: absolute;
  inset: 10px 6px 5px;
  border-radius: 8px 8px 6px 6px;
  background: var(--accent-ink);
}

.brand-mark > span::before,
.brand-mark > span::after {
  position: absolute;
  top: 6px;
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: var(--accent);
  content: "";
}

.brand-mark > span::before {
  left: 5px;
}

.brand-mark > span::after {
  right: 5px;
}

.brand-mark:has(.theme-aware-logo) {
  overflow: visible;
  border-radius: 0;
  color: var(--theme-logo-color);
  background: transparent;
}

.brand-mark:has(.theme-aware-logo)::before,
.brand-mark:has(.theme-aware-logo)::after {
  display: none;
}

.brand-mark .theme-aware-logo {
  display: block;
  width: 100%;
  height: 100%;
}

.desktop-nav {
  display: flex;
  align-items: center;
  gap: 31px;
}

.desktop-nav a {
  position: relative;
  color: var(--text-soft);
  font-size: 14px;
  font-weight: 560;
}

.desktop-nav a:hover,
.desktop-nav a[aria-current="page"] {
  color: var(--text);
}

.desktop-nav a[aria-current="page"]::after {
  position: absolute;
  right: 0;
  bottom: -26px;
  left: 0;
  height: 2px;
  background: var(--accent);
  content: "";
}

.header-actions {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
}

.header-search,
.icon-button,
.account-link,
.header-role-link,
.header-logout {
  display: inline-flex;
  min-height: 40px;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--line);
  background: var(--surface);
  transition:
    border-color 160ms ease,
    background-color 160ms ease,
    transform 160ms ease;
}

.header-search:hover,
.icon-button:hover,
.account-link:hover,
.header-role-link:hover,
.header-logout:hover {
  border-color: var(--line-strong);
  background: var(--surface-2);
}

.header-search:active,
.icon-button:active,
.account-link:active,
.header-role-link:active,
.header-logout:active,
.button:active {
  transform: translateY(1px);
}

.header-search {
  gap: 9px;
  min-width: 182px;
  justify-content: flex-start;
  padding: 0 10px 0 13px;
  border-radius: 999px;
  color: var(--muted);
  font-size: 13px;
}

.header-search span {
  flex: 1;
  text-align: left;
}

.header-search kbd {
  min-width: 22px;
  padding: 2px 6px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: var(--bg-soft);
  color: var(--text-soft);
  font-family: var(--font-geist-mono), monospace;
  font-size: 11px;
}

.icon-button {
  width: 40px;
  border-radius: 50%;
  color: var(--text-soft);
}

.account-link {
  gap: 8px;
  min-width: 88px;
  padding: 0 12px;
  border-radius: 999px;
  color: var(--text);
  font-size: 13px;
  font-weight: 640;
}

.header-role-link,
.header-logout {
  gap: 7px;
  padding: 0 12px;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 700;
}

.header-role-link {
  border-color: color-mix(in srgb, var(--accent) 48%, var(--line));
  background: color-mix(in srgb, var(--accent) 10%, var(--surface));
  color: var(--accent);
}

.header-role-link.is-admin {
  background: var(--brand-gradient);
  color: var(--accent-ink);
}

.header-logout {
  color: var(--text-soft);
}

.header-overflow {
  position: relative;
}

.header-overflow-menu {
  position: absolute;
  z-index: 120;
  top: calc(100% + 10px);
  right: 0;
  display: grid;
  width: min(280px, calc(100vw - 24px));
  overflow: hidden;
  padding: 7px;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius);
  background: color-mix(in srgb, var(--surface) 96%, transparent);
  box-shadow: 0 18px 50px var(--shadow);
  backdrop-filter: blur(20px);
}

.header-overflow-menu :is(a, button) {
  display: flex;
  min-height: 44px;
  align-items: center;
  gap: 10px;
  padding: 0 11px;
  border-radius: var(--radius-small);
  background: transparent;
  color: var(--text-soft);
  cursor: pointer;
  text-align: left;
  font-size: 12px;
  font-weight: 660;
}

.header-overflow-menu :is(a, button):hover,
.header-overflow-menu :is(a, button):focus-visible {
  background: var(--surface-2);
  color: var(--text);
}

.header-overflow-menu .is-danger {
  margin-top: 5px;
  border-top: 1px solid var(--line);
  border-radius: 0 0 var(--radius-small) var(--radius-small);
  color: var(--danger);
}

.announcement {
  min-height: 35px;
  padding: 8px 18px;
  background: var(--accent);
  color: var(--accent-ink);
  text-align: center;
  font-size: 12px;
  line-height: 19px;
}

.announcement span {
  margin-right: 10px;
  font-weight: 760;
}

.announcement a {
  margin-left: 12px;
  border-bottom: 1px solid currentColor;
  font-weight: 700;
}

.hero-section {
  position: relative;
  min-height: calc(100dvh - 107px);
  max-height: 900px;
  overflow: hidden;
  background: var(--bg);
  isolation: isolate;
}

.hero-art,
.hero-vignette {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.hero-art {
  z-index: -3;
  object-fit: cover;
  object-position: center;
}

.hero-vignette {
  z-index: -2;
  background:
    linear-gradient(90deg, rgba(8, 11, 8, 0.96) 3%, rgba(8, 11, 8, 0.82) 32%, rgba(8, 11, 8, 0.12) 67%, rgba(8, 11, 8, 0.18)),
    linear-gradient(0deg, rgba(8, 11, 8, 0.7), transparent 38%);
}

.hero-copy {
  min-height: inherit;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: flex-start;
  padding-top: 54px;
  padding-bottom: 64px;
}

.eyebrow {
  margin: 0 0 18px;
  color: var(--accent);
  font-size: 11px;
  font-weight: 750;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.hero-copy h1 {
  max-width: 660px;
  margin: 0;
  color: #f2f4ee;
  font-size: clamp(48px, 5.7vw, 84px);
  font-weight: 710;
  letter-spacing: -0.065em;
  line-height: 0.98;
}

.hero-copy > p:not(.eyebrow) {
  max-width: 510px;
  margin: 24px 0 0;
  color: #c8cdc3;
  font-size: 18px;
  line-height: 1.55;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 11px;
  margin-top: 31px;
}

.button {
  display: inline-flex;
  min-height: 46px;
  align-items: center;
  justify-content: center;
  gap: 9px;
  padding: 0 19px;
  border: 1px solid transparent;
  border-radius: 999px;
  cursor: pointer;
  font-size: 14px;
  font-weight: 680;
  line-height: 1;
  white-space: nowrap;
  transition:
    background-color 160ms ease,
    border-color 160ms ease,
    color 160ms ease,
    transform 160ms ease;
}

.button:disabled {
  cursor: wait;
  opacity: 0.64;
}

.button-primary {
  border-color: var(--theme-button-accent);
  background: var(--theme-button-accent);
  color: var(--theme-button-accent-alternate);
}

.button-primary:hover {
  border-color: var(--theme-primary-l1);
  background: var(--theme-primary-l1);
  filter: none;
}

.button-primary:active {
  border-color: var(--theme-primary-l2);
  background: var(--theme-primary-l2);
}

.button-secondary {
  border-color: var(--line-strong);
  background: color-mix(in srgb, var(--surface) 84%, transparent);
  color: var(--text);
}

.hero-section .button-secondary {
  border-color: rgba(242, 244, 238, 0.28);
  background: rgba(19, 22, 19, 0.54);
  color: #f2f4ee;
  backdrop-filter: blur(12px);
}

.button-secondary:hover,
.button-quiet:hover {
  border-color: var(--accent);
}

.button-quiet {
  border-color: var(--line);
  background: transparent;
  color: var(--text);
}

.hero-title-card {
  position: absolute;
  right: 5.4vw;
  bottom: 38px;
  display: grid;
  gap: 4px;
  padding: 13px 16px;
  border: 1px solid rgba(242, 244, 238, 0.18);
  border-radius: var(--radius-small);
  background: rgba(14, 17, 14, 0.56);
  color: #f2f4ee;
  backdrop-filter: blur(14px);
}

.hero-title-card span {
  font-size: 14px;
  font-weight: 690;
}

.hero-title-card small {
  color: #afb5ab;
  font-size: 11px;
}

.home-continue {
  position: relative;
  z-index: 3;
  margin-top: -27px;
}

.continue-card,
.continue-guest {
  min-height: 118px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
  box-shadow: 0 22px 70px var(--shadow);
}

.continue-card {
  display: grid;
  grid-template-columns: 76px 1fr auto;
  align-items: center;
  gap: 20px;
  max-width: 650px;
  padding: 13px 18px 13px 13px;
}

.continue-card > img {
  width: 76px;
  height: 92px;
  border-radius: var(--radius-small);
  object-fit: cover;
  object-position: top;
}

.continue-card > div > span {
  color: var(--accent);
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.14em;
}

.continue-card h2 {
  margin: 7px 0 3px;
  font-size: 18px;
  letter-spacing: -0.03em;
}

.continue-card p {
  margin: 0 0 10px;
  color: var(--muted);
  font-size: 12px;
}

.mini-progress {
  width: 100%;
  height: 3px;
  overflow: hidden;
  border-radius: 999px;
  background: var(--theme-progress-track);
}

.mini-progress i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--theme-progress-fill);
}

.continue-play {
  display: grid;
  width: 44px;
  height: 44px;
  place-items: center;
  border-radius: 50%;
  background: var(--accent);
  color: var(--accent-ink);
}

.continue-guest {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 24px 27px;
}

.continue-guest > div {
  display: flex;
  align-items: center;
  gap: 17px;
}

.continue-guest svg {
  color: var(--accent);
}

.continue-guest span {
  display: grid;
  gap: 4px;
  color: var(--text-soft);
  font-size: 13px;
}

.continue-guest strong {
  color: var(--text);
  font-size: 15px;
}

.content-section {
  padding-top: 105px;
  padding-bottom: 105px;
}

.section-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 28px;
  margin-bottom: 31px;
}

.section-heading h2 {
  margin: 0;
  font-size: clamp(30px, 3vw, 45px);
  font-weight: 690;
  letter-spacing: -0.055em;
  line-height: 1.05;
}

.section-heading p {
  max-width: 520px;
  margin: 10px 0 0;
  color: var(--muted);
  font-size: 14px;
  line-height: 1.6;
}

.section-heading > a,
.section-tabs > a {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--text-soft);
  font-size: 13px;
  font-weight: 660;
}

.section-heading > a:hover,
.section-tabs > a:hover {
  color: var(--accent);
}

.section-tabs {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 38px;
  margin-bottom: 31px;
}

.section-tabs h2 {
  margin: 0;
  font-size: clamp(32px, 3vw, 45px);
  letter-spacing: -0.055em;
}

.section-tabs > div {
  display: flex;
  gap: 3px;
  width: max-content;
  padding: 4px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--surface);
}

.section-tabs button,
.billing-toggle button {
  min-height: 34px;
  padding: 0 15px;
  border-radius: 999px;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  font-size: 12px;
  font-weight: 650;
}

.section-tabs button[aria-selected="true"],
.billing-toggle button[aria-pressed="true"] {
  background: var(--surface-3);
  color: var(--text);
}

.series-rail {
  display: grid;
  grid-auto-columns: minmax(185px, 1fr);
  grid-auto-flow: column;
  gap: 22px;
  overflow-x: auto;
  padding: 3px 3px 18px;
  scrollbar-width: thin;
  scroll-snap-type: x proximity;
}

.ranked-card {
  position: relative;
  min-width: 185px;
  scroll-snap-align: start;
}

.ranked-card > span {
  position: absolute;
  z-index: 3;
  top: -5px;
  left: -4px;
  color: var(--accent);
  font-family: var(--font-geist-mono), monospace;
  font-size: 12px;
  font-weight: 770;
}

.series-card {
  min-width: 0;
}

.cover-link {
  position: relative;
  display: block;
  aspect-ratio: 2 / 3;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface-2);
  box-shadow: 0 18px 38px color-mix(in srgb, var(--shadow) 62%, transparent);
}

.cover-link > img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 500ms cubic-bezier(0.16, 1, 0.3, 1);
}

.cover-link:hover > img {
  transform: scale(1.035);
}

.cover-shade {
  position: absolute;
  inset: 0;
  background: linear-gradient(0deg, rgba(6, 8, 6, 0.84), transparent 38%);
}

.access-badge {
  display: inline-flex;
  min-height: 25px;
  align-items: center;
  gap: 5px;
  padding: 0 8px;
  border: 1px solid rgba(242, 244, 238, 0.16);
  border-radius: 999px;
  background: rgba(13, 15, 13, 0.72);
  color: #e6e9e1;
  font-size: 10px;
  font-weight: 650;
  backdrop-filter: blur(9px);
}

.cover-link > .access-badge {
  position: absolute;
  top: 10px;
  right: 10px;
}

.access-free {
  color: var(--accent);
}

.access-premium,
.access-early_access {
  color: #f1d078;
}

.quick-read {
  position: absolute;
  right: 12px;
  bottom: 12px;
  display: flex;
  align-items: center;
  gap: 6px;
  color: #f2f4ee;
  font-size: 11px;
  font-weight: 680;
  opacity: 0;
  transform: translateY(7px);
  transition:
    opacity 180ms ease,
    transform 180ms ease;
}

.cover-link:hover .quick-read,
.cover-link:focus-visible .quick-read {
  opacity: 1;
  transform: translateY(0);
}

.series-card-copy {
  padding: 13px 3px 0;
}

.series-card h3 {
  overflow: hidden;
  margin: 0;
  color: var(--text);
  font-size: 15px;
  font-weight: 680;
  letter-spacing: -0.025em;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.series-card-copy > p {
  overflow: hidden;
  margin: 5px 0 0;
  color: var(--muted);
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.series-meta {
  display: flex;
  align-items: center;
  gap: 13px;
  margin-top: 9px;
  color: var(--text-soft);
  font-size: 11px;
}

.series-meta span {
  display: flex;
  align-items: center;
  gap: 4px;
}

.series-meta svg {
  color: var(--accent);
}

.updates-section {
  padding: 102px 0;
  background: var(--bg-soft);
}

.updates-layout {
  display: grid;
  grid-template-columns: minmax(0, 1.65fr) minmax(320px, 0.75fr);
  gap: 68px;
}

.update-rows {
  border-top: 1px solid var(--line);
}

.update-row {
  display: grid;
  grid-template-columns: 48px minmax(150px, 1.2fr) minmax(100px, 0.7fr) minmax(96px, 0.65fr) 58px 18px;
  align-items: center;
  gap: 14px;
  min-height: 80px;
  border-bottom: 1px solid var(--line);
  transition: background-color 160ms ease;
}

.update-row:hover {
  background: color-mix(in srgb, var(--surface) 65%, transparent);
}

.update-thumb {
  width: 39px;
  height: 54px;
  overflow: hidden;
  border-radius: 7px;
}

.update-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.update-title {
  display: grid;
  gap: 4px;
}

.update-title strong {
  font-size: 13px;
}

.update-title small,
.update-row time {
  color: var(--muted);
  font-size: 10px;
}

.update-chapter {
  color: var(--text-soft);
  font-size: 12px;
}

.update-access {
  color: var(--accent);
  font-size: 11px;
  font-weight: 620;
}

.update-row > svg {
  color: var(--muted);
}

.editor-pick {
  position: relative;
  align-self: stretch;
  overflow: hidden;
  padding: 34px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background:
    radial-gradient(circle at 70% 45%, color-mix(in srgb, var(--accent) 14%, transparent), transparent 44%),
    var(--surface);
}

.editor-pick h2 {
  max-width: 320px;
  margin: 0;
  font-size: clamp(30px, 3vw, 46px);
  line-height: 1.02;
  letter-spacing: -0.055em;
}

.editor-pick > p:not(.eyebrow) {
  max-width: 390px;
  margin: 18px 0 24px;
  color: var(--text-soft);
  font-size: 13px;
  line-height: 1.65;
}

.cover-stack {
  position: relative;
  height: 215px;
  margin: 25px 0 29px;
}

.cover-stack img {
  position: absolute;
  bottom: 0;
  left: 50%;
  width: 130px;
  height: 195px;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius-small);
  object-fit: cover;
  box-shadow: 0 18px 36px var(--shadow);
  transform-origin: bottom center;
}

.cover-stack img:nth-child(1) {
  transform: translateX(-104%) rotate(-8deg) scale(0.92);
}

.cover-stack img:nth-child(2) {
  z-index: 2;
  transform: translateX(-50%);
}

.cover-stack img:nth-child(3) {
  transform: translateX(4%) rotate(8deg) scale(0.92);
}

.feature-mosaic {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 22px;
}

.feature-mosaic > .series-card:first-child {
  grid-row: auto;
  grid-column: auto;
}

.feature-mosaic > .series-card:first-child .cover-link {
  aspect-ratio: 2 / 3;
}

.mosaic-message {
  display: flex;
  min-height: 240px;
  flex-direction: column;
  align-items: flex-start;
  justify-content: flex-end;
  padding: 25px;
  border: 1px solid color-mix(in srgb, var(--accent) 38%, var(--line));
  border-radius: var(--radius);
  background:
    linear-gradient(145deg, color-mix(in srgb, var(--accent) 15%, var(--surface)), var(--surface));
}

.mosaic-message > svg {
  margin-bottom: auto;
  color: var(--accent);
}

.mosaic-message h3 {
  margin: 32px 0 7px;
  font-size: 24px;
  letter-spacing: -0.04em;
}

.mosaic-message p {
  margin: 0 0 17px;
  color: var(--text-soft);
  font-size: 13px;
  line-height: 1.55;
}

.mosaic-message a {
  color: var(--accent);
  font-size: 12px;
  font-weight: 670;
}

.genre-section {
  padding: 105px 0;
  background: var(--surface);
}

.genre-section h2 {
  margin: 0 0 37px;
  font-size: clamp(35px, 4vw, 58px);
  letter-spacing: -0.06em;
}

.genre-cloud {
  display: flex;
  flex-wrap: wrap;
  gap: 11px;
}

.genre-cloud a {
  display: inline-flex;
  min-height: 51px;
  align-items: center;
  gap: 12px;
  padding: 0 20px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--bg-soft);
  font-size: 16px;
  font-weight: 600;
  transition:
    border-color 160ms ease,
    background-color 160ms ease,
    transform 160ms ease;
}

.genre-cloud a:hover {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 10%, var(--bg-soft));
  transform: translateY(-2px);
}

.genre-cloud .genre-large {
  min-height: 61px;
  padding-inline: 27px;
  font-size: 22px;
}

.community-section {
  display: grid;
  grid-template-columns: 1.45fr 0.72fr;
  gap: 23px;
  padding-top: 105px;
  padding-bottom: 105px;
}

.team-spotlight,
.membership-panel {
  min-height: 330px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
}

.team-spotlight {
  position: relative;
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: center;
  overflow: hidden;
  padding: 46px;
  background:
    linear-gradient(115deg, var(--surface), color-mix(in srgb, var(--accent) 8%, var(--surface)));
}

.team-spotlight p {
  margin: 0 0 17px;
  color: var(--muted);
  font-size: 12px;
}

.team-spotlight h2 {
  margin: 0;
  font-size: clamp(43px, 5vw, 72px);
  letter-spacing: -0.07em;
}

.team-spotlight > div:first-child > span {
  display: block;
  margin-top: 13px;
  color: var(--text-soft);
  font-size: 12px;
}

.team-mark {
  display: grid;
  width: 120px;
  height: 120px;
  place-items: center;
  border-radius: 50%;
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 32px;
  font-weight: 800;
  letter-spacing: -0.08em;
}

.team-spotlight > a {
  position: absolute;
  right: 45px;
  bottom: 37px;
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 660;
}

.membership-panel {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  padding: 37px;
  background: var(--surface);
}

.membership-panel > svg {
  color: var(--accent);
}

.membership-panel h2 {
  margin: 28px 0 8px;
  font-size: 36px;
  letter-spacing: -0.055em;
}

.membership-panel p {
  margin: 0;
  color: var(--text-soft);
  font-size: 13px;
  line-height: 1.55;
}

.membership-panel > span {
  margin-top: 13px;
  color: var(--muted);
  font-size: 11px;
}

.membership-panel .button {
  margin-top: auto;
}

.newsletter-section {
  border-top: 1px solid var(--line);
  background: var(--bg-soft);
}

.newsletter-inner {
  display: grid;
  grid-template-columns: 1fr 1.1fr;
  align-items: center;
  gap: 90px;
  min-height: 270px;
  padding-top: 55px;
  padding-bottom: 55px;
}

.newsletter-inner h2 {
  margin: 0;
  font-size: clamp(34px, 4vw, 55px);
  letter-spacing: -0.06em;
}

.newsletter-inner > div > p {
  margin: 13px 0 0;
  color: var(--muted);
  font-size: 14px;
}

.newsletter-form {
  display: grid;
  gap: 8px;
}

.newsletter-form > label,
.settings-form label > span,
.catalog-toolbar label > span {
  color: var(--text-soft);
  font-size: 11px;
  font-weight: 650;
}

.newsletter-form > div {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 8px;
}

.newsletter-form input,
.newsletter-form button,
.settings-form input,
.settings-form select {
  min-height: 47px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
}

.newsletter-form input,
.settings-form input,
.settings-form select {
  min-width: 0;
  padding: 0 14px;
  background: var(--surface);
  color: var(--text);
}

.newsletter-form input::placeholder,
.catalog-search input::placeholder {
  color: var(--muted);
}

.newsletter-form button {
  padding: 0 19px;
  background: var(--accent);
  color: var(--accent-ink);
  cursor: pointer;
  font-weight: 680;
}

.newsletter-form .form-error,
.newsletter-form .form-help {
  margin: 0;
  font-size: 11px;
}

.form-error {
  color: var(--danger) !important;
}

.form-help {
  color: var(--muted) !important;
