  background: var(--theme-accent);
  color: var(--theme-mid-tone);
}

.reader-header > a {
  width: 39px;
  height: 39px;
}

.reader-header > div:nth-child(2) {
  display: grid;
  gap: 3px;
}

.reader-header strong {
  font-size: 12px;
}

.reader-header span {
  color: var(--theme-mid-tone);
  font-size: 9px;
}

.reader-header-actions {
  display: flex;
  gap: 7px;
}

.reader-header-actions :is(button, a) {
  min-height: 39px;
  gap: 7px;
  padding: 0 13px;
  cursor: pointer;
  font-size: 10px;
}

.reader-show-ui {
  position: fixed;
  z-index: 50;
  top: 18px;
  right: 18px;
  min-height: 38px;
  padding: 0 14px;
  border-radius: 999px;
  background: var(--theme-accent-l2);
  color: var(--theme-text-color);
  cursor: pointer;
  font-size: 11px;
}

.reader-controls {
  position: fixed;
  z-index: 45;
  top: 81px;
  right: 18px;
  display: grid;
  gap: 9px;
  padding: 9px;
  border: 1px solid var(--theme-accent-l3);
  border-radius: var(--radius);
  color: var(--theme-text-color);
  background: color-mix(in srgb, var(--theme-accent) 90%, transparent);
  backdrop-filter: blur(14px);
  transition:
    opacity 180ms ease,
    transform 180ms ease;
}

.reader-controls-hidden {
  pointer-events: none;
  opacity: 0;
  transform: translateX(12px);
}

.reader-controls > div {
  display: grid;
  gap: 4px;
}

.reader-controls button {
  display: flex;
  min-height: 36px;
  align-items: center;
  gap: 8px;
  padding: 0 11px;
  border-radius: var(--radius-small);
  background: transparent;
  color: var(--theme-mid-tone);
  cursor: pointer;
  font-size: 10px;
}

.reader-controls button[aria-pressed="true"] {
  background: var(--theme-accent-l2);
  color: var(--theme-primary);
}

.reader-controls label {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 6px;
  border-top: 1px solid var(--theme-accent-l3);
}

.reader-controls input {
  width: 92px;
  accent-color: var(--accent);
}

.reader-stage {
  position: relative;
  display: flex;
  max-width: 920px;
  min-height: 100dvh;
  flex-direction: column;
  gap: 10px;
  margin-inline: auto;
  padding: 78px 0 80px;
}

.comic-page {
  position: relative;
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  grid-template-rows: 1fr 0.78fr;
  gap: 7px;
  aspect-ratio: 0.71;
  overflow: hidden;
  padding: 9px;
  background: #e9ece4;
  color: #111411;
}

.comic-page-hidden {
  display: none;
}

.comic-frame {
  position: relative;
  overflow: hidden;
  border: 4px solid #111411;
  background: #252b25;
}

.comic-frame::before,
.comic-frame::after,
.comic-frame span {
  position: absolute;
  content: "";
}

.comic-frame-a {
  grid-row: span 2;
  background:
    radial-gradient(circle at 64% 34%, #dfe4d9 0 7%, transparent 7.5%),
    linear-gradient(128deg, transparent 40%, #596259 40% 47%, transparent 48%),
    repeating-linear-gradient(78deg, #1c211c 0 8px, #323932 8px 11px);
}

.comic-frame-a::before {
  top: 25%;
  right: 12%;
  width: 37%;
  height: 51%;
  border-radius: 46% 46% 20% 20%;
  background: #0e110e;
  box-shadow: -34px 44px 0 -21px var(--accent);
}

.comic-frame-a::after {
  right: 0;
  bottom: 8%;
  left: 0;
  height: 3px;
  background: repeating-linear-gradient(90deg, #bbc2b6 0 4px, transparent 4px 11px);
}

.comic-frame-b {
  background:
    linear-gradient(160deg, #c9cec4 0 23%, #4f584f 23% 38%, #181d18 38%),
    #171b17;
}

.comic-frame-b::before {
  inset: 23% 14%;
  border: 9px solid #111411;
  transform: skew(-12deg);
}

.comic-frame-b span {
  top: 47%;
  left: 29%;
  width: 48%;
  height: 4px;
  background: var(--accent);
  transform: rotate(-20deg);
}

.comic-frame-c {
  background:
    radial-gradient(ellipse at 50% 62%, #aab2a7 0 18%, #3c443c 18% 27%, #121612 28%),
    #171b17;
}

.comic-frame-c::before {
  inset: 0;
  background: repeating-radial-gradient(circle at 40% 20%, transparent 0 12px, rgba(232, 236, 227, 0.2) 13px 14px);
}

.comic-page > p {
  position: absolute;
  z-index: 4;
  right: 4%;
  bottom: 3%;
  left: 4%;
  margin: 0;
  color: #eff1eb;
  font-family: var(--font-geist-mono), monospace;
  font-size: clamp(13px, 1.5vw, 21px);
  font-weight: 800;
  letter-spacing: 0.14em;
  text-align: center;
  text-shadow: 0 2px 9px rgba(3, 5, 3, 0.9);
}

.comic-page-2 .comic-frame-a,
.comic-page-5 .comic-frame-b,
.comic-page-8 .comic-frame-c {
  filter: invert(0.8);
}

.comic-page-3 .comic-frame-a::before,
.comic-page-6 .comic-frame-a::before {
  right: auto;
  left: 15%;
  transform: scaleX(-1);
}

.reader-mode-single .reader-stage {
  max-width: 760px;
  justify-content: center;
}

.reader-mode-double .reader-stage {
  max-width: 1320px;
  flex-direction: row;
  align-items: center;
}

.reader-mode-double .comic-page {
  width: 50%;
}

.reader-page-nav {
  position: fixed;
  z-index: 43;
  inset: 50% 22px auto;
  display: flex;
  justify-content: space-between;
  pointer-events: none;
}

.reader-page-nav button {
  display: grid;
  width: 50px;
  height: 50px;
  place-items: center;
  border: 1px solid var(--theme-accent-l3);
  border-radius: 50%;
  background: color-mix(in srgb, var(--theme-accent) 78%, transparent);
  color: var(--theme-text-color);
  cursor: pointer;
  pointer-events: auto;
}

.reader-page-nav button:disabled {
  opacity: 0.25;
}

.reader-footer {
  position: fixed;
  z-index: 44;
  right: 0;
  bottom: 0;
  left: 0;
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 19px;
  min-height: 50px;
  padding: 0 20px;
  border-top: 1px solid var(--theme-accent-l3);
  background: color-mix(in srgb, var(--theme-main-background) 90%, transparent);
  color: var(--theme-mid-tone);
  font-size: 10px;
  backdrop-filter: blur(14px);
  transition:
    opacity 180ms ease,
    transform 180ms ease;
}

.reader-footer-hidden {
  pointer-events: none;
  opacity: 0;
  transform: translateY(12px);
}

.reader-progress {
  height: 3px;
