  font-size: 11px;
}

.chapter-management-error h1 {
  margin: 0;
  font-size: 28px;
}

.chapter-management-error .button {
  justify-self: center;
  margin-top: 10px;
}

.reader-comments-disabled {
  display: flex;
  max-width: 760px;
  min-height: 92px;
  align-items: center;
  gap: 14px;
  margin: 0 auto 30px;
  padding: 20px;
  border: 1px solid var(--theme-accent-l3);
