  cursor: pointer;
}

.support-grid > :is(a, button) > svg:first-child {
  color: var(--accent);
}

.support-grid > :is(a, button) strong {
  font-size: 13px;
}

.support-ticket {
  grid-column: span 2;
  display: flex;
  min-height: 230px;
  flex-direction: column;
  align-items: flex-start;
  justify-content: flex-end;
  padding: 34px;
  border: 1px solid color-mix(in srgb, var(--accent) 35%, var(--line));
  border-radius: var(--radius);
  background:
    radial-gradient(circle at 80% 20%, color-mix(in srgb, var(--accent) 14%, transparent), transparent 40%),
    var(--surface);
}

.support-ticket > svg {
  margin-bottom: auto;
  color: var(--accent);
}

.support-ticket h2 {
  margin: 25px 0 7px;
  font-size: 29px;
}

.support-ticket p {
  margin: 0 0 20px;
  color: var(--text-soft);
  font-size: 12px;
}

.notification-list {
  display: grid;
  gap: 8px;
  max-width: 850px;
}

.notification-list > div {
  display: grid;
  grid-template-columns: 42px 1fr auto;
  align-items: center;
  gap: 13px;
  min-height: 82px;
  padding: 13px 17px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
}

.notification-list > div > span {
  display: grid;
  width: 39px;
  height: 39px;
  place-items: center;
  border-radius: 50%;
  background: color-mix(in srgb, var(--accent) 12%, var(--surface-2));
  color: var(--accent);
}

.notification-list strong,
.notification-list p {
  margin: 0;
}

.notification-list strong {
  font-size: 12px;
}

.notification-list p,
.notification-list time {
  margin-top: 4px;
  color: var(--muted);
  font-size: 10px;
}

.legal-article {
  display: grid;
  grid-template-columns: 220px minmax(0, 760px);
  gap: 75px;
}

.legal-article > aside {
  display: grid;
  align-content: start;
  gap: 5px;
}

.legal-article > aside a {
  padding: 10px 0;
  color: var(--muted);
  font-size: 11px;
}

.legal-article > div > h2 {
  margin: 44px 0 12px;
  font-size: 25px;
  letter-spacing: -0.04em;
}

.legal-article > div > p {
  color: var(--text-soft);
  font-size: 14px;
  line-height: 1.75;
}

.legal-notice {
  display: flex;
  align-items: flex-start;
  gap: 11px;
  padding: 16px;
  border: 1px solid color-mix(in srgb, var(--warning) 50%, var(--line));
  border-radius: var(--radius-small);
  background: color-mix(in srgb, var(--warning) 8%, var(--surface));
}

.legal-notice svg {
  flex: 0 0 auto;
  color: var(--warning);
}

.legal-notice p {
  margin: 0;
  color: var(--text-soft);
  font-size: 11px;
  line-height: 1.55;
}

.legal-updated {
  margin-top: 50px !important;
  color: var(--muted) !important;
  font-size: 10px !important;
}

.status-page {
  max-width: 950px;
}

.status-hero {
  margin-bottom: 50px;
}

.status-hero > span {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: var(--accent);
  font-size: 12px;
  font-weight: 650;
}

.status-hero h1 {
  margin: 24px 0 10px;
  font-size: clamp(49px, 6vw, 78px);
  letter-spacing: -0.07em;
}

.status-hero p {
  margin: 0;
  color: var(--muted);
  font-size: 14px;
}

.service-list {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
}

.service-list > div {
  display: grid;
  grid-template-columns: 24px minmax(0, 1fr) 110px 150px;
  align-items: center;
  gap: 12px;
  min-height: 68px;
  padding: 0 20px;
  border-bottom: 1px solid var(--line);
}

.service-list > div:last-child {
  border-bottom: 0;
}

.service-list strong {
  font-size: 12px;
}

.service-list span,
.service-list small {
  color: var(--muted);
  font-size: 10px;
}

.service-list .service-ok {
  color: var(--accent);
}

.service-list .service-test {
  color: var(--warning);
}

.incident-card {
  margin-top: 40px;
}

.incident-card h2 {
  margin: 0 0 18px;
  font-size: 25px;
}

.site-footer {
  padding: 68px 0 92px;
  border-top: 1px solid var(--line);
  background: var(--bg-soft);
}

.footer-main {
  display: grid;
  grid-template-columns: minmax(230px, 0.9fr) minmax(0, 1.7fr);
  gap: clamp(48px, 7vw, 110px);
}

.footer-brand {
  display: grid;
  align-content: start;
  gap: 13px;
}

.footer-brand p {
  max-width: 380px;
  margin: 0;
  color: var(--text-soft);
  font-size: 13px;
  line-height: 1.7;
}

.footer-socials {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 5px;
}

.footer-socials a {
  color: var(--text-soft);
  font-size: 12px;
  font-weight: 650;
}

.footer-socials a:hover {
  color: var(--accent);
}

.footer-links {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 34px;
}

.footer-links details {
  min-width: 0;
}

.footer-links summary {
  margin-bottom: 16px;
  color: var(--text);
  font-size: 12px;
  font-weight: 750;
  list-style: none;
}

.footer-links summary::-webkit-details-marker {
  display: none;
}

.footer-links details > div {
  display: grid;
  gap: 11px;
}

.footer-links a {
  color: var(--muted);
  font-size: 12px;
}

.footer-links a:hover {
  color: var(--accent);
}

.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  margin-top: 55px;
  padding-top: 20px;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 11px;
}

.footer-bottom > div,
.footer-bottom a,
.footer-bottom button {
  display: flex;
  align-items: center;
}

.footer-bottom > div {
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

.footer-bottom a,
.footer-bottom button {
  min-height: 36px;
  gap: 7px;
  padding: 0 11px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--surface);
  color: var(--text-soft);
  cursor: pointer;
  font-size: 11px;
}

.footer-bottom a:hover,
.footer-bottom button:hover {
  border-color: var(--line-strong);
  color: var(--text);
}

.series-reviews {
  display: grid;
  gap: 24px;
  margin-top: 34px;
  padding: clamp(20px, 3vw, 32px);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
}

.review-heading,
.review-heading > label,
.review-stars,
.review-list article > header,
.review-composer > div,
.review-distribution > div {
  display: flex;
  align-items: center;
}

.review-heading {
  justify-content: space-between;
  gap: 24px;
}

.review-collapse-toggle {
  display: inline-flex;
  min-height: 2.7rem;
  align-items: center;
  justify-content: center;
  gap: .55rem;
  padding: .55rem .75rem;
  border: 1px solid color-mix(in srgb, var(--accent) 32%, var(--line));
  border-radius: var(--site-button-radius, var(--radius-small));
  background: color-mix(in srgb, var(--accent) 8%, var(--surface-2));
  color: var(--text);
  font: inherit;
  font-size: .78rem;
  font-weight: 750;
  cursor: pointer;
  transition: border-color .18s ease, background-color .18s ease, transform .16s ease;
}

.review-collapse-toggle:hover,
.review-collapse-toggle:focus-visible {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 16%, var(--surface-2));
  outline: 2px solid color-mix(in srgb, var(--accent) 32%, transparent);
  outline-offset: 2px;
}

.review-collapse-toggle:active {
  transform: scale(.98);
}

.review-collapse-toggle svg {
  color: var(--accent);
  transition: transform .18s ease;
}

.review-collapse-toggle[aria-expanded="true"] svg {
  transform: rotate(180deg);
}

.review-collapsible {
  display: grid;
  gap: 24px;
}

.review-collapsible[hidden] {
  display: none;
}

.review-toolbar {
  display: flex;
  justify-content: flex-end;
}

.review-toolbar > label {
  display: block;
  width: min(100%, 12rem);
}

.review-heading h2 {
  margin: 0;
  font-size: clamp(24px, 3vw, 34px);
  letter-spacing: -0.045em;
}

.review-summary-grid {
  display: grid;
  grid-template-columns: 150px minmax(180px, 0.8fr) minmax(280px, 1.4fr);
  gap: 24px;
}

.review-score,
.review-distribution,
.review-composer {
  padding: 20px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface-2);
}

.review-score {
  display: grid;
  place-items: center;
  align-content: center;
  gap: 8px;
  text-align: center;
}

.review-score > strong {
  font-family: var(--font-geist-mono), monospace;
  font-size: 44px;
  letter-spacing: -0.08em;
}

.review-score > span:last-child {
  color: var(--muted);
  font-size: 11px;
}

.review-stars {
  gap: 2px;
  color: var(--warning);
}

.review-stars button {
  display: grid;
  width: 32px;
  height: 32px;
  place-items: center;
  padding: 0;
  border-radius: 50%;
  background: transparent;
  color: var(--warning);
  cursor: pointer;
}

.review-stars button:hover {
  background: color-mix(in srgb, var(--warning) 12%, transparent);
}

.review-distribution {
  display: grid;
  align-content: center;
  gap: 7px;
}

.review-distribution > div {
  display: grid;
  grid-template-columns: 12px 14px minmax(60px, 1fr) 24px;
  gap: 6px;
  color: var(--muted);
  font-size: 10px;
}

.review-distribution svg {
  color: var(--warning);
}

.review-distribution i {
  height: 5px;
  overflow: hidden;
  border-radius: 999px;
  background: var(--surface-3);
}

.review-distribution b {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--warning);
}

.review-composer {
  display: grid;
  gap: 13px;
}

.review-composer > div:first-child {
  justify-content: space-between;
  gap: 15px;
}

.review-composer textarea {
  width: 100%;
  min-height: 104px;
  resize: vertical;
  padding: 12px 13px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  outline: 0;
  background: var(--surface);
  line-height: 1.55;
}

.review-composer textarea:focus {
  border-color: var(--accent);
}

.review-composer > div:last-child {
  justify-content: flex-end;
  gap: 10px;
}

.review-composer > div:last-child label {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-right: auto;
  color: var(--muted);
  font-size: 11px;
}

.review-composer > div:last-child > button:not(.button) {
  display: flex;
  min-height: 38px;
  align-items: center;
  gap: 6px;
  padding: 0 11px;
  border-radius: 999px;
  background: transparent;
  color: var(--danger);
  cursor: pointer;
  font-size: 11px;
}

.review-list {
  display: grid;
  gap: 10px;
}

.review-list article {
  padding: 17px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface-2);
}

.review-list article > header {
  gap: 10px;
}

.review-list article > header > span:first-child {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  border-radius: 50%;
  background: var(--brand-gradient);
  color: var(--accent-ink);
  font-size: 12px;
  font-weight: 800;
}

.review-list article > header > div {
  display: grid;
  gap: 2px;
}

.review-list article > header small {
  color: var(--muted);
  font-size: 10px;
}

.review-list article > header .review-stars {
  margin-left: auto;
}

.review-list article > p,
.review-list details p {
  margin: 14px 0 0;
  color: var(--text-soft);
  font-size: 13px;
  line-height: 1.65;
}

.review-list details {
  margin-top: 13px;
}

.review-list details summary {
  width: max-content;
  cursor: pointer;
  color: var(--warning);
  font-size: 11px;
  font-weight: 700;
}

.review-rating-only {
  color: var(--muted) !important;
  font-style: italic;
}

.review-empty {
  display: grid;
  min-height: 130px;
  place-items: center;
  align-content: center;
  gap: 6px;
  border: 1px dashed var(--line);
  border-radius: var(--radius-small);
  color: var(--muted);
  text-align: center;
  font-size: 12px;
}

.review-empty svg {
  color: var(--warning);
}

.mobile-nav {
  display: none;
}

.search-overlay {
  position: fixed;
  z-index: 90;
  inset: 0;
  display: grid;
  place-items: start center;
  padding-top: min(14vh, 130px);
}

.search-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(4, 6, 4, 0.74);
  cursor: default;
  backdrop-filter: blur(8px);
}

.search-panel {
  position: relative;
  width: min(680px, calc(100vw - 32px));
  overflow: hidden;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius);
  background: var(--surface);
  box-shadow: 0 36px 110px rgba(2, 4, 2, 0.62);
  animation: panel-in 220ms cubic-bezier(0.16, 1, 0.3, 1);
}

.search-panel-input {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 12px;
  min-height: 66px;
  padding: 0 15px 0 20px;
  border-bottom: 1px solid var(--line);
}

.search-panel-input > svg {
  color: var(--muted);
}

.search-panel-input input {
  width: 100%;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--text);
}

.search-panel-input input::placeholder {
  color: var(--muted);
}

.search-panel-input button {
  display: grid;
  width: 35px;
  height: 35px;
  place-items: center;
  border-radius: 50%;
  background: var(--surface-2);
  color: var(--text-soft);
  cursor: pointer;
}

.search-panel-body {
  max-height: 520px;
  overflow-y: auto;
  padding: 20px;
}

.panel-label {
  margin: 0 0 13px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 660;
}

.search-results {
  display: grid;
  gap: 5px;
}

.search-result {
  display: grid;
  grid-template-columns: 45px 1fr auto;
  align-items: center;
  gap: 13px;
  min-height: 68px;
  padding: 8px 10px 8px 8px;
  border-radius: var(--radius-small);
}

.search-result:hover {
  background: var(--surface-2);
}

.search-result img {
  width: 42px;
  height: 55px;
  border-radius: 6px;
  object-fit: cover;
}

.search-result > span {
  display: grid;
  gap: 4px;
}

.search-result strong {
  font-size: 12px;
}

.search-result small {
  color: var(--muted);
  font-size: 9px;
}

.search-result > svg {
  color: var(--muted);
}

.ops-shell {
  display: grid;
  grid-template-columns: 250px minmax(0, 1fr);
  min-height: 100dvh;
  background: var(--bg);
}

.ops-sidebar {
  position: sticky;
  top: 0;
  display: grid;
  grid-template-rows: auto auto 1fr auto auto;
  gap: 18px;
  height: 100dvh;
  padding: 22px 15px 16px;
  border-right: 1px solid var(--line);
  background: var(--bg-soft);
}

.ops-sidebar > .brand {
  margin: 0 8px 5px;
}

.ops-workspace {
  display: grid;
  grid-template-columns: 35px 1fr auto;
  align-items: center;
  gap: 9px;
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface);
}

.ops-workspace > span {
  display: grid;
  width: 35px;
  height: 35px;
  place-items: center;
  border-radius: 50%;
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 10px;
  font-weight: 780;
}

.ops-workspace > div {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.ops-workspace strong,
.ops-user strong {
  overflow: hidden;
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ops-workspace small,
.ops-user small {
  color: var(--muted);
  font-size: 8px;
}

.ops-sidebar nav {
  display: grid;
  align-content: start;
  gap: 2px;
  overflow-y: auto;
}

.ops-sidebar nav :is(a, button) {
  display: flex;
  min-height: 38px;
  align-items: center;
  gap: 10px;
  padding: 0 10px;
  border-radius: var(--radius-small);
  color: var(--muted);
  background: transparent;
  font-size: 10px;
  font-weight: 560;
  text-align: left;
  cursor: pointer;
}

.ops-sidebar nav :is(a, button)[aria-current="page"],
.ops-sidebar nav :is(a, button):hover {
  background: var(--surface);
  color: var(--text);
}

.ops-sidebar nav :is(a, button)[aria-current="page"] svg {
  color: var(--accent);
}

.ops-sidebar nav :is(a, button) > span {
  display: grid;
  min-width: 20px;
  height: 20px;
  margin-left: auto;
  place-items: center;
  border-radius: 999px;
  background: var(--surface-3);
  color: var(--text-soft);
  font-size: 8px;
}

.ops-user {
  display: grid;
  grid-template-columns: 34px 1fr auto;
  align-items: center;
  gap: 9px;
  padding: 9px;
  border-top: 1px solid var(--line);
}

.ops-user > span {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  border-radius: 50%;
  background: var(--surface-3);
  font-size: 11px;
  font-weight: 700;
}

.ops-user > div {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.ops-session-actions {
  display: grid;
  gap: 4px;
  padding-top: 12px;
  border-top: 1px solid var(--line);
}

.ops-session-actions a {
  display: flex;
  min-height: 40px;
  align-items: center;
  gap: 10px;
  padding: 0 10px;
  border-radius: var(--radius-small);
  color: var(--text-soft);
  font-size: 10px;
  font-weight: 650;
}

.ops-session-actions a:hover {
  background: var(--surface);
  color: var(--text);
}

.ops-session-actions a:last-child:hover {
  color: var(--danger);
}

.ops-main {
  min-width: 0;
  padding: 32px 38px 60px;
}

.ops-header {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 30px;
  margin-bottom: 30px;
}

.ops-header p,
.ops-header h1 {
  margin: 0;
}

.ops-header p {
  margin-bottom: 5px;
  color: var(--muted);
  font-size: 9px;
}

.ops-header h1 {
  font-size: 35px;
  letter-spacing: -0.055em;
}

.ops-header > div:last-child {
  display: flex;
  gap: 7px;
}

.ops-header > div:last-child > button:not(.button) {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: var(--surface);
  color: var(--text-soft);
  cursor: pointer;
}

.ops-mobile-section {
  position: relative;
  display: none;
}

.ops-metrics {
  display: grid;
  grid-template-columns: 1.15fr 0.95fr 1.08fr 0.82fr;
  gap: 12px;
}

.ops-metrics article {
  display: grid;
  grid-template-columns: 1fr auto;
  min-height: 150px;
  padding: 19px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
}

.ops-metrics article > svg {
  grid-column: 2;
  grid-row: 1;
  color: var(--accent);
}

.ops-metrics article > span {
  grid-column: 1;
  grid-row: 1;
  color: var(--muted);
  font-size: 9px;
}

.ops-metrics article > strong {
  grid-column: 1 / span 2;
  align-self: end;
  font-size: 29px;
  letter-spacing: -0.05em;
}

.ops-metrics article > small {
  grid-column: 1 / span 2;
  color: var(--muted);
  font-size: 9px;
}

.ops-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.65fr) minmax(270px, 0.65fr);
  gap: 13px;
  margin-top: 13px;
}

.ops-table-card,
.ops-activity {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
}

.ops-card-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 78px;
  padding: 0 21px;
  border-bottom: 1px solid var(--line);
}

.ops-card-heading h2,
.ops-card-heading p {
  margin: 0;
}

.ops-card-heading h2 {
  font-size: 15px;
}

.ops-card-heading p {
  margin-top: 4px;
  color: var(--muted);
  font-size: 8px;
}

.ops-card-heading button {
  display: flex;
  align-items: center;
  gap: 6px;
  background: transparent;
  color: var(--text-soft);
  cursor: pointer;
  font-size: 9px;
}

.ops-table-head,
.ops-table-row {
  display: grid;
  grid-template-columns: minmax(210px, 1.35fr) 0.7fr 0.8fr 0.5fr 28px;
  align-items: center;
  gap: 11px;
  padding: 0 20px;
}

.ops-table-head {
  min-height: 37px;
  color: var(--muted);
  font-size: 8px;
}

.ops-table-row {
  min-height: 68px;
  border-top: 1px solid var(--line);
  font-size: 9px;
}

.ops-table-row > span:first-child {
  display: grid;
  gap: 4px;
}

.ops-table-row strong {
  font-size: 10px;
}

.ops-table-row small {
  color: var(--muted);
  font-size: 8px;
}

.ops-status {
  width: max-content;
  padding: 5px 7px;
  border-radius: 999px;
  background: var(--surface-3);
  color: var(--text-soft);
}

.ops-ready-for-review {
  background: color-mix(in srgb, var(--accent) 12%, var(--surface-3));
  color: var(--accent);
}

.ops-attention {
  background: color-mix(in srgb, var(--warning) 12%, var(--surface-3));
  color: var(--warning);
}

.ops-table-row button {
  background: transparent;
  color: var(--muted);
  cursor: pointer;
}

.ops-activity {
  padding-bottom: 9px;
}

.ops-activity > div:not(.ops-card-heading) {
  display: grid;
  grid-template-columns: 26px 1fr;
  gap: 10px;
  padding: 14px 18px;
}

.ops-activity > div:not(.ops-card-heading) > span {
  display: grid;
  width: 24px;
  height: 24px;
  place-items: center;
  border-radius: 50%;
  background: color-mix(in srgb, var(--accent) 12%, var(--surface-2));
  color: var(--accent);
}

.ops-activity p {
  display: grid;
  gap: 4px;
  margin: 0;
}

.ops-activity strong {
  font-size: 9px;
}

.ops-activity small {
  color: var(--muted);
  font-size: 8px;
}

.access-page,
.error-page,
.fatal-error {
  display: grid;
  min-height: 100dvh;
  place-items: center;
  padding: 28px;
  background:
    radial-gradient(circle at 50% 25%, color-mix(in srgb, var(--accent) 9%, transparent), transparent 34rem),
    var(--bg);
}

.access-page > section,
.error-page,
.fatal-error main {
  width: min(500px, 100%);
  text-align: center;
}

.access-page .brand,
.error-page .brand {
  margin-inline: auto;
}

.access-icon {
  display: grid;
  width: 70px;
  height: 70px;
  margin: 55px auto 25px;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--accent) 40%, var(--line));
  border-radius: 50%;
  background: color-mix(in srgb, var(--accent) 10%, var(--surface));
  color: var(--accent);
}

.access-page h1 {
  margin: 0;
  font-size: 39px;
  letter-spacing: -0.055em;
}

.access-page section > p {
  margin: 15px auto 25px;
  color: var(--text-soft);
  font-size: 13px;
  line-height: 1.65;
}

.access-page section > .button {
  width: 100%;
}

.access-identity {
  display: grid;
  grid-template-columns: 42px 1fr;
  align-items: center;
  gap: 11px;
  margin: 0 auto 23px;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
  text-align: left;
}

.access-identity > span {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border-radius: 50%;
  background: var(--surface-3);
}

.access-identity > div {
  display: grid;
  gap: 3px;
}

.access-identity strong {
  font-size: 11px;
}

.access-identity small {
  color: var(--muted);
  font-size: 9px;
}

.access-page section > small {
  display: block;
  margin-top: 19px;
  color: var(--muted);
  font-size: 9px;
  line-height: 1.55;
}

.access-page section > a:last-child {
  display: inline-block;
  margin-top: 25px;
  color: var(--text-soft);
  font-size: 10px;
}

.error-page > span,
.status-code {
  margin-top: 70px;
  color: var(--accent);
  font-family: var(--font-geist-mono), monospace;
  font-size: 14px;
  font-weight: 750;
}

.error-page h1,
.fatal-error h1 {
  margin: 17px 0 10px;
  font-size: 45px;
  letter-spacing: -0.06em;
}

.error-page > p,
.fatal-error p {
  margin: 0;
  color: var(--text-soft);
  font-size: 13px;
  line-height: 1.65;
}

.error-page > div {
  display: flex;
  justify-content: center;
  gap: 9px;
  margin-top: 27px;
}

.fatal-error main button,
.fatal-error main a {
  display: inline-flex;
  min-height: 42px;
  align-items: center;
  margin: 23px 4px 0;
  padding: 0 15px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--surface);
  color: var(--text);
  cursor: pointer;
}

/* EZMANGA-inspired latest release surface */
.latest-page {
  padding-top: 0;
  padding-bottom: 110px;
}

.latest-hero {
  padding-top: 82px;
  padding-bottom: 54px;
}

.latest-hero h1 {
  margin: 4px 0 14px;
  font-size: clamp(52px, 7vw, 94px);
  line-height: 0.95;
  letter-spacing: -0.075em;
}

.latest-hero > p:last-child {
  max-width: 650px;
  margin: 0;
  color: var(--text-soft);
  font-size: 15px;
  line-height: 1.65;
}

.latest-updates-block {
  min-width: 0;
}

.latest-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 20px 24px;
}

.latest-card {
  display: grid;
  grid-template-columns: 118px minmax(0, 1fr);
  gap: 16px;
  min-width: 0;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
  transition:
    border-color 160ms ease,
    transform 160ms ease;
}

.latest-card:hover {
  border-color: color-mix(in srgb, var(--accent) 45%, var(--line));
  transform: translateY(-2px);
}

.latest-cover {
  display: block;
  aspect-ratio: 2 / 3;
  overflow: hidden;
  border-radius: var(--radius-small);
  background: var(--surface-2);
}

.latest-cover img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center top;
}

.latest-card-copy {
  min-width: 0;
}

.latest-card-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  padding-bottom: 10px;
}

.latest-card-head h3 {
  overflow: hidden;
  margin: 0;
  font-size: 15px;
  line-height: 1.25;
  letter-spacing: -0.025em;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.latest-card-head > span {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: var(--accent);
  font-size: 11px;
}

.latest-chapters {
  display: grid;
  margin: 0;
  padding: 0;
  list-style: none;
}

.latest-chapters li {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 8px;
  min-height: 29px;
  border-top: 1px solid var(--line);
  font-size: 11px;
}

.latest-chapters a {
  overflow: hidden;
  color: var(--text-soft);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.latest-chapters a:hover {
  color: var(--accent);
}

.latest-chapters time {
  color: var(--muted);
  font-size: 9px;
  white-space: nowrap;
}

.latest-chapters b {
  color: var(--accent);
  font-size: 8px;
  letter-spacing: 0.06em;
}

.latest-pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  margin-top: 38px;
}

.latest-pagination button,
.latest-pagination span {
  display: inline-flex;
  min-width: 36px;
  min-height: 36px;
  align-items: center;
  justify-content: center;
  gap: 4px;
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--surface);
  color: var(--text-soft);
  font-size: 10px;
}

.latest-pagination button {
  cursor: pointer;
}

.latest-pagination button[aria-current="page"] {
  border-color: var(--accent);
  background: var(--accent);
  color: var(--accent-ink);
}

.latest-pagination button:disabled {
  cursor: not-allowed;
  opacity: 0.42;
}

/* Account commerce */
.wallet-orders-panel {
  display: grid;
  gap: 30px;
}

.commerce-tabs {
  display: inline-flex;
  width: max-content;
  gap: 5px;
  padding: 5px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--surface);
}

.commerce-tabs button {
  display: inline-flex;
  min-height: 38px;
  align-items: center;
  gap: 7px;
  padding: 0 15px;
  border-radius: 999px;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  font-size: 11px;
}

.commerce-tabs button[aria-selected="true"] {
  background: var(--surface-3);
  color: var(--text);
}

.orders-section {
  display: grid;
  gap: 0;
}

.orders-section > .button {
  width: max-content;
  margin-top: 24px;
}

.order-row {
  display: grid;
  grid-template-columns: 40px minmax(0, 1fr) auto auto auto;
  align-items: center;
  gap: 14px;
  min-height: 76px;
  border-bottom: 1px solid var(--line);
}

.order-row > span {
  display: grid;
  width: 36px;
  height: 36px;
  place-items: center;
  border-radius: 50%;
  background: var(--surface-2);
  color: var(--accent);
}

.order-row > div {
  display: grid;
  gap: 4px;
}

.order-row strong {
  font-size: 12px;
}

.order-row small,
.order-row time {
  color: var(--muted);
  font-size: 9px;
}

.order-row b {
  font-size: 12px;
}

.order-row em {
  padding: 5px 8px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--accent) 12%, var(--surface));
  color: var(--accent);
  font-size: 9px;
  font-style: normal;
  font-weight: 720;
}

.commerce-loading,
.commerce-error {
  display: flex;
  min-height: 190px;
  align-items: center;
  justify-content: center;
  gap: 11px;
  padding: 28px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--text-soft);
}

.commerce-loading span {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--accent);
  animation: commerce-shimmer 900ms infinite alternate;
}

.commerce-loading span:nth-child(2) {
  animation-delay: 180ms;
}

.commerce-loading span:nth-child(3) {
  animation-delay: 360ms;
}

.commerce-error {
  justify-content: flex-start;
}

.commerce-error > div {
  flex: 1;
}

.commerce-error p {
  margin: 5px 0 0;
  color: var(--muted);
  font-size: 11px;
}

.commerce-error button {
  min-height: 38px;
  padding: 0 13px;
  border-radius: 999px;
  background: var(--accent);
  color: var(--accent-ink);
  cursor: pointer;
}

.account-setting-card {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 18px;
  padding: 24px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
}

.account-setting-card > svg {
  color: var(--accent);
}

.account-setting-card h3,
.account-setting-card p {
  margin: 0;
}

.account-setting-card p {
  margin-top: 6px;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.6;
}

.settings-check {
  display: flex !important;
  min-height: 48px;
  align-items: center;
  flex-direction: row !important;
  gap: 12px;
  padding: 0 4px;
  border-bottom: 1px solid var(--line);
}

.settings-check input {
  width: 18px;
  height: 18px;
  accent-color: var(--accent);
}

.gift-options {
  display: grid;
  gap: 4px;
  margin-top: 10px;
}

.gift-options a {
  padding: 9px 11px;
  border-radius: var(--radius-small);
  background: var(--surface-2);
  color: var(--text-soft);
  font-size: 10px;
}

.new-list-form {
  display: grid;
  grid-template-columns: auto minmax(180px, 1fr) auto;
  align-items: center;
  gap: 12px;
  margin: -16px 0 24px;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
}

.new-list-form label {
  color: var(--text-soft);
  font-size: 11px;
}

.new-list-form input {
  min-height: 42px;
  padding: 0 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--bg);
}

.library-collection-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 18px;
  padding: 34px 0 78px;
}

/* Admin appearance and section-specific controls */
.theme-settings-panel,
.ops-section-panel {
  display: grid;
  gap: 24px;
  padding: 28px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
}

.theme-settings-panel > header,
.ops-section-panel > header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
}

.theme-settings-panel h2,
.ops-section-panel h2 {
  margin: 7px 0 8px;
  font-size: clamp(28px, 4vw, 46px);
  letter-spacing: -0.055em;
}

.theme-settings-panel header p,
.ops-section-panel header span {
  max-width: 670px;
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.6;
}

.ops-kicker {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin: 0;
  color: var(--accent);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.theme-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

.theme-actions > button:not(.button) {
  min-height: 40px;
  padding: 0 12px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--surface-2);
  color: var(--text-soft);
  cursor: pointer;
  font-size: 10px;
}

.theme-palette-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
}

.theme-palette,
.theme-gradient {
  min-width: 0;
  margin: 0;
  padding: 20px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
}

.theme-palette legend,
.theme-gradient legend {
  padding: 0 8px;
  font-size: 12px;
  font-weight: 720;
}

.theme-palette > div,
.theme-brand-controls {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px 14px;
}

.theme-brand-controls {
  grid-template-columns: repeat(5, minmax(0, 1fr));
}

.theme-palette label,
.theme-brand-controls label {
  display: grid;
  grid-template-columns: 1fr 30px;
  align-items: center;
  gap: 4px 8px;
  min-width: 0;
  padding: 8px 0;
  border-bottom: 1px solid var(--line);
}

.theme-palette label > span,
.theme-brand-controls label > span {
  overflow: hidden;
  color: var(--text-soft);
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.theme-palette input[type="color"],
.theme-brand-controls input[type="color"],
.theme-gradient input[type="color"] {
  width: 30px;
  height: 30px;
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: transparent;
  cursor: pointer;
}

.theme-palette code,
.theme-brand-controls code {
  grid-column: 1 / -1;
  color: var(--muted);
  font-size: 8px;
}

.theme-gradient > div:not(.theme-preview) {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 14px;
  margin-top: 18px;
}

.theme-gradient label {
  display: grid;
  gap: 8px;
  color: var(--text-soft);
  font-size: 10px;
}

.theme-gradient input[type="range"] {
  width: 100%;
  accent-color: var(--accent);
}

.theme-switch {
  display: flex !important;
  align-items: center;
  grid-template-columns: none !important;
  flex-direction: row;
}

.theme-switch input {
  width: 18px;
  height: 18px;
  accent-color: var(--accent);
}

.theme-preview {
  display: grid;
  min-height: 190px;
  align-content: end;
  justify-items: start;
  gap: 8px;
  margin-top: 22px;
  padding: 22px;
  border-radius: var(--radius);
  background:
    linear-gradient(0deg, color-mix(in srgb, var(--bg) 88%, transparent), transparent),
    var(--brand-gradient);
}

.theme-preview > span {
  color: var(--accent);
  font-size: 9px;
  font-weight: 750;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.theme-preview > strong {
  font-size: clamp(24px, 3vw, 40px);
  letter-spacing: -0.045em;
}

.theme-preview button {
  min-height: 40px;
  padding: 0 14px;
  border-radius: 999px;
  background: var(--brand-gradient);
  color: var(--accent-ink);
}

.theme-status {
  display: flex;
  align-items: center;
  gap: 7px;
  margin: 0;
  color: var(--accent);
  font-size: 11px;
}

.theme-status-error,
.release-error {
  color: var(--danger);
}

.settings-loading {
  min-height: 180px;
  color: var(--muted);
}

.ops-section-search {
  display: flex;
  min-width: min(420px, 100%);
  min-height: 44px;
  align-items: center;
  gap: 9px;
  padding: 0 12px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--bg);
}

.ops-section-search input {
  width: 100%;
  border: 0;
  outline: 0;
  background: transparent;
}

.ops-section-records,
.ops-notification-panel {
  display: grid;
  gap: 8px;
}

.ops-section-records article,
.ops-notification-panel button {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 14px;
  min-height: 70px;
  padding: 10px 14px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface-2);
  color: var(--text);
}

.ops-section-records article > span {
  color: var(--accent);
  font-family: var(--font-geist-mono), monospace;
  font-size: 10px;
}

.ops-section-records article > div,
.ops-notification-panel button > span {
  display: grid;
  gap: 4px;
  text-align: left;
}

.ops-section-records small,
.ops-notification-panel small {
  color: var(--muted);
  font-size: 9px;
}

.ops-section-records em {
  color: var(--accent);
  font-size: 9px;
  font-style: normal;
}

.ops-section-records button,
.ops-notification-panel button {
  cursor: pointer;
}

.ops-section-records article > button {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  background: transparent;
  color: var(--text-soft);
  font-size: 10px;
}

.ops-notification-panel button {
  grid-template-columns: 24px minmax(0, 1fr) auto;
}

.release-error {
  flex: 1;
  margin: 0;
  font-size: 10px;
}

@keyframes panel-in {
  from {
    opacity: 0;
    transform: translateY(-12px) scale(0.985);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes commerce-shimmer {
  from {
    opacity: 0.28;
    transform: translateY(2px);
  }
  to {
    opacity: 1;
    transform: translateY(-2px);
  }
}

@media (max-width: 1180px) {
  :root {
    --page: min(100% - 40px, 1160px);
  }

  .site-header-inner {
    gap: 26px;
  }

  .desktop-nav {
    gap: 20px;
  }

  .header-search {
    min-width: 42px;
    width: 42px;
    padding: 0;
    justify-content: center;
  }

  .header-search span,
  .header-search kbd {
    display: none;
  }

  .header-role-link,
  .header-logout {
    width: 42px;
    min-width: 42px;
    padding: 0;
    border-radius: 50%;
  }

  .header-role-link span,
  .header-logout span {
    display: none;
  }

  .catalog-results.catalog-grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .updates-layout {
    gap: 38px;
  }

  .ops-shell {
    grid-template-columns: 220px minmax(0, 1fr);
  }

  .ops-main {
    padding-inline: 24px;
  }

  .ops-table-head,
  .ops-table-row {
    grid-template-columns: minmax(190px, 1fr) 0.7fr 0.8fr 0.5fr 24px;
