    width: 100%;
  }

  .roulette-tasks > header {
    align-items: start;
    flex-direction: column;
  }
}

/* V34 request workspace: one primary detail surface with a compact selector. */
.request-list-layout {
  display: block;
}

.request-record-list {
  display: flex;
  gap: 10px;
  overflow-x: auto;
  padding: 0 0 12px;
  border: 0;
  background: transparent;
  scrollbar-width: thin;
}

.request-record-list > button {
  flex: 0 0 min(330px, 84vw);
}

.request-detail {
  width: 100%;
}

@media (max-width: 430px) {
  .hero-actions {
    display: grid;
    width: 100%;
  }

  .hero-actions .button {
    width: 100%;
  }

  .continue-card {
    grid-template-columns: 60px 1fr;
  }

  .continue-card > img {
    width: 60px;
  }

  .continue-play {
    display: none;
  }

  .section-tabs > a {
    font-size: 0;
  }

  .catalog-results.catalog-grid {
    gap-inline: 11px;
  }

  .library-preview {
    min-height: 320px;
  }

  .title-hero-inner {
    grid-template-columns: 1fr;
  }

  .title-cover {
    position: static;
    width: 150px;
  }

  .title-badges {
    margin-top: 8px;
  }

  .ops-metrics {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: 1fr;
  }

  .footer-grid > div:first-child {
    grid-column: auto;
  }
}

@media (max-width: 980px) {
  .review-summary-grid {
    grid-template-columns: 140px minmax(180px, 1fr);
  }

  .review-composer {
    grid-column: 1 / -1;
  }

  .footer-main {
    grid-template-columns: minmax(210px, 0.7fr) minmax(0, 1.3fr);
    gap: 44px;
  }
}

@media (max-width: 700px) {
  .series-reviews {
    padding: 18px;
  }

  .review-heading {
    align-items: flex-start;
  }

  .review-summary-grid {
    grid-template-columns: 1fr;
  }

  .review-score {
    min-height: 150px;
  }

  .review-composer {
    grid-column: auto;
  }

  .footer-main {
    grid-template-columns: 1fr;
    gap: 36px;
  }

  .footer-links {
    grid-template-columns: 1fr;
    gap: 0;
    border-top: 1px solid var(--line);
  }

  .footer-links details {
    border-bottom: 1px solid var(--line);
  }

  .footer-links summary {
    position: relative;
    margin: 0;
    padding: 16px 28px 16px 0;
    cursor: pointer;
  }

  .footer-links summary::after {
    position: absolute;
    top: 14px;
    right: 3px;
    content: "+";
    color: var(--muted);
    font-size: 18px;
  }

  .footer-links details[open] summary::after {
    content: "−";
  }

  .footer-links details > div {
    padding: 0 0 17px;
  }

  .footer-bottom {
    align-items: flex-start;
    flex-direction: column;
  }

  .footer-bottom > div {
    justify-content: flex-start;
  }
}

@media (max-width: 470px) {
  .review-heading {
    display: grid;
  }

  .review-heading > label,
  .review-heading select {
    width: 100%;
  }

  .review-composer > div:first-child,
  .review-composer > div:last-child {
    align-items: flex-start;
    flex-wrap: wrap;
  }

  .review-composer > div:last-child label {
    width: 100%;
  }

  .review-list article > header {
    align-items: flex-start;
    flex-wrap: wrap;
  }

  .review-list article > header .review-stars {
    width: 100%;
    margin: 7px 0 0 44px;
  }
}

/* Consistent 2:3 covers across every viewport. */
.continue-card > img,
.series-list-row > img,
.continue-grid img,
.library-row img,
.title-cover,
.ranking-list img,
.search-result img {
  aspect-ratio: 2 / 3;
  height: auto;
  max-height: none;
  object-fit: cover;
  object-position: center top;
}

@media (max-width: 1180px) {
  .latest-card {
    grid-template-columns: 104px minmax(0, 1fr);
  }

  .theme-brand-controls {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 900px) {
  .latest-grid {
    grid-template-columns: 1fr;
  }

  .latest-card {
    grid-template-columns: 112px minmax(0, 1fr);
  }

  .theme-palette-grid,
  .theme-gradient > div:not(.theme-preview) {
    grid-template-columns: 1fr 1fr;
  }

  .theme-settings-panel > header,
  .ops-section-panel > header {
    flex-direction: column;
  }

  .theme-actions {
    justify-content: flex-start;
  }

  .library-collection-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 700px) {
  .latest-card {
    grid-template-columns: 90px minmax(0, 1fr);
    gap: 12px;
    padding: 10px;
  }

  .latest-pagination {
    justify-content: flex-start;
    overflow-x: auto;
    padding-bottom: 8px;
  }

  .order-row {
    grid-template-columns: 36px minmax(0, 1fr) auto;
  }

  .order-row time,
  .order-row em {
    display: none;
  }

  .theme-settings-panel,
  .ops-section-panel {
    padding: 18px;
  }

  .theme-palette-grid,
  .theme-brand-controls,
  .theme-gradient > div:not(.theme-preview) {
    grid-template-columns: 1fr;
  }

  .new-list-form {
    grid-template-columns: 1fr;
  }

  .library-collection-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .account-setting-card {
    grid-template-columns: auto 1fr;
  }

  .account-setting-card .button {
    grid-column: 1 / -1;
    width: 100%;
  }
}

@media (max-width: 430px) {
  .latest-card {
    grid-template-columns: 82px minmax(0, 1fr);
    gap: 10px;
  }

  .latest-chapters li {
    gap: 5px;
  }

  .latest-chapters b {
    display: none;
  }

  .commerce-tabs {
    width: 100%;
  }

  .commerce-tabs button {
    flex: 1;
    justify-content: center;
  }
}

/* Manhwa-first series information, chapter discovery, and discussions. */
.title-hero {
  background: var(--bg-soft);
}

.title-backdrop {
  filter: blur(58px) saturate(0.72);
  opacity: 0.34;
}

.title-hero::after {
  background:
    linear-gradient(
      90deg,
      color-mix(in srgb, var(--bg) 97%, transparent),
      color-mix(in srgb, var(--bg) 74%, transparent) 58%,
      color-mix(in srgb, var(--bg) 90%, transparent)
    ),
    linear-gradient(
      0deg,
      color-mix(in srgb, var(--bg) 98%, transparent),
      transparent 56%
    );
}

.title-hero-inner {
  grid-template-columns: minmax(220px, 300px) minmax(0, 1fr);
  gap: clamp(38px, 5vw, 68px);
}

.title-cover {
  aspect-ratio: 2 / 3;
}

.title-copy h1 {
  max-width: 960px;
  color: var(--text);
  overflow-wrap: anywhere;
  text-wrap: balance;
}

.title-subtitle,
.title-kicker,
.title-stats,
.title-synopsis {
  color: var(--text-soft);
}

.title-subtitle {
  font-size: 18px;
}

.title-kicker {
  margin: 7px 0 0;
  font-size: 13px;
  font-style: italic;
}

.title-stats svg {
  color: var(--accent);
}

.tag-row a {
  display: inline-flex;
  min-height: 38px;
  align-items: center;
  padding: 0 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  color: var(--text-soft);
  transition:
    border-color 180ms ease,
    color 180ms ease,
    transform 180ms ease;
}

.tag-row a:hover {
  border-color: var(--accent);
  color: var(--text);
  transform: translateY(-1px);
}

.title-actions .button-secondary,
.title-actions .icon-button {
  border-color: var(--line-strong);
  background: color-mix(in srgb, var(--surface) 72%, transparent);
  color: var(--text);
}

.series-jump {
  position: sticky;
  z-index: 20;
  top: 67px;
  display: flex;
  overflow-x: auto;
  gap: 4px;
  padding-block: 8px;
  border-bottom: 1px solid var(--line);
  background: color-mix(in srgb, var(--bg) 92%, transparent);
  backdrop-filter: blur(16px);
  scrollbar-width: none;
}

.series-jump::-webkit-scrollbar {
  display: none;
}

.series-jump a {
  display: inline-flex;
  min-height: 42px;
  flex: 0 0 auto;
  align-items: center;
  padding-inline: 14px;
  border-radius: var(--radius-small);
  color: var(--muted);
  font-size: 12px;
  font-weight: 650;
  transition:
    background 180ms ease,
    color 180ms ease;
}

.series-jump a:hover {
  background: var(--surface);
  color: var(--text);
}

.series-details {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(330px, 0.95fr) minmax(220px, 0.55fr);
  align-items: start;
  gap: clamp(28px, 4vw, 58px);
  padding-top: clamp(64px, 7vw, 96px);
  padding-bottom: clamp(60px, 7vw, 90px);
  border-bottom: 1px solid var(--line);
  scroll-margin-top: 140px;
}

.series-details-copy .eyebrow,
.chapter-heading .eyebrow,
.title-sidebar .eyebrow,
.comments-header .eyebrow {
  margin: 0 0 9px;
  color: var(--accent);
}

.series-details-copy h2 {
  max-width: 680px;
  margin: 0;
  font-size: clamp(34px, 4vw, 56px);
  line-height: 0.98;
  letter-spacing: -0.055em;
  text-wrap: balance;
}

.series-details-copy > p:not(.eyebrow) {
  max-width: 65ch;
  margin: 23px 0 0;
  color: var(--text-soft);
  font-size: 15px;
  line-height: 1.78;
}

.series-facts {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0 24px;
  margin: 0;
}

.series-facts div {
  display: grid;
  gap: 5px;
  min-width: 0;
  padding: 13px 0;
  border-bottom: 1px solid var(--line);
}

.series-facts dt,
.series-facts dd {
  margin: 0;
}

.series-facts dt {
  color: var(--muted);
  font-size: 10px;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.series-facts dd {
  color: var(--text);
  overflow-wrap: anywhere;
  font-size: 12px;
  font-weight: 620;
}

.series-team-card {
  display: grid;
  grid-template-columns: 52px minmax(0, 1fr) 36px;
  align-items: center;
  gap: 13px;
  padding: 18px;
  border: 1px solid color-mix(in srgb, var(--accent) 38%, var(--line));
  border-radius: var(--radius);
  background:
    radial-gradient(
      circle at 100% 0,
      color-mix(in srgb, var(--accent) 14%, transparent),
      transparent 55%
    ),
    var(--surface);
}

.series-team-mark {
  display: grid;
  width: 52px;
  aspect-ratio: 1;
  place-items: center;
  border-radius: calc(var(--radius-small) + 2px);
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 14px;
  font-weight: 800;
}

.series-team-card > div {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.series-team-card small {
  color: var(--muted);
  font-size: 9px;
}

.series-team-card strong {
  overflow: hidden;
  font-size: 13px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.series-team-card > div > span {
  display: flex;
  align-items: center;
  gap: 5px;
  color: var(--accent);
  font-size: 9px;
}

.series-team-card > a {
  display: grid;
  width: 36px;
  height: 36px;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 50%;
  transition:
    border-color 180ms ease,
    transform 180ms ease;
}

.series-team-card > a:hover {
  border-color: var(--accent);
  transform: translateX(2px);
}

.title-content {
  grid-template-columns: minmax(240px, 280px) minmax(0, 1fr);
  align-items: start;
  gap: clamp(36px, 5vw, 70px);
  padding-top: clamp(56px, 7vw, 92px);
  padding-bottom: 60px;
}

.title-main {
  display: grid;
  min-width: 0;
  gap: clamp(64px, 8vw, 104px);
}

.title-sidebar {
  position: sticky;
  top: 138px;
  display: grid;
  gap: 12px;
}

.title-sidebar > section {
  padding: 22px;
  border-color: color-mix(in srgb, var(--accent) 22%, var(--line));
  background:
    radial-gradient(
      circle at 100% 0,
      color-mix(in srgb, var(--accent) 9%, transparent),
      transparent 56%
    ),
    var(--surface);
}

.title-sidebar h3 {
  margin: 0;
  font-size: 24px;
  letter-spacing: -0.045em;
}

.reading-guide-copy {
  margin: 12px 0 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.6;
}

.chapter-quick-links {
  display: grid;
  gap: 8px;
  margin-top: 22px;
}

.chapter-quick-links .button {
  width: 100%;
  min-height: 43px;
}

.report-link {
  min-height: 44px;
}

.chapter-panel,
.series-comments {
  scroll-margin-top: 140px;
}

.chapter-heading {
  align-items: end;
  padding-bottom: 24px;
}

.chapter-heading h2 {
  font-size: clamp(34px, 4vw, 52px);
  line-height: 1;
}

.chapter-heading > div:first-child > span {
  display: block;
  margin-top: 8px;
  color: var(--muted);
  font-size: 11px;
}

.chapter-tools {
  display: grid !important;
  grid-template-columns: minmax(180px, 260px) 116px;
  gap: 8px !important;
}

.chapter-tools .chapter-search {
  min-height: 44px;
  margin: 0;
  padding: 0 12px;
}

.chapter-tools .chapter-search input {
  min-width: 0;
  font-size: 12px;
}

.chapter-sort {
  position: relative;
  display: flex;
  min-height: 44px;
  align-items: center;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface);
}

.chapter-sort select {
  width: 100%;
  height: 42px;
  padding: 0 31px 0 12px;
  border: 0;
  outline: 0;
  appearance: none;
  background: transparent;
  color: var(--text-soft);
  cursor: pointer;
  font-size: 11px;
  font-weight: 650;
}

.chapter-sort svg {
  position: absolute;
  right: 10px;
  pointer-events: none;
}

.chapter-row {
  grid-template-columns: 52px minmax(170px, 1fr) auto auto;
  gap: 16px;
  min-height: 82px;
  padding-inline: 10px;
  border-radius: var(--radius-small);
  transition:
    background 180ms ease,
    transform 180ms ease;
}

.chapter-row:hover {
  background: var(--surface);
  transform: translateX(3px);
}

.chapter-row:active {
  transform: translateX(3px) scale(0.995);
}

.chapter-number {
  color: var(--accent);
  font-size: 12px;
  font-weight: 700;
}

.chapter-row strong {
  font-size: 14px;
}

.chapter-row small {
  font-size: 10px;
}

.chapter-access {
  min-height: 28px;
  padding: 0 8px;
  border: 1px solid var(--line);
  border-radius: 999px;
  white-space: nowrap;
}

.chapter-access-free {
  border-color: color-mix(in srgb, var(--accent) 38%, var(--line));
  color: var(--accent);
}

.chapter-read {
  min-height: 44px;
  font-size: 11px;
}

.chapter-empty {
  display: grid;
  min-height: 250px;
  place-items: center;
  align-content: center;
  gap: 8px;
  border-bottom: 1px solid var(--line);
  color: var(--muted);
  text-align: center;
}

.chapter-empty strong {
  color: var(--text);
  font-size: 15px;
}

.chapter-empty span {
  font-size: 11px;
}

.chapter-empty button {
  min-height: 40px;
  margin-top: 7px;
  padding-inline: 14px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface);
  cursor: pointer;
}

.series-comments {
  padding-top: clamp(52px, 6vw, 78px);
  border-top: 1px solid var(--line);
}

.comments-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 24px;
}

.comments-header h2 {
  margin: 0;
  font-size: clamp(34px, 4vw, 50px);
  line-height: 1;
  letter-spacing: -0.05em;
}

.comments-header > div:first-child > span {
  display: block;
  margin-top: 9px;
  color: var(--muted);
  font-size: 11px;
}

.comment-sort {
  display: flex;
  padding: 3px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface);
}

.comment-sort button {
  min-width: 72px;
  min-height: 38px;
  border-radius: calc(var(--radius-small) - 3px);
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  font-size: 11px;
  font-weight: 650;
}

.comment-sort button[aria-pressed="true"] {
  background: var(--surface-3);
  color: var(--text);
}

.comment-composer,
.comment-signin,
.comment-error,
.comment-empty {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
}

.comment-composer {
  padding: 18px;
}

.comment-composer-heading {
  display: flex;
  align-items: center;
  gap: 11px;
  margin-bottom: 14px;
}

.comment-composer-heading > div:last-child {
  display: grid;
  gap: 3px;
}

.comment-composer-heading strong {
  font-size: 12px;
}

.comment-composer-heading span {
  color: var(--muted);
  font-size: 9px;
}

.comment-avatar {
  display: grid;
  width: 40px;
  height: 40px;
  flex: 0 0 auto;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--accent) 40%, var(--line));
  border-radius: calc(var(--radius-small) + 1px);
  background: color-mix(in srgb, var(--accent) 10%, var(--surface-2));
  color: var(--accent);
  font-size: 10px;
  font-weight: 800;
}

.replying-to {
  display: flex;
  min-height: 36px;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 8px;
  padding: 0 10px;
  border-radius: var(--radius-small);
  background: color-mix(in srgb, var(--accent) 8%, var(--surface-2));
  color: var(--text-soft);
  font-size: 10px;
}

.replying-to button {
  padding: 0;
  background: transparent;
  color: var(--accent);
  cursor: pointer;
  font-size: 10px;
}

.comment-field {
  display: block;
}

.comment-field textarea {
  width: 100%;
  min-height: 122px;
  resize: vertical;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  outline: 0;
  background: var(--surface-2);
  color: var(--text);
  font-size: 13px;
  line-height: 1.6;
}

.comment-field textarea:focus {
  border-color: var(--accent);
}

.comment-composer-actions {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-top: 11px;
}

.comment-composer-actions > label {
  display: flex;
  min-height: 40px;
  align-items: center;
  gap: 8px;
  color: var(--text-soft);
  cursor: pointer;
  font-size: 10px;
}

.comment-composer-actions input {
  accent-color: var(--accent);
}

.comment-composer-actions > span {
  margin-left: auto;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
  font-size: 9px;
}

.comment-composer-actions .button {
  min-height: 42px;
}

.comment-composer-actions .button:disabled {
  cursor: not-allowed;
  opacity: 0.42;
}

.comment-list {
  display: grid;
  gap: 12px;
  margin-top: 18px;
}

.comment-item {
  display: grid;
  grid-template-columns: 40px minmax(0, 1fr);
  gap: 13px;
  padding: 17px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
}

.comment-content {
  min-width: 0;
}

.comment-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.comment-meta > div {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 7px;
}

.comment-meta strong {
  overflow: hidden;
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.comment-meta time {
  flex: 0 0 auto;
  color: var(--muted);
  font-size: 9px;
}

.comment-role {
  padding: 3px 5px;
  border: 1px solid var(--line);
  border-radius: 4px;
  color: var(--muted);
  font-size: 8px;
}

.comment-role-administrator,
.comment-role-team_leader {
  border-color: color-mix(in srgb, var(--accent) 42%, var(--line));
  color: var(--accent);
}

.comment-body,
.comment-removed {
  margin: 12px 0 0;
  overflow-wrap: anywhere;
  color: var(--text-soft);
  font-size: 12px;
  line-height: 1.7;
  white-space: pre-wrap;
}

.comment-removed {
  color: var(--muted);
  font-style: italic;
}

.spoiler-cover {
  display: flex;
  width: 100%;
  min-height: 48px;
  align-items: center;
  gap: 8px;
  margin-top: 11px;
  padding: 0 12px;
  border: 1px dashed var(--line-strong);
  border-radius: var(--radius-small);
  background:
    repeating-linear-gradient(
      135deg,
      var(--surface-2) 0 8px,
      var(--surface-3) 8px 16px
    );
  color: var(--text-soft);
  cursor: pointer;
  font-size: 10px;
  text-align: left;
}

.comment-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 3px;
  margin-top: 10px;
}

.comment-actions button,
.comment-actions > span,
.show-replies {
  display: inline-flex;
  min-height: 36px;
  align-items: center;
  gap: 5px;
  padding: 0 8px;
  border-radius: var(--radius-small);
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  font-size: 9px;
}

.comment-actions button:hover,
.comment-actions button[aria-pressed="true"] {
  background: var(--surface-2);
  color: var(--text);
}

.comment-actions button[aria-pressed="true"] svg {
  color: var(--accent);
}

.comment-actions .comment-delete {
  color: var(--danger);
}

.comment-inline-action {
  display: flex;
  flex-wrap: wrap;
  align-items: end;
  gap: 7px;
  margin-top: 10px;
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface-2);
}

.comment-inline-action label {
  display: grid;
  flex: 1 1 190px;
  gap: 5px;
}

.comment-inline-action label span {
  color: var(--muted);
  font-size: 8px;
}

.comment-inline-action select,
.comment-inline-action button {
  min-height: 36px;
  border: 1px solid var(--line);
  border-radius: calc(var(--radius-small) - 2px);
  background: var(--surface);
  font-size: 9px;
}

.comment-inline-action select {
  padding: 0 9px;
}

.comment-inline-action button {
  padding: 0 11px;
  cursor: pointer;
}

.comment-remove-confirm > span {
  margin-right: auto;
  color: var(--text-soft);
  font-size: 10px;
}

.comment-remove-confirm button:first-of-type {
  border-color: color-mix(in srgb, var(--danger) 50%, var(--line));
  color: var(--danger);
}

.comment-replies {
  display: grid;
  gap: 8px;
  margin: 13px 0 0 8px;
  padding-left: 14px;
  border-left: 1px solid var(--line);
}

.comment-item-reply {
  grid-template-columns: 32px minmax(0, 1fr);
  padding: 12px;
  border: 0;
  border-radius: var(--radius-small);
  background: var(--surface-2);
}

.comment-item-reply .comment-avatar {
  width: 32px;
  height: 32px;
}

.show-replies {
  margin-top: 8px;
  color: var(--accent);
}

.comment-signin,
.comment-error {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 13px;
  min-height: 92px;
  padding: 17px;
}

.comment-signin > svg,
.comment-error > svg {
  color: var(--accent);
}

.comment-signin > div,
.comment-error > div {
  display: grid;
  gap: 4px;
}

.comment-signin strong,
.comment-error strong {
  font-size: 11px;
}

.comment-signin span,
.comment-error span {
  color: var(--muted);
  font-size: 9px;
}

.comment-error > button {
  min-height: 38px;
  padding: 0 11px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface-2);
  cursor: pointer;
  font-size: 10px;
}

.comment-empty {
  display: grid;
  min-height: 220px;
  place-items: center;
  align-content: center;
  gap: 8px;
  color: var(--muted);
  text-align: center;
}

.comment-empty svg {
  color: var(--accent);
}

.comment-empty strong {
  color: var(--text);
  font-size: 13px;
}

.comment-empty span {
  font-size: 10px;
}

.comment-loading {
  display: grid;
  gap: 9px;
  margin-top: 18px;
}

.comment-loading span {
  height: 84px;
  border-radius: var(--radius);
  background:
    linear-gradient(
      90deg,
      var(--surface) 0 38%,
      var(--surface-2) 50%,
      var(--surface) 62% 100%
    );
  background-size: 220% 100%;
  animation: comment-shimmer 1.25s linear infinite;
}

@keyframes comment-shimmer {
  to {
    background-position: -220% 0;
  }
}

.reader-discussion {
  width: min(980px, calc(100% - 32px));
  margin-inline: auto;
  padding: 18px 0 140px;
  color: var(--text);
}

.reader-discussion .series-comments {
  scroll-margin-top: 86px;
}

.end-chapter .end-chapter-discuss {
  border-color: #343b34;
  background: #1a1e1a;
  color: #edf0e9;
}

@media (max-width: 1180px) {
  .series-details {
    grid-template-columns: minmax(0, 1.1fr) minmax(300px, 0.9fr);
  }

  .series-team-card {
    grid-column: 1 / -1;
    max-width: 390px;
  }
}

@media (max-width: 900px) {
  .title-hero-inner {
    grid-template-columns: minmax(150px, 190px) minmax(0, 1fr);
    gap: clamp(24px, 4vw, 36px);
    min-height: auto;
    padding-block: 48px;
  }

  .title-copy h1 {
    font-size: clamp(42px, 8vw, 68px);
  }

  .series-details {
    grid-template-columns: minmax(0, 1fr) minmax(290px, 0.9fr);
  }

  .series-team-card {
    max-width: none;
  }

  .title-content {
    grid-template-columns: 1fr;
  }

  .title-sidebar {
    position: static;
    grid-template-columns: 1fr;
  }

  .title-sidebar > section {
    display: grid;
    grid-template-columns: minmax(0, 1fr) minmax(250px, 0.7fr);
    align-items: end;
    gap: 20px;
  }

  .title-sidebar > section > :not(.chapter-quick-links) {
    grid-column: 1;
  }

  .chapter-quick-links {
    grid-column: 2;
    grid-row: 1 / span 4;
    margin-top: 0;
  }
}

@media (max-width: 700px) {
  .series-jump {
    top: 62px;
    width: 100%;
    padding-inline: 14px;
  }

  .series-jump a {
    min-height: 44px;
  }

  .title-backdrop {
    inset: -10%;
    filter: blur(28px) saturate(0.72);
    opacity: 0.28;
  }

  .title-hero-inner {
    grid-template-columns: minmax(124px, 32vw) minmax(0, 1fr);
    align-items: start;
    gap: 19px;
    padding-block: 38px 44px;
  }

  .title-cover {
    position: static;
  }

  .title-copy h1 {
    margin-top: 14px;
    font-size: clamp(34px, 9vw, 52px);
    line-height: 0.98;
    letter-spacing: -0.05em;
  }

  .title-subtitle {
    font-size: 14px;
  }

  .title-kicker {
    font-size: 10px;
  }

  .title-stats {
    gap: 9px;
    margin-top: 15px;
  }

  .title-synopsis,
  .title-copy > .tag-row {
    display: none;
  }

  .title-actions {
    margin-top: 19px;
  }

  .series-details {
    grid-template-columns: 1fr;
    gap: 34px;
    padding-top: 58px;
    padding-bottom: 62px;
  }

  .series-facts {
    grid-template-columns: repeat(3, 1fr);
    gap: 0 15px;
  }

  .series-team-card {
    max-width: 430px;
  }

  .title-content {
    gap: 56px;
    padding-top: 50px;
  }

  .title-sidebar > section {
    grid-template-columns: 1fr;
  }

  .title-sidebar > section > :not(.chapter-quick-links) {
    grid-column: auto;
  }

  .chapter-quick-links {
    grid-column: auto;
    grid-row: auto;
    margin-top: 18px;
  }

  .chapter-heading {
    align-items: stretch;
    gap: 20px;
  }

  .chapter-tools {
    grid-template-columns: minmax(0, 1fr) 112px;
  }

  .chapter-row {
    grid-template-columns: 42px minmax(0, 1fr) 34px;
    gap: 9px;
    min-height: 94px;
    padding-block: 10px;
  }

  .chapter-row > span:nth-child(2) {
    align-self: end;
  }

  .chapter-access {
    display: inline-flex;
    grid-column: 2;
    grid-row: 2;
    width: max-content;
    max-width: 100%;
    min-height: 25px;
    overflow: hidden;
    font-size: 9px;
    text-overflow: ellipsis;
  }

  .chapter-read {
    display: flex;
    grid-column: 3;
    grid-row: 1 / span 2;
    align-self: center;
    justify-content: center;
    font-size: 0;
  }

  .chapter-read svg {
    width: 18px;
    height: 18px;
  }

  .comments-header {
    align-items: stretch;
    flex-direction: column;
  }

  .comment-sort {
    width: max-content;
  }

  .comment-composer-actions {
    align-items: stretch;
    flex-wrap: wrap;
  }

  .comment-composer-actions > span {
    margin-left: auto;
  }

  .comment-composer-actions .button {
    width: 100%;
  }

  .comment-item {
    grid-template-columns: 34px minmax(0, 1fr);
    gap: 10px;
    padding: 14px;
  }

  .comment-avatar {
    width: 34px;
    height: 34px;
  }

  .comment-replies {
    margin-left: 0;
    padding-left: 9px;
  }

  .comment-item-reply {
    grid-template-columns: 28px minmax(0, 1fr);
    padding: 10px;
  }

  .comment-item-reply .comment-avatar {
    width: 28px;
    height: 28px;
  }

  .comment-signin,
  .comment-error {
    grid-template-columns: auto minmax(0, 1fr);
  }

  .comment-signin .button,
  .comment-error > button {
    grid-column: 1 / -1;
    width: 100%;
  }

  .reader-discussion {
    width: calc(100% - 28px);
    padding-bottom: 120px;
  }
}

@media (max-width: 430px) {
  .title-hero-inner {
    grid-template-columns: 1fr;
  }

  .title-cover {
    width: min(45vw, 172px);
  }

  .title-copy h1 {
    font-size: clamp(38px, 12vw, 52px);
    letter-spacing: -0.045em;
  }

  .title-actions {
    display: grid;
    grid-template-columns: 1fr 1fr auto;
    width: 100%;
  }

  .title-actions .button-primary {
    grid-column: 1 / -1;
    width: 100%;
  }

  .series-details-copy h2 {
    font-size: 38px;
  }

  .series-facts {
    grid-template-columns: 1fr 1fr;
  }

  .chapter-tools {
    grid-template-columns: 1fr;
  }

  .chapter-sort {
    width: 100%;
  }

  .chapter-row {
    grid-template-columns: 38px minmax(0, 1fr) 30px;
  }

  .comment-meta {
    align-items: flex-start;
    flex-direction: column;
    gap: 5px;
  }

  .comment-inline-action {
    align-items: stretch;
    flex-direction: column;
  }

  .comment-inline-action label {
    flex-basis: auto;
  }

  .end-chapter > div {
    width: 100%;
    flex-direction: column;
  }

  .end-chapter button,
  .end-chapter a {
    justify-content: center;
  }
}

@media (prefers-reduced-motion: no-preference) {
  .hero-copy > * {
    animation: hero-enter 680ms cubic-bezier(0.16, 1, 0.3, 1) both;
  }

  .hero-copy > *:nth-child(2) {
    animation-delay: 70ms;
  }

  .hero-copy > *:nth-child(3) {
    animation-delay: 130ms;
  }

  .hero-copy > *:nth-child(4) {
    animation-delay: 190ms;
  }

  @keyframes hero-enter {
    from {
      opacity: 0;
      transform: translateY(18px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* Public discovery sections */
.public-discovery-loading,
.public-discovery-error,
.public-discovery-empty {
  min-height: 10rem;
  display: grid;
  place-content: center;
  gap: 0.45rem;
  text-align: center;
  border: 1px solid var(--line);
  border-radius: 1rem;
  color: var(--muted);
  background: color-mix(in srgb, var(--surface) 88%, transparent);
}

.public-discovery-error strong,
.public-discovery-empty strong {
  color: var(--text);
}

.new-series-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1.1rem;
}

.new-series-card {
  min-width: 0;
  color: inherit;
  text-decoration: none;
}

.new-series-cover {
  position: relative;
  display: block;
  overflow: hidden;
  aspect-ratio: 2 / 3;
  border-radius: 0.9rem;
  background: var(--surface);
}

.new-series-cover img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
  transition: transform 180ms ease;
}

.new-series-cover-placeholder {
  width: 100%;
  height: 100%;
  display: grid;
  place-content: center;
  justify-items: center;
  gap: 0.45rem;
  color: var(--muted);
}

.new-series-cover-placeholder em {
  font-size: 0.78rem;
  font-style: normal;
}

.new-series-card:hover .new-series-cover img {
  transform: scale(1.025);
}

.new-series-cover > small {
  position: absolute;
  top: 0.75rem;
  left: 0.75rem;
  padding: 0.3rem 0.55rem;
  border-radius: 999px;
  color: #fff;
  background: var(--accent);
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.new-series-copy {
  display: grid;
  gap: 0.25rem;
  padding: 0.75rem 0.1rem 0;
}

.new-series-copy strong,
.new-series-copy span,
.new-series-copy small,
.new-series-copy em {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.new-series-copy span,
.new-series-copy small,
.new-series-copy em {
  color: var(--muted);
  font-size: 0.84rem;
  font-style: normal;
}

.teams-heading > div:last-child {
  flex-shrink: 0;
}

.teams-carousel-controls {
  display: flex;
  gap: 0.45rem;
}

.teams-carousel-controls button {
  width: 2.75rem;
  height: 2.75rem;
  display: grid;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--text);
  background: var(--surface);
}

.teams-carousel {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: minmax(20rem, 35%);
  gap: 1rem;
  overflow-x: auto;
  overscroll-behavior-inline: contain;
  scroll-snap-type: inline mandatory;
  scrollbar-width: thin;
  padding: 0.15rem 0 0.8rem;
}

.teams-carousel.is-single {
  grid-auto-columns: minmax(20rem, 36rem);
}

.team-carousel-card {
  position: relative;
  overflow: hidden;
  scroll-snap-align: start;
  min-height: 20rem;
  border: 1px solid var(--line);
  border-radius: 1.15rem;
  background: var(--surface);
}

.team-carousel-banner {
  display: block;
  height: 8rem;
  overflow: hidden;
  background: linear-gradient(135deg, var(--surface-strong), var(--surface));
}

.team-carousel-banner img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
}

.team-carousel-logo {
  position: absolute;
  top: 5.6rem;
  left: 1.25rem;
  width: 4.8rem;
  height: 4.8rem;
  padding: 0.2rem;
  overflow: hidden;
  border: 3px solid var(--surface);
  border-radius: 1.1rem;
  background: var(--surface-strong);
}

.team-carousel-logo img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: contain;
}

.team-carousel-logo > span {
  width: 100%;
  height: 100%;
  display: grid;
  place-items: center;
  color: var(--accent);
  font-weight: 850;
}

.team-carousel-card > div {
  display: grid;
  gap: 0.65rem;
  padding: 3rem 1.25rem 1.25rem;
}

.team-carousel-card h3,
.team-carousel-card p {
  margin: 0;
}

.team-carousel-card p {
  min-height: 3rem;
  color: var(--muted);
  line-height: 1.5;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  overflow: hidden;
}

.team-public-metrics {
  display: flex;
  flex-wrap: wrap;
  gap: 0.8rem;
  color: var(--muted);
}

.team-public-metrics small,
.team-carousel-card a {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
}

.team-carousel-card a {
  width: fit-content;
  color: var(--accent);
  font-weight: 750;
}

@media (max-width: 900px) {
  .new-series-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .teams-carousel {
    grid-auto-columns: minmax(18rem, 72%);
  }
}

@media (max-width: 560px) {
  .new-series-grid {
    gap: 0.8rem;
  }

  .teams-carousel {
    grid-auto-columns: 88%;
  }

  .team-carousel-card {
    min-height: 19rem;
  }
}

/* Library view modes */
.library-workspace {
  display: grid;
  gap: 1.25rem;
  margin-top: 1.5rem;
}

.library-workspace-head,
.library-workspace-controls {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
}

.library-workspace-head h2,
.library-workspace-head p {
  margin: 0;
}

.library-workspace-controls {
  align-items: center;
  justify-content: flex-start;
  padding: 0.9rem;
  border: 1px solid var(--line);
  border-radius: 1rem;
  background: var(--surface);
}

.library-workspace-controls label {
  display: grid;
  gap: 0.3rem;
  min-width: 10rem;
  color: var(--muted);
  font-size: 0.8rem;
}

.library-workspace-controls select {
  min-height: 2.65rem;
  border: 1px solid var(--line);
  border-radius: 0.7rem;
  color: var(--text);
  background: var(--surface-strong);
  padding: 0 0.75rem;
}

.library-view-switcher {
  display: flex;
  gap: 0.25rem;
  margin-left: auto;
  padding: 0.2rem;
  border: 1px solid var(--line);
  border-radius: 0.75rem;
}

.library-view-switcher button {
  width: 2.5rem;
  height: 2.5rem;
  display: grid;
  place-items: center;
  border: 0;
  border-radius: 0.55rem;
  color: var(--muted);
  background: transparent;
}

.library-view-switcher button[aria-pressed="true"] {
  color: var(--theme-button-accent-alternate);
  background: var(--accent);
}

.library-workspace-state {
  min-height: 12rem;
  display: grid;
  place-content: center;
  justify-items: center;
  gap: 0.55rem;
  text-align: center;
  border: 1px dashed var(--line);
  border-radius: 1rem;
  color: var(--muted);
}

.library-workspace-state strong {
  color: var(--text);
}

.library-workspace-state button,
.library-workspace-state a {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  color: var(--accent);
  font-weight: 750;
}

.library-records {
  display: grid;
  gap: 1rem;
}

.library-records.is-cover {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.library-records.is-compact {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.library-record {
  position: relative;
  min-width: 0;
}

.is-cover .library-record-cover {
  display: block;
  overflow: hidden;
  aspect-ratio: 2 / 3;
  border-radius: 0.9rem;
  background: var(--surface);
}

.library-record-cover img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
}

.library-cover-placeholder {
  width: 100%;
  height: 100%;
  display: grid;
  place-items: center;
  color: var(--accent);
  background: var(--surface-strong);
  font-weight: 850;
}

.library-record-copy {
  min-width: 0;
  display: grid;
  gap: 0.3rem;
}

.is-cover .library-record-copy {
  padding: 0.75rem 0.1rem 0;
}

.library-record-copy h3,
.library-record-copy p {
  margin: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.library-record-copy p,
.library-record-copy span {
  color: var(--muted);
  font-size: 0.82rem;
}

.library-record-progress {
  height: 0.3rem;
  overflow: hidden;
  border-radius: 999px;
  background: var(--theme-progress-track);
}

.library-record-progress i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--theme-progress-fill);
}

.library-record-status {
  display: inline-flex;
  width: fit-content;
  margin-top: 0.55rem;
  padding: 0.25rem 0.5rem;
  border-radius: 999px;
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 12%, transparent);
  font-size: 0.75rem;
  font-weight: 750;
}

.is-compact .library-record {
  display: grid;
  grid-template-columns: 4.5rem minmax(0, 1fr);
  gap: 0.8rem;
  padding: 0.75rem;
  border: 1px solid var(--line);
  border-radius: 0.9rem;
  background: var(--surface);
}

.is-compact .library-record-cover {
  overflow: hidden;
  aspect-ratio: 2 / 3;
  border-radius: 0.55rem;
}

.is-list .library-record {
  display: grid;
  grid-template-columns: 4rem minmax(10rem, 1.5fr) minmax(8rem, 0.5fr);
  align-items: center;
  gap: 1rem;
  padding: 0.75rem;
  border: 1px solid var(--line);
  border-radius: 0.9rem;
  background: var(--surface);
}

.is-list .library-record-cover {
  overflow: hidden;
  aspect-ratio: 2 / 3;
  border-radius: 0.5rem;
}

.is-list .library-record-status {
  justify-self: end;
  margin: 0;
}

@media (max-width: 900px) {
  .library-records.is-cover,
  .library-records.is-compact {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .library-workspace-head,
  .library-workspace-controls {
    align-items: stretch;
    flex-wrap: wrap;
  }
}

@media (max-width: 620px) {
  .library-workspace-head {
    display: grid;
  }

  .library-workspace-head .button {
    justify-content: center;
  }

  .library-workspace-controls label {
    flex: 1 1 9rem;
  }

  .library-view-switcher {
    width: 100%;
    margin: 0;
  }

  .library-view-switcher button {
    flex: 1;
  }

  .library-records.is-compact {
    grid-template-columns: 1fr;
  }

  .is-list .library-record {
    grid-template-columns: 4rem minmax(0, 1fr);
  }

  .is-list .library-record-status {
    grid-column: 2;
    justify-self: start;
  }
}

/* Public reader profiles */
.public-profile-state {
  min-height: 60vh;
  display: grid;
  place-content: center;
  justify-items: center;
  gap: 0.65rem;
  text-align: center;
}

.public-profile-page {
  padding-top: 0;
}

.public-profile-hero {
  position: relative;
  border-bottom: 1px solid var(--line);
  background: var(--surface);
}

.public-profile-banner {
  display: block;
  height: clamp(11rem, 28vw, 19rem);
  overflow: hidden;
  background:
    radial-gradient(circle at 20% 20%, color-mix(in srgb, var(--accent) 24%, transparent), transparent 45%),
    linear-gradient(140deg, var(--surface-strong), var(--surface));
}

.public-profile-banner img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
}

.public-profile-identity {
  position: relative;
  display: grid;
  grid-template-columns: 8rem minmax(0, 1fr) auto;
  align-items: end;
  gap: 1.25rem;
  padding-top: 1.25rem;
  padding-bottom: 1.75rem;
}

.public-profile-avatar {
  width: 8rem;
  height: 8rem;
  margin-top: -5rem;
  overflow: hidden;
  border: 4px solid var(--surface);
  border-radius: 1.6rem;
  background: var(--surface-strong);
}

.public-profile-avatar img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
}

.public-profile-avatar > span {
  width: 100%;
  height: 100%;
  display: grid;
  place-items: center;
  color: var(--accent);
  font-size: 1.65rem;
  font-weight: 850;
}

.public-profile-identity h1,
.public-profile-identity p {
  margin: 0;
}

.public-profile-identity > div {
  display: grid;
  gap: 0.4rem;
}

.public-profile-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.9rem;
  color: var(--muted);
}

.public-profile-meta small {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
}

.public-profile-content {
  display: grid;
  gap: 1rem;
  padding-top: 1.5rem;
  padding-bottom: 3rem;
}

.public-profile-panel {
  padding: 1.25rem;
  border: 1px solid var(--line);
  border-radius: 1rem;
  background: var(--surface);
}

.public-profile-panel > h2 {
  margin-top: 0;
}

.public-profile-alert {
  padding: 0.8rem 1rem;
  border: 1px solid color-mix(in srgb, var(--theme-danger) 50%, var(--line));
  border-radius: 0.8rem;
  color: var(--theme-danger);
  background: color-mix(in srgb, var(--theme-danger) 8%, var(--surface));
}

.public-profile-teams,
.public-library-summary {
  display: flex;
  flex-wrap: wrap;
  gap: 0.65rem;
}

.public-profile-teams a {
  padding: 0.45rem 0.7rem;
  border-radius: 999px;
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 12%, transparent);
  font-weight: 750;
}

.public-profile-series-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 0.8rem;
}

.public-profile-series-grid > a {
  position: relative;
  display: grid;
  min-width: 0;
  gap: 0.5rem;
  color: inherit;
}

.public-profile-series-grid img,
.public-profile-series-grid .public-reading-cover-placeholder {
  width: 100%;
  height: auto;
  aspect-ratio: 2 / 3;
  object-fit: cover;
  border-radius: 0.7rem;
}

.public-profile-series-grid strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.public-profile-series-rank {
  position: absolute;
  top: 0.45rem;
  left: 0.45rem;
  z-index: 1;
  padding: 0.25rem 0.45rem;
  border-radius: 999px;
  color: var(--surface);
  background: var(--accent);
  font-size: 0.72rem;
  font-weight: 850;
}

.public-profile-achievements,
.public-profile-comments {
  display: grid;
  gap: 0.65rem;
}

.public-profile-achievements article,
.public-profile-comments article {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: start;
  gap: 0.75rem;
  padding: 0.8rem;
  border: 1px solid var(--line);
  border-radius: 0.8rem;
  background: var(--surface-strong);
}

.public-profile-achievements article > span,
.public-profile-comments article > div {
  display: grid;
  min-width: 0;
  gap: 0.25rem;
}

.public-profile-achievements small,
.public-profile-comments small {
  color: var(--muted);
}

.public-profile-comments article {
  grid-template-columns: auto minmax(0, 1fr);
}

.public-profile-comments :is(a, p) {
  margin: 0;
}

.public-profile-comments a {
  color: var(--accent);
  font-weight: 780;
}

.public-profile-comments p {
  overflow-wrap: anywhere;
  line-height: 1.55;
}

.public-reading-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.75rem;
}

.public-reading-grid > a {
  display: grid;
  grid-template-columns: 3.5rem minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.75rem;
  min-width: 0;
  padding: 0.65rem;
  border: 1px solid var(--line);
  border-radius: 0.8rem;
  color: inherit;
}

.public-reading-grid img {
  width: 3.5rem;
  height: 5.25rem;
  object-fit: cover;
  border-radius: 0.45rem;
}

.public-reading-cover-placeholder {
  width: 3.5rem;
  height: 5.25rem;
  display: grid;
  place-items: center;
  border-radius: 0.45rem;
  color: var(--muted);
  background: var(--surface-strong);
}

.public-reading-grid span {
  min-width: 0;
  display: grid;
  gap: 0.3rem;
}

.public-reading-grid strong,
.public-reading-grid small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.public-reading-grid small {
  color: var(--muted);
}

.public-profile-empty {
  min-height: 8rem;
  display: grid;
  place-content: center;
  justify-items: center;
  gap: 0.4rem;
  color: var(--muted);
  text-align: center;
}

.public-profile-empty strong {
  color: var(--text);
}

.public-library-summary span {
  min-width: 8rem;
  display: grid;
  gap: 0.15rem;
  padding: 0.8rem;
  border: 1px solid var(--line);
  border-radius: 0.8rem;
}

.public-library-summary strong {
  font-size: 1.3rem;
}

.public-library-summary small {
  color: var(--muted);
}

@media (max-width: 760px) {
  .public-profile-identity {
    grid-template-columns: 5.5rem minmax(0, 1fr);
    align-items: start;
  }

  .public-profile-avatar {
    width: 5.5rem;
    height: 5.5rem;
    margin-top: -3rem;
    border-radius: 1.1rem;
  }

  .public-profile-identity > .button {
    grid-column: 1 / -1;
    justify-content: center;
  }

  .public-reading-grid {
    grid-template-columns: 1fr;
  }

  .public-profile-series-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

/* Profile settings */
.profile-settings-state {
  min-height: 14rem;
  display: grid;
  place-content: center;
  justify-items: center;
  gap: 0.55rem;
  text-align: center;
}

.profile-settings-workspace {
  display: grid;
  gap: 1rem;
}

.profile-settings-workspace > header,
.profile-settings-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
}

.profile-settings-workspace h2,
.profile-settings-workspace h3,
.profile-settings-workspace p {
  margin: 0;
}

.profile-settings-workspace > header > div,
.profile-settings-card > div:first-child {
  display: grid;
  gap: 0.35rem;
}

.profile-settings-alert {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.8rem 1rem;
  border: 1px solid color-mix(in srgb, #e25d5d 50%, var(--line));
  border-radius: 0.8rem;
  color: #e25d5d;
  background: color-mix(in srgb, #e25d5d 8%, var(--surface));
}

.profile-settings-card {
  display: grid;
  grid-template-columns: minmax(12rem, 0.35fr) minmax(0, 1fr);
  gap: 1.5rem;
  padding: 1.25rem;
  border: 1px solid var(--line);
  border-radius: 1rem;
  background: var(--surface);
}

.profile-settings-card > div:first-child p {
  color: var(--muted);
  line-height: 1.5;
}

.profile-settings-grid,
.profile-privacy-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.9rem;
}

.profile-settings-grid label,
.profile-privacy-grid > label:not(.profile-privacy-toggle) {
  display: grid;
  align-content: start;
  gap: 0.35rem;
}

.profile-settings-grid input,
.profile-settings-grid textarea,
.profile-settings-grid select,
.profile-privacy-grid select {
  width: 100%;
  min-height: 2.75rem;
  border: 1px solid var(--line);
  border-radius: 0.7rem;
  color: var(--text);
  background: var(--surface-strong);
  padding: 0.65rem 0.75rem;
}

.profile-settings-grid textarea {
  resize: vertical;
}

.profile-settings-grid small,
.profile-privacy-toggle small {
  color: var(--muted);
}

.profile-favorites-editor {
  display: grid;
  gap: 0.8rem;
}

.profile-favorites-editor > label {
  display: grid;
  gap: 0.35rem;
}

.profile-favorites-editor select {
  width: 100%;
  min-height: 2.75rem;
  padding: 0.65rem 0.75rem;
  border: 1px solid var(--line);
  border-radius: 0.7rem;
  color: var(--text);
  background: var(--surface-strong);
}

.profile-favorites-editor ol {
  display: grid;
  gap: 0.45rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.profile-favorites-editor li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.65rem 0.75rem;
  border: 1px solid var(--line);
  border-radius: 0.7rem;
  background: var(--surface-strong);
}

.profile-favorites-editor li > span {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  gap: 0.45rem;
}

.profile-favorites-editor li strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.profile-favorites-editor li button {
  display: grid;
  width: 2rem;
  height: 2rem;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 0.55rem;
  color: var(--text);
  background: transparent;
}

.profile-favorites-editor li button:disabled {
  opacity: 0.35;
}

.profile-settings-wide {
  grid-column: 1 / -1;
}

.profile-privacy-toggle {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: start;
  gap: 0.7rem;
  padding: 0.8rem;
  border: 1px solid var(--line);
  border-radius: 0.8rem;
}

.profile-privacy-toggle input {
  width: 1.1rem;
  height: 1.1rem;
  margin-top: 0.15rem;
}

.profile-privacy-toggle > span {
  display: grid;
  gap: 0.2rem;
}

.profile-media-fields {
  display: grid;
  grid-template-columns: minmax(9rem, 0.42fr) minmax(14rem, 1fr);
  gap: 0.9rem;
}

.profile-media-field {
  display: grid;
  align-content: start;
  gap: 0.6rem;
  min-width: 0;
}

.profile-media-preview {
  display: grid;
  place-items: center;
  overflow: hidden;
  aspect-ratio: 1;
  border: 1px solid var(--line);
  border-radius: 1rem;
  color: var(--muted);
  background: var(--surface-strong);
}

.profile-media-field.is-banner .profile-media-preview {
  aspect-ratio: 16 / 6;
}

.profile-media-preview img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
}

.profile-media-field label {
  display: grid;
  gap: 0.35rem;
}

.profile-media-field input[type="file"] {
  width: 100%;
  color: var(--muted);
}

.profile-media-field button {
  width: fit-content;
  border: 0;
  color: #e25d5d;
  background: transparent;
  font-weight: 750;
}

.profile-settings-actions {
  position: sticky;
  bottom: 0.75rem;
  z-index: 5;
  padding: 0.8rem;
  border: 1px solid var(--line);
  border-radius: 0.9rem;
  background: color-mix(in srgb, var(--surface) 92%, transparent);
  backdrop-filter: blur(14px);
}

.profile-settings-actions > span {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  color: var(--muted);
}

@media (max-width: 820px) {
  .profile-settings-card {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 620px) {
  .profile-settings-workspace > header {
    align-items: stretch;
    flex-direction: column;
  }

  .profile-settings-grid,
  .profile-privacy-grid {
    grid-template-columns: 1fr;
  }

  .profile-settings-actions {
    bottom: 0;
  }

  .profile-media-fields {
    grid-template-columns: 1fr;
  }
}

.chapter-image-page {
  display: block;
  width: 100%;
  aspect-ratio: auto;
  overflow: visible;
  padding: 0;
  background: transparent;
}

.chapter-image-page > img {
  width: 100%;
  height: auto;
  background: #111;
  object-fit: contain;
}

.reader-page-state {
  display: grid;
  min-height: min(70dvh, 720px);
  place-items: center;
  align-content: center;
  gap: 10px;
  padding: 32px;
  color: var(--theme-mid-tone);
  text-align: center;
}

.reader-page-state > svg {
  color: var(--accent);
}

.reader-page-state > span {
  max-width: 520px;
  font-size: 12px;
  line-height: 1.55;
}

.reader-page-state > button {
  min-height: 42px;
  margin-top: 8px;
  padding: 0 14px;
  border: 1px solid var(--theme-accent-l3);
  border-radius: var(--radius-small);
  background: var(--theme-accent);
  color: var(--theme-text-color);
  cursor: pointer;
}


.catalog-cover-placeholder {
  display: grid;
  width: 100%;
  height: 100%;
  place-items: center;
  align-content: center;
  gap: 8px;
  aspect-ratio: var(--cover-ratio);
  background:
    linear-gradient(145deg, color-mix(in srgb, var(--accent) 9%, transparent), transparent 55%),
    var(--surface-2);
  color: var(--muted);
  text-align: center;
}

.catalog-cover-placeholder small {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.series-list-cover {
  display: block;
  width: 68px;
  aspect-ratio: var(--cover-ratio);
  overflow: hidden;
  border-radius: var(--radius-small);
  background: var(--surface-2);
}

.series-list-cover > img,
.series-list-cover > .catalog-cover-placeholder {
  width: 100%;
  height: 100%;
  object-fit: cover;
}









.catalog-loading-grid i {
  aspect-ratio: var(--cover-ratio);
}

.catalog-loading-grid b {
  width: 82%;
  height: 16px;
}

.catalog-loading-grid small {
  width: 55%;
  height: 11px;
}


.catalog-error {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 14px;
  align-items: center;
  min-height: 110px;
  padding: 18px;
  border: 1px solid color-mix(in srgb, var(--danger) 42%, var(--line));
  border-radius: var(--radius);
  background: color-mix(in srgb, var(--danger) 6%, var(--surface));
}

.catalog-error > svg {
  color: var(--danger);
}

.catalog-error > div {
  display: grid;
  gap: 5px;
}

.catalog-error span {
  color: var(--muted);
  font-size: 12px;
}

.catalog-error button {
  min-height: 40px;
  padding: 0 14px;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius-small);
  background: var(--surface-2);
  cursor: pointer;
  font-size: 12px;
  font-weight: 750;
}

.catalog-pagination {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto auto;
  gap: 12px;
  align-items: center;
  margin-top: 38px;
  padding: 15px;
  border-top: 1px solid var(--line);
}

.catalog-pagination > div {
  display: flex;
  gap: 6px;
  justify-content: center;
}

.catalog-pagination button {
  display: inline-flex;
  min-width: 40px;
  min-height: 40px;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface);
  cursor: pointer;
  font-size: 12px;
  font-weight: 720;
}

.catalog-pagination button[aria-current="page"] {
  border-color: var(--accent);
  background: var(--accent);
  color: var(--accent-ink);
}

.catalog-pagination button:disabled {
  cursor: not-allowed;
  opacity: 0.42;
}

.catalog-pagination > label {
  display: grid;
  gap: 4px;
  color: var(--muted);
  font-size: 10px;
}

.catalog-pagination select {
  min-height: 40px;
  padding: 0 28px 0 10px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface);
  color: var(--text);
}

@media (max-width: 1080px) {
  .catalog-loading-grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}

@media (max-width: 760px) {
  .catalog-loading-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 22px 12px;
  }

  .catalog-pagination {
    grid-template-columns: 1fr 1fr;
  }

  .catalog-pagination > div {
    grid-column: 1 / -1;
    grid-row: 1;
    overflow-x: auto;
  }

  .catalog-pagination > label {
    grid-column: 1 / -1;
  }
}

@media (max-width: 480px) {
  .catalog-loading-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .catalog-error {
    grid-template-columns: auto minmax(0, 1fr);
  }

  .catalog-error button {
    grid-column: 1 / -1;
  }
}

@media (prefers-reduced-motion: reduce) {
  .catalog-loading-grid i,
  .catalog-loading-grid b,
  .catalog-loading-grid small,
  .latest-loading-grid :is(i, b, small) {
    animation: none;
  }
}

.commerce-unavailable,
.community-highlight-loading {
  border: 1px solid color-mix(in srgb, var(--accent) 24%, var(--line));
  border-radius: var(--radius);
  background: color-mix(in srgb, var(--surface-2) 92%, var(--accent) 8%);
  color: var(--muted);
  padding: 14px 16px;
}

.commerce-unavailable {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  margin-bottom: 22px;
}

.community-highlights {
  padding-block: clamp(44px, 6vw, 84px);
}

.community-highlight-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.community-highlight-card {
  display: grid;
  grid-template-columns: 66px minmax(0, 1fr);
  min-width: 0;
  gap: 14px;
  align-items: center;
  padding: 12px;
  color: inherit;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
  transition:
    border-color 160ms ease,
    transform 160ms ease,
    background-color 160ms ease;
}

.community-highlight-card:hover,
.community-highlight-card:focus-visible {
  border-color: color-mix(in srgb, var(--accent) 60%, var(--line));
  background: var(--surface-2);
  transform: translateY(-2px);
}

.community-highlight-cover {
  display: grid;
  place-items: center;
  width: 66px;
  aspect-ratio: var(--cover-ratio, 2 / 3);
  overflow: hidden;
  border-radius: calc(var(--radius) - 5px);
  background: var(--surface-2);
  color: var(--muted);
}

.community-highlight-cover img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.community-highlight-copy {
  display: grid;
  min-width: 0;
  gap: 6px;
}

.community-highlight-copy small,
.community-highlight-copy > span {
  color: var(--muted);
  font-size: 11px;
}

.community-highlight-copy strong {
  display: -webkit-box;
  overflow: hidden;
  color: var(--text);
  font-size: 13px;
  line-height: 1.45;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.comment-source-link {
  display: inline-flex;
  gap: 5px;
  align-items: center;
  width: fit-content;
  margin: 5px 0 8px;
  color: var(--accent);
  font-size: 11px;
  font-weight: 700;
}

.comment-pinned {
  display: inline-flex;
  width: fit-content;
  align-items: center;
  gap: 5px;
  margin: 5px 0 8px;
  padding: 5px 8px;
  border: 1px solid color-mix(in srgb, var(--accent) 36%, var(--line));
  border-radius: 999px;
  background: color-mix(in srgb, var(--accent) 9%, var(--surface));
  color: var(--accent);
  font-size: 10px;
  font-weight: 750;
}

@media (max-width: 760px) {
  .community-highlight-grid {
    grid-template-columns: 1fr;
  }

  .community-highlight-card {
    grid-template-columns: 54px minmax(0, 1fr);
  }

  .community-highlight-cover {
    width: 54px;
  }
}

/* Dedicated chapter publishing routes. */
.header-upload-link {
  display: inline-flex;
  min-height: 38px;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 0 12px;
  border: 1px solid color-mix(in srgb, var(--accent) 55%, var(--line));
  border-radius: var(--radius-small);
  background: color-mix(in srgb, var(--accent) 10%, var(--surface));
  color: var(--accent);
  font-size: 13px;
  font-weight: 750;
}

.header-upload-link:hover {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 16%, var(--surface));
}

.upload-mode-hub {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
  margin-top: 22px;
}

.upload-mode-hub > a {
  display: grid;
  min-height: 190px;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: start;
  gap: 16px;
  padding: 24px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
  transition:
    border-color 160ms ease,
    background 160ms ease,
    transform 160ms ease;
}

.upload-mode-hub > a:hover {
  border-color: color-mix(in srgb, var(--accent) 65%, var(--line));
  background: color-mix(in srgb, var(--accent) 5%, var(--surface));
  transform: translateY(-2px);
}

.upload-mode-hub > a > span {
  display: grid;
  width: 50px;
  height: 50px;
  place-items: center;
  border-radius: 14px;
  background: color-mix(in srgb, var(--accent) 12%, var(--surface-2));
  color: var(--accent);
}

.upload-mode-hub small,
.upload-mode-hub strong,
.upload-mode-hub p {
  display: block;
}

.upload-mode-hub small {
  margin-bottom: 7px;
  color: var(--accent);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: .11em;
  text-transform: uppercase;
}

.upload-mode-hub strong {
  font-size: clamp(18px, 2vw, 23px);
}

.upload-mode-hub p {
  margin: 10px 0 0;
  color: var(--text-soft);
  font-size: 14px;
  line-height: 1.55;
}

.upload-mode-hub > a > svg {
  margin-top: 15px;
  color: var(--muted);
}

.upload-hub-notes {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 16px;
}

.upload-hub-notes span {
  display: inline-flex;
  min-height: 40px;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--text-soft);
  font-size: 12px;
}

.upload-hub-notes svg {
  color: var(--accent);
}

@media (max-width: 760px) {
  .upload-mode-hub {
    grid-template-columns: 1fr;
  }

  .upload-mode-hub > a {
    min-height: 0;
    padding: 18px;
  }
}

@media (max-width: 560px) {
  .header-upload-link {
    width: 40px;
    min-height: 40px;
    padding: 0;
  }

  .header-upload-link span {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
  }

  .upload-mode-hub > a {
    grid-template-columns: auto minmax(0, 1fr);
  }

  .upload-mode-hub > a > svg {
    display: none;
  }
}

/* Selectable manga discovery systems and deterministic Trending geometry. */
:root {
  --slider-card-width: 188px;
  --slider-gap: 20px;
}

:root[data-slider-size="compact"] {
  --slider-card-width: 148px;
  --slider-gap: 15px;
}

:root[data-slider-size="large"] {
  --slider-card-width: 232px;
  --slider-gap: 24px;
}

.trending-section {
  overflow: hidden;
}

.trending-heading {
  grid-template-columns: minmax(180px, auto) minmax(0, 1fr) auto;
}

.trending-title .eyebrow {
  margin-bottom: 7px;
}

.trending-periods {
  justify-self: start;
}

.trending-actions {
  display: flex;
  align-items: center;
  gap: 15px;
}

.trending-actions > div {
  display: flex;
  gap: 6px;
}

.trending-actions button {
  display: grid;
  width: 38px;
  min-height: 38px;
  place-items: center;
  padding: 0;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: var(--surface);
  color: var(--text-soft);
  cursor: pointer;
  transition:
    border-color 180ms ease,
    color 180ms ease,
    transform 180ms ease;
}

.trending-actions button:hover {
  border-color: var(--accent);
  color: var(--text);
  transform: translateY(-1px);
}

.trending-actions button:active {
  transform: scale(0.96);
}

.trending-actions > a {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: var(--text-soft);
  font-size: 12px;
  font-weight: 650;
  white-space: nowrap;
}

.trending-rail {
  grid-auto-columns: var(--slider-card-width);
  gap: var(--slider-gap);
  overscroll-behavior-inline: contain;
  scroll-padding-inline: 3px;
}

.trending-rail .ranked-card {
  width: var(--slider-card-width);
  min-width: 0;
}

.trending-rail .series-card-copy {
  min-height: 84px;
}

.trending-rail .cover-link,
.trending-rail .cover-link > img {
  width: 100%;
  aspect-ratio: var(--cover-ratio);
  object-fit: cover;
  object-position: center top;
}

:root[data-slider-style="clean-grid"] .trending-rail {
  display: grid;
  grid-auto-flow: row;
  grid-template-columns: repeat(
    auto-fit,
    minmax(min(100%, var(--slider-card-width)), 1fr)
  );
  overflow: visible;
  padding-bottom: 0;
}

:root[data-slider-style="clean-grid"] .trending-rail .ranked-card {
  width: auto;
}

:root[data-slider-style="clean-grid"] .trending-actions > div {
  display: none;
}

:root[data-slider-style="rank-strip"] .ranked-card {
  padding-left: 21px;
}

:root[data-slider-style="rank-strip"] .ranked-card > span {
  top: auto;
  bottom: 78px;
  left: -3px;
  color: color-mix(in srgb, var(--accent) 84%, var(--text));
  font-size: clamp(29px, 3.4vw, 47px);
  letter-spacing: -0.08em;
  line-height: 0.8;
  text-shadow: 0 8px 28px var(--bg);
}

:root[data-slider-style="spotlight-stack"] .trending-rail {
  display: flex;
  overflow-x: auto;
}

:root[data-slider-style="spotlight-stack"] .trending-rail .ranked-card {
  flex: 0 0 var(--slider-card-width);
}

:root[data-slider-style="spotlight-stack"]
  .trending-rail
  .ranked-card:first-child {
  flex-basis: calc(var(--slider-card-width) * 1.36);
}

:root[data-slider-style="chapter-carousel"] {
  --slider-card-width: clamp(288px, 28vw, 356px);
}

:root[data-slider-style="chapter-carousel"] .trending-rail .series-card {
  display: grid;
  grid-template-columns: clamp(82px, 8vw, 112px) minmax(0, 1fr);
  align-items: center;
  gap: 13px;
  min-height: 184px;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
}

:root[data-slider-style="chapter-carousel"] .trending-rail .cover-link {
  border-radius: var(--radius-small);
  box-shadow: none;
}

:root[data-slider-style="chapter-carousel"] .trending-rail .series-card-copy {
  min-height: 0;
  padding: 0;
}

:root[data-slider-style="chapter-carousel"] .trending-rail .series-card h3 {
  white-space: normal;
}

:root[data-slider-style="chapter-carousel"] .trending-rail .quick-read,
:root[data-slider-style="chapter-carousel"]
  .trending-rail
  .cover-link
  > .access-badge {
  display: none;
}

/* Five original layout templates inspired by familiar manga discovery patterns. */
:root[data-site-template="webtoon-spotlight"] {
  --page: min(1320px, calc(100vw - 72px));
}

:root[data-site-template="webtoon-spotlight"] .hero-section {
  min-height: min(790px, 82dvh);
  width: min(1540px, calc(100vw - 36px));
  margin: 18px auto 0;
  overflow: hidden;
  border-radius: calc(var(--radius) * 1.8);
}

:root[data-site-template="webtoon-spotlight"] .hero-copy h1 {
  max-width: 760px;
  font-size: clamp(58px, 6.5vw, 100px);
}

:root[data-site-template="webtoon-spotlight"] .content-section {
  padding-top: 124px;
  padding-bottom: 136px;
}

:root[data-site-template="scan-directory"] {
  --page: min(1500px, calc(100vw - 44px));
  --radius-small: min(var(--radius), 6px);
}

:root[data-site-template="scan-directory"] .hero-section {
  min-height: 510px;
}

:root[data-site-template="scan-directory"] .hero-copy h1 {
  max-width: 610px;
  font-size: clamp(46px, 5vw, 72px);
}

:root[data-site-template="scan-directory"] .content-section,
:root[data-site-template="scan-directory"] .updates-section {
  padding-top: 70px;
  padding-bottom: 70px;
}

:root[data-site-template="scan-directory"] .series-card-copy {
  padding-top: 9px;
}

:root[data-site-template="scan-directory"] .series-card-copy > p {
  display: none;
}

:root[data-site-template="scan-directory"] .latest-grid {
  gap: 10px 12px;
}

:root[data-site-template="scan-directory"] .latest-card {
  grid-template-columns: 96px minmax(0, 1fr);
  gap: 12px;
  padding: 10px;
  border-radius: var(--radius-small);
  box-shadow: none;
}

:root[data-site-template="cinema-rails"] {
  --page: min(1640px, calc(100vw - 72px));
}

:root[data-site-template="cinema-rails"] .hero-section {
  min-height: min(780px, 80dvh);
}

:root[data-site-template="cinema-rails"] .content-section {
  padding-top: 112px;
  padding-bottom: 112px;
}

:root[data-site-template="cinema-rails"] .section-heading h2,
:root[data-site-template="cinema-rails"] .section-tabs h2 {
  font-size: clamp(38px, 4vw, 62px);
}

:root[data-site-template="cinema-rails"] .cover-link {
  box-shadow: 0 28px 70px color-mix(in srgb, var(--shadow) 82%, transparent);
}

:root[data-site-template="paper-shelf"] {
  --page: min(1280px, calc(100vw - 64px));
}

:root[data-site-template="paper-shelf"] .hero-section {
  min-height: 590px;
  border-bottom: 1px solid var(--line);
}

:root[data-site-template="paper-shelf"] .content-section {
  padding-top: 92px;
  padding-bottom: 92px;
}

:root[data-site-template="paper-shelf"] :is(.cover-link, .latest-card) {
  box-shadow: none;
}

:root[data-site-template="paper-shelf"] .latest-card {
  border-width: 0 0 1px;
  border-radius: 0;
  background: transparent;
}

:root[data-site-template="paper-shelf"] .section-heading,
:root[data-site-template="paper-shelf"] .section-tabs {
  padding-bottom: 16px;
  border-bottom: 1px solid var(--line);
}

.experience-control {
  min-width: 0;
  margin: 0;
  padding: 22px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: color-mix(in srgb, var(--surface-2) 88%, transparent);
}

.experience-control > legend {
  padding: 0 8px;
  color: var(--text);
  font-size: 15px;
  font-weight: 720;
}

.experience-control > p {
  max-width: 72ch;
  margin: 0 0 18px;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.6;
}

.template-option-grid,
.slider-option-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 9px;
}

.template-option-grid > button,
.slider-option-grid > button {
  display: grid;
  min-width: 0;
  align-content: start;
  gap: 9px;
  padding: 11px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface);
  color: var(--text);
  text-align: left;
  cursor: pointer;
  transition:
    border-color 180ms ease,
    background 180ms ease,
    transform 180ms ease;
}

.template-option-grid > button:hover,
.slider-option-grid > button:hover {
  border-color: var(--line-strong);
  transform: translateY(-1px);
}

.template-option-grid > button.is-selected,
.slider-option-grid > button.is-selected {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 8%, var(--surface));
  box-shadow: inset 0 0 0 1px
    color-mix(in srgb, var(--accent) 24%, transparent);
}

.template-option-grid strong,
.slider-option-grid strong {
  font-size: 11px;
}

.template-option-grid small,
.slider-option-grid small {
  color: var(--muted);
  font-size: 9px;
  line-height: 1.45;
}

.template-mini,
.slider-mini {
  display: grid;
  width: 100%;
  aspect-ratio: 16 / 9;
  overflow: hidden;
  gap: 4px;
  padding: 6px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: var(--bg);
}

.template-mini i,
.slider-mini i {
  display: block;
  border-radius: 3px;
  background: var(--surface-3);
}

.template-mini {
  grid-template-columns: 1.7fr repeat(2, 0.65fr);
  grid-template-rows: 1.3fr 0.7fr;
}

.template-mini i:first-child {
  grid-row: 1 / -1;
  background: color-mix(in srgb, var(--accent) 38%, var(--surface-3));
}

.template-mini-2 {
  grid-template-columns: 1fr 1fr;
}

.template-mini-2 i:first-child {
  grid-column: 1 / -1;
  grid-row: auto;
}

.template-mini-3 {
  grid-template-columns: repeat(4, 1fr);
  grid-template-rows: 1fr 1fr;
}

.template-mini-3 i:first-child {
  grid-column: auto;
  grid-row: 1 / -1;
}

.template-mini-4 {
  grid-template-columns: 2fr repeat(3, 0.72fr);
  grid-template-rows: 1fr;
}

.template-mini-4 i:first-child,
.template-mini-5 i:first-child {
  grid-row: auto;
}

.template-mini-5 {
  grid-template-columns: repeat(2, 1fr);
  grid-template-rows: repeat(2, 1fr);
}

.slider-mini {
  grid-auto-flow: column;
  grid-auto-columns: 1fr;
}

.slider-mini i {
  aspect-ratio: 2 / 3;
  background: color-mix(in srgb, var(--accent) 28%, var(--surface-3));
}

.slider-mini-2,
.slider-mini-5 {
  grid-template-columns: repeat(2, 1fr);
  grid-auto-flow: row;
}

.slider-mini-4 {
  grid-template-columns: 1.45fr repeat(3, 0.85fr);
  grid-auto-flow: row;
}

.slider-mini-5 i {
  aspect-ratio: auto;
}

.slider-behavior-controls {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(190px, 0.45fr);
  align-items: end;
  gap: 18px;
  margin-top: 18px;
  padding-top: 18px;
  border-top: 1px solid var(--line);
}

.slider-behavior-controls > div > span,
.slider-behavior-controls > label > span {
  display: block;
  margin-bottom: 8px;
  color: var(--muted);
  font-size: 9px;
  font-weight: 700;
}

.slider-behavior-controls > div > div {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 6px;
}

.slider-behavior-controls > div button {
  display: grid;
  gap: 3px;
  min-height: 54px;
  padding: 8px 10px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface);
  text-align: left;
  cursor: pointer;
}

.slider-behavior-controls > div button[aria-pressed="true"] {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 8%, var(--surface));
}

.slider-behavior-controls > div button strong {
  font-size: 10px;
}

.slider-behavior-controls > div button small {
  color: var(--muted);
  font-size: 8px;
}

.slider-behavior-controls > label:last-child input {
  width: 100%;
  accent-color: var(--accent);
}

@media (max-width: 1160px) {
  .template-option-grid,
  .slider-option-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .slider-behavior-controls {
    grid-template-columns: 1fr 1fr;
  }

  .slider-behavior-controls > label:last-child {
    grid-column: 1 / -1;
  }
}

@media (max-width: 760px) {
  :root {
    --slider-card-width: min(43vw, 182px);
    --slider-gap: 14px;
  }

  :root[data-slider-size="compact"] {
    --slider-card-width: min(35vw, 148px);
  }

  :root[data-slider-size="large"] {
    --slider-card-width: min(56vw, 224px);
  }

  :root[data-slider-style="chapter-carousel"] {
    --slider-card-width: min(82vw, 342px);
  }

  .trending-heading {
    grid-template-columns: 1fr auto;
    gap: 16px;
  }

  .trending-periods {
    grid-column: 1 / -1;
    grid-row: 2;
    width: max-content;
  }

  .trending-actions {
    grid-column: 2;
    grid-row: 1;
  }

  .trending-actions > a {
    display: none;
  }

  :root[data-slider-style="clean-grid"] .trending-rail {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 18px 12px;
  }

  :root[data-site-template="webtoon-spotlight"] .hero-section {
    width: calc(100vw - 20px);
    margin-top: 10px;
    border-radius: calc(var(--radius) * 1.35);
  }

  .template-option-grid,
  .slider-option-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .slider-behavior-controls {
    grid-template-columns: 1fr;
  }

  .slider-behavior-controls > label:last-child {
    grid-column: auto;
  }
}

@media (max-width: 480px) {
  :root[data-slider-style="clean-grid"] .trending-rail {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .trending-periods {
    width: 100%;
  }

  .trending-periods button {
    flex: 1 1 0;
    padding-inline: 8px;
  }

  .template-option-grid,
  .slider-option-grid {
    grid-template-columns: 1fr;
  }

  .experience-control {
    padding: 16px;
  }

  .slider-behavior-controls > div > div {
    grid-template-columns: 1fr;
  }
}

@media (prefers-reduced-transparency: reduce) {
  .site-header,
  .search-backdrop,
  .reader-header,
  .reader-footer,
  .reader-controls {
    backdrop-filter: none;
    -webkit-backdrop-filter: none;
  }
}

/* Enhanced reader discussions and administrator community controls. */
.enhanced-comments {
  width: min(1080px, 100%);
  margin-inline: auto;
  scroll-margin-top: 94px;
}

.enhanced-comments .comments-header {
  align-items: center;
  padding-bottom: 20px;
  border-bottom: 1px solid var(--line);
}

.comments-toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
}

.comments-refresh {
  display: grid;
  width: 44px;
  height: 44px;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface);
  color: var(--muted);
  cursor: pointer;
  transition:
    border-color 180ms ease,
    color 180ms ease,
    transform 180ms ease;
}

.comments-refresh:hover {
  border-color: var(--line-strong);
  color: var(--text);
}

.comments-refresh:active {
  transform: scale(0.96);
}

.enhanced-comments .comment-sort button {
  min-width: 68px;
  min-height: 38px;
}

.enhanced-comments .comment-composer {
  position: relative;
  margin-top: 18px;
  padding: 18px;
  border-color: color-mix(in srgb, var(--accent) 18%, var(--line));
  background:
    radial-gradient(
      circle at 4% 0%,
      color-mix(in srgb, var(--accent) 7%, transparent),
      transparent 36%
    ),
    var(--surface);
  box-shadow:
    0 18px 42px color-mix(in srgb, var(--background) 34%, transparent),
    inset 0 1px 0 color-mix(in srgb, var(--text) 4%, transparent);
}

.enhanced-comments .comment-composer-heading {
  position: relative;
}

.composer-close {
  display: grid;
  width: 36px;
  height: 36px;
  margin-left: auto;
  place-items: center;
  border-radius: var(--radius-small);
  background: transparent;
  color: var(--muted);
  cursor: pointer;
}

.composer-close:hover {
  background: var(--surface-2);
  color: var(--text);
}

.comment-composer-tools {
  display: grid;
  gap: 10px;
  margin-top: 11px;
}

.composer-media-toolbar {
  position: relative;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 5px;
}

.composer-media-toolbar > button,
.emoji-picker-wrap > button,
.comment-gif-picker-wrap > button {
  display: inline-flex;
  min-height: 42px;
  align-items: center;
  gap: 7px;
  padding: 0 11px;
  border: 1px solid transparent;
  border-radius: var(--radius-small);
  background: var(--surface-2);
  color: var(--text-soft);
  cursor: pointer;
  font-size: 10px;
  font-weight: 650;
  transition:
    border-color 180ms ease,
    background 180ms ease,
    color 180ms ease;
}

.composer-media-toolbar > button:hover,
.emoji-picker-wrap > button:hover,
.emoji-picker-wrap > button[aria-expanded="true"],
.comment-gif-picker-wrap > button:hover,
.comment-gif-picker-wrap > button[aria-expanded="true"] {
  border-color: var(--line-strong);
  background: var(--surface-3);
  color: var(--text);
}

.composer-media-toolbar button:disabled {
  cursor: not-allowed;
  opacity: 0.42;
}

.media-uploading {
  display: inline-flex;
  min-height: 42px;
  align-items: center;
  gap: 7px;
  padding: 0 8px;
  color: var(--muted);
  font-size: 10px;
}



.emoji-picker-wrap,
.comment-reaction-picker-wrap {
  position: relative;
}

.emoji-picker {
  position: absolute;
  z-index: 12;
  bottom: calc(100% + 8px);
  left: 0;
  width: min(330px, calc(100vw - 48px));
  padding: 13px;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius);
  background: var(--surface-raised, var(--surface));
  box-shadow: 0 22px 64px color-mix(in srgb, var(--background) 74%, transparent);
}

.emoji-picker > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 8px;
}

.emoji-picker > header strong {
  font-size: 12px;
}

.emoji-picker > header button {
  display: grid;
  width: 32px;
  height: 32px;
  place-items: center;
  border-radius: 7px;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
}

.emoji-picker section {
  display: grid;
  gap: 5px;
  padding-top: 9px;
  border-top: 1px solid var(--line);
}

.emoji-picker section + section {
  margin-top: 9px;
}

.emoji-picker section > span {
  color: var(--muted);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.emoji-picker section > div {
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  gap: 3px;
}

.emoji-picker section button {
  display: grid;
  min-width: 0;
  aspect-ratio: 1;
  place-items: center;
  border-radius: 7px;
  background: transparent;
  cursor: pointer;
  font-size: 20px;
}

.emoji-picker section button:hover,
.emoji-picker section button:focus-visible {
  background: var(--surface-2);
  outline: 1px solid var(--line-strong);
}

.pending-media-tray {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
  margin-top: 10px;
}

.pending-media-tray article {
  position: relative;
  min-width: 0;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface-2);
}

.pending-media-tray img {
  width: 100%;
  aspect-ratio: 16 / 10;
  object-fit: cover;
}

.pending-media-tray article > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  padding: 7px 8px;
}

.pending-media-tray strong,
.pending-media-tray span {
  font-size: 8px;
}

.pending-media-tray span {
  color: var(--muted);
}

.pending-media-tray article > button {
  position: absolute;
  top: 6px;
  right: 6px;
  display: grid;
  width: 30px;
  height: 30px;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--text) 14%, transparent);
  border-radius: 8px;
  background: color-mix(in srgb, var(--background) 78%, transparent);
  color: var(--text);
  cursor: pointer;
  backdrop-filter: blur(8px);
}

.comment-media-error {
  display: flex;
  align-items: center;
  gap: 7px;
  margin: 9px 0 0;
  color: var(--danger);
  font-size: 10px;
}

.enhanced-comments .comment-composer-actions {
  margin-top: 0;
}

.enhanced-comments .comment-list {
  gap: 0;
  margin-top: 20px;
  overflow: visible;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}

.enhanced-comments .comment-item {
  position: relative;
  grid-template-columns: 42px minmax(0, 1fr);
  gap: 14px;
  padding: 22px 2px;
  border: 0;
  border-bottom: 1px solid var(--line);
  border-radius: 0;
  background: transparent;
}

.enhanced-comments .comment-list > .comment-item:last-child {
  border-bottom: 0;
}

.enhanced-comments .comment-meta strong {
  font-size: 12px;
}

.enhanced-comments .comment-meta time,
.enhanced-comments .comment-meta em {
  color: var(--muted);
  font-size: 9px;
  font-style: normal;
}

.enhanced-comments .comment-body,
.enhanced-comments .comment-removed {
  max-width: 76ch;
  margin-top: 10px;
  color: var(--text-soft);
  font-size: 14px;
  line-height: 1.68;
}

.comment-media-grid {
  display: grid;
  max-width: 720px;
  gap: 6px;
  margin-top: 12px;
}

.comment-media-grid.media-count-1 {
  grid-template-columns: minmax(0, 520px);
}

.comment-media-grid:not(.media-count-1) {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.comment-media-grid a {
  position: relative;
  min-width: 0;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface-2);
}

.comment-media-grid img {
  display: block;
  width: 100%;
  max-height: 480px;
  aspect-ratio: 4 / 3;
  object-fit: cover;
  transition: transform 240ms ease;
}

.comment-media-grid.media-count-1 img {
  height: auto;
  max-height: 560px;
  aspect-ratio: auto;
  object-fit: contain;
}

.comment-media-grid a:hover img {
  transform: scale(1.012);
}

.comment-media-grid a > span {
  position: absolute;
  right: 8px;
  bottom: 8px;
  padding: 5px 7px;
  border-radius: 6px;
  background: color-mix(in srgb, var(--background) 82%, transparent);
  color: var(--text);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.08em;
  backdrop-filter: blur(8px);
}

.comment-engagement {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  margin-top: 13px;
}

.comment-votes {
  display: inline-flex;
  min-height: 38px;
  align-items: center;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface);
}

.comment-votes button {
  display: grid;
  width: 38px;
  min-height: 38px;
  place-items: center;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
}

.comment-votes button:hover {
  background: var(--surface-2);
  color: var(--text);
}

.comment-votes button[aria-pressed="true"]:first-child {
  color: var(--accent);
}

.comment-votes button[aria-pressed="true"]:last-child {
  color: var(--danger);
}

.comment-votes strong {
  min-width: 31px;
  color: var(--text-soft);
  font-size: 10px;
  font-variant-numeric: tabular-nums;
  text-align: center;
}

.comment-reaction-summary {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 5px;
}

.comment-reaction-summary > button,
.add-reaction {
  display: inline-flex;
  min-height: 38px;
  align-items: center;
  gap: 5px;
  padding: 0 9px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface);
  color: var(--muted);
  cursor: pointer;
  font-size: 9px;
  font-variant-numeric: tabular-nums;
}

.comment-reaction-summary > button span {
  font-size: 15px;
}

.comment-reaction-summary > button:hover,
.comment-reaction-summary > button[aria-pressed="true"],
.add-reaction:hover,
.add-reaction[aria-expanded="true"] {
  border-color: color-mix(in srgb, var(--accent) 42%, var(--line));
  background: color-mix(in srgb, var(--accent) 7%, var(--surface));
  color: var(--text);
}

.comment-reaction-picker {
  position: absolute;
  z-index: 10;
  bottom: calc(100% + 7px);
  left: 0;
  display: grid;
  width: 210px;
  padding: 7px;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius-small);
  background: var(--surface-raised, var(--surface));
  box-shadow: 0 18px 48px color-mix(in srgb, var(--background) 72%, transparent);
}

.comment-reaction-picker button {
  display: flex;
  min-height: 40px;
  align-items: center;
  gap: 9px;
  padding: 0 9px;
  border-radius: 7px;
  background: transparent;
  color: var(--text-soft);
  cursor: pointer;
  font-size: 10px;
  text-align: left;
}

.comment-reaction-picker button:hover,
.comment-reaction-picker button[aria-pressed="true"] {
  background: var(--surface-2);
  color: var(--text);
}

.comment-reaction-picker button span {
  font-size: 17px;
}

.enhanced-comments .comment-actions {
  margin-top: 5px;
}

.enhanced-comments .comment-actions button,
.enhanced-comments .comment-actions > span,
.enhanced-comments .show-replies {
  min-height: 40px;
  font-size: 10px;
}

.enhanced-comments .comment-replies {
  gap: 0;
  margin: 14px 0 0 clamp(0px, 1.5vw, 12px);
  padding-left: clamp(10px, 2vw, 18px);
  border-left-color: color-mix(in srgb, var(--accent) 24%, var(--line));
}

.enhanced-comments .comment-replies .comment-item {
  grid-template-columns: 34px minmax(0, 1fr);
  gap: 11px;
  padding: 16px 0;
}

.enhanced-comments .comment-replies .comment-avatar {
  width: 34px;
  height: 34px;
}

.comment-composer-inline {
  margin: 12px 0 4px;
  padding: 14px !important;
  box-shadow: none !important;
}

.comment-composer-inline .comment-field textarea {
  min-height: 92px;
}

.comment-edit-form {
  display: grid;
  gap: 8px;
  margin-top: 10px;
}

.comment-edit-form textarea {
  width: 100%;
  min-height: 104px;
  resize: vertical;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  outline: 0;
  background: var(--surface-2);
  color: var(--text);
  font: inherit;
  font-size: 13px;
  line-height: 1.6;
}

.comment-edit-form textarea:focus {
  border-color: var(--accent);
}

.comment-edit-form > div {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 7px;
}

.comment-edit-form label {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-right: auto;
  color: var(--text-soft);
  font-size: 10px;
}

.comment-edit-form button {
  min-height: 38px;
  padding: 0 11px;
  border-radius: var(--radius-small);
  background: var(--surface-2);
  color: var(--text-soft);
  cursor: pointer;
  font-size: 10px;
}

.load-more-comments {
  display: flex;
  width: 100%;
  min-height: 52px;
  align-items: center;
  justify-content: center;
  gap: 9px;
  margin-top: 16px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface);
  color: var(--text);
  cursor: pointer;
  font-size: 11px;
  font-weight: 700;
}

.load-more-comments span {
  color: var(--muted);
  font-size: 9px;
  font-weight: 500;
}

.load-more-comments:hover {
  border-color: var(--line-strong);
  background: var(--surface-2);
}

.discussion-settings-panel {
  display: grid;
  gap: 18px;
}

.discussion-settings-panel > header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 22px;
  padding: 24px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background:
    radial-gradient(
      circle at 5% 0%,
      color-mix(in srgb, var(--accent) 10%, transparent),
      transparent 34%
    ),
    var(--surface);
}

.discussion-settings-panel > header h2 {
  margin: 9px 0 6px;
  font-size: clamp(28px, 3vw, 40px);
  letter-spacing: -0.045em;
}

.discussion-settings-panel > header p {
  max-width: 64ch;
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.7;
}

.discussion-settings-actions {
  display: flex;
  flex: 0 0 auto;
  gap: 7px;
}

.discussion-settings-actions button {
  display: inline-flex;
  min-height: 42px;
  align-items: center;
  gap: 7px;
  padding: 0 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface-2);
  color: var(--text-soft);
  cursor: pointer;
  font-size: 10px;
}

.discussion-settings-actions .button-primary {
  border-color: transparent;
  color: var(--accent-ink, #07100b);
}

.reaction-catalog-editor,
.discussion-policy-grid > article,
.discussion-policy-grid > label {
  border: 1px solid var(--line);
  background: var(--surface);
}

.reaction-catalog-editor {
  padding: 20px;
  border-radius: var(--radius);
}

.discussion-settings-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 14px;
}

.discussion-settings-heading h3,
.discussion-policy-grid h3 {
  margin: 0;
  font-size: 14px;
}

.discussion-settings-heading p,
.discussion-policy-grid p {
  margin: 5px 0 0;
  color: var(--muted);
  font-size: 9px;
  line-height: 1.6;
}

.discussion-settings-heading > button {
  display: inline-flex;
  min-height: 40px;
  align-items: center;
  gap: 6px;
  padding: 0 11px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface-2);
  color: var(--text-soft);
  cursor: pointer;
  font-size: 10px;
}

.reaction-editor-list {
  display: grid;
  gap: 7px;
}

.reaction-editor-list article {
  display: grid;
  grid-template-columns: 86px 92px minmax(160px, 1fr) minmax(100px, auto) auto;
  align-items: end;
  gap: 8px;
  padding: 10px;
  border-radius: var(--radius-small);
  background: var(--surface-2);
}

.reaction-editor-list label {
  display: grid;
  gap: 5px;
}

.reaction-editor-list label > span,
.discussion-policy-grid > label > span {
  color: var(--muted);
  font-size: 8px;
}

.reaction-editor-list input,
.discussion-policy-grid select {
  min-width: 0;
  min-height: 38px;
  padding: 0 9px;
  border: 1px solid var(--line);
  border-radius: 7px;
  background: var(--surface);
  color: var(--text);
  font-size: 10px;
}

.reaction-editor-list .reaction-enabled {
  display: flex;
  min-height: 38px;
  align-items: center;
  gap: 7px;
}

.reaction-editor-list .reaction-enabled input {
  min-height: auto;
  accent-color: var(--accent);
}

.reaction-editor-list .reaction-emoji-field input {
  font-size: 19px;
  text-align: center;
}

.reaction-editor-list code {
  align-self: center;
  overflow: hidden;
  color: var(--muted);
  font-size: 8px;
  text-overflow: ellipsis;
}

.reaction-order-actions {
  display: flex;
  gap: 3px;
}

.reaction-order-actions button {
  display: grid;
  width: 36px;
  height: 38px;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 7px;
  background: var(--surface);
  color: var(--muted);
  cursor: pointer;
}

.reaction-order-actions button:hover {
  color: var(--text);
}

.reaction-order-actions .reaction-remove {
  color: var(--danger);
}

.reaction-live-preview {
  display: grid;
  gap: 8px;
  margin-top: 14px;
  padding-top: 14px;
  border-top: 1px solid var(--line);
}

.reaction-live-preview > span {
  color: var(--muted);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.reaction-live-preview > div {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.reaction-live-preview button {
  display: inline-flex;
  min-height: 40px;
  align-items: center;
  gap: 6px;
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface-2);
  color: var(--text-soft);
  font-size: 9px;
}

.reaction-live-preview button[aria-pressed="true"] {
  border-color: color-mix(in srgb, var(--accent) 42%, var(--line));
  color: var(--text);
}

.reaction-live-preview button span {
  font-size: 16px;
}

.discussion-policy-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.discussion-policy-grid > article,
.discussion-policy-grid > label {
  padding: 18px;
  border-radius: var(--radius);
}

.discussion-policy-grid > article {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.discussion-policy-grid > article svg {
  margin-bottom: 10px;
  color: var(--accent);
}

.discussion-policy-grid > label {
  display: grid;
  gap: 7px;
}

@media (max-width: 900px) {
  .discussion-settings-panel > header,
  .discussion-settings-heading {
    align-items: stretch;
    flex-direction: column;
  }

  .discussion-settings-actions {
    flex-wrap: wrap;
  }

  .reaction-editor-list article {
    grid-template-columns: 86px 92px minmax(160px, 1fr);
  }

  .reaction-editor-list code {
    grid-column: 1 / 3;
  }

  .reaction-order-actions {
    justify-content: flex-end;
  }
}

@media (max-width: 700px) {
  .enhanced-comments .comments-header {
    align-items: stretch;
  }

  .comments-toolbar {
    justify-content: space-between;
  }

  .enhanced-comments .comment-sort {
    width: auto;
    flex: 1;
  }

  .enhanced-comments .comment-sort button {
    min-width: 0;
    flex: 1;
  }

  .enhanced-comments .comment-composer {
    padding: 14px;
  }

  .pending-media-tray {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .enhanced-comments .comment-composer-actions {
    display: grid;
    grid-template-columns: 1fr auto;
    gap: 7px 12px;
  }

  .enhanced-comments .comment-composer-actions > span {
    align-self: center;
    margin: 0;
  }

  .enhanced-comments .comment-composer-actions .button {
    grid-column: 1 / -1;
  }

  .enhanced-comments .comment-item {
    grid-template-columns: 36px minmax(0, 1fr);
    gap: 10px;
    padding: 18px 0;
  }

  .enhanced-comments .comment-avatar {
    width: 36px;
    height: 36px;
  }

  .enhanced-comments .comment-replies {
    margin-left: 0;
    padding-left: 9px;
  }

  .enhanced-comments .comment-replies .comment-item {
    grid-template-columns: 30px minmax(0, 1fr);
    gap: 8px;
  }

  .enhanced-comments .comment-replies .comment-avatar {
    width: 30px;
    height: 30px;
  }

  .comment-media-grid {
    grid-template-columns: 1fr !important;
  }

  .comment-media-grid img {
    max-height: 440px;
  }

  .comment-engagement {
    align-items: flex-start;
    flex-direction: column;
  }

  .comment-reaction-summary {
    width: 100%;
  }

  .comment-edit-form > div {
    align-items: stretch;
    flex-wrap: wrap;
  }

  .comment-edit-form label {
    width: 100%;
  }

  .discussion-policy-grid {
    grid-template-columns: 1fr;
  }

  .reaction-editor-list article {
    grid-template-columns: 82px minmax(0, 1fr);
  }

  .reaction-label-field {
    grid-column: 1 / -1;
  }

  .reaction-editor-list code {
    grid-column: 1 / 2;
  }
}

@media (max-width: 430px) {
  .comments-toolbar {
    align-items: stretch;
  }

  .comments-refresh {
    flex: 0 0 auto;
  }

  .composer-media-toolbar > button,
  .emoji-picker-wrap > button {
    flex: 1 1 auto;
    justify-content: center;
  }

  .emoji-picker {
    position: fixed;
    right: 14px;
    bottom: 18px;
    left: 14px;
    width: auto;
  }

  .enhanced-comments .comment-meta {
    gap: 6px;
  }

  .enhanced-comments .comment-meta > div {
    flex-wrap: wrap;
  }

  .comment-reaction-picker {
    right: 0;
    left: auto;
  }

  .discussion-settings-actions {
    display: grid;
    grid-template-columns: 1fr;
  }

  .discussion-settings-actions button {
    justify-content: center;
  }

  .reaction-editor-list article {
    grid-template-columns: 1fr 1fr;
  }

  .reaction-editor-list code {
    grid-column: 1 / -1;
  }

  .reaction-order-actions {
    grid-column: 1 / -1;
    justify-content: flex-start;
  }
}

/* Unified cover geometry, administrator control room, and reader navigation. */
.cover-link,
.latest-cover,
.title-cover,
.admin-cover-preview,
.admin-series-cover,
.continue-card > img,
.series-list-row > img,
.continue-grid img,
.library-row img,
.ranking-list img,
.search-result img {
  aspect-ratio: var(--cover-ratio);
}

:is(
    .cover-link,
    .latest-cover,
    .admin-cover-preview,
    .admin-series-cover
  )
  > img,
.title-cover,
.continue-card > img,
.series-list-row > img,
.continue-grid img,
.library-row img,
.ranking-list img,
.search-result img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center top;
}

.title-cover {
  align-self: start;
  height: auto;
}

.ops-sidebar {
  grid-template-rows: auto auto minmax(0, 1fr) auto auto;
}

.ops-sidebar nav :is(a, button),
.ops-session-actions a {
  min-height: 42px;
  font-size: 12px;
}

.ops-workspace strong,
.ops-user strong {
  font-size: 12px;
}

.ops-workspace small,
.ops-user small {
  font-size: 10px;
}

.ops-main {
  overflow: hidden;
  padding: clamp(24px, 3vw, 44px) clamp(20px, 3.4vw, 54px) 80px;
}

.ops-header {
  align-items: center;
  margin-bottom: 24px;
}

.ops-header h1 {
  font-size: clamp(30px, 4vw, 50px);
  text-wrap: balance;
}

.ops-header > div:last-child {
  align-items: center;
}

.ops-header > div:last-child .button {
  min-height: 44px;
}

.control-panel,
.discussion-settings-panel {
  display: grid;
  gap: 24px;
  min-width: 0;
  padding: clamp(20px, 2.5vw, 34px);
  border: 1px solid var(--line);
  border-radius: calc(var(--radius) + 4px);
  background:
    radial-gradient(
      circle at 90% -10%,
      color-mix(in srgb, var(--accent) 6%, transparent),
      transparent 30rem
    ),
    var(--surface);
  box-shadow: 0 28px 90px color-mix(in srgb, var(--shadow) 58%, transparent);
}

.control-panel-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 28px;
  padding-bottom: 22px;
  border-bottom: 1px solid var(--line);
}

.control-panel-header h2 {
  margin: 8px 0 9px;
  font-size: clamp(30px, 4.4vw, 56px);
  line-height: 0.98;
  letter-spacing: -0.06em;
  text-wrap: balance;
}

.control-panel-header p {
  max-width: 720px;
  margin: 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.65;
}

.control-panel-actions {
  display: flex;
  flex: 0 0 auto;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

.control-panel-actions > button,
.control-section-heading > button,
.team-records .control-section-heading > button {
  display: inline-flex;
  min-height: 42px;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 0 13px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface-2);
  color: var(--text-soft);
  cursor: pointer;
  font-size: 11px;
  font-weight: 650;
  transition:
    border-color 180ms ease,
    color 180ms ease,
    transform 180ms ease;
}

.control-panel-actions > button:hover,
.control-section-heading > button:hover {
  border-color: var(--accent);
  color: var(--text);
  transform: translateY(-1px);
}

.control-message {
  display: flex;
  min-height: 48px;
  align-items: center;
  gap: 9px;
  margin: 0;
  padding: 10px 13px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface-2);
  color: var(--text-soft);
  font-size: 12px;
  line-height: 1.5;
}

.control-message-success {
  border-color: color-mix(in srgb, var(--accent) 40%, var(--line));
  color: var(--accent);
}

.control-message-error {
  border-color: color-mix(in srgb, var(--danger) 44%, var(--line));
  color: var(--danger);
}

.control-loading {
  display: grid;
  gap: 10px;
}

.control-loading > span {
  height: 78px;
  border-radius: var(--radius);
  background:
    linear-gradient(
      90deg,
      var(--surface-2) 0 40%,
      var(--surface-3) 50%,
      var(--surface-2) 60% 100%
    );
  background-size: 220% 100%;
  animation: comment-shimmer 1.25s linear infinite;
}

.control-empty {
  display: grid;
  min-height: 180px;
  place-items: center;
  align-content: center;
  gap: 8px;
  padding: 28px;
  border: 1px dashed var(--line-strong);
  border-radius: var(--radius);
  color: var(--muted);
  text-align: center;
}

.control-empty strong {
  color: var(--text);
  font-size: 15px;
}

.control-empty span {
  max-width: 480px;
  font-size: 11px;
  line-height: 1.6;
}

.control-metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.control-metrics article,
.analytics-facts article {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  min-height: 142px;
  align-content: space-between;
  gap: 7px;
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface-2);
}

.control-metrics article > svg {
  grid-column: 2;
  grid-row: 1;
  color: var(--accent);
}

.control-metrics article > span,
.analytics-facts article > span {
  color: var(--muted);
  font-size: 10px;
}

.control-metrics article > strong,
.analytics-facts article > strong {
  grid-column: 1 / -1;
  align-self: end;
  font-family: var(--font-geist-mono), monospace;
  font-size: clamp(25px, 3vw, 37px);
  letter-spacing: -0.055em;
}

.control-metrics article > small,
.analytics-facts article > small {
  grid-column: 1 / -1;
  color: var(--text-soft);
  font-size: 10px;
}

.control-overview-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.3fr) minmax(270px, 0.7fr);
  gap: 12px;
}

.control-quick-actions,
.control-health-card,
.control-activity,
.upload-console,
.upload-queue,
.series-create-form,
.series-records,
.team-create-form,
.team-records {
  min-width: 0;
  padding: 20px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: color-mix(in srgb, var(--surface-2) 86%, transparent);
}

.control-quick-actions {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.control-quick-actions > div {
  grid-column: 1 / -1;
  padding-bottom: 9px;
}

.control-quick-actions > div span,
.control-health-card > div:first-child span,
.control-section-heading span {
  color: var(--accent);
  font-size: 10px;
  font-weight: 720;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.control-quick-actions h3,
.control-section-heading h3 {
  margin: 6px 0 0;
  font-size: 18px;
  letter-spacing: -0.035em;
}

.control-quick-actions > button {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  min-height: 60px;
  align-items: center;
  gap: 10px;
  padding: 0 14px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface);
  color: var(--text);
  text-align: left;
  cursor: pointer;
}

.control-quick-actions > button > svg:first-child {
  color: var(--accent);
}

.control-health-card {
  display: grid;
  align-content: start;
}

.control-health-card > div {
  display: flex;
  min-height: 44px;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border-bottom: 1px solid var(--line);
  font-size: 11px;
}

.control-health-card > div:first-child {
  display: grid;
  min-height: 70px;
  align-content: start;
}

.control-health-card > div:first-child strong {
  font-size: 18px;
}

.control-health-card em {
  color: var(--warning);
  font-style: normal;
}

.control-health-card em.is-ok {
  color: var(--accent);
}

.control-section-heading {
  display: flex;
  min-width: 0;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 16px;
}

.control-section-heading > div {
  min-width: 0;
}

.control-activity article {
  display: grid;
  grid-template-columns: 30px minmax(0, 1fr);
  align-items: center;
  gap: 10px;
  min-height: 58px;
  border-top: 1px solid var(--line);
}

.control-activity article > span,
.review-queue-list article > span:first-child,
.audit-list article > span:first-child {
  display: grid;
  width: 28px;
  height: 28px;
  place-items: center;
  border-radius: 50%;
  background: color-mix(in srgb, var(--accent) 12%, var(--surface-3));
  color: var(--accent);
}

.control-activity article > div {
  display: grid;
  gap: 3px;
}

.control-activity small,
.control-table small,
.review-queue-list small,
.audit-list small {
  color: var(--muted);
  font-size: 9px;
}

.upload-control-panel {
  gap: 18px;
}

.upload-console {
  display: grid;
  gap: 18px;
}

.upload-source-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 8px;
}

.upload-source-grid > button {
  display: grid;
  min-height: 132px;
  align-content: start;
  gap: 7px;
  padding: 15px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--muted);
  text-align: left;
  cursor: pointer;
  transition:
    border-color 180ms ease,
    background 180ms ease,
    transform 180ms ease;
}

.upload-source-grid > button:hover,
.upload-source-grid > button.is-selected {
  border-color: color-mix(in srgb, var(--accent) 65%, var(--line));
  background: color-mix(in srgb, var(--accent) 8%, var(--surface));
  color: var(--text);
  transform: translateY(-1px);
}

.upload-source-grid > button.is-selected > svg {
  color: var(--accent);
}

.upload-source-grid strong {
  color: inherit;
  font-size: 12px;
}

.upload-source-grid span {
  color: var(--muted);
  font-size: 10px;
  line-height: 1.45;
}

.upload-details-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.upload-details-grid > label,
.series-form-fields > label,
.team-create-form > label,
.user-admin-list label {
  display: grid;
  gap: 7px;
}

.upload-details-grid label > span,
.series-create-form label > span:first-child,
.team-create-form label > span,
.user-admin-list label > span {
  color: var(--text-soft);
  font-size: 10px;
  font-weight: 650;
}

.upload-details-grid :is(input, select),
.series-create-form :is(input, select, textarea),
.team-create-form :is(input, textarea),
.user-admin-list select,
.control-search {
  min-height: 44px;
  padding: 0 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface);
  color: var(--text);
  outline: none;
}

.upload-details-grid fieldset {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
  margin: 0;
  padding: 5px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
}

.upload-details-grid legend {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
}

.upload-details-grid fieldset button {
  border-radius: calc(var(--radius-small) - 3px);
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  font-size: 10px;
}

.upload-details-grid fieldset button[aria-pressed="true"] {
  background: var(--surface-3);
  color: var(--text);
}

.chapter-dropzone {
  display: grid;
  min-height: 230px;
  place-items: center;
  align-content: center;
  gap: 8px;
  padding: 26px;
  border: 1px dashed var(--line-strong);
  border-radius: var(--radius);
  background:
    radial-gradient(
      circle at center,
      color-mix(in srgb, var(--accent) 7%, transparent),
      transparent 62%
    ),
    var(--surface);
  text-align: center;
  cursor: pointer;
}

.chapter-dropzone > svg {
  color: var(--accent);
}

.chapter-dropzone > span {
  max-width: 580px;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.55;
}

.chapter-dropzone input {
  width: min(420px, 100%);
  margin-top: 8px;
  font-size: 10px;
}

.drive-import-field {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 12px 14px;
  padding: 22px;
  border: 1px dashed var(--line-strong);
  border-radius: var(--radius);
  background: var(--surface);
}

.drive-import-field > svg {
  color: var(--accent);
}

.drive-import-field > span {
  display: grid;
  gap: 4px;
}

.drive-import-field small {
  color: var(--muted);
  font-size: 10px;
}

.drive-import-field input {
  grid-column: 1 / -1;
  min-height: 48px;
  padding: 0 13px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface-2);
}

.selected-upload-files {
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
}

.selected-upload-files > div {
  display: flex;
  min-height: 54px;
  align-items: center;
  gap: 12px;
  padding: 0 14px;
  border-bottom: 1px solid var(--line);
}

.selected-upload-files > div > span {
  margin-left: auto;
  color: var(--muted);
  font-size: 10px;
}

.selected-upload-files > div > button {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  background: transparent;
  color: var(--danger);
  cursor: pointer;
  font-size: 10px;
}

.selected-upload-files ol {
  max-height: 260px;
  overflow: auto;
  margin: 0;
  padding: 0;
  list-style: none;
}

.selected-upload-files li {
  display: grid;
  grid-template-columns: 32px minmax(0, 1fr) auto auto;
  min-height: 42px;
  align-items: center;
  gap: 9px;
  padding: 0 14px;
  border-top: 1px solid var(--line);
  font-size: 10px;
}

.selected-upload-files li > span {
  color: var(--accent);
  font-family: var(--font-geist-mono), monospace;
}

.selected-upload-files li > strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.selected-upload-files li > small,
.selected-upload-files > p {
  color: var(--muted);
  font-size: 9px;
}

.release-metadata-panel {
  display: grid;
  gap: 14px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: color-mix(in srgb, var(--surface-2) 88%, var(--accent) 4%);
}

.release-metadata-grid,
.release-credits > div {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.release-metadata-grid label,
.release-credits label {
  display: grid;
  gap: 7px;
}

.release-metadata-grid label > span,
.release-credits label > span {
  color: var(--text-soft);
  font-size: 10px;
  font-weight: 650;
}

.release-metadata-grid :is(input, textarea),
.release-credits input {
  width: 100%;
  min-height: 44px;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  outline: none;
  background: var(--surface);
  color: var(--text);
}

.release-notes-field {
  grid-column: 1 / -1;
}

.release-notes-field textarea {
  resize: vertical;
}

.release-credits {
  border-top: 1px solid var(--line);
  padding-top: 12px;
}

.release-credits summary {
  width: fit-content;
  margin-bottom: 12px;
  color: var(--accent);
  cursor: pointer;
  font-size: 11px;
  font-weight: 750;
}

.file-order-actions {
  display: inline-flex;
  gap: 4px;
}

.file-order-actions button {
  display: grid;
  width: 30px;
  height: 30px;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 7px;
  background: var(--surface-2);
  color: var(--text);
  cursor: pointer;
}

.file-order-actions button:disabled {
  cursor: not-allowed;
  opacity: 0.35;
}

.review-preview-link {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: var(--accent);
  font-size: 10px;
  font-weight: 720;
}

@media (max-width: 980px) {
  .release-metadata-grid,
  .release-credits > div {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 620px) {
  .release-metadata-grid,
  .release-credits > div {
    grid-template-columns: 1fr;
  }

  .selected-upload-files li {
    grid-template-columns: 28px minmax(0, 1fr) auto;
    padding-block: 7px;
  }

  .selected-upload-files li > small {
    grid-column: 2;
  }

  .file-order-actions {
    grid-column: 3;
    grid-row: 1 / span 2;
  }
}

.selected-upload-files > p {
  margin: 0;
  padding: 10px 14px;
  border-top: 1px solid var(--line);
}

.upload-submit-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
}

.upload-submit-row > div {
  display: flex;
  align-items: center;
  gap: 7px;
  color: var(--muted);
  font-size: 10px;
}

.upload-submit-row > div svg {
  color: var(--accent);
}

.upload-submit-row .button {
  min-height: 46px;
}

.control-table {
  min-width: 740px;
}

.upload-queue {
  overflow-x: auto;
}

.control-table-head,
.control-table article {
  display: grid;
  grid-template-columns: minmax(210px, 1.35fr) minmax(110px, 0.6fr) 85px 120px minmax(
      150px,
      0.8fr
    );
  min-height: 54px;
  align-items: center;
  gap: 11px;
  padding: 0 12px;
  border-top: 1px solid var(--line);
  font-size: 10px;
}

.control-table-head {
  min-height: 34px;
  border-top: 0;
  color: var(--muted);
  font-size: 9px;
}

.control-table article > span:first-child {
  display: grid;
  min-width: 0;
  gap: 3px;
}

.control-table article > span:first-child strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.control-status {
  display: inline-flex;
  width: max-content;
  max-width: 100%;
  min-height: 27px;
  align-items: center;
  padding: 0 8px;
  border-radius: 999px;
  background: var(--surface-3);
  color: var(--text-soft);
  font-size: 9px;
  font-style: normal;
  white-space: nowrap;
}

.status-ready,
.status-verified,
.status-active,
.status-published {
  background: color-mix(in srgb, var(--accent) 12%, var(--surface-3));
  color: var(--accent);
}

.status-failed,
.status-suspended {
  background: color-mix(in srgb, var(--danger) 12%, var(--surface-3));
  color: var(--danger);
}

.status-pending,
.status-pending_import,
.status-uploaded,
.status-draft {
  background: color-mix(in srgb, var(--warning) 11%, var(--surface-3));
  color: var(--warning);
}

.series-manager-grid,
.team-manager-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) minmax(340px, 0.9fr);
  gap: 12px;
  align-items: start;
}

.series-create-form,
.team-create-form {
  display: grid;
  gap: 16px;
}

.series-form-layout {
  display: grid;
  grid-template-columns: 170px minmax(0, 1fr);
  gap: 18px;
  align-items: start;
}

.admin-cover-field {
  display: grid;
  gap: 8px;
}

.admin-cover-preview {
  display: grid;
  width: 100%;
  overflow: hidden;
  place-items: center;
  align-content: center;
  gap: 8px;
  border: 1px dashed var(--line-strong);
  border-radius: var(--radius);
  background: var(--surface);
  color: var(--muted);
}

.admin-cover-preview small {
  max-width: 120px;
  font-size: 9px;
  line-height: 1.4;
  text-align: center;
}

.admin-cover-field > input {
  width: 100%;
  font-size: 9px;
}

.series-form-fields {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.series-create-form textarea,
.team-create-form textarea {
  min-height: 112px;
  padding-block: 11px;
  resize: vertical;
}

.series-synopsis-field {
  grid-column: 1 / -1;
}

.series-create-form > .button,
.team-create-form > .button {
  justify-self: end;
  min-height: 46px;
}

.series-admin-list,
.team-admin-list,
.user-admin-list,
.review-queue-list,
.audit-list {
  display: grid;
}

.series-admin-list article {
  display: grid;
  grid-template-columns: 52px minmax(0, 1fr) auto;
  min-height: 86px;
  align-items: center;
  gap: 12px;
  border-top: 1px solid var(--line);
}

.admin-series-cover {
  display: grid;
  width: 52px;
  overflow: hidden;
  place-items: center;
  border-radius: 7px;
  background: var(--surface);
  color: var(--muted);
}

.series-admin-list article > div,
.team-admin-list article > div,
.user-admin-list article > div {
  display: grid;
  min-width: 0;
  gap: 4px;
}

.series-admin-list small,
.team-admin-list small,
.user-admin-list small {
  color: var(--muted);
  font-size: 9px;
}

.team-create-form {
  position: sticky;
  top: 24px;
}

.team-admin-list article {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr) 130px;
  align-items: start;
  gap: 12px;
  padding: 16px 0;
  border-top: 1px solid var(--line);
}

.team-admin-mark,
.user-admin-avatar {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border-radius: 11px;
  background: color-mix(in srgb, var(--accent) 12%, var(--surface-3));
  color: var(--accent);
  font-size: 11px;
  font-weight: 750;
}

.user-admin-avatar {
  overflow: hidden;
}

.user-admin-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.team-admin-list p {
  overflow: hidden;
  margin: 2px 0 0;
  color: var(--text-soft);
  font-size: 10px;
  line-height: 1.5;
  text-overflow: ellipsis;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

.team-admin-list article > label {
  display: grid;
  justify-items: end;
  gap: 8px;
}

.team-admin-list select {
  width: 130px;
  min-height: 38px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface);
  color: var(--text);
  font-size: 9px;
}

.control-search {
  display: flex;
  width: min(360px, 100%);
  align-items: center;
  gap: 8px;
}

.control-search input {
  width: 100%;
  border: 0;
  outline: 0;
  background: transparent;
}

.user-admin-list article {
  display: grid;
  grid-template-columns: 46px minmax(220px, 1fr) 170px 140px;
  align-items: center;
  gap: 14px;
  min-height: 82px;
  border-top: 1px solid var(--line);
}

.user-admin-list article > div > strong {
  display: flex;
  align-items: center;
  gap: 7px;
}

.user-admin-list article > div > strong em {
  padding: 3px 6px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--accent) 12%, var(--surface-3));
  color: var(--accent);
  font-size: 8px;
  font-style: normal;
}

.user-admin-list article > div > span {
  color: var(--text-soft);
  font-size: 9px;
}

.review-queue-list article {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) minmax(150px, auto);
  align-items: center;
  gap: 12px;
  min-height: 72px;
  border-top: 1px solid var(--line);
}

.review-queue-list article > div {
  display: grid;
  min-width: 0;
  gap: 4px;
}

.review-queue-list article > div:last-child {
  justify-items: end;
}

.analytics-facts {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.analytics-live-facts article:first-child {
  border-color: color-mix(in srgb, var(--accent) 45%, var(--line));
  background:
    radial-gradient(
      circle at 90% 10%,
      color-mix(in srgb, var(--accent) 13%, transparent),
      transparent 54%
    ),
    var(--surface-2);
}

.analytics-updated {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: var(--muted);
  font-size: 9px;
}

.analytics-updated i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--accent);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--accent) 11%, transparent);
}

.analytics-updated i.is-stale {
  background: var(--warning);
  box-shadow: 0 0 0 4px color-mix(in srgb, var(--warning) 11%, transparent);
}

.analytics-range-tabs {
  display: inline-flex;
  justify-self: start;
  gap: 5px;
  padding: 4px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface);
}

.analytics-range-tabs button {
  min-height: 35px;
  padding: 0 14px;
  border-radius: calc(var(--radius-small) - 3px);
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  font-size: 9px;
  font-weight: 750;
}

.analytics-range-tabs button.active {
  background: var(--surface-3);
  color: var(--text);
}

.analytics-chart-card,
.analytics-ranking,
.analytics-live-feed {
  min-width: 0;
  padding: 20px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface-2);
}

.analytics-chart-card {
  overflow: hidden;
}

.analytics-legend {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 12px;
  color: var(--muted);
  font-size: 9px;
}

.analytics-legend span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.analytics-legend i {
  width: 17px;
  height: 2px;
  border-radius: 999px;
}

.analytics-legend .views {
  background: var(--accent);
}

.analytics-legend .starts {
  background: var(--warning);
}

.analytics-line-chart {
  display: block;
  width: 100%;
  min-height: 230px;
  overflow: visible;
}

.analytics-line-chart line {
  stroke: var(--line);
  stroke-width: 1;
  vector-effect: non-scaling-stroke;
}

.analytics-line-chart text {
  fill: var(--muted);
  font-family: var(--font-geist-mono), monospace;
  font-size: 8px;
  text-anchor: end;
}

.analytics-line-chart .axis-label {
  text-anchor: middle;
}

.analytics-line-chart polyline {
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 3;
  vector-effect: non-scaling-stroke;
}

.analytics-line-chart .views-line {
  stroke: var(--accent);
}

.analytics-line-chart .starts-line {
  stroke: var(--warning);
}

.analytics-detail-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.15fr) minmax(310px, 0.85fr);
  gap: 12px;
}

.analytics-ranking,
.analytics-live-feed {
  display: grid;
  align-content: start;
  gap: 0;
}

.analytics-ranking article {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr) auto;
  min-height: 66px;
  align-items: center;
  gap: 11px;
  border-top: 1px solid var(--line);
}

.analytics-ranking article > b {
  color: var(--muted);
  font-family: var(--font-geist-mono), monospace;
  font-size: 9px;
}

.analytics-ranking article > div,
.analytics-ranking article > div > span {
  display: grid;
  min-width: 0;
  gap: 5px;
}

.analytics-ranking article strong,
.analytics-ranking article small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.analytics-ranking article strong {
  font-size: 11px;
}

.analytics-ranking article small {
  color: var(--muted);
  font-size: 8px;
}

.analytics-ranking article > div > i {
  display: block;
  height: 3px;
  overflow: hidden;
  border-radius: 999px;
  background: var(--surface-3);
}

.analytics-ranking article > div > i > span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--accent);
}

.analytics-ranking article > em {
  color: var(--text-soft);
  font-family: var(--font-geist-mono), monospace;
  font-size: 9px;
  font-style: normal;
}

.analytics-live-feed article {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr) auto;
  min-height: 66px;
  align-items: center;
  gap: 10px;
  border-top: 1px solid var(--line);
}

.analytics-live-feed article > span {
  display: grid;
  width: 27px;
  height: 27px;
  place-items: center;
  border-radius: 50%;
  background: color-mix(in srgb, var(--accent) 11%, var(--surface-3));
  color: var(--accent);
}

.analytics-live-feed article > div {
  display: grid;
  min-width: 0;
  gap: 4px;
}

.analytics-live-feed article strong,
.analytics-live-feed article small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.analytics-live-feed article strong {
  font-size: 10px;
}

.analytics-live-feed article small,
.analytics-live-feed time {
  color: var(--muted);
  font-size: 8px;
}

.analytics-live-feed time {
  max-width: 84px;
  text-align: right;
}

.analytics-integrity-strip {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  padding: 13px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface);
}

.analytics-integrity-strip > span {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 9px;
  border-radius: 999px;
  background: var(--surface-3);
  color: var(--text-soft);
  font-size: 9px;
}

.analytics-integrity-strip > span svg {
  color: var(--accent);
}

.analytics-integrity-strip > small {
  flex: 1 1 300px;
  color: var(--muted);
  font-size: 8px;
  line-height: 1.5;
}

.security-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.security-grid > section {
  padding: 20px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface-2);
}

.security-grid article {
  display: grid;
  grid-template-columns: 30px minmax(0, 1fr);
  gap: 11px;
  padding: 13px 0;
  border-top: 1px solid var(--line);
}

.security-grid article > span {
  display: grid;
  width: 28px;
  height: 28px;
  place-items: center;
  border-radius: 50%;
}

.security-ok {
  background: color-mix(in srgb, var(--accent) 12%, var(--surface-3));
  color: var(--accent);
}

.security-warn {
  background: color-mix(in srgb, var(--warning) 12%, var(--surface-3));
  color: var(--warning);
}

.security-grid article p {
  margin: 4px 0 0;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.55;
}

.security-operator-item {
  display: grid;
  grid-template-columns: 20px minmax(0, 1fr);
  align-items: start;
  gap: 9px;
  padding: 11px 0;
  border-top: 1px solid var(--line);
  color: var(--text-soft);
  font-size: 10px;
  line-height: 1.5;
}

.security-operator-item > svg {
  margin-top: 1px;
  color: var(--warning);
}

.service-check-strip {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}

.service-check-strip > span {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  min-height: 54px;
  align-items: center;
  gap: 8px;
  padding: 0 13px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface-2);
  color: var(--muted);
  font-size: 10px;
}

.service-check-strip strong {
  color: var(--accent);
  font-size: 9px;
  text-transform: uppercase;
}

.audit-list {
  min-width: 800px;
}

.control-panel:has(.audit-list) {
  overflow-x: auto;
}

.audit-list article {
  display: grid;
  grid-template-columns: 30px minmax(190px, 1fr) minmax(160px, 0.75fr) 170px 100px;
  min-height: 68px;
  align-items: center;
  gap: 12px;
  border-top: 1px solid var(--line);
}

.audit-list article > div {
  display: grid;
  min-width: 0;
  gap: 4px;
}

.audit-list article > div :is(strong, small) {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.audit-list time {
  color: var(--text-soft);
  font-size: 9px;
}

.audit-list code {
  color: var(--muted);
  font-size: 8px;
}

.workspace-task-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 9px;
}

.workspace-task-grid article {
  min-height: 140px;
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface-2);
}

.workspace-task-grid article > span {
  color: var(--accent);
  font-family: var(--font-geist-mono), monospace;
  font-size: 10px;
}

.workspace-task-grid p {
  margin: 32px 0 0;
  color: var(--text-soft);
  font-size: 12px;
  line-height: 1.6;
}

.workspace-task-grid + .button {
  justify-self: start;
}

.chapter-access-policy {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  margin: 0;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface-2);
}

.chapter-access-policy legend {
  grid-column: 1 / -1;
  padding: 0 6px;
  color: var(--text);
  font-size: 11px;
  font-weight: 750;
}

.chapter-access-policy > label {
  display: grid;
  gap: 7px;
}

.chapter-access-policy > label > span {
  color: var(--text-soft);
  font-size: 10px;
  font-weight: 650;
}

.chapter-access-policy :is(input, select) {
  min-height: 44px;
  padding: 0 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface);
  color: var(--text);
}

.chapter-access-metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
}

.chapter-access-metrics article {
  display: grid;
  min-height: 96px;
  align-content: space-between;
  gap: 16px;
  padding: 15px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface-2);
}

.chapter-access-metrics span {
  color: var(--muted);
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 0.09em;
}

.chapter-access-metrics strong {
  font-size: clamp(24px, 3vw, 36px);
  line-height: 0.9;
}

.chapter-access-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.chapter-access-toolbar > label {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  width: min(380px, 100%);
  min-height: 44px;
  align-items: center;
  gap: 8px;
  padding: 0 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface);
  color: var(--muted);
}

.chapter-access-toolbar input {
  min-width: 0;
  border: 0;
  background: transparent;
  color: var(--text);
  outline: 0;
}

.chapter-access-toolbar > div {
  display: flex;
  gap: 5px;
  padding: 4px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface);
}

.chapter-access-toolbar > div button {
  min-height: 34px;
  padding: 0 12px;
  border-radius: calc(var(--radius-small) - 3px);
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  font-size: 9px;
  font-weight: 750;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.chapter-access-toolbar > div button.active {
  background: var(--surface-3);
  color: var(--text);
}

.chapter-access-result-note {
  margin: -2px 0 0;
  color: var(--muted);
  font-size: 9px;
}

.chapter-access-manager {
  display: grid;
  grid-template-columns: minmax(280px, 0.8fr) minmax(360px, 1.2fr);
  min-height: 560px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
}

.chapter-access-list {
  max-height: 680px;
  overflow: auto;
  border-right: 1px solid var(--line);
  background: var(--surface-2);
}

.chapter-access-list > button {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) auto;
  width: 100%;
  min-height: 74px;
  align-items: center;
  gap: 10px;
  padding: 10px 13px;
  border-bottom: 1px solid var(--line);
  background: transparent;
  color: var(--text);
  text-align: left;
  cursor: pointer;
}

.chapter-access-list > button:hover,
.chapter-access-list > button.active {
  background: color-mix(in srgb, var(--accent) 8%, var(--surface-2));
}

.chapter-access-list > button.active {
  box-shadow: inset 3px 0 var(--accent);
}

.chapter-access-list > button > span:nth-child(2),
.chapter-access-list > button > span:last-child {
  display: grid;
  min-width: 0;
  gap: 4px;
}

.chapter-access-list strong,
.chapter-access-list small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.chapter-access-list strong {
  font-size: 11px;
}

.chapter-access-list small {
  color: var(--muted);
  font-size: 8px;
}

.chapter-access-list > button > span:last-child {
  justify-items: end;
  text-align: right;
}

.chapter-access-icon {
  display: grid;
  width: 32px;
  height: 32px;
  place-items: center;
  border-radius: 50%;
  background: var(--surface-3);
  color: var(--muted);
}

.chapter-access-icon:not(.access-free) {
  background: color-mix(in srgb, var(--accent) 15%, var(--surface-3));
  color: var(--accent);
}

.chapter-access-editor {
  display: grid;
  align-content: start;
  gap: 14px;
  padding: clamp(18px, 3vw, 30px);
}

.chapter-access-editor > label {
  display: grid;
  gap: 7px;
}

.chapter-access-editor > label > span {
  color: var(--text-soft);
  font-size: 10px;
  font-weight: 650;
}

.chapter-access-editor :is(input, select, textarea) {
  min-height: 46px;
  padding: 0 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface-2);
  color: var(--text);
}

.chapter-access-editor textarea {
  min-height: 96px;
  padding-block: 12px;
  resize: vertical;
}

.chapter-access-context {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.chapter-access-context span {
  padding: 6px 9px;
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--muted);
  font-size: 8px;
}

.chapter-access-note {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 9px;
  padding: 12px;
  border: 1px solid color-mix(in srgb, var(--accent) 32%, var(--line));
  border-radius: var(--radius-small);
  background: color-mix(in srgb, var(--accent) 7%, var(--surface));
  color: var(--text-soft);
  font-size: 9px;
  line-height: 1.5;
}

.chapter-access-note svg {
  color: var(--accent);
}

.reader-access-page {
  display: grid;
  min-height: 68vh;
  place-items: center;
  padding: clamp(80px, 12vw, 150px) var(--page-padding);
  background:
    radial-gradient(
      circle at 50% 0,
      color-mix(in srgb, var(--accent) 15%, transparent),
      transparent 52%
    ),
    var(--theme-main-background);
}

.reader-access-card {
  display: grid;
  width: min(560px, 100%);
  justify-items: center;
  gap: 15px;
  padding: clamp(22px, 5vw, 42px);
  border: 1px solid var(--theme-accent-l3);
  border-radius: var(--radius);
  background: color-mix(in srgb, var(--theme-accent) 92%, transparent);
  color: var(--theme-text-color);
  text-align: center;
  box-shadow: 0 32px 80px rgba(0, 0, 0, 0.34);
}

.reader-lock-cover {
  position: relative;
  width: min(136px, 42vw);
  aspect-ratio: 2 / 3;
  overflow: hidden;
  border-radius: calc(var(--radius) * 0.7);
  background: var(--theme-accent-l1);
}

.reader-lock-cover img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.reader-lock-cover > span {
  position: absolute;
  right: 8px;
  bottom: 8px;
  display: grid;
  width: 32px;
  height: 32px;
  place-items: center;
  border-radius: 50%;
  background: var(--accent);
  color: var(--accent-ink);
}

.reader-lock-copy {
  display: grid;
  justify-items: center;
  gap: 15px;
}

.reader-lock-copy h1 {
  max-width: 16ch;
  margin: 0;
  font-size: clamp(30px, 6vw, 54px);
  line-height: 0.95;
}

.reader-lock-copy > p:not(.eyebrow) {
  max-width: 48ch;
  margin: 0;
  color: var(--theme-mid-tone);
  font-size: 11px;
  line-height: 1.65;
}

.reader-lock-copy dl {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
  margin: 0;
}

.reader-lock-copy dl > div {
  display: grid;
  gap: 4px;
  min-width: 110px;
  padding: 10px 12px;
  border: 1px solid var(--theme-accent-l3);
  border-radius: 10px;
}

.reader-lock-copy dt {
  color: var(--theme-mid-tone);
  font-size: 8px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.reader-lock-copy dd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  margin: 0;
  font-size: 10px;
  font-weight: 750;
}

.reader-lock-copy .button {
  min-width: min(260px, 100%);
}

.reader-access-back {
  position: absolute;
  top: max(24px, env(safe-area-inset-top));
  left: max(var(--page-padding), env(safe-area-inset-left));
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: var(--theme-mid-tone);
  font-size: 10px;
}

.reader-wallet-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--theme-mid-tone);
  font-size: 9px;
}

.reader-access-error {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: var(--theme-danger) !important;
}



.series-recommendations {
  scroll-margin-top: 86px;
  margin-top: 64px;
  padding-top: 42px;
  border-top: 1px solid var(--line);
}

.series-recommendations .section-heading {
  margin-bottom: 18px;
}

.recommend-item {
  min-width: 0;
}

.recommend-item > span {
  display: block;
  margin-top: 7px;
  color: var(--muted);
  font-size: 9px;
}

.reader-discussion .series-recommendations {
  margin-top: 56px;
}

.reader-quick-nav {
  position: fixed;
  z-index: 48;
  right: max(14px, env(safe-area-inset-right));
  bottom: calc(78px + env(safe-area-inset-bottom));
  display: grid;
  gap: 7px;
}

.reader-quick-nav button {
  display: grid;
  width: 46px;
  height: 46px;
  place-items: center;
  border: 1px solid var(--theme-accent-l3);
  border-radius: 13px;
  background: color-mix(in srgb, var(--theme-accent) 88%, transparent);
  color: var(--theme-text-color);
  box-shadow: 0 14px 36px rgba(0, 0, 0, 0.32);
  backdrop-filter: blur(14px);
  cursor: pointer;
  transition:
    border-color 180ms ease,
    color 180ms ease,
    transform 180ms ease;
}

.reader-quick-nav button:hover {
  border-color: var(--accent);
  color: var(--accent);
  transform: translateY(-1px);
}

.reader-quick-nav button:active {
  transform: translateY(1px) scale(0.98);
}

.show-replies {
  min-height: 44px;
}

.show-replies[aria-expanded="true"] > svg {
  transform: rotate(180deg);
}

.enhanced-comments .comment-sort button,
.enhanced-comments .comment-actions button {
  min-height: 44px;
}

.reader-footer {
  padding-bottom: env(safe-area-inset-bottom);
}

@media (max-width: 1180px) {
  .control-metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .upload-source-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .series-manager-grid,
  .team-manager-grid {
    grid-template-columns: 1fr;
  }

  .team-create-form {
    position: static;
  }

  .analytics-facts {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .chapter-access-manager {
    grid-template-columns: minmax(250px, 0.75fr) minmax(340px, 1.25fr);
  }

  .analytics-detail-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 900px) {
  .ops-header > div:last-child .button-secondary {
    display: none;
  }

  .control-panel,
  .discussion-settings-panel {
    border-radius: var(--radius);
  }

  .control-panel-header {
    align-items: stretch;
    flex-direction: column;
  }

  .control-panel-actions {
    justify-content: flex-start;
  }

  .control-overview-grid,
  .security-grid {
    grid-template-columns: 1fr;
  }

  .upload-details-grid {
    grid-template-columns: 1fr 1fr;
  }

  .upload-details-grid fieldset {
    grid-column: 1 / -1;
  }

  .series-form-layout {
    grid-template-columns: 145px minmax(0, 1fr);
  }

  .user-admin-list {
    overflow-x: auto;
  }

  .user-admin-list article {
    min-width: 760px;
  }

  .workspace-task-grid {
    grid-template-columns: 1fr;
  }

  .chapter-access-policy,
  .chapter-access-metrics {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .chapter-access-manager {
    grid-template-columns: 1fr;
  }

  .chapter-access-list {
    max-height: 330px;
    border-right: 0;
    border-bottom: 1px solid var(--line);
  }

  .analytics-chart-card,
  .analytics-ranking,
  .analytics-live-feed {
    padding: 15px;
  }
}

@media (max-width: 700px) {
  .ops-main {
    padding: 20px 14px 110px;
  }

  .ops-header {
    align-items: stretch;
    flex-direction: column;
    gap: 16px;
  }

  .ops-header > div:last-child {
    width: 100%;
  }

  .ops-header > div:last-child .button-primary {
    width: 100%;
  }

  .control-panel,
  .discussion-settings-panel {
    gap: 18px;
    padding: 17px;
  }

  .control-panel-header h2 {
    font-size: clamp(31px, 10vw, 46px);
  }

  .control-metrics,
  .control-quick-actions,
  .analytics-facts,
  .service-check-strip {
    grid-template-columns: 1fr;
  }

  .upload-source-grid {
    display: flex;
    overflow-x: auto;
    padding-bottom: 6px;
    scroll-snap-type: x mandatory;
  }

  .upload-source-grid > button {
    min-width: 174px;
    scroll-snap-align: start;
  }

  .upload-details-grid {
    grid-template-columns: 1fr;
  }

  .upload-details-grid fieldset {
    grid-column: auto;
  }

  .upload-submit-row {
    align-items: stretch;
    flex-direction: column;
  }

  .upload-submit-row .button {
    width: 100%;
  }

  .series-form-layout {
    grid-template-columns: 1fr;
  }

  .admin-cover-field {
    width: min(180px, 58vw);
  }

  .series-form-fields {
    grid-template-columns: 1fr;
  }

  .series-synopsis-field {
    grid-column: auto;
  }

  .team-admin-list article {
    grid-template-columns: 42px minmax(0, 1fr);
  }

  .team-admin-list article > label {
    grid-column: 1 / -1;
    align-items: center;
    justify-items: start;
    grid-template-columns: 1fr 150px;
  }

  .review-queue-list article {
    grid-template-columns: 32px minmax(0, 1fr);
    padding: 12px 0;
  }

  .review-queue-list article > div:last-child {
    grid-column: 2;
    justify-items: start;
  }

  .chapter-access-toolbar {
    align-items: stretch;
    flex-direction: column;
  }

  .chapter-access-toolbar > label {
    width: 100%;
  }

  .chapter-access-toolbar > div {
    overflow-x: auto;
  }

  .chapter-access-toolbar > div button {
    flex: 1 0 auto;
  }

  .analytics-range-tabs {
    display: flex;
    width: 100%;
  }

  .analytics-range-tabs button {
    flex: 1;
    padding-inline: 8px;
  }

  .analytics-chart-card .control-section-heading {
    align-items: flex-start;
    flex-direction: column;
  }

  .analytics-legend {
    justify-content: flex-start;
  }

  .recommend-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .reader-quick-nav {
    right: max(10px, env(safe-area-inset-right));
    bottom: calc(70px + env(safe-area-inset-bottom));
    gap: 6px;
  }

  .reader-quick-nav button {
    width: 44px;
    height: 44px;
  }
}

@media (max-width: 430px) {
  .control-panel {
    padding: 14px;
    border-right: 0;
    border-left: 0;
  }

  .control-quick-actions {
    grid-template-columns: 1fr;
  }

  .chapter-dropzone {
    min-height: 200px;
    padding: 20px 12px;
  }

  .selected-upload-files > div {
    flex-wrap: wrap;
    padding-block: 10px;
  }

  .selected-upload-files > div > span {
    margin-left: 0;
  }

  .series-admin-list article {
    grid-template-columns: 46px minmax(0, 1fr);
    padding: 11px 0;
  }

  .series-admin-list article > .control-status {
    grid-column: 2;
  }

  .chapter-access-policy,
  .chapter-access-metrics {
    grid-template-columns: 1fr;
  }

  .chapter-access-list > button {
    grid-template-columns: 32px minmax(0, 1fr);
  }

  .chapter-access-list > button > span:last-child {
    grid-column: 2;
    justify-items: start;
    text-align: left;
  }

  .recommend-grid {
    gap: 14px 9px;
  }

  .series-recommendations {
    margin-top: 46px;
    padding-top: 34px;
  }

  .reader-quick-nav {
    bottom: calc(66px + env(safe-area-inset-bottom));
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  .reader-quick-nav button,
  .upload-source-grid > button,
  .control-panel-actions > button {
    transition: none;
  }
}

/* Production polish: discovery hierarchy, commercial controls, and reader UX. */
:root {
  --cover-ratio: 2 / 3;
  --type-page-title: clamp(40px, 5.4vw, 72px);
  --type-section-title: clamp(30px, 3.3vw, 46px);
  --type-card-title: clamp(13px, 1.2vw, 16px);
}

.latest-hero h1 {
  max-width: 13ch;
  font-size: var(--type-page-title);
  line-height: 0.98;
}

.announcement {
  min-height: 42px;
  padding: 5px max(12px, var(--page-padding));
  text-align: left;
}

.announcement-inner {
  display: grid;
  width: min(100%, 1180px);
  min-height: 32px;
  grid-template-columns: auto minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 12px;
  margin-inline: auto;
}

.announcement-inner > span {
  margin: 0;
  padding: 3px 7px;
  border: 1px solid color-mix(in srgb, currentColor 35%, transparent);
  border-radius: 999px;
  font-size: 9px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.announcement-inner p {
  min-width: 0;
  margin: 0;
  font-weight: 620;
}

.announcement-inner a {
  margin: 0;
  white-space: nowrap;
}

.announcement-inner button {
  display: grid;
  width: 32px;
  height: 32px;
  place-items: center;
  border-radius: 50%;
  background: color-mix(in srgb, currentColor 11%, transparent);
  color: currentColor;
  cursor: pointer;
}

.latest-periods {
  display: flex;
  width: max-content;
  max-width: 100%;
  overflow-x: auto;
  gap: 4px;
  margin-top: 24px;
  padding: 4px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--surface);
  scrollbar-width: none;
  scroll-snap-type: x proximity;
}

.latest-periods::-webkit-scrollbar {
  display: none;
}

.latest-periods button {
  min-width: max-content;
  min-height: 38px;
  padding: 0 16px;
  border-radius: 999px;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  font-size: 12px;
  font-weight: 680;
  scroll-snap-align: start;
}

.latest-periods button[aria-selected="true"] {
  background: var(--surface-3);
  color: var(--text);
  box-shadow: inset 0 0 0 1px var(--line);
}

.trending-heading {
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: end;
  gap: 24px;
}

.trending-heading > .trending-title,
.trending-heading > .trending-actions {
  width: auto;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
}

.trending-heading > .trending-title {
  display: block;
  min-width: 0;
}

.trending-title h2 {
  max-width: 100%;
  margin: 0;
  font-size: var(--type-section-title);
  font-weight: 710;
  letter-spacing: -0.055em;
  line-height: 1;
  overflow-wrap: anywhere;
}

.trending-actions {
  justify-self: end;
}

:root[data-slider-style="rank-strip"] .ranked-card,
.trending-rail .ranked-card {
  padding-left: 0;
}

.trending-rail .ranked-card > span,
:root[data-slider-style="rank-strip"] .ranked-card > span {
  position: absolute;
  z-index: 6;
  top: 10px;
  bottom: auto;
  left: 10px;
  display: grid;
  width: 47px;
  height: 38px;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--accent) 52%, white 10%);
  border-radius: 9px;
  background: color-mix(in srgb, var(--bg) 77%, transparent);
  color: color-mix(in srgb, var(--accent) 78%, white);
  font-family: var(--font-geist-mono), monospace;
  font-size: clamp(18px, 1.8vw, 24px);
  font-weight: 850;
  letter-spacing: -0.08em;
  line-height: 1;
  text-shadow:
    0 0 12px color-mix(in srgb, var(--accent) 42%, transparent),
    0 2px 10px var(--bg);
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, white 5%, transparent),
    0 10px 24px color-mix(in srgb, var(--bg) 60%, transparent);
  backdrop-filter: blur(12px);
}

.trending-rail .cover-link > .access-badge {
  top: 10px;
  right: 10px;
}

.chapter-status-badge {
  display: inline-flex;
  width: max-content;
  min-height: 25px;
  align-items: center;
  gap: 5px;
  padding: 0 8px;
  border: 1px solid currentColor;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 740;
  line-height: 1;
}

.chapter-status-free,
.chapter-status-unlocked {
  background: color-mix(in srgb, var(--accent) 10%, transparent);
  color: var(--accent);
}

.chapter-status-premium,
.chapter-status-early_access {
  background: color-mix(in srgb, #e3bd63 11%, transparent);
  color: #e3bd63;
}

.chapter-status-wait_to_unlock {
  background: color-mix(in srgb, var(--warning) 10%, transparent);
  color: var(--warning);
}

.series-secondary-action {
  width: 142px;
  min-height: 44px;
  justify-content: center;
  padding-inline: 16px;
  border-radius: var(--radius-small);
  font-size: 12px;
  font-weight: 700;
}

.notification-cta {
  border-block: 1px solid var(--line);
  background: var(--bg-soft);
}

.notification-cta-inner {
  display: flex;
  min-height: 150px;
  align-items: center;
  justify-content: space-between;
  gap: 30px;
  padding-block: 30px;
}

.notification-cta-inner > div {
  display: grid;
  gap: 7px;
}

.notification-cta-inner h2,
.notification-cta-inner p {
  margin: 0;
}

.notification-cta-inner h2 {
  font-size: clamp(23px, 2.6vw, 34px);
  letter-spacing: -0.04em;
}

.notification-cta-inner p {
  max-width: 58ch;
  color: var(--text-soft);
  font-size: 13px;
  line-height: 1.6;
}

.site-footer {
  padding: 52px 0 34px;
}

.footer-bottom {
  justify-content: flex-start;
  margin-top: 34px;
  padding-top: 17px;
}

.commercial-settings {
  gap: 20px;
}

.commercial-settings-loading {
  min-height: 260px;
  place-items: center;
  align-content: center;
}


.commercial-block {
  display: grid;
  gap: 18px;
  padding: clamp(17px, 2.4vw, 25px);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
}

.commercial-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.commercial-form-grid.commercial-four {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}

.commercial-form-grid label {
  display: grid;
  min-width: 0;
  gap: 7px;
  color: var(--text-soft);
  font-size: 11px;
  font-weight: 680;
}

.commercial-form-grid :is(input, textarea) {
  width: 100%;
  min-height: 43px;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--bg);
  color: var(--text);
  font: inherit;
}

.commercial-form-grid textarea {
  min-height: 92px;
  resize: vertical;
}

.commercial-wide {
  grid-column: 1 / -1;
}

.commercial-rules,
.announcement-reset,
.commercial-save {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px 20px;
}

.settings-check {
  display: inline-flex;
  min-height: 42px;
  align-items: center;
  gap: 9px;
  color: var(--text-soft);
  font-size: 11px;
  font-weight: 650;
}

.settings-check input {
  width: 17px;
  height: 17px;
  accent-color: var(--accent);
}

.announcement-reset {
  justify-content: space-between;
  color: var(--muted);
  font-size: 11px;
}

.announcement-reset button,
.control-section-heading > button,
.commercial-repeaters article > header button {
  display: inline-flex;
  min-height: 38px;
  align-items: center;
  gap: 7px;
  padding: 0 11px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface-2);
  color: var(--text-soft);
  cursor: pointer;
  font-size: 11px;
  font-weight: 680;
}

.commercial-repeaters {
  display: grid;
  gap: 14px;
}

.commercial-repeaters > article {
  display: grid;
  gap: 15px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--bg-soft);
}

.commercial-repeaters article > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.commercial-repeaters article > header button {
  width: 38px;
  justify-content: center;
  padding: 0;
  color: var(--danger);
}

.commercial-save {
  position: sticky;
  z-index: 6;
  bottom: 12px;
  justify-content: space-between;
  padding: 13px 15px;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius);
  background: color-mix(in srgb, var(--surface) 92%, transparent);
  box-shadow: 0 18px 48px var(--shadow);
  backdrop-filter: blur(18px);
}

.commercial-save > span {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--text-soft);
  font-size: 11px;
}

.reader-page {
  min-height: 100dvh;
  background: var(--reader-background, #090b09);
}

.reader-stage {
  max-width: min(920px, 100%);
  gap: var(--reader-image-gap, 8px);
  padding-top: var(--reader-top-margin, 76px);
  padding-bottom: var(--reader-bottom-margin, 86px);
}

.reader-mode-single .reader-stage {
  max-width: min(820px, 100%);
}

.reader-mode-double .reader-stage {
  width: min(100%, 1480px);
  max-width: 1480px;
  gap: var(--reader-image-gap, 8px);
  padding-inline: max(10px, env(safe-area-inset-left));
}

.reader-mode-double .chapter-image-page {
  width: calc(50% - var(--reader-image-gap, 8px) / 2);
}

.reader-fit-height .chapter-image-page > img {
  width: auto;
  max-width: 100%;
  max-height: calc(100dvh - 150px);
  margin-inline: auto;
}

.reader-fit-page .chapter-image-page {
  display: grid;
  min-height: calc(100dvh - 150px);
  place-items: center;
}

.reader-fit-page .chapter-image-page > img {
  width: min(100%, 100vw);
  height: calc(100dvh - 150px);
  max-width: 100%;
  object-fit: contain;
}

.reader-mode-double.reader-fit-page .chapter-image-page > img {
  width: 100%;
}

.reader-fit-original .chapter-image-page > img {
  width: auto;
  max-width: 100%;
  margin-inline: auto;
}

.reader-mode-single.reader-fit-smart .chapter-image-page > img,
.reader-mode-double.reader-fit-smart .chapter-image-page > img {
  width: auto;
  max-width: 100%;
  max-height: calc(100dvh - 150px);
  margin-inline: auto;
}

.reader-theme-paper {
  color-scheme: light;
}

.reader-theme-paper .reader-stage {
  color: #25231f;
}

.chapter-image-page {
  position: relative;
  min-height: 120px;
}

.reader-image-state {
  position: absolute;
  z-index: 3;
  inset: 0;
  display: grid;
  min-height: 150px;
  place-items: center;
  align-content: center;
  gap: 8px;
  padding: 18px;
  background: color-mix(in srgb, var(--reader-background, #090b09) 92%, transparent);
  color: var(--theme-mid-tone);
  text-align: center;
  font-size: 11px;
}

.reader-image-state > strong {
  color: var(--theme-text-color);
  font-size: 13px;
}

.reader-image-state > button {
  min-height: 40px;
  margin-top: 4px;
  padding: 0 13px;
  border: 1px solid var(--theme-accent-l3);
  border-radius: var(--radius-small);
  background: var(--theme-accent-l1);
  color: var(--theme-text-color);
  cursor: pointer;
  font-weight: 680;
}

.reader-image-ready {
  pointer-events: none;
}

.reader-settings-panel {
  position: fixed;
  z-index: 70;
  top: 72px;
  right: 12px;
  bottom: 78px;
  width: min(390px, calc(100vw - 24px));
  overflow-y: auto;
  border: 1px solid var(--theme-accent-l3);
  border-radius: 16px;
  background: color-mix(in srgb, var(--theme-main-background) 96%, transparent);
  color: var(--theme-text-color);
  box-shadow: 0 28px 80px rgba(0, 0, 0, 0.5);
  backdrop-filter: blur(20px);
}

.reader-settings-close {
  position: sticky;
  z-index: 3;
  top: 10px;
  float: right;
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  margin: 10px 10px -48px 0;
  border: 1px solid var(--theme-accent-l3);
  border-radius: 50%;
  background: var(--theme-accent-l1);
  color: var(--theme-text-color);
  cursor: pointer;
}

.reader-settings-sheet {
  display: grid;
  gap: 0;
}

.reader-settings-sheet > header {
  display: flex;
  min-height: 76px;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 16px 62px 16px 18px;
  border-bottom: 1px solid var(--theme-accent-l3);
}

.reader-settings-sheet > header > div {
  display: grid;
  gap: 3px;
}

.reader-settings-sheet > header span,
.reader-settings-sheet h3 {
  color: var(--theme-mid-tone);
  font-size: 10px;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.reader-settings-sheet > header strong {
  font-size: 16px;
}

.reader-settings-sheet > section {
  display: grid;
  gap: 13px;
  padding: 17px 18px;
  border-bottom: 1px solid var(--theme-accent-l3);
}

.reader-settings-sheet h3 {
  display: flex;
  align-items: center;
  gap: 7px;
  margin: 0;
}

.reader-setting-choices {
  min-width: 0;
  margin: 0;
  padding: 0;
  border: 0;
}

.reader-setting-choices legend {
  margin-bottom: 8px;
  color: var(--theme-mid-tone);
  font-size: 11px;
}

.reader-setting-choices > div {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 6px;
}

.reader-setting-choices button {
  min-height: 39px;
  padding: 7px 9px;
  border: 1px solid var(--theme-accent-l3);
  border-radius: 9px;
  background: var(--theme-accent);
  color: var(--theme-mid-tone);
  cursor: pointer;
  font-size: 10px;
}

.reader-setting-choices button[aria-pressed="true"] {
  border-color: color-mix(in srgb, var(--theme-primary) 55%, var(--theme-accent-l3));
  background: color-mix(in srgb, var(--theme-primary) 11%, var(--theme-accent));
  color: var(--theme-primary);
}

.reader-setting-range,
.reader-color-control,
.reader-setting-toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  color: var(--theme-mid-tone);
  font-size: 11px;
}

.reader-setting-range {
  flex-wrap: wrap;
}

.reader-setting-range > span {
  width: 100%;
}

.reader-setting-range output {
  float: right;
  color: var(--accent);
}

.reader-setting-range input {
  width: 100%;
  accent-color: var(--accent);
}

.reader-color-control input {
  width: 42px;
  height: 32px;
  padding: 2px;
  border: 1px solid var(--theme-accent-l3);
  border-radius: 7px;
  background: transparent;
}

.reader-setting-toggle > span {
  display: grid;
  gap: 3px;
}

.reader-setting-toggle small {
  max-width: 30ch;
  color: var(--theme-mid-tone);
  font-size: 9px;
  line-height: 1.45;
}

.reader-setting-toggle input {
  width: 19px;
  height: 19px;
  flex: 0 0 auto;
  accent-color: var(--accent);
}

.reader-setting-toggle.is-disabled {
  opacity: 0.48;
}

.reader-settings-reset {
  display: inline-flex;
  min-height: 44px;
  align-items: center;
  justify-content: center;
  gap: 8px;
  margin: 16px 18px 20px;
  border: 1px solid var(--theme-accent-l3);
  border-radius: 10px;
  background: var(--theme-accent-l1);
  color: var(--theme-text-color);
  cursor: pointer;
  font-size: 11px;
  font-weight: 700;
}

.reader-tap-zones {
  position: fixed;
  z-index: 35;
  inset: 72px 0 78px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  pointer-events: none;
}

.reader-tap-zones button {
  background: transparent;
  cursor: pointer;
  pointer-events: auto;
}

.reader-page-nav {
  z-index: 44;
}

.reader-unlock-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 9px;
}

.reader-lock-cover-placeholder {
  display: grid;
  width: 100%;
  height: 100%;
  place-items: center;
  color: var(--theme-mid-tone);
}

.reader-lock-copy .reader-unlock-actions .button {
  width: auto;
  min-width: 190px;
}

.mobile-nav a {
  width: 100%;
  text-align: center;
}

.mobile-nav .mobile-home {
  grid-column: 3;
  justify-self: center;
}

@media (max-width: 1020px) {
  .commercial-form-grid.commercial-four {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 760px) {
  :root {
    --type-page-title: clamp(36px, 12vw, 54px);
    --type-section-title: clamp(29px, 9vw, 40px);
  }

  .announcement-inner {
    grid-template-columns: auto minmax(0, 1fr) auto;
    gap: 8px;
  }

  .announcement-inner > span {
    display: none;
  }

  .announcement-inner p {
    font-size: 10px;
    line-height: 1.35;
  }

  .announcement-inner a {
    font-size: 10px;
  }

  .trending-heading {
    grid-template-columns: minmax(0, 1fr) auto;
  }

  .trending-actions > a {
    display: none;
  }

  :root[data-slider-style="clean-grid"] .trending-rail {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .trending-rail .ranked-card > span,
  :root[data-slider-style="rank-strip"] .ranked-card > span {
    top: 7px;
    left: 7px;
    width: 40px;
    height: 33px;
    font-size: 18px;
  }

  .latest-periods {
    width: 100%;
  }

  .notification-cta-inner {
    min-height: 0;
    align-items: stretch;
    flex-direction: column;
    padding-block: 28px;
  }

  .notification-cta-inner .button {
    width: 100%;
  }

  .series-secondary-action {
    width: calc(50% - 5px);
    min-width: 0;
  }

  .site-footer {
    padding-top: 42px;
    padding-bottom: calc(28px + env(safe-area-inset-bottom));
  }

  .footer-bottom {
    margin-top: 25px;
  }

  .commercial-form-grid,
  .commercial-form-grid.commercial-four {
    grid-template-columns: 1fr;
  }

  .commercial-wide {
    grid-column: auto;
  }

  .commercial-save {
    align-items: stretch;
    flex-direction: column;
  }

  .commercial-save .button {
    width: 100%;
  }

  .reader-settings-panel {
    top: auto;
    right: 0;
    bottom: 0;
    left: 0;
    width: 100%;
    max-height: min(82dvh, 720px);
    border-right: 0;
    border-bottom: 0;
    border-left: 0;
    border-radius: 18px 18px 0 0;
    padding-bottom: env(safe-area-inset-bottom);
  }

  .reader-mode-double .reader-stage {
    padding-inline: 0;
  }

  .reader-mode-double .chapter-image-page {
    width: calc(50% - var(--reader-image-gap, 8px) / 2);
  }

  .reader-lock-copy .reader-unlock-actions {
    width: 100%;
  }

  .reader-lock-copy .reader-unlock-actions .button {
    width: 100%;
  }
}

@media (max-width: 430px) {
  .announcement-inner {
    grid-template-columns: minmax(0, 1fr) auto;
  }

  .announcement-inner a {
    display: none;
  }

  .trending-actions button {
    width: 36px;
    min-height: 36px;
  }

  .reader-setting-choices > div {
    grid-template-columns: 1fr 1fr;
  }
}

.chapter-editor-section {
  display: grid;
  gap: 13px;
  padding: 15px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--bg-soft);
}

.chapter-editor-heading,
.chapter-editor-heading > a {
  display: flex;
  align-items: center;
}

.chapter-editor-heading {
  justify-content: space-between;
  gap: 14px;
}

.chapter-editor-heading > div {
  display: grid;
  gap: 3px;
}

.chapter-editor-heading span {
  color: var(--muted);
  font-size: 9px;
  font-weight: 720;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.chapter-editor-heading h4 {
  margin: 0;
  color: var(--text);
  font-size: 15px;
}

.chapter-editor-heading > a {
  gap: 6px;
  color: var(--text-soft);
  font-size: 10px;
  font-weight: 680;
}

.chapter-editor-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 11px;
}

.chapter-editor-wide {
  grid-column: 1 / -1;
}

.chapter-page-order,
.chapter-comment-moderation {
  display: grid;
  gap: 7px;
  max-height: 410px;
  overflow-y: auto;
}

.chapter-page-order > article {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  min-height: 61px;
  padding: 7px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: var(--surface);
}

.chapter-page-order img {
  width: 44px;
  aspect-ratio: 2 / 3;
  border-radius: 5px;
  background: var(--surface-2);
  object-fit: cover;
}

.chapter-page-order article > div:nth-child(2) {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.chapter-page-order strong {
  font-size: 11px;
}

.chapter-page-order span {
  color: var(--muted);
  font-size: 9px;
}

.chapter-page-order article > div:last-child {
  display: flex;
  gap: 5px;
}

.chapter-page-order button,
.chapter-comment-moderation button {
  display: inline-flex;
  min-height: 34px;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 0 9px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--surface-2);
  color: var(--text-soft);
  cursor: pointer;
  font-size: 9px;
  font-weight: 680;
}

.chapter-page-order button {
  width: 34px;
  padding: 0;
}

.chapter-page-order button:disabled {
  cursor: not-allowed;
  opacity: 0.35;
}

.chapter-detail-loading,
.chapter-detail-empty {
  display: grid;
  min-height: 72px;
  place-items: center;
  padding: 15px;
  border: 1px dashed var(--line);
  border-radius: 9px;
  color: var(--muted);
  text-align: center;
  font-size: 10px;
}

.chapter-comment-moderation > article {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 12px;
  padding: 11px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: var(--surface);
}

.chapter-comment-moderation article > div:first-child {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.chapter-comment-moderation strong {
  font-size: 10px;
}

.chapter-comment-moderation span {
  color: var(--warning);
  font-size: 9px;
}

.chapter-comment-moderation p {
  display: -webkit-box;
  overflow: hidden;
  margin: 2px 0 0;
  color: var(--text-soft);
  font-size: 10px;
  line-height: 1.45;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
}

.chapter-comment-moderation article > div:last-child {
  display: flex;
  align-items: start;
  gap: 5px;
}

.chapter-comment-moderation button.is-danger {
  color: var(--danger);
}

@media (max-width: 620px) {
  .chapter-editor-grid {
    grid-template-columns: 1fr;
  }

  .chapter-editor-wide {
    grid-column: auto;
  }

  .chapter-editor-heading {
    align-items: flex-start;
    flex-direction: column;
  }

  .chapter-comment-moderation > article {
    grid-template-columns: 1fr;
  }
}

/* Store, editorial, and discovery polish */
.series-type-badge {
  display: inline-flex;
  width: max-content;
  min-height: 24px;
  align-items: center;
  padding: 0 8px;
  border: 1px solid color-mix(in srgb, var(--accent) 40%, var(--line));
  border-radius: 999px;
  background: color-mix(in srgb, var(--surface) 76%, transparent);
  color: color-mix(in srgb, var(--accent) 80%, white);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.08em;
  line-height: 1;
  text-transform: uppercase;
  backdrop-filter: blur(12px);
}

.cover-link > .series-type-badge {
  position: absolute;
  z-index: 2;
  top: 10px;
  right: 10px;
}

.chapter-status-paid {
  border-color: color-mix(in srgb, var(--theme-status-yellow) 72%, var(--line));
  background: color-mix(in srgb, var(--theme-status-yellow) 11%, transparent);
  color: var(--theme-status-yellow);
}

.latest-card-head > div {
  display: grid;
  min-width: 0;
  gap: 6px;
}

.latest-card-head > div > a {
  min-width: 0;
}

.search-panel {
  width: min(780px, calc(100vw - 32px));
}

.search-panel-body {
  max-height: min(68vh, 680px);
}

.search-preview-card {
  grid-template-columns: 60px minmax(0, 1fr) auto;
  min-height: 104px;
  padding: 7px;
}

.search-preview-card > img,
.search-cover-placeholder {
  width: 60px;
  height: 90px;
  border-radius: 8px;
}

.search-cover-placeholder {
  display: grid;
  place-items: center;
  border: 1px solid var(--line);
  background: var(--surface-2);
  color: var(--muted);
}

.search-preview-copy {
  display: grid;
  min-width: 0;
  gap: 5px;
}

.search-preview-copy strong,
.search-preview-copy small,
.search-preview-copy em {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.search-preview-copy strong {
  font-size: 14px;
}

.search-preview-copy small {
  color: var(--text-soft);
  font-size: 10px;
}

.search-preview-copy em {
  color: var(--muted);
  font-size: 9px;
  font-style: normal;
}

.search-preview-copy mark {
  border-radius: 3px;
  background: color-mix(in srgb, var(--accent) 32%, transparent);
  color: var(--text);
}

.search-discovery {
  display: grid;
  gap: 22px;
}

.search-discovery > section {
  min-width: 0;
}

.search-discovery-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.search-discovery-head button {
  color: var(--accent);
  font-size: 10px;
  cursor: pointer;
}

.recent-searches {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.recent-searches button {
  display: inline-flex;
  min-height: 34px;
  align-items: center;
  gap: 6px;
  padding: 0 11px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--surface-2);
  color: var(--text-soft);
  font-size: 10px;
  cursor: pointer;
}

.search-results-compact {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.search-inline-error {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px;
  border: 1px solid color-mix(in srgb, var(--danger) 40%, var(--line));
  border-radius: var(--radius-small);
  color: var(--danger);
  font-size: 11px;
}

.editors-pick-section {
  padding-block: clamp(44px, 7vw, 88px);
}

.editors-pick-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 22px;
}

.editors-pick-heading h2 {
  margin: 4px 0 7px;
  font-size: clamp(26px, 3.2vw, 44px);
  letter-spacing: -0.045em;
}

.editors-pick-heading > div > span {
  color: var(--muted);
  font-size: 12px;
}

.editors-pick-controls {
  display: flex;
  align-items: center;
  gap: 9px;
}

.editors-pick-controls button {
  display: grid;
  width: 40px;
  height: 40px;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: var(--surface);
  color: var(--text);
  cursor: pointer;
}

.editors-pick-controls span {
  min-width: 52px;
  color: var(--muted);
  text-align: center;
  font-size: 10px;
}

.editors-pick-card {
  position: relative;
  display: grid;
  min-height: 460px;
  grid-template-columns: minmax(230px, 34%) minmax(0, 1fr);
  align-items: center;
  gap: clamp(28px, 6vw, 78px);
  overflow: hidden;
  padding: clamp(28px, 5vw, 64px);
  border: 1px solid color-mix(in srgb, var(--accent) 32%, var(--line));
  border-radius: calc(var(--radius) * 1.4);
  background: var(--surface);
  box-shadow: 0 32px 90px color-mix(in srgb, var(--shadow) 72%, transparent);
}

.editors-pick-backdrop,
.editors-pick-vignette {
  position: absolute;
  inset: 0;
}

.editors-pick-backdrop {
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: blur(34px) saturate(0.8);
  opacity: 0.34;
  transform: scale(1.15);
}

.editors-pick-vignette {
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--bg) 80%, transparent), color-mix(in srgb, var(--surface) 68%, transparent)),
    linear-gradient(0deg, var(--surface), transparent 70%);
}

.editors-pick-cover,
.editors-pick-copy {
  position: relative;
  z-index: 1;
}

.editors-pick-cover {
  justify-self: center;
  width: min(290px, 100%);
  aspect-ratio: 2 / 3;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, white 14%, var(--line));
  border-radius: var(--radius);
  background: var(--surface-2);
  box-shadow: 0 26px 64px color-mix(in srgb, var(--shadow) 82%, transparent);
  transform: rotate(-1.5deg);
}

.editors-pick-cover img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.editors-pick-cover > span {
  display: grid;
  height: 100%;
  place-items: center;
  color: var(--muted);
}

.editors-pick-copy {
  display: grid;
  justify-items: start;
  gap: 14px;
}

.editors-pick-copy h3 {
  max-width: 18ch;
  margin: 0;
  font-size: clamp(32px, 5vw, 70px);
  letter-spacing: -0.06em;
  line-height: 0.96;
}

.editors-pick-copy > small {
  color: var(--muted);
  font-size: 11px;
}

.editors-pick-copy > p {
  max-width: 55ch;
  margin: 0;
  color: var(--text-soft);
  font-size: 13px;
  line-height: 1.65;
}

.editors-pick-chips,
.editors-pick-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 7px;
}

.editors-pick-chips > span:not(.series-type-badge) {
  padding: 5px 9px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: color-mix(in srgb, var(--surface-2) 84%, transparent);
  color: var(--text-soft);
  font-size: 9px;
}

.editors-pick-meta {
  color: var(--muted);
  font-size: 10px;
}

.editors-pick-meta span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.editors-pick-meta svg {
  color: var(--accent);
}

.editors-pick-dots {
  display: flex;
  justify-content: center;
  gap: 7px;
  padding-top: 16px;
}

.editors-pick-dots button {
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: var(--line-strong);
  cursor: pointer;
  transition: width 180ms ease, background 180ms ease;
}

.editors-pick-dots button[aria-selected="true"] {
  width: 28px;
  background: var(--accent);
}

.feature-mosaic {
  grid-template-columns: minmax(0, 1.45fr) repeat(2, minmax(0, 1fr));
}

.store-marketplace {
  padding-block: clamp(28px, 5vw, 64px);
}

.store-collection-tabs {
  display: flex;
  overflow-x: auto;
  gap: 8px;
  margin: 18px 0 24px;
  padding-bottom: 5px;
  scrollbar-width: thin;
}

.store-collection-tabs button {
  display: inline-flex;
  min-height: 40px;
  flex: 0 0 auto;
  align-items: center;
  gap: 7px;
  padding: 0 14px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--surface);
  color: var(--text-soft);
  font-size: 11px;
  cursor: pointer;
}

.store-collection-tabs button[aria-selected="true"] {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 12%, var(--surface));
  color: var(--accent);
}

.store-collection-tabs small {
  color: var(--warning);
  font-size: 8px;
  text-transform: uppercase;
}

.store-cosmetics-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: clamp(12px, 2vw, 22px);
}

.store-cosmetic-card {
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
  box-shadow: 0 18px 52px color-mix(in srgb, var(--shadow) 46%, transparent);
  transition: border-color 180ms ease, transform 180ms ease;
}

.store-cosmetic-card:hover {
  border-color: color-mix(in srgb, var(--accent) 44%, var(--line));
  transform: translateY(-3px);
}

.store-cosmetic-preview {
  position: relative;
  display: grid;
  min-height: 230px;
  place-items: center;
  overflow: hidden;
  background:
    radial-gradient(circle at 70% 20%, var(--store-accent), transparent 5%),
    radial-gradient(circle at 28% 75%, color-mix(in srgb, var(--store-accent) 60%, transparent), transparent 10%),
    linear-gradient(135deg, var(--store-from), var(--store-to));
  color: var(--store-accent);
}

.store-cosmetic-preview::before {
  position: absolute;
  inset: 12%;
  border: 1px solid color-mix(in srgb, var(--store-accent) 46%, transparent);
  border-radius: 50%;
  content: "";
  box-shadow: 0 0 42px color-mix(in srgb, var(--store-accent) 26%, transparent);
}

.store-cosmetic-preview > img {
  position: absolute;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.store-preview-avatar {
  position: relative;
  z-index: 1;
  display: grid;
  width: 84px;
  height: 84px;
  place-items: center;
  border: 2px solid currentColor;
  border-radius: 50%;
  background: color-mix(in srgb, var(--store-to) 72%, transparent);
  box-shadow: 0 0 0 10px color-mix(in srgb, currentColor 10%, transparent);
}

.store-cosmetic-preview > strong {
  position: absolute;
  z-index: 1;
  bottom: 42px;
  font-family: var(--font-geist-mono), monospace;
  font-size: 9px;
  letter-spacing: 0.22em;
}

.store-preview-label {
  position: absolute;
  z-index: 2;
  top: 12px;
  left: 12px;
  padding: 5px 8px;
  border: 1px solid color-mix(in srgb, white 20%, transparent);
  border-radius: 999px;
  background: rgba(3, 17, 31, 0.56);
  color: white;
  font-size: 8px;
  text-transform: uppercase;
  backdrop-filter: blur(10px);
}

.store-cosmetic-copy {
  display: grid;
  gap: 8px;
  padding: 17px;
}

.store-cosmetic-copy > span {
  color: var(--accent);
  font-size: 9px;
  font-weight: 750;
  text-transform: uppercase;
}

.store-cosmetic-copy h3 {
  margin: 0;
  font-size: 18px;
  letter-spacing: -0.03em;
}

.store-cosmetic-copy p {
  min-height: 3.1em;
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.55;
}

.store-cosmetic-copy > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding-top: 7px;
}

.store-cosmetic-copy > div > strong {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--theme-status-yellow);
  font-size: 13px;
}

.store-cosmetic-copy .button {
  min-height: 37px;
  padding-inline: 13px;
  font-size: 10px;
}

.store-cosmetics-loading > span {
  display: grid;
  min-height: 330px;
  gap: 10px;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
}

.store-cosmetics-loading i,
.store-cosmetics-loading b,
.store-cosmetics-loading small {
  display: block;
  border-radius: 8px;
  background: linear-gradient(90deg, var(--surface-2), var(--surface-3), var(--surface-2));
  background-size: 200% 100%;
  animation: shimmer 1.5s infinite;
}

.store-cosmetics-loading i {
  min-height: 220px;
}

.store-cosmetics-loading b {
  width: 64%;
  height: 16px;
}

.store-cosmetics-loading small {
  width: 88%;
  height: 10px;
}

.reader-lock-cover img {
  filter: blur(7px) saturate(0.7);
  transform: scale(1.08);
}

.reader-lock-cover > span {
  right: 50%;
  bottom: 50%;
  width: 68px;
  height: 68px;
  border: 1px solid color-mix(in srgb, white 24%, transparent);
  background: color-mix(in srgb, var(--accent) 82%, transparent);
  transform: translate(50%, 50%);
  box-shadow: 0 0 46px color-mix(in srgb, var(--accent) 42%, transparent);
  backdrop-filter: blur(10px);
}

.footer-links summary {
  cursor: pointer;
}

.footer-links summary::after {
  float: right;
  color: var(--muted);
  content: "+";
}

.footer-links details[open] summary::after {
  content: "−";
}

.mobile-nav {
  grid-template-columns: repeat(5, minmax(0, 1fr));
}

.mobile-nav a {
  justify-self: stretch;
}

@media (max-width: 900px) {
  .editors-pick-card {
    grid-template-columns: minmax(170px, 31%) minmax(0, 1fr);
    min-height: 400px;
    gap: 28px;
  }

  .editors-pick-copy h3 {
    font-size: clamp(29px, 6vw, 48px);
  }

  .store-cosmetics-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .search-results-compact {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 620px) {
  .search-overlay {
    place-items: end center;
    padding-top: 0;
  }

  .search-panel {
    width: 100%;
    max-height: 92dvh;
    border-radius: 20px 20px 0 0;
  }

  .search-panel-body {
    max-height: calc(92dvh - 66px);
    padding: 14px;
  }

  .search-preview-card {
    grid-template-columns: 52px minmax(0, 1fr) auto;
    min-height: 90px;
  }

  .search-preview-card > img,
  .search-cover-placeholder {
    width: 52px;
    height: 78px;
  }

  .editors-pick-section {
    padding-block: 42px;
  }

  .editors-pick-heading {
    align-items: flex-start;
  }

  .editors-pick-heading > div:first-child > span {
    display: none;
  }

  .editors-pick-card {
    min-height: 0;
    grid-template-columns: 112px minmax(0, 1fr);
    gap: 18px;
    padding: 18px;
    border-radius: var(--radius);
  }

  .editors-pick-cover {
    width: 112px;
    align-self: start;
    border-radius: 11px;
  }

  .editors-pick-copy {
    gap: 9px;
  }

  .editors-pick-copy h3 {
    font-size: clamp(24px, 7.5vw, 34px);
  }

  .editors-pick-copy > small,
  .editors-pick-meta {
    display: none;
  }

  .editors-pick-copy > p {
    display: -webkit-box;
    overflow: hidden;
    font-size: 10px;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 3;
  }

  .editors-pick-chips > span:nth-of-type(n + 3) {
    display: none;
  }

  .editors-pick-copy .button {
    min-height: 38px;
    padding-inline: 12px;
    font-size: 10px;
  }

  .feature-mosaic,
  .store-cosmetics-grid {
    grid-template-columns: 1fr 1fr;
  }

  .feature-mosaic > :first-child {
    grid-column: 1 / -1;
  }

  .store-cosmetic-preview {
    min-height: 170px;
  }

  .store-cosmetic-copy {
    padding: 13px;
  }

  .store-cosmetic-copy p {
    min-height: 0;
  }

  .store-cosmetic-copy > div {
    align-items: stretch;
    flex-direction: column;
  }

  .store-cosmetic-copy .button {
    width: 100%;
  }

  .footer-links {
    grid-template-columns: 1fr;
    gap: 0;
  }

  .footer-links details {
    padding-block: 14px;
    border-top: 1px solid var(--line);
  }

  .footer-links summary {
    margin: 0;
  }

  .footer-links details > div {
    padding-top: 13px;
  }
}

@media (max-width: 420px) {
  .store-cosmetics-grid {
    grid-template-columns: 1fr;
  }

  .editors-pick-card {
    grid-template-columns: 96px minmax(0, 1fr);
  }

  .editors-pick-cover {
    width: 96px;
  }
}

/* NyaScans v1.2 administration system */
.admin-workspace {
  display: grid;
  width: min(100%, 1480px);
  min-width: 0;
  gap: 22px;
  margin-inline: auto;
}

.admin-breadcrumbs {
  display: flex;
  min-width: 0;
  flex-wrap: wrap;
  gap: 7px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 650;
  letter-spacing: 0.04em;
}

.admin-breadcrumbs i {
  margin-right: 7px;
  color: var(--line-strong);
  font-style: normal;
}

.admin-workspace-header,
.store-management-heading,
.appearance-component-preview > header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: clamp(18px, 3vw, 40px);
}

.admin-workspace-header > div:first-child,
.store-management-heading > div,
.appearance-component-preview > header > div {
  min-width: 0;
}

.admin-workspace-header h2,
.store-management-heading h2 {
  max-width: 920px;
  margin: 8px 0 10px;
  font-size: clamp(30px, 4vw, 54px);
  line-height: 0.98;
  letter-spacing: -0.055em;
  text-wrap: balance;
}

.admin-workspace-header p,
.store-management-heading p,
.appearance-component-preview > header p {
  max-width: 760px;
  margin: 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.7;
}

.admin-primary-action,
.admin-header-actions {
  display: flex;
  flex: 0 0 auto;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 9px;
}

.admin-subnav {
  display: flex;
  min-width: 0;
  gap: 4px;
  padding: 5px;
  overflow-x: auto;
  border: 1px solid var(--line);
  border-radius: calc(var(--radius) + 1px);
  background: color-mix(in srgb, var(--surface) 88%, transparent);
  scrollbar-width: thin;
}

.admin-subnav button {
  display: inline-flex;
  min-height: 42px;
  flex: 0 0 auto;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 0 14px;
  border: 1px solid transparent;
  border-radius: var(--radius-small);
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  font-size: 11px;
  font-weight: 700;
  white-space: nowrap;
}

.admin-subnav button[aria-selected="true"] {
  border-color: color-mix(in srgb, var(--accent) 38%, var(--line));
  background: color-mix(in srgb, var(--accent) 11%, var(--surface-2));
  color: var(--text);
}

.admin-subnav small,
.store-section-nav small {
  display: inline-grid;
  min-width: 20px;
  height: 20px;
  place-items: center;
  padding-inline: 5px;
  border-radius: 999px;
  background: var(--surface-3);
  color: var(--text-soft);
  font-size: 9px;
}

.admin-notice {
  display: flex;
  min-height: 48px;
  align-items: flex-start;
  gap: 10px;
  padding: 13px 15px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface-2);
  color: var(--text-soft);
  font-size: 12px;
  line-height: 1.5;
}

.admin-notice svg {
  flex: 0 0 auto;
  margin-top: 1px;
}

.admin-notice-success {
  border-color: color-mix(in srgb, var(--site-success, #39c98a) 45%, var(--line));
  color: var(--site-success, #39c98a);
}

.admin-notice-error {
  border-color: color-mix(in srgb, var(--danger) 45%, var(--line));
  color: var(--danger);
}

.admin-notice-neutral,
.admin-notice.is-warning {
  border-color: color-mix(in srgb, var(--warning) 44%, var(--line));
  color: var(--warning);
}

.admin-notice.is-warning {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
}

.admin-notice.is-warning strong {
  grid-column: 1 / -1;
}

.admin-state-card {
  display: grid;
  min-height: 220px;
  place-items: center;
  align-content: center;
  gap: 10px;
  padding: 32px;
  border: 1px dashed var(--line-strong);
  border-radius: calc(var(--radius) + 2px);
  background: color-mix(in srgb, var(--surface) 80%, transparent);
  color: var(--muted);
  text-align: center;
}

.admin-state-card h3,
.admin-state-card p {
  margin: 0;
}

.admin-state-card h3 {
  color: var(--text);
  font-size: 18px;
}

.admin-state-card p {
  max-width: 540px;
  font-size: 12px;
  line-height: 1.6;
}


.admin-master-detail {
  display: grid;
  min-width: 0;
  grid-template-columns: minmax(250px, 0.3fr) minmax(0, 1fr);
  align-items: start;
  gap: 20px;
}

.admin-record-browser,
.admin-record-list {
  display: grid;
  min-width: 0;
  max-height: min(760px, calc(100vh - 180px));
  gap: 8px;
  padding: 12px;
  overflow: auto;
  border: 1px solid var(--line);
  border-radius: calc(var(--radius) + 2px);
  background: var(--surface);
  position: sticky;
  top: 18px;
}

.admin-record-browser > form,
.admin-search-field {
  display: grid;
  min-height: 44px;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px;
  padding: 0 11px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--bg-soft);
}

.admin-search-field {
  grid-template-columns: 1fr;
  gap: 4px;
  padding-block: 8px;
}

.admin-search-field > span {
  color: var(--muted);
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
}

.admin-record-browser input,
.admin-search-field input {
  min-width: 0;
  border: 0;
  outline: 0;
  background: transparent;
}

.admin-record-browser > form button,
.admin-record-browser > button,
.admin-record-list > button:not(.button),
.admin-record-browser > div > button {
  display: flex;
  width: 100%;
  min-height: 54px;
  align-items: center;
  gap: 10px;
  padding: 8px 10px;
  border: 1px solid transparent;
  border-radius: var(--radius-small);
  background: transparent;
  color: var(--text-soft);
  cursor: pointer;
  text-align: left;
}

.admin-record-browser > button {
  min-height: 40px;
}

.admin-record-browser > div {
  display: grid;
  gap: 5px;
}

.admin-record-browser > div > button.is-active,
.admin-record-list > button[aria-current="true"],
.admin-record-browser > div > button:hover,
.admin-record-list > button:not(.button):hover {
  border-color: color-mix(in srgb, var(--accent) 32%, var(--line));
  background: color-mix(in srgb, var(--accent) 8%, var(--surface-2));
  color: var(--text);
}

.admin-record-browser > div > button > span,
.admin-list-avatar,
.reaction-admin-thumb {
  display: grid;
  width: 42px;
  height: 42px;
  flex: 0 0 auto;
  place-items: center;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--surface-3);
  color: var(--accent);
  font-size: 11px;
  font-weight: 800;
}

.admin-record-browser img,
.admin-list-avatar img,
.reaction-admin-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.admin-record-browser > div > button > div,
.admin-record-list > button > span:nth-child(2) {
  display: grid;
  min-width: 0;
  flex: 1;
  gap: 3px;
}

.admin-record-browser strong,
.admin-record-list strong {
  overflow: hidden;
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.admin-record-browser small,
.admin-record-list small,
.admin-record-list em {
  color: var(--muted);
  font-size: 9px;
  font-style: normal;
}

.admin-detail-form,
.admin-editor-form {
  display: grid;
  min-width: 0;
  gap: 18px;
}

.admin-form-section {
  display: grid;
  min-width: 0;
  gap: 20px;
  padding: clamp(18px, 2.3vw, 30px);
  border: 1px solid var(--line);
  border-radius: calc(var(--radius) + 3px);
  background:
    radial-gradient(
      circle at 95% 0,
      color-mix(in srgb, var(--accent) 6%, transparent),
      transparent 24rem
    ),
    var(--surface);
}

.admin-form-section > header,
.admin-section-heading {
  display: flex;
  align-items: flex-start;
  gap: 13px;
  padding-bottom: 16px;
  border-bottom: 1px solid var(--line);
}

.admin-section-heading > span {
  display: grid;
  width: 32px;
  height: 32px;
  flex: 0 0 auto;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--accent) 40%, var(--line));
  border-radius: 50%;
  color: var(--accent);
  font-size: 10px;
  font-weight: 800;
}

.admin-form-section h3,
.admin-section-heading h3 {
  margin: 0 0 5px;
  font-size: 20px;
  letter-spacing: -0.025em;
}

.admin-form-section header p,
.admin-section-heading p {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.55;
}

.admin-form-grid,
.admin-review-grid,
.admin-summary-grid {
  display: grid;
  min-width: 0;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 15px;
}

.admin-review-grid,
.admin-summary-grid {
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
}

.admin-review-grid > div,
.admin-summary-grid > div,
.admin-data-list > article,
.admin-source-list > article {
  display: grid;
  gap: 5px;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface-2);
}

.admin-review-grid span,
.admin-summary-grid span {
  color: var(--muted);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.admin-form-section label,
.admin-form-grid label,
.admin-inline-field label,
.admin-entity-field > label,
.audit-filter-grid label,
.admin-filter-bar label,
.theme-token-groups label {
