  min-width: 0;
  gap: 10px;
}

.admin-entity-field > div:not(.admin-chip-list),
.admin-inline-field,
.admin-import-controls,
.admin-filter-bar {
  display: flex;
  min-width: 0;
  align-items: end;
  flex-wrap: wrap;
  gap: 10px;
}

.admin-entity-field > div:not(.admin-chip-list) > input,
.admin-inline-field > label,
.admin-import-controls > label {
  min-width: min(100%, 220px);
  flex: 1 1 220px;
