.admin-chip-list {
  display: flex;
  min-height: 32px;
  flex-wrap: wrap;
  gap: 7px;
}

.admin-chip-list > span {
  display: inline-flex;
  min-height: 31px;
  align-items: center;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--accent) 28%, var(--line));
  border-radius: 999px;
  background: color-mix(in srgb, var(--accent) 8%, var(--surface-2));
  color: var(--text-soft);
}

.admin-chip-list button,
.admin-chip-list em {
  min-height: 29px;
  padding: 0 10px;
  background: transparent;
  color: inherit;
  font-size: 10px;
  font-style: normal;
}

.admin-chip-list button {
  cursor: pointer;
}

.admin-chip-list > span > button:last-child {
  display: grid;
  width: 30px;
  place-items: center;
  padding: 0;
  border-left: 1px solid var(--line);
}

.admin-team-selection,
.admin-data-list,
.admin-source-list {
  display: grid;
  gap: 9px;
}

.admin-team-selection > article,
.admin-data-list > article,
.admin-source-list > article {
  display: flex;
  min-width: 0;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 14px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface-2);
}

.admin-inline-empty,
.admin-disabled-reason,
.admin-entity-feedback {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.5;
}

.admin-disabled-reason {
  color: var(--warning);
}

.admin-entity-feedback {
  color: var(--accent);
}

.admin-import-preview {
  display: grid;
  gap: 9px;
  padding: 15px;
  border: 1px solid color-mix(in srgb, var(--accent) 34%, var(--line));
  border-radius: var(--radius);
  background: color-mix(in srgb, var(--accent) 5%, var(--surface-2));
}

.admin-import-preview > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.admin-import-preview > label {
  display: grid !important;
  min-height: 52px;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: start;
  gap: 10px;
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface);
}

.admin-import-preview > label input {
  width: 18px;
  min-height: 18px;
  padding: 0;
}

.admin-import-preview > label span {
  display: grid;
  gap: 3px;
}

.admin-import-preview small {
  overflow-wrap: anywhere;
  color: var(--muted);
  font-size: 9px;
  font-weight: 500;
}

.taxonomy-create-row {
  display: flex;
  align-items: end;
  gap: 10px;
}

.taxonomy-create-row label {
  min-width: min(100%, 280px);
  flex: 1;
}

.taxonomy-layout {
  display: grid;
  min-width: 0;
  grid-template-columns: minmax(220px, 0.45fr) minmax(0, 1fr);
  gap: 14px;
}

.taxonomy-list {
  display: grid;
  max-height: 520px;
  align-content: start;
  gap: 5px;
  padding: 8px;
  overflow: auto;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--bg-soft);
}

.taxonomy-list button {
  display: flex;
  width: 100%;
  min-height: 50px;
  align-items: center;
  padding: 9px 10px;
  border: 1px solid transparent;
  border-radius: 8px;
  background: transparent;
  color: var(--text-soft);
  cursor: pointer;
  text-align: left;
}

.taxonomy-list button[aria-current="true"] {
  border-color: color-mix(in srgb, var(--accent) 38%, var(--line));
  background: color-mix(in srgb, var(--accent) 9%, var(--surface-2));
}

.taxonomy-list button span {
  display: grid;
  gap: 4px;
}

.taxonomy-list small {
  color: var(--muted);
  font-size: 9px;
}

.taxonomy-editor {
  display: grid;
  min-width: 0;
  align-content: start;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 12px;
  padding: 15px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface-2);
}

.taxonomy-editor .button {
  align-self: end;
}

.admin-media-grid,
.site-media-grid {
  display: grid;
  min-width: 0;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 15px;
}

.admin-media-field {
  display: grid;
  min-width: 0;
  grid-template-columns: minmax(100px, 0.38fr) minmax(0, 1fr);
  gap: 14px;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface-2);
}

.admin-media-preview {
  display: grid;
  min-height: 150px;
  place-items: center;
  overflow: hidden;
  border: 1px dashed var(--line-strong);
  border-radius: var(--radius-small);
  background: var(--bg-soft);
  color: var(--muted);
  position: relative;
}

.admin-media-preview img {
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.admin-media-preview > span:not(.admin-media-progress) {
  display: grid;
  justify-items: center;
  gap: 7px;
  font-size: 10px;
}

.admin-media-progress {
  position: absolute;
  right: 8px;
  bottom: 8px;
  left: 8px;
  padding: 6px 8px;
  border-radius: 7px;
  background: rgba(3, 17, 31, 0.86);
  color: white;
  font-size: 9px;
  text-align: center;
}

.admin-media-copy {
  display: grid;
  min-width: 0;
  align-content: start;
  gap: 7px;
}

.admin-media-copy p,
.admin-media-copy small {
  margin: 0;
  color: var(--muted);
  font-size: 9px;
  line-height: 1.5;
}

.admin-media-copy > div {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin-top: 5px;
}

.admin-media-copy input[type="file"],
.site-media-grid input[type="file"] {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
}

.admin-sticky-actions {
  display: flex;
  min-height: 64px;
  align-items: center;
  justify-content: flex-end;
  gap: 9px;
  padding: 12px 14px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: color-mix(in srgb, var(--surface) 92%, transparent);
  box-shadow: 0 18px 48px color-mix(in srgb, var(--shadow) 48%, transparent);
  backdrop-filter: blur(16px);
  position: sticky;
  bottom: 12px;
  z-index: 8;
}

.admin-sticky-actions small {
  margin-right: auto;
  color: var(--muted);
  font-size: 10px;
}

.admin-dialog-backdrop,
.admin-drawer-backdrop {
  display: grid;
  padding: 18px;
  background: rgba(1, 8, 18, 0.78);
  backdrop-filter: blur(8px);
  position: fixed;
  inset: 0;
  z-index: 300;
}

.admin-dialog-backdrop {
  place-items: center;
}

.admin-confirm-dialog {
  display: grid;
  width: min(100%, 470px);
  max-height: calc(100dvh - 36px);
  gap: 14px;
  padding: clamp(20px, 4vw, 30px);
  overflow: auto;
  border: 1px solid var(--line-strong);
  border-radius: calc(var(--radius) + 4px);
  background: var(--surface);
  box-shadow: 0 36px 100px rgba(0, 0, 0, 0.5);
}

.admin-confirm-dialog h3,
.admin-confirm-dialog p {
  margin: 0;
}

.admin-confirm-dialog p {
  color: var(--muted);
  font-size: 12px;
  line-height: 1.6;
}

.admin-confirm-dialog > div {
  display: flex;
  justify-content: flex-end;
  gap: 9px;
}

.admin-drawer-backdrop {
  justify-items: end;
  padding: 0;
}

.audit-detail-drawer {
  width: min(100%, 640px);
  height: 100dvh;
  padding: clamp(18px, 3vw, 30px);
  overflow: auto;
  border-left: 1px solid var(--line);
  background: var(--surface);
  box-shadow: -24px 0 80px rgba(0, 0, 0, 0.45);
}

.audit-detail-drawer > header,
.commerce-customer-preview > header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}

.audit-detail-drawer h3,
.audit-detail-drawer h4,
.commerce-customer-preview h3 {
  margin: 4px 0;
}

.audit-detail-drawer > header button {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: var(--surface-2);
  cursor: pointer;
}

.audit-detail-summary,
.audit-reason {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin: 20px 0;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface-2);
  color: var(--text-soft);
  font-size: 12px;
  line-height: 1.6;
}

.audit-detail-drawer dl {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.audit-detail-drawer dl > div {
  min-width: 0;
  padding: 10px;
  border: 1px solid var(--line);
  border-radius: 8px;
}

.audit-detail-drawer dt {
  color: var(--muted);
  font-size: 9px;
  text-transform: uppercase;
}

.audit-detail-drawer dd {
  margin: 5px 0 0;
  overflow-wrap: anywhere;
  font-size: 11px;
}

.audit-detail-drawer pre {
  max-height: 280px;
  padding: 13px;
  overflow: auto;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: var(--bg);
  color: var(--text-soft);
  font-size: 10px;
  line-height: 1.6;
  white-space: pre-wrap;
}

.audit-filter-grid {
  display: grid;
  min-width: 0;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 11px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
}

.audit-filter-actions {
  display: flex;
  grid-column: 1 / -1;
  justify-content: flex-end;
  gap: 8px;
}

.audit-event-table {
  min-width: 0;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
}

.audit-event-head,
.audit-event-table > button {
  display: grid;
  width: 100%;
  grid-template-columns: 150px minmax(140px, 0.8fr) minmax(180px, 1fr) minmax(160px, 0.9fr) 90px;
  align-items: center;
  gap: 14px;
  padding: 12px 14px;
  text-align: left;
}

.audit-event-head {
  min-height: 42px;
  background: var(--surface-2);
  color: var(--muted);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.audit-event-table > button {
  min-height: 66px;
  border-top: 1px solid var(--line);
  background: transparent;
  color: var(--text-soft);
  cursor: pointer;
}

.audit-event-table > button:hover {
  background: color-mix(in srgb, var(--accent) 6%, var(--surface-2));
}

.audit-event-table > button > span {
  display: grid;
  min-width: 0;
  gap: 3px;
}

.audit-event-table strong,
.audit-event-table small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.audit-event-table strong,
.audit-event-table time {
  font-size: 10px;
}

.audit-event-table small {
  color: var(--muted);
  font-size: 8px;
}

.audit-result {
  justify-self: start;
  padding: 5px 8px;
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--text-soft);
  font-size: 8px;
  font-style: normal;
  font-weight: 800;
}

.audit-result.result-success {
  border-color: color-mix(in srgb, var(--theme-status-green) 42%, var(--line));
  color: var(--theme-status-green);
}

.audit-result.result-failure,
.audit-result.result-denied {
  border-color: color-mix(in srgb, var(--danger) 42%, var(--line));
  color: var(--danger);
}

.admin-pagination {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
}

.admin-pagination > span {
  margin-right: auto;
  color: var(--muted);
  font-size: 10px;
}

.admin-pagination button {
  display: inline-flex;
  min-height: 40px;
  align-items: center;
  gap: 6px;
  padding: 0 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface);
  color: var(--text-soft);
  cursor: pointer;
  font-size: 10px;
}

.admin-pagination button:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.team-effect-preview,
.reaction-live-preview {
  display: flex;
  min-height: 92px;
  align-items: center;
  gap: 14px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface-2);
}

.team-effect-preview > span,
.reaction-live-preview > span,
.reaction-live-preview > img {
  display: grid;
  width: 48px;
  height: 48px;
  flex: 0 0 auto;
  place-items: center;
  object-fit: contain;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--bg-soft);
  color: var(--accent);
  font-weight: 800;
}

.team-effect-preview > div,
.reaction-live-preview > div {
  display: grid;
  gap: 4px;
}

.team-effect-preview p,
.reaction-live-preview small {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
}

.team-effect-preview.effect-border {
  border-color: var(--team-accent);
}

.team-effect-preview.effect-glow {
  box-shadow: 0 0 var(--team-glow) color-mix(in srgb, var(--team-accent) 35%, transparent);
}

.team-effect-preview.effect-accent {
  background: color-mix(in srgb, var(--team-accent) 12%, var(--surface-2));
}

.commerce-customer-preview {
  display: grid;
  gap: 14px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--bg-soft);
}

.commerce-customer-preview > header > div:last-child {
  display: flex;
  gap: 5px;
}

.commerce-customer-preview > header button {
  display: inline-flex;
  min-height: 38px;
  align-items: center;
  gap: 6px;
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--surface);
  color: var(--muted);
  cursor: pointer;
  font-size: 10px;
}

.commerce-customer-preview > header button[aria-pressed="true"] {
  border-color: var(--accent);
  color: var(--text);
}

.commerce-offer-preview {
  display: grid;
  width: min(100%, 720px);
  min-height: 250px;
  grid-template-columns: minmax(180px, 0.45fr) minmax(0, 1fr);
  align-items: stretch;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: calc(var(--radius) + 4px);
  background: linear-gradient(135deg, var(--surface-2), var(--surface));
  background-position: center;
  background-size: cover;
  box-shadow: 0 24px 70px color-mix(in srgb, var(--shadow) 60%, transparent);
}

.commerce-offer-preview.preview-mobile {
  width: min(100%, 350px);
  grid-template-columns: 1fr;
}

.commerce-preview-art {
  display: grid;
  min-height: 200px;
  place-items: center;
  overflow: hidden;
  background: color-mix(in srgb, var(--accent) 12%, var(--surface-3));
  color: var(--accent);
}

.commerce-preview-art img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.commerce-offer-preview > div {
  display: grid;
  align-content: center;
  justify-items: start;
  gap: 9px;
  padding: 24px;
}

.commerce-preview-icon {
  width: 34px;
  height: 34px;
  object-fit: contain;
  border-radius: 9px;
}

.commerce-offer-preview h4,
.commerce-offer-preview p {
  margin: 0;
}

.commerce-offer-preview p {
  color: var(--muted);
  font-size: 11px;
  line-height: 1.55;
}

.commerce-offer-preview em,
.commerce-preview-cta {
  padding: 6px 9px;
  border-radius: 999px;
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 9px;
  font-style: normal;
  font-weight: 800;
}

.commerce-preview-cta {
  border-radius: 8px;
}

.store-management-workspace {
  display: grid;
  min-width: 0;
  gap: 22px;
}

.store-management-groups {
  display: grid;
  grid-template-columns: minmax(280px, 0.72fr) minmax(0, 1.28fr);
  align-items: start;
  gap: 14px;
}

.store-management-group {
  display: grid;
  min-width: 0;
  gap: 12px;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: calc(var(--radius) + 2px);
  background: color-mix(in srgb, var(--surface) 88%, var(--bg-soft));
}

.store-management-group > header {
  display: grid;
  gap: 4px;
  padding: 0 2px;
}

.store-management-group > header span {
  color: var(--text);
  font-size: 13px;
  font-weight: 820;
}

.store-management-group > header p {
  max-width: 60ch;
  margin: 0;
  color: var(--muted);
  font-size: 9px;
  line-height: 1.5;
}

.store-management-category-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
  gap: 9px;
}

.store-management-category-card {
  display: grid;
  min-width: 0;
  align-content: start;
  gap: 10px;
  padding: 14px;
  text-align: left;
  border: 1px solid var(--line);
  border-radius: 12px;
  color: var(--text);
  background: var(--surface);
  cursor: pointer;
  transition:
    transform 180ms ease,
    border-color 180ms ease,
    background-color 180ms ease;
}

.store-management-category-card:hover {
  transform: translateY(-1px);
  border-color: color-mix(in srgb, var(--accent) 42%, var(--line));
  background: color-mix(in srgb, var(--accent) 4%, var(--surface));
}

.store-management-category-card:active {
  transform: translateY(0);
}

.store-management-category-card:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.store-management-category-card.is-active {
  border-color: color-mix(in srgb, var(--accent) 62%, var(--line));
  background: color-mix(in srgb, var(--accent) 7%, var(--surface));
  box-shadow: inset 3px 0 0 var(--accent);
}

.store-management-category-title {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 9px;
}

.store-management-category-title strong {
  font-size: 12px;
}

.store-management-category-title em {
  flex: 0 0 auto;
  padding: 4px 6px;
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--text-soft);
  background: var(--surface-2);
  font-size: 8px;
  font-style: normal;
  font-variant-numeric: tabular-nums;
}

.store-management-category-card > small {
  min-height: 38px;
  color: var(--muted);
  font-size: 9px;
  line-height: 1.45;
}

.store-management-category-tools {
  display: flex;
  min-height: 46px;
  align-content: flex-start;
  flex-wrap: wrap;
  gap: 5px;
}

.store-management-category-tools i {
  padding: 4px 6px;
  border: 1px solid var(--line);
  border-radius: 7px;
  color: var(--muted);
  background: var(--surface-2);
  font-size: 7px;
  font-style: normal;
}

.store-management-category-action {
  display: inline-flex;
  min-height: 32px;
  align-items: center;
  justify-content: center;
  padding: 0 9px;
  border-radius: 8px;
  color: var(--text-soft);
  background: var(--surface-3);
  font-size: 9px;
  font-weight: 780;
}

.store-management-category-card.is-active
  .store-management-category-action {
  color: var(--accent-ink);
  background: var(--accent);
}

.store-management-selection {
  display: grid;
  grid-template-columns: auto auto minmax(0, 1fr);
  align-items: baseline;
  gap: 7px 12px;
  padding: 11px 14px;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: var(--surface);
}

.store-management-selection span {
  color: var(--accent);
  font-size: 8px;
  font-weight: 850;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.store-management-selection strong {
  font-size: 12px;
}

.store-management-selection small {
  overflow: hidden;
  color: var(--muted);
  font-size: 9px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.appearance-workspace-panels,
.appearance-component-preview {
  display: grid;
  min-width: 0;
  gap: 20px;
}

.palette-presets-panel {
  display: grid;
  gap: 22px;
  padding: clamp(20px, 3vw, 32px);
  border: 1px solid var(--line);
  border-radius: calc(var(--radius) + 3px);
  background:
    radial-gradient(
      circle at 88% 4%,
      color-mix(in srgb, var(--accent) 10%, transparent),
      transparent 30%
    ),
    var(--surface);
}

.palette-presets-panel > header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
}

.palette-presets-panel h2 {
  max-width: 720px;
  margin: 8px 0 9px;
  font-size: clamp(28px, 4vw, 48px);
  letter-spacing: -0.055em;
  line-height: 1;
  text-wrap: balance;
}

.palette-presets-panel header p {
  max-width: 660px;
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.65;
}

.palette-current-status {
  display: grid;
  min-width: 178px;
  gap: 3px;
  padding: 13px 15px;
  border: 1px solid color-mix(in srgb, var(--accent) 25%, var(--line));
  border-radius: 12px;
  background: color-mix(in srgb, var(--accent) 6%, var(--surface-2));
}

.palette-current-status span,
.palette-current-status small {
  color: var(--muted);
  font-size: 8px;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.palette-current-status strong {
  color: var(--text);
  font-size: 13px;
}

.palette-preset-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(220px, 1fr));
  gap: 13px;
}

.palette-preset-card {
  display: grid;
  min-width: 0;
  align-content: start;
  gap: 14px;
  padding: 12px;
  overflow: hidden;
  text-align: left;
  border: 1px solid var(--line);
  border-radius: calc(var(--radius) + 1px);
  color: var(--text);
  background: color-mix(in srgb, var(--surface-2) 72%, var(--surface));
  box-shadow: 0 14px 34px color-mix(in srgb, var(--shadow) 18%, transparent);
  cursor: pointer;
  transition:
    transform 180ms ease,
    border-color 180ms ease,
    background-color 180ms ease,
    box-shadow 180ms ease;
}

.palette-preset-card:hover:not(:disabled) {
  transform: translateY(-2px);
  border-color: color-mix(in srgb, var(--accent) 48%, var(--line));
  background: color-mix(in srgb, var(--accent) 5%, var(--surface-2));
  box-shadow: 0 20px 46px color-mix(in srgb, var(--shadow) 28%, transparent);
}

.palette-preset-card:active:not(:disabled) {
  transform: translateY(0);
}

.palette-preset-card:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}

.palette-preset-card:disabled {
  cursor: default;
  opacity: 0.68;
}

.palette-preset-card.is-active {
  border-color: color-mix(in srgb, var(--accent) 62%, var(--line));
  opacity: 1;
  box-shadow:
    inset 0 0 0 1px color-mix(in srgb, var(--accent) 20%, transparent),
    0 18px 45px color-mix(in srgb, var(--accent) 10%, transparent);
}

.palette-preset-preview {
  position: relative;
  display: grid;
  min-height: 132px;
  grid-template-columns: 1.1fr 0.72fr;
  grid-template-rows: 1fr 0.65fr;
  gap: 7px;
  overflow: hidden;
  padding: 12px;
  border-radius: 11px;
}

.palette-preset-preview::after {
  position: absolute;
  inset: 0;
  border: 1px solid rgb(255 255 255 / 12%);
  border-radius: inherit;
  box-shadow: inset 0 1px 0 rgb(255 255 255 / 8%);
  content: "";
  pointer-events: none;
}

.palette-preset-preview > i {
  display: block;
  min-width: 0;
  min-height: 0;
  border-radius: 8px;
  box-shadow: 0 9px 24px rgb(0 0 0 / 18%);
}

.palette-preset-preview > i:first-child {
  grid-row: 1 / 3;
}

.palette-preset-copy {
  display: grid;
  gap: 5px;
}

.palette-preset-copy small {
  color: var(--accent);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.palette-preset-copy strong {
  font-size: 16px;
  letter-spacing: -0.02em;
}

.palette-preset-copy > span {
  min-height: 40px;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.5;
}

.palette-preset-swatches {
  display: flex;
  gap: 6px;
}

.palette-preset-swatches i {
  width: 20px;
  height: 20px;
  border: 2px solid color-mix(in srgb, var(--text) 14%, transparent);
  border-radius: 7px;
}

.palette-preset-action {
  display: inline-flex;
  min-height: 38px;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 0 12px;
  border-radius: 9px;
  color: var(--accent-ink);
  background: var(--accent);
  font-size: 10px;
  font-weight: 820;
}

.palette-preset-card.is-active .palette-preset-action {
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 12%, var(--surface-3));
}

.palette-presets-state {
  display: grid;
  min-height: 260px;
  place-content: center;
  justify-items: center;
  gap: 8px;
  padding: 28px;
  border: 1px dashed var(--line-strong);
  border-radius: var(--radius);
  color: var(--muted);
  background: var(--surface);
  text-align: center;
}

.palette-presets-state strong {
  color: var(--text);
}

.palette-presets-state span {
  max-width: 480px;
  font-size: 11px;
  line-height: 1.55;
}

.palette-presets-state.is-error > svg {
  color: var(--danger);
}


.appearance-component-preview {
  padding: clamp(18px, 2.5vw, 30px);
  border: 1px solid var(--line);
  border-radius: calc(var(--radius) + 3px);
  background: var(--surface);
}

.appearance-component-preview > header nav {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.appearance-component-preview > header nav :is(a, span) {
  padding: 8px 10px;
  border: 1px solid var(--line);
  border-radius: 8px;
  color: var(--text-soft);
  font-size: 10px;
}

.appearance-preview-grid {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  gap: 14px;
}

.appearance-preview-grid > article {
  min-width: 0;
  padding: 15px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface-2);
}

.appearance-preview-card {
  display: grid;
  grid-column: span 7;
  grid-template-columns: 130px minmax(0, 1fr);
  gap: 16px;
}

.appearance-preview-cover {
  display: grid;
  aspect-ratio: 2 / 3;
  place-items: center;
  border-radius: 10px;
  background: var(--brand-gradient);
  color: var(--accent-ink);
  font-size: 10px;
  font-weight: 800;
}

.appearance-preview-card h4,
.appearance-preview-card p,
.appearance-preview-dialog h4,
.appearance-preview-dialog p {
  margin: 7px 0;
}

.appearance-preview-card p,
.appearance-preview-dialog p {
  color: var(--muted);
  font-size: 10px;
  line-height: 1.5;
}

.appearance-preview-chapter {
  display: flex;
  grid-column: span 5;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.appearance-preview-chapter > div {
  display: grid;
  gap: 4px;
}

.appearance-preview-chapter span,
.appearance-preview-chapter em {
  color: var(--muted);
  font-size: 9px;
  font-style: normal;
}

.appearance-preview-reader {
  display: grid;
  min-height: 190px;
  grid-column: span 7;
  place-items: center;
  align-content: space-between;
  background: #02060b !important;
}

.appearance-preview-reader > div,
.appearance-preview-dialog > div {
  display: flex;
  align-items: center;
  gap: 9px;
}

.appearance-preview-reader > div span {
  padding: 7px 10px;
  border: 1px solid var(--line);
  border-radius: 7px;
  color: var(--text-soft);
  font-size: 9px;
}

.appearance-preview-dialog {
  grid-column: span 5;
}

.appearance-preview-mobile {
  display: grid;
  grid-column: span 4;
  justify-items: start;
  gap: 8px;
}

.appearance-preview-mobile span:not(:first-child) {
  width: 100%;
  padding: 8px;
  border: 1px solid var(--line);
  border-radius: 7px;
  font-size: 9px;
}

.site-configuration-panel,
.theme-settings-panel {
  min-width: 0;
}

.site-configuration-panel > header {
  gap: 20px;
}

.site-identity-fields textarea {
  min-height: 90px;
  resize: vertical;
}

.site-media-grid > article {
  min-width: 0;
}

.site-media-grid > article > div:last-child {
  display: flex;
  min-width: 0;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.site-media-grid > article > div:last-child > strong,
.site-media-grid > article > div:last-child > p,
.site-media-grid > article > div:last-child > small {
  width: 100%;
}

.site-social-list {
  display: grid;
  gap: 10px;
}

.site-social-list > article {
  display: grid;
  min-width: 0;
  grid-template-columns: auto repeat(3, minmax(130px, 1fr)) auto auto auto;
  align-items: end;
  gap: 10px;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface-2);
}

.site-social-list > article > svg {
  align-self: center;
}

.site-social-order {
  display: flex;
  gap: 4px;
}

.site-social-order button,
.site-social-list > article > button {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: var(--surface);
  cursor: pointer;
}

.site-social-order button:disabled,
.site-social-list > article > button:disabled {
  opacity: 0.38;
  cursor: not-allowed;
}

.site-social-preview {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 14px;
  padding: 14px;
  border: 1px dashed var(--line-strong);
  border-radius: var(--radius);
}

.site-social-preview a {
  display: inline-flex;
  min-height: 38px;
  align-items: center;
  gap: 7px;
  padding: 0 11px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--surface-2);
  font-size: 10px;
}

.site-social-preview a span {
  color: var(--accent);
  font-size: 8px;
}

.theme-token-groups {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
}

.theme-token-groups fieldset {
  display: grid;
  min-width: 0;
  align-content: start;
  gap: 14px;
  margin: 0;
  padding: 16px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface-2);
}

.theme-token-groups legend {
  padding-inline: 6px;
  color: var(--text);
  font-size: 11px;
  font-weight: 800;
}

.theme-preview em {
  display: inline-flex;
  min-height: 40px;
  align-items: center;
  padding: 0 13px;
  border-radius: var(--site-button-radius, var(--radius-small));
  background: var(--brand-gradient);
  color: var(--accent-ink);
  font-size: 10px;
  font-style: normal;
  font-weight: 800;
}

.ops-grouped-nav {
  display: grid;
  min-height: 0;
  align-content: start;
  gap: 7px;
  overflow-y: auto;
}

.ops-nav-group {
  display: grid;
  gap: 3px;
}

.ops-nav-group-toggle {
  min-height: 30px !important;
  padding: 0 9px !important;
  color: var(--muted) !important;
  font-size: 8px !important;
  font-weight: 800 !important;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.ops-nav-group-toggle svg {
  margin-left: auto;
  transition: transform 160ms ease;
}

.ops-nav-group-toggle[aria-expanded="true"] svg {
  transform: rotate(180deg);
}

.ops-nav-group-items {
  display: grid;
  gap: 2px;
}

.ops-nav-group-items[hidden] {
  display: none;
}

.store-section-nav a[aria-current="page"] {
  border-color: color-mix(in srgb, var(--accent) 50%, var(--line));
  background: color-mix(in srgb, var(--accent) 11%, var(--surface-2));
  color: var(--text);
}

.store-section-nav a {
  gap: 7px;
}

.comment-reaction-summary button span img,
.comment-reaction-picker button span img {
  width: 22px;
  height: 22px;
  object-fit: contain;
}

.comment-team-badge {
  width: 19px;
  height: 19px;
  object-fit: contain;
  border-radius: 5px;
}

.comment-team-effect {
  position: relative;
  border-color: color-mix(
    in srgb,
    var(--comment-team-accent) var(--comment-team-border-mix),
    var(--line)
  );
}

.comment-team-effect-border {
  border-left: 3px solid var(--comment-team-accent);
}

.comment-team-effect-glow {
  box-shadow: 0 0 var(--comment-team-glow)
    color-mix(in srgb, var(--comment-team-accent) 22%, transparent);
}

.comment-team-effect-accent {
  background: color-mix(
    in srgb,
    var(--comment-team-accent) var(--comment-team-background-mix),
    var(--surface)
  );
}

.comment-team-effect-sparkle::after {
  content: "✦";
  color: var(--comment-team-accent);
  font-size: 12px;
  position: absolute;
  top: 10px;
  right: 12px;
}

.comment-team-effect-verified .comment-role {
  border-color: var(--comment-team-accent);
  color: var(--comment-team-accent);
}

.comment-team-effect-motion {
  animation: team-comment-breathe 4s ease-in-out infinite;
}

@keyframes team-comment-breathe {
  0%,
  100% {
    box-shadow: 0 0 0 color-mix(in srgb, var(--comment-team-accent) 0%, transparent);
  }
  50% {
    box-shadow: 0 0 18px color-mix(in srgb, var(--comment-team-accent) 18%, transparent);
  }
}

@media (max-width: 1180px) {
  .store-management-groups {
    grid-template-columns: 1fr;
  }

  .store-management-category-grid {
    grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
  }

  .palette-preset-grid {
    grid-template-columns: repeat(2, minmax(220px, 1fr));
  }

  .audit-filter-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .site-social-list > article {
    grid-template-columns: auto repeat(2, minmax(150px, 1fr)) auto auto;
  }

  .site-social-list > article > label:nth-of-type(3) {
    grid-column: 2;
  }
}

@media (max-width: 900px) {
  .admin-master-detail {
    grid-template-columns: 1fr;
  }

  .taxonomy-layout {
    grid-template-columns: 1fr;
  }

  .admin-record-browser,
  .admin-record-list {
    max-height: 320px;
    position: static;
  }

  .admin-form-grid,
  .theme-token-groups {
    grid-template-columns: 1fr;
  }

  .admin-media-grid {
    grid-template-columns: 1fr;
  }

  .audit-event-table {
    display: grid;
    gap: 10px;
    overflow: visible;
    border: 0;
    background: transparent;
  }

  .audit-event-head {
    display: none;
  }

  .audit-event-table > button {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px;
    border: 1px solid var(--line);
    border-radius: var(--radius);
    background: var(--surface);
  }

  .audit-event-table > button > *::before {
    display: block;
    margin-bottom: 3px;
    color: var(--muted);
    font-size: 7px;
    font-weight: 800;
    letter-spacing: 0.06em;
    text-transform: uppercase;
  }

  .audit-event-table > button time::before {
    content: "Timestamp";
  }

  .audit-event-table > button > span:nth-of-type(1)::before {
    content: "Actor";
  }

  .audit-event-table > button > span:nth-of-type(2)::before {
    content: "Action";
  }

  .audit-event-table > button > span:nth-of-type(3)::before {
    content: "Target";
  }

  .audit-result::before {
    content: "Result";
  }

  .appearance-preview-card,
  .appearance-preview-chapter,
  .appearance-preview-reader,
  .appearance-preview-dialog,
  .appearance-preview-mobile {
    grid-column: span 12;
  }

  .site-social-list > article {
    grid-template-columns: auto minmax(0, 1fr) auto auto;
  }

  .site-social-list > article > label {
    grid-column: 2 / -1;
  }

  .site-social-list > article > .site-social-enabled {
    grid-column: 2;
  }
}

@media (max-width: 680px) {
  .admin-workspace {
    gap: 16px;
  }

  .admin-workspace-header,
  .store-management-heading,
  .palette-presets-panel > header,
  .appearance-component-preview > header,
  .site-configuration-panel > header {
    align-items: stretch;
    flex-direction: column;
  }

  .admin-primary-action,
  .admin-header-actions {
    width: 100%;
    justify-content: stretch;
  }

  .admin-primary-action > *,
  .admin-header-actions > * {
    flex: 1;
  }

  .admin-subnav {
    margin-inline: -4px;
    border-right: 0;
    border-left: 0;
    border-radius: 0;
  }

  .admin-form-section {
    padding: 16px;
  }

  .admin-form-grid,
  .admin-review-grid,
  .admin-summary-grid,
  .audit-filter-grid {
    grid-template-columns: 1fr;
  }

  .admin-media-field {
    grid-template-columns: 1fr;
  }

  .taxonomy-create-row,
  .taxonomy-editor {
    align-items: stretch;
    grid-template-columns: 1fr;
  }

  .taxonomy-create-row {
    flex-direction: column;
  }

  .taxonomy-create-row > * {
    width: 100%;
  }

  .admin-media-preview {
    min-height: 190px;
  }

  .admin-sticky-actions {
    align-items: stretch;
    flex-direction: column;
    bottom: 8px;
  }

  .admin-sticky-actions > * {
    width: 100%;
  }

  .admin-sticky-actions small {
    order: -1;
    text-align: center;
  }

  .store-management-category-grid {
    grid-template-columns: 1fr;
  }

  .store-management-selection {
    grid-template-columns: auto 1fr;
  }

  .store-management-selection small {
    grid-column: 1 / -1;
    white-space: normal;
  }

  .palette-preset-grid {
    grid-template-columns: 1fr;
  }

  .palette-current-status {
    width: 100%;
  }

  .audit-filter-actions,
  .admin-confirm-dialog > div,
  .admin-pagination {
    align-items: stretch;
    flex-direction: column;
  }

  .audit-filter-actions > *,
  .admin-confirm-dialog > div > *,
  .admin-pagination > button {
    width: 100%;
  }

  .admin-pagination > span {
    margin: 0 0 4px;
    text-align: center;
  }

  .audit-event-table > button {
    grid-template-columns: 1fr;
  }

  .audit-detail-drawer dl {
    grid-template-columns: 1fr;
  }

  .appearance-preview-card {
    grid-template-columns: 96px minmax(0, 1fr);
  }

  .commerce-offer-preview {
    grid-template-columns: 1fr;
  }

  .site-social-list > article {
    grid-template-columns: auto minmax(0, 1fr) auto;
  }

  .site-social-list > article > label,
  .site-social-list > article > .site-social-enabled {
    grid-column: 2 / -1;
  }

  .site-social-order {
    grid-column: 2;
  }

  .site-social-list > article > button {
    grid-column: 3;
  }

  .ops-nav-group-toggle {
    justify-content: center;
    padding: 0 !important;
  }

  .ops-nav-group-toggle span,
  .ops-nav-group-toggle svg {
    display: none;
  }
}

.chapter-reactions-box.is-status > div:last-child {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: .35rem;
  margin-top: 0;
  overflow: visible;
}

.chapter-reactions-box.is-status > button {
  display: inline-flex;
  width: max-content;
  min-height: 2.75rem;
  justify-self: center;
  flex-direction: row;
  padding: .6rem .9rem;
  border-color: var(--line);
  border-radius: var(--site-button-radius, 10px);
  background: var(--surface-strong);
}

@media (prefers-reduced-motion: reduce) {
  .comment-team-effect-motion {
    animation: none;
  }
}

/* Store, editorial, and publishing workspace */
.panel-header {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 16px;
  align-items: start;
}

.panel-header > span:first-child {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--accent) 38%, var(--line));
  border-radius: 13px;
  background: color-mix(in srgb, var(--accent) 12%, var(--surface));
  color: var(--accent);
}

.panel-header > div:nth-child(2) {
  display: grid;
  gap: 5px;
  min-width: 0;
}

.panel-header p,
.panel-header h1 {
  margin: 0;
}

.panel-header p {
  color: var(--accent);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.panel-header h1 {
  font-size: clamp(24px, 3vw, 38px);
  line-height: 1.05;
}

.panel-header > div:nth-child(2) > span {
  max-width: 740px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.65;
}

.store-admin-header-actions,
.store-admin-collection-actions,
.store-admin-collection-editor-actions,
.editorial-actions,
.review-state-actions {
  display: flex;
  gap: 8px;
  align-items: center;
}

.store-admin-message,
.store-admin-error {
  display: flex;
  gap: 9px;
  align-items: center;
  margin: 0;
  padding: 12px 14px;
  border: 1px solid color-mix(in srgb, var(--accent) 35%, var(--line));
  border-radius: var(--radius-small);
  background: color-mix(in srgb, var(--accent) 8%, var(--surface));
  color: var(--text);
  font-size: 12px;
}

.store-admin-error {
  border-color: color-mix(in srgb, var(--danger) 42%, var(--line));
  background: color-mix(in srgb, var(--danger) 7%, var(--surface));
  color: var(--danger);
}

.store-admin-form,
.store-admin-editor,
.store-admin-collections,
.store-admin-items,
.store-test-coins,
.editorial-picker,
.editorial-pick-list,
.workspace-live-list,
.workspace-settings-form {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
}

.store-admin-form {
  display: grid;
  gap: 18px;
  padding: 20px;
}

.store-admin-form h2,
.store-admin-items h2,
.store-admin-collection-heading h2 {
  margin: 0;
  font-size: 17px;
}

.store-admin-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.store-admin-form-grid > label,
.store-admin-editor > label,
.store-test-coins > label,
.editorial-picker > label,
.editorial-fields > label,
.workspace-settings-form > label:not(.workspace-settings-check) {
  display: grid;
  gap: 7px;
  min-width: 0;
  color: var(--muted);
  font-size: 10px;
  font-weight: 760;
  letter-spacing: 0.03em;
}

.store-admin-form-grid :is(input, select, textarea),
.store-test-coins input,
.editorial-picker :is(input, select),
.editorial-fields :is(input, textarea),
.workspace-settings-form :is(input, select) {
  width: 100%;
  min-height: 42px;
  padding: 10px 12px;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius-small);
  outline: none;
  background: var(--surface-2);
  color: var(--text);
  font: inherit;
  letter-spacing: 0;
}

.store-admin-form-grid textarea,
.editorial-fields textarea {
  min-height: 90px;
  resize: vertical;
}

.store-admin-form-grid :is(input, select, textarea):focus,
.store-test-coins input:focus,
.editorial-picker :is(input, select):focus,
.editorial-fields :is(input, textarea):focus,
.workspace-settings-form :is(input, select):focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 15%, transparent);
}

.store-admin-wide {
  grid-column: 1 / -1;
}

.store-admin-check,
.workspace-settings-check {
  display: flex !important;
  min-height: 42px;
  flex-direction: row !important;
  gap: 9px !important;
  align-items: center;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface-2);
  color: var(--text) !important;
  font-size: 11px !important;
}

.store-admin-check input,
.workspace-settings-check input {
  width: 16px !important;
  min-height: 16px !important;
  margin: 0;
  accent-color: var(--accent);
}

.store-admin-layout {
  display: grid;
  grid-template-columns: minmax(310px, 0.86fr) minmax(420px, 1.14fr);
  gap: 18px;
  align-items: start;
}

.store-admin-catalog {
  display: grid;
  gap: 18px;
  min-width: 0;
}

.store-admin-collections,
.store-admin-items {
  overflow: hidden;
  padding: 18px;
}

.store-admin-collection-heading {
  display: flex;
  gap: 14px;
  align-items: start;
  justify-content: space-between;
  margin-bottom: 14px;
}

.store-admin-collection-heading p {
  max-width: 520px;
  margin: 5px 0 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.55;
}

.store-admin-collection-heading > span {
  flex: 0 0 auto;
  padding: 5px 8px;
  border-radius: 999px;
  background: var(--surface-2);
  color: var(--muted);
  font-size: 9px;
  font-weight: 800;
  text-transform: uppercase;
}

.store-admin-collection-list {
  display: grid;
  gap: 9px;
}

.store-admin-collection-list > article {
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface-2);
}

.store-admin-collection-list > article.is-editing {
  border-color: color-mix(in srgb, var(--accent) 55%, var(--line));
}

.store-admin-collection-summary {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 12px;
  align-items: center;
  padding: 12px;
}

.store-admin-collection-summary > div:first-child {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.store-admin-collection-summary strong {
  font-size: 12px;
}

.store-admin-collection-summary span,
.store-admin-collection-summary small {
  overflow: hidden;
  color: var(--muted);
  font-size: 9px;
  line-height: 1.45;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.store-admin-collection-actions button,
.store-admin-editor > header button,
.editorial-actions button {
  display: inline-flex;
  min-width: 34px;
  min-height: 34px;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 0 9px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: var(--surface);
  color: var(--text);
  cursor: pointer;
  font-size: 10px;
}

.store-admin-collection-editor {
  border-width: 1px 0 0;
  border-radius: 0;
  background: color-mix(in srgb, var(--surface-2) 92%, var(--accent) 8%);
}

.store-admin-items {
  display: grid;
  gap: 15px;
}

.store-admin-items > div {
  display: grid;
  gap: 7px;
}

.store-admin-items h3 {
  margin: 5px 0 2px;
  color: var(--muted);
  font-size: 10px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.store-admin-items > div > button {
  display: grid;
  grid-template-columns: 46px minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
  width: 100%;
  min-height: 58px;
  padding: 7px;
  border: 1px solid transparent;
  border-radius: var(--radius-small);
  background: transparent;
  color: var(--text);
  cursor: pointer;
  text-align: start;
}

.store-admin-items > div > button:hover,
.store-admin-items > div > button.is-active {
  border-color: color-mix(in srgb, var(--accent) 45%, var(--line));
  background: color-mix(in srgb, var(--accent) 8%, var(--surface-2));
}

.store-admin-items > div > button > span {
  display: grid;
  width: 46px;
  height: 46px;
  place-items: center;
  overflow: hidden;
  border-radius: 10px;
  font-size: 18px;
}

.store-admin-items > div > button img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.store-admin-items > div > button > div {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.store-admin-items > div > button strong,
.store-admin-items > div > button small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.store-admin-items > div > button strong {
  font-size: 11px;
}

.store-admin-items > div > button small,
.store-admin-items > div > button em {
  color: var(--muted);
  font-size: 9px;
  font-style: normal;
}

.store-admin-editor {
  position: sticky;
  top: 18px;
  display: grid;
  gap: 18px;
  overflow: hidden;
  padding: 20px;
}

.store-admin-editor > header,
.store-admin-editor > footer {
  display: flex;
  gap: 12px;
  align-items: center;
  justify-content: space-between;
}

.store-admin-editor > header > div:first-child {
  display: grid;
  gap: 3px;
}

.store-admin-editor > header span,
.store-admin-editor > header small {
  color: var(--muted);
  font-size: 9px;
  font-weight: 760;
  text-transform: uppercase;
}

.store-admin-editor > header h2 {
  margin: 0;
  font-size: 20px;
}

.store-admin-editor > header > div:last-child {
  display: flex;
  gap: 6px;
}

.store-admin-preview {
  position: relative;
  display: grid;
  min-height: 220px;
  place-items: center;
  overflow: hidden;
  border-radius: var(--radius);
}

.store-admin-preview > img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.store-admin-preview > strong {
  font-size: 58px;
}

.store-admin-preview > label {
  position: absolute;
  right: 10px;
  bottom: 10px;
  display: inline-flex;
  min-height: 38px;
  align-items: center;
  gap: 7px;
  padding: 0 12px;
  border-radius: 999px;
  background: rgb(3 12 25 / 78%);
  color: #fff;
  cursor: pointer;
  font-size: 10px;
  font-weight: 800;
  backdrop-filter: blur(12px);
}

.store-admin-preview input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
}

.button-danger {
  border-color: color-mix(in srgb, var(--danger) 48%, var(--line)) !important;
  color: var(--danger) !important;
}

.store-test-coins {
  display: grid;
  grid-template-columns: minmax(240px, 1.3fr) repeat(3, minmax(130px, 0.7fr)) auto;
  gap: 12px;
  align-items: end;
  padding: 18px;
}

.store-test-coins > div {
  display: flex;
  gap: 12px;
  align-items: center;
}

.store-test-coins > div > svg {
  flex: 0 0 auto;
  color: var(--accent);
}

.store-test-coins > div span {
  display: grid;
  gap: 3px;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.45;
}

.store-test-coins > div strong {
  color: var(--text);
  font-size: 12px;
}

.store-admin-loading,
.store-admin-empty {
  display: grid;
  min-height: 130px;
  place-items: center;
  align-content: center;
  gap: 8px;
  padding: 22px;
  color: var(--muted);
  text-align: center;
}

.store-admin-loading {
  display: flex;
}

.store-admin-empty strong {
  color: var(--text);
}

.store-admin-empty span {
  max-width: 380px;
  font-size: 11px;
  line-height: 1.55;
}

.editorial-picker {
  display: grid;
  grid-template-columns: minmax(180px, 0.75fr) minmax(240px, 1.25fr) auto;
  gap: 12px;
  align-items: end;
  padding: 16px;
}

.editorial-pick-list {
  display: grid;
  overflow: hidden;
}

.editorial-pick-list > article {
  display: grid;
  grid-template-columns: 44px 72px minmax(0, 1fr) auto;
  gap: 14px;
  align-items: center;
  padding: 14px;
  border-bottom: 1px solid var(--line);
}

.editorial-pick-list > article:last-child {
  border-bottom: 0;
}

.editorial-order {
  color: color-mix(in srgb, var(--accent) 75%, var(--text));
  font-family: var(--font-display);
  font-size: 17px;
  font-weight: 900;
}

.editorial-cover {
  display: grid;
  width: 62px;
  aspect-ratio: var(--cover-ratio);
  place-items: center;
  overflow: hidden;
  border-radius: 9px;
  background: var(--surface-2);
  color: var(--muted);
}

.editorial-cover img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.editorial-fields {
  display: grid;
  grid-template-columns: minmax(150px, 0.55fr) minmax(220px, 1fr);
  gap: 10px;
  min-width: 0;
}

.editorial-fields > header {
  grid-column: 1 / -1;
  display: flex;
  gap: 12px;
  align-items: center;
  justify-content: space-between;
}

.editorial-fields > header > div {
  display: grid;
  gap: 3px;
  min-width: 0;
}

.editorial-fields > header strong,
.editorial-fields > header small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.editorial-fields > header small {
  color: var(--muted);
  font-size: 9px;
}

.editorial-fields > header label {
  display: flex;
  flex: 0 0 auto;
  gap: 6px;
  align-items: center;
  font-size: 10px;
}

.editorial-actions {
  flex-direction: column;
}

.editorial-actions .is-danger {
  color: var(--danger);
}

.team-access-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
}

.team-access-list {
  display: grid;
  gap: 7px;
  max-height: 270px;
  overflow: auto;
  padding-top: 4px;
}

.team-access-list > span {
  display: grid;
  gap: 2px;
  padding: 9px 10px;
  border-radius: 9px;
  background: var(--surface-2);
  color: var(--muted);
  font-size: 9px;
  line-height: 1.45;
}

.team-access-list strong {
  color: var(--text);
  font-size: 10px;
}

.review-state-actions {
  flex-wrap: wrap;
  justify-content: flex-end;
}

.review-state-actions button {
  display: inline-flex;
  min-height: 34px;
  align-items: center;
  gap: 5px;
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: var(--surface-2);
  color: var(--text);
  cursor: pointer;
  font-size: 10px;
  font-weight: 750;
}

.workspace-live-metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.workspace-live-metrics article,
.workspace-analytics-legend article {
  display: grid;
  gap: 7px;
  padding: 15px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface);
}

.workspace-live-metrics span,
.workspace-analytics-legend span {
  color: var(--muted);
  font-size: 9px;
  font-weight: 760;
  text-transform: uppercase;
}

.workspace-live-metrics strong,
.workspace-analytics-legend strong {
  font-size: 22px;
}

.workspace-live-list {
  display: grid;
  overflow: hidden;
}

.workspace-live-list h2 {
  margin: 0;
  padding: 16px;
  border-bottom: 1px solid var(--line);
  font-size: 16px;
}

.workspace-live-list > article,
.workspace-series-table > article {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  gap: 12px;
  align-items: center;
  padding: 13px 15px;
  border-bottom: 1px solid var(--line);
}

.workspace-live-list > article:last-child,
.workspace-series-table > article:last-child {
  border-bottom: 0;
}

.workspace-live-list article > div,
.workspace-series-table article > div {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.workspace-live-list article span,
.workspace-series-table article span,
.workspace-live-list article em,
.workspace-series-table article em {
  color: var(--muted);
  font-size: 10px;
  font-style: normal;
}

.workspace-live-list article a,
.workspace-series-table article a,
.workspace-comment-list article a {
  display: inline-flex;
  min-height: 34px;
  align-items: center;
  gap: 5px;
  color: var(--accent);
  font-size: 10px;
  font-weight: 760;
}

.workspace-series-table {
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
}

.workspace-series-table > article {
  grid-template-columns: minmax(0, 1fr) auto auto auto;
}

.workspace-series-table em {
  padding: 5px 8px;
  border-radius: 999px;
  background: var(--surface-2);
  font-weight: 760;
}

.workspace-series-table em[data-status="active"] {
  background: color-mix(in srgb, var(--success) 14%, var(--surface));
  color: var(--success);
}

.workspace-comment-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.workspace-comment-list article {
  display: grid;
  gap: 10px;
  padding: 15px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface);
}

.workspace-comment-list article header,
.workspace-comment-list article footer {
  display: flex;
  gap: 10px;
  align-items: center;
  justify-content: space-between;
}

.workspace-comment-list article :is(header span, footer span) {
  color: var(--muted);
  font-size: 9px;
}

.workspace-comment-list article p {
  margin: 0;
  color: var(--text-soft);
  font-size: 11px;
  line-height: 1.6;
}

.workspace-analytics {
  display: grid;
  gap: 18px;
}

.workspace-analytics-chart {
  display: flex;
  height: 230px;
  align-items: end;
  gap: 5px;
  padding: 18px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background:
    linear-gradient(to top, var(--line) 1px, transparent 1px) 0 0 / 100% 25%,
    var(--surface);
}

.workspace-analytics-chart > span {
  min-width: 4px;
  flex: 1 1 0;
  border-radius: 5px 5px 2px 2px;
  background: linear-gradient(to top, var(--accent-strong), var(--accent));
}

.workspace-analytics-legend {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.workspace-settings-form {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
  max-width: 820px;
  padding: 20px;
}

.workspace-settings-form > .button {
  justify-self: start;
}

@media (max-width: 1120px) {
  .store-admin-layout {
    grid-template-columns: 1fr;
  }

  .store-admin-editor {
    position: static;
  }

  .store-test-coins {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .store-test-coins > div {
    grid-column: 1 / -1;
  }

  .store-test-coins > button {
    grid-column: 1 / -1;
    justify-self: start;
  }

  .editorial-pick-list > article {
    grid-template-columns: 36px 62px minmax(0, 1fr);
  }

  .editorial-actions {
    grid-column: 3;
    flex-direction: row;
  }
}

@media (max-width: 760px) {
  .panel-header {
    grid-template-columns: auto minmax(0, 1fr);
  }

  .panel-header > .store-admin-header-actions,
  .panel-header > .button {
    grid-column: 1 / -1;
    width: 100%;
  }

  .store-admin-header-actions > .button {
    flex: 1 1 0;
  }

  .store-admin-form-grid,
  .editorial-fields,
  .team-access-grid,
  .workspace-comment-list,
  .workspace-settings-form {
    grid-template-columns: 1fr;
  }

  .store-admin-wide,
  .editorial-fields > header {
    grid-column: auto;
  }

  .store-test-coins,
  .editorial-picker {
    grid-template-columns: 1fr;
  }

  .store-test-coins > div,
  .store-test-coins > button {
    grid-column: auto;
  }

  .editorial-picker > .button,
  .store-test-coins > .button {
    width: 100%;
  }

  .editorial-pick-list > article {
    grid-template-columns: 34px 56px minmax(0, 1fr);
    gap: 10px;
  }

  .editorial-fields {
    grid-column: 3;
  }

  .editorial-actions {
    grid-column: 1 / -1;
    justify-content: flex-end;
  }

  .workspace-live-metrics,
  .workspace-analytics-legend {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .workspace-live-list > article,
  .workspace-series-table > article {
    grid-template-columns: minmax(0, 1fr) auto;
  }

  .workspace-live-list article > a,
  .workspace-series-table article > a {
    grid-column: 1 / -1;
    justify-self: start;
  }
}

@media (max-width: 480px) {
  .panel-header > span:first-child {
    width: 38px;
    height: 38px;
  }

  .panel-header h1 {
    font-size: 24px;
  }

  .store-admin-header-actions,
  .store-admin-editor > footer {
    align-items: stretch;
    flex-direction: column;
  }

  .store-admin-header-actions > .button,
  .store-admin-editor > footer > .button {
    width: 100%;
  }

  .store-admin-collection-summary {
    grid-template-columns: 1fr;
  }

  .store-admin-collection-actions {
    justify-content: flex-end;
  }

  .store-admin-editor,
  .store-admin-form,
  .store-admin-collections,
  .store-admin-items,
  .workspace-settings-form {
    padding: 14px;
  }

  .store-admin-preview {
    min-height: 180px;
  }

  .editorial-pick-list > article {
    grid-template-columns: 32px 50px minmax(0, 1fr);
    padding: 11px;
  }

  .editorial-cover {
    width: 50px;
  }

  .editorial-fields > header {
    align-items: start;
    flex-direction: column;
  }

  .workspace-live-metrics,
  .workspace-analytics-legend {
    grid-template-columns: 1fr 1fr;
  }

  .workspace-live-metrics strong,
  .workspace-analytics-legend strong {
    font-size: 18px;
  }

  .workspace-comment-list article footer {
    align-items: flex-start;
    flex-direction: column;
  }
}

.footer-group {
  min-width: 0;
}

.footer-group-toggle {
  display: flex;
  width: 100%;
  align-items: center;
  justify-content: space-between;
  margin: 0 0 14px;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--text);
  cursor: pointer;
  font: inherit;
  font-size: 12px;
  font-weight: 750;
  text-align: start;
}

.footer-group-toggle > span {
  color: var(--muted);
  font-size: 17px;
  font-weight: 500;
}

.footer-group > div {
  display: grid;
  gap: 11px;
}

.footer-group-toggle:focus-visible {
  border-radius: 5px;
  outline: 2px solid var(--accent);
  outline-offset: 5px;
}

@media (max-width: 760px) {
  .footer-group {
    border-bottom: 1px solid var(--line);
  }

  .footer-group-toggle {
    min-height: 50px;
    margin: 0;
    padding: 0 3px;
  }

  .footer-group > div {
    padding: 0 0 17px;
  }
}

/* Site identity, publishing, and insight controls */
.brand-logo-image {
  width: 29px;
  height: 29px;
  flex: 0 0 29px;
  border-radius: 9px;
  object-fit: contain;
}

.store-section-nav {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  padding-block: 18px 4px;
  scrollbar-width: none;
}

.store-section-nav::-webkit-scrollbar {
  display: none;
}

.store-section-nav a {
  display: inline-flex;
  min-height: 44px;
  flex: 0 0 auto;
  align-items: center;
  padding: 0 16px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--surface);
  color: var(--text-soft);
  font-size: 11px;
  font-weight: 780;
  transition:
    border-color 160ms ease,
    background 160ms ease,
    color 160ms ease;
}

.store-section-nav a:hover,
.store-section-nav a:focus-visible {
  border-color: color-mix(in srgb, var(--accent) 55%, var(--line));
  background: color-mix(in srgb, var(--accent) 8%, var(--surface));
  color: var(--accent);
}

.store-category-section {
  display: grid;
  gap: 18px;
  scroll-margin-top: 90px;
  padding-block: 22px;
}

.store-category-section > header {
  display: flex;
  gap: 18px;
  align-items: end;
  justify-content: space-between;
}

.store-category-section > header > div {
  display: grid;
  gap: 5px;
}

.store-category-section > header span {
  color: var(--accent);
  font-size: 10px;
  font-weight: 820;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.store-category-section > header h2 {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(22px, 3vw, 34px);
}

.store-category-section > header p {
  max-width: 560px;
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.55;
}

.site-configuration-panel {
  display: grid;
  gap: 22px;
  padding: 22px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
}

.site-configuration-panel > header {
  display: flex;
  gap: 20px;
  align-items: start;
  justify-content: space-between;
}

.site-configuration-panel > header > div {
  display: grid;
  gap: 6px;
}

.site-configuration-panel h2,
.site-configuration-panel h3,
.site-configuration-panel p {
  margin: 0;
}

.site-configuration-panel > header h2 {
  font-size: 21px;
}

.site-configuration-panel > header p,
.site-media-grid p {
  max-width: 650px;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.55;
}

.site-identity-fields,
.site-media-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.site-identity-fields label,
.site-social-list label {
  display: grid;
  gap: 7px;
}

.site-identity-fields label > span,
.site-social-list label > span {
  color: var(--muted);
  font-size: 10px;
  font-weight: 740;
}

.site-identity-fields input,
.site-social-list input,
.workspace-series-create input,
.workspace-series-create textarea,
.workspace-series-create select,
.workspace-comments-toolbar select,
.workspace-comment-editor textarea,
.analytics-custom-range input {
  width: 100%;
  min-height: 44px;
  padding: 0 12px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--surface-2);
  color: var(--text);
}

.site-media-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.site-media-grid > article {
  display: grid;
  grid-template-columns: 92px minmax(0, 1fr);
  gap: 14px;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: var(--radius-small);
  background: var(--surface-2);
}

.site-media-preview {
  display: grid;
  width: 92px;
  aspect-ratio: 2 / 3;
  place-items: center;
  overflow: hidden;
  border-radius: 10px;
  background: var(--surface-3);
  color: var(--muted);
}

.site-media-grid > article:first-child .site-media-preview {
  aspect-ratio: 1;
}

.site-media-preview img {
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.site-media-grid > article > div:last-child {
  display: grid;
  align-content: start;
  gap: 9px;
}

.site-media-grid label.button {
  position: relative;
  overflow: hidden;
}

.site-media-grid label.button > input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
}

.site-media-grid label:last-child {
  display: flex;
  gap: 7px;
  align-items: center;
  color: var(--text-soft);
  font-size: 10px;
}

.site-social-settings {
  display: grid;
  gap: 12px;
}

.site-social-list {
  display: grid;
  gap: 9px;
}

.site-social-list > article {
  display: grid;
  grid-template-columns: auto minmax(120px, 0.45fr) minmax(220px, 1fr) auto auto;
  gap: 10px;
  align-items: end;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: var(--surface-2);
}

.site-social-list > article > svg {
  align-self: center;
  color: var(--accent);
}

.site-social-enabled {
  display: flex !important;
  min-height: 44px;
  align-items: center;
  gap: 7px;
}

.site-social-enabled input {
  width: auto;
  min-height: auto;
}

.site-social-list > article > button {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
}

.site-configuration-message {
  display: flex;
  min-height: 44px;
  align-items: center;
  gap: 9px;
  padding: 0 13px;
  border-radius: 10px;
  background: color-mix(in srgb, var(--success) 12%, var(--surface));
  color: var(--success);
  font-size: 11px;
}

.site-configuration-message.is-error {
  background: color-mix(in srgb, var(--danger) 11%, var(--surface));
  color: var(--danger);
}

.workspace-series-create {
  display: grid;
  gap: 16px;
  padding: 18px;
  border: 1px solid color-mix(in srgb, var(--accent) 25%, var(--line));
  border-radius: var(--radius);
  background:
    linear-gradient(
      135deg,
      color-mix(in srgb, var(--accent) 7%, transparent),
      transparent 55%
    ),
    var(--surface);
}

.workspace-series-create-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 12px;
}

.workspace-series-create-grid label {
  display: grid;
  gap: 7px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 720;
}

.workspace-series-create-grid label:has(textarea) {
  grid-column: span 2;
}

.workspace-series-create textarea,
.workspace-comment-editor textarea {
  min-height: 110px;
  padding-block: 11px;
  resize: vertical;
}

.workspace-series-create > .button {
  justify-self: start;
}

.workspace-comments {
  display: grid;
  gap: 15px;
}

.workspace-comments-toolbar {
  display: flex;
  gap: 14px;
  align-items: end;
  justify-content: space-between;
}

.workspace-comments-toolbar label {
  display: grid;
  width: min(420px, 100%);
  gap: 7px;
}

.workspace-comments-toolbar label > span,
.workspace-comments-toolbar > span {
  color: var(--muted);
  font-size: 10px;
  font-weight: 730;
}

.workspace-comment-list {
  grid-template-columns: 1fr;
}

.workspace-comment-list article {
  gap: 12px;
}

.workspace-comment-list article[data-status="hidden"] {
  border-style: dashed;
  opacity: 0.82;
}

.workspace-comment-list article[data-status="deleted"] {
  background: color-mix(in srgb, var(--danger) 4%, var(--surface));
}

.workspace-comment-list article header > div {
  display: grid;
  gap: 3px;
}

.workspace-comment-list article header time {
  color: var(--muted);
  font-size: 9px;
}

.workspace-comment-metrics,
.workspace-comment-actions,
.workspace-comment-editor > div,
.workspace-comment-pagination {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  align-items: center;
}

.workspace-comment-metrics span {
  padding: 5px 8px;
  border-radius: 999px;
  background: var(--surface-2);
  color: var(--muted);
  font-size: 9px;
}

.workspace-comment-actions {
  justify-content: flex-end;
}

.workspace-comment-actions button,
.workspace-comment-editor button,
.workspace-comment-pagination button {
  display: inline-flex;
  min-height: 36px;
  align-items: center;
  gap: 5px;
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: var(--surface-2);
  color: var(--text-soft);
  cursor: pointer;
  font-size: 9px;
  font-weight: 750;
}

.workspace-comment-actions .is-destructive {
  color: var(--danger);
}

.workspace-comment-actions button:disabled,
.workspace-comment-editor button:disabled,
.workspace-comment-pagination button:disabled {
  cursor: not-allowed;
  opacity: 0.48;
}

.workspace-comment-editor {
  display: grid;
  gap: 8px;
}

.workspace-comment-pagination {
  justify-content: center;
  padding-top: 4px;
}

.workspace-comment-pagination span {
  color: var(--muted);
  font-size: 10px;
}

.analytics-custom-range {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.analytics-custom-range label {
  display: grid;
  width: min(220px, 100%);
  gap: 6px;
}

.analytics-custom-range label > span {
  color: var(--muted);
  font-size: 9px;
  font-weight: 740;
}

.workspace-analytics-summary {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.workspace-analytics-summary article {
  display: grid;
  gap: 6px;
  padding: 13px;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: var(--surface);
}

.workspace-analytics-summary span {
  color: var(--muted);
  font-size: 9px;
  font-weight: 760;
  text-transform: uppercase;
}

.workspace-analytics-summary strong {
  font-size: 20px;
}

.workspace-analytics-details {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.workspace-analytics-details > section,
.analytics-region-list {
  overflow: hidden;
  padding: 15px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
}

.workspace-analytics-details section > article,
.analytics-region-list > article {
  display: flex;
  gap: 10px;
  align-items: center;
  justify-content: space-between;
  padding: 10px 0;
  border-top: 1px solid var(--line);
}

.workspace-analytics-details article > div {
  display: grid;
  gap: 3px;
}

.workspace-analytics-details :is(span, em),
.analytics-region-list :is(span, em) {
  color: var(--muted);
  font-size: 9px;
  font-style: normal;
}

.analytics-audience-grid {
  margin-top: 14px;
}

.analytics-purchase-breakdown {
  display: grid;
  gap: 7px;
  margin-top: 14px;
  padding-top: 14px;
  border-top: 1px solid var(--line);
}

.analytics-purchase-breakdown h4,
.analytics-purchase-breakdown p {
  margin: 0;
}

.analytics-purchase-breakdown p {
  display: flex;
  gap: 12px;
  justify-content: space-between;
  color: var(--muted);
  font-size: 9px;
}

@media (max-width: 980px) {
  .site-media-grid,
  .workspace-series-create-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .site-media-grid > article:last-child {
    grid-column: 1 / -1;
  }

  .site-social-list > article {
    grid-template-columns: auto minmax(120px, 0.55fr) minmax(200px, 1fr);
  }

  .site-social-enabled,
  .site-social-list > article > button {
    grid-column: auto;
  }

  .workspace-analytics-summary {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 680px) {
  .brand-logo-image {
    width: 27px;
    height: 27px;
    flex-basis: 27px;
  }

  .site-configuration-panel {
    padding: 15px;
  }

  .site-configuration-panel > header,
  .workspace-comments-toolbar,
  .store-category-section > header {
    align-items: stretch;
    flex-direction: column;
  }

  .site-configuration-panel > header > .button {
    width: 100%;
  }

  .site-identity-fields,
  .site-media-grid,
  .workspace-series-create-grid,
  .workspace-analytics-details {
    grid-template-columns: 1fr;
  }

  .site-media-grid > article:last-child,
  .workspace-series-create-grid label:has(textarea) {
    grid-column: auto;
  }

  .site-social-list > article {
    grid-template-columns: auto minmax(0, 1fr) auto;
  }

  .site-social-list > article > label:not(.site-social-enabled) {
    grid-column: 2 / -1;
  }

  .site-social-enabled {
    grid-column: 2;
  }

  .site-social-list > article > button {
    grid-column: 3;
  }

  .workspace-comment-list article footer {
    gap: 10px;
  }

  .workspace-comment-actions {
    width: 100%;
    justify-content: flex-start;
  }

  .workspace-analytics-summary {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 420px) {
  .site-media-grid > article {
    grid-template-columns: 72px minmax(0, 1fr);
  }

  .site-media-preview {
    width: 72px;
  }

  .workspace-analytics-summary {
    grid-template-columns: 1fr 1fr;
  }
}
.store-offer-art {
  display: block;
  width: 100%;
  max-height: 190px;
  margin: 0 0 1rem;
  border-radius: var(--radius-card, 18px);
  object-fit: cover;
  aspect-ratio: 16 / 9;
}

.configured-coin-icon img {
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.store-offer-theme-onyx {
  --offer-accent: #8ba0bb;
}

.store-offer-theme-aurora {
  --offer-accent: #5ee7c4;
}

.store-offer-theme-sunset {
  --offer-accent: #ff9c73;
}

.store-offer-theme-minimal {
  --offer-accent: currentColor;
}

.admin-filter-context {
  display: inline-flex;
  min-height: 42px;
  align-items: center;
  padding: 0 0.85rem;
  border: 1px solid var(--border-subtle);
  border-radius: 12px;
  color: var(--text-secondary);
  background: var(--surface-raised);
  font-size: 0.85rem;
}

/* v1.2 Upload Center: focused team publishing workspace. */
.upload-center-workspace {
  display: grid;
  grid-template-columns: 230px minmax(0, 1fr);
  min-height: min(820px, calc(100vh - 150px));
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: calc(var(--radius) + 6px);
  background: color-mix(in srgb, var(--surface) 94%, transparent);
  box-shadow: 0 24px 70px color-mix(in srgb, var(--shadow) 44%, transparent);
}

.upload-center-nav {
  min-width: 0;
  padding: 1.15rem 0.8rem;
  border-right: 1px solid var(--line);
  background:
    radial-gradient(circle at 10% 0%, color-mix(in srgb, var(--accent) 14%, transparent), transparent 34%),
    var(--bg-soft);
}

.upload-center-nav > div {
  display: flex;
  gap: 0.75rem;
  align-items: center;
  padding: 0.35rem 0.55rem 1.15rem;
}

.upload-center-nav > div > svg {
  flex: 0 0 auto;
  color: var(--accent);
}

.upload-center-nav > div span,
.upload-center-nav > div strong,
.upload-center-nav > div small {
  display: block;
  min-width: 0;
}

.upload-center-nav > div strong {
  font-size: 0.9rem;
}

.upload-center-nav > div small {
  margin-top: 0.18rem;
  color: var(--muted);
  font-size: 0.72rem;
}

.upload-center-nav nav {
  display: grid;
  gap: 0.22rem;
}

.upload-center-nav nav a {
  display: flex;
  min-height: 42px;
  gap: 0.7rem;
  align-items: center;
  padding: 0.65rem 0.72rem;
  border: 1px solid transparent;
  border-radius: 10px;
  color: var(--text-soft);
  font-size: 0.82rem;
  font-weight: 700;
}

.upload-center-nav nav a:hover {
  border-color: var(--line);
  color: var(--text);
  background: var(--surface);
}

.upload-center-nav nav a[aria-current="page"] {
  border-color: color-mix(in srgb, var(--accent) 38%, var(--line));
  color: var(--text);
  background: color-mix(in srgb, var(--accent) 13%, var(--surface));
  box-shadow: inset 3px 0 var(--accent);
}

.upload-center-main {
  min-width: 0;
  padding: clamp(1rem, 2.4vw, 2rem);
  overflow: hidden;
}

.upload-center-mobile-nav {
  display: none;
}

.upload-section-heading {
  display: flex;
  gap: 1rem;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 1.15rem;
}

.upload-section-heading > div {
  min-width: 0;
}

.upload-section-heading span {
  color: var(--accent);
  font-size: 0.69rem;
  font-weight: 850;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.upload-section-heading h2,
.upload-section-heading h3 {
  margin: 0.25rem 0 0;
  line-height: 1.08;
}

.upload-section-heading h2 {
  font-size: clamp(1.45rem, 3vw, 2.2rem);
}

.upload-section-heading h3 {
  font-size: 1.08rem;
}

.upload-section-heading p {
  max-width: 68ch;
  margin: 0.55rem 0 0;
  color: var(--text-soft);
  line-height: 1.6;
}

.upload-section-heading > :is(a, button) {
  display: inline-flex;
  flex: 0 0 auto;
  gap: 0.45rem;
  align-items: center;
}

.upload-alert {
  display: flex;
  min-height: 46px;
  gap: 0.65rem;
  align-items: center;
  margin: 0 0 1rem;
  padding: 0.8rem 0.95rem;
  border: 1px solid var(--line);
  border-radius: 11px;
  color: var(--text-soft);
  background: var(--surface-2);
}

.upload-alert svg {
  flex: 0 0 auto;
}

.upload-alert button {
  margin-left: auto;
  color: var(--accent);
  background: transparent;
  cursor: pointer;
}

.upload-alert.is-error {
  border-color: color-mix(in srgb, var(--danger) 55%, var(--line));
  color: var(--danger);
  background: color-mix(in srgb, var(--danger) 9%, var(--surface));
}

.upload-alert.is-success {
  border-color: color-mix(in srgb, #5fdaa0 45%, var(--line));
  color: #79e4b1;
  background: color-mix(in srgb, #5fdaa0 8%, var(--surface));
}

:root[data-theme="light"] .upload-alert.is-success {
  color: #176d48;
}

.upload-loading,
.upload-empty {
  display: grid;
  min-height: 190px;
  place-items: center;
  align-content: center;
  gap: 0.55rem;
  padding: 2rem;
  border: 1px dashed var(--line-strong);
  border-radius: var(--radius);
  color: var(--muted);
  text-align: center;
}

.upload-loading {
  display: flex;
  min-height: 100px;
}

.upload-empty strong {
  color: var(--text);
}

.upload-empty p {
  max-width: 52ch;
  margin: 0;
  line-height: 1.5;
}



.upload-metric-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.75rem;
  margin-bottom: 1rem;
}

.upload-metric-grid article {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 0.6rem;
  align-items: center;
  padding: 1rem;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface-2);
}

.upload-metric-grid svg {
  grid-row: span 2;
  color: var(--accent);
}

.upload-metric-grid span {
  color: var(--muted);
  font-size: 0.75rem;
  font-weight: 700;
}

.upload-metric-grid strong {
  font-size: 1.45rem;
}

.upload-primary-actions {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.75rem;
  margin-bottom: 1.5rem;
}

.upload-primary-actions a {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 0.32rem 0.65rem;
  padding: 1rem;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
}

.upload-primary-actions a:hover {
  border-color: var(--accent);
  transform: translateY(-1px);
}

.upload-primary-actions svg {
  grid-row: span 2;
  color: var(--accent);
}

.upload-primary-actions span {
  color: var(--muted);
  font-size: 0.76rem;
  line-height: 1.45;
}

.upload-job-list {
  display: grid;
  gap: 0.55rem;
}

.upload-job-list > article {
  display: grid;
  grid-template-columns: 38px minmax(170px, 1fr) auto minmax(125px, auto) auto;
  gap: 0.75rem;
  align-items: center;
  padding: 0.8rem;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--surface);
}

.upload-job-kind {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  border-radius: 10px;
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 13%, var(--surface-2));
}

.upload-job-list > article > div {
  min-width: 0;
}

.upload-job-list strong,
.upload-job-list small,
.upload-job-list em {
  display: block;
}

.upload-job-list strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.upload-job-list small,
.upload-job-list time {
  color: var(--muted);
  font-size: 0.72rem;
}

.upload-job-list em {
  margin-top: 0.25rem;
  overflow: hidden;
  color: var(--danger);
  font-size: 0.72rem;
  font-style: normal;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.upload-status {
  display: inline-flex;
  width: fit-content;
  min-height: 28px;
  align-items: center;
  padding: 0.35rem 0.55rem;
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--text-soft);
  background: var(--surface-2);
  font-size: 0.65rem;
  font-weight: 850;
  letter-spacing: 0.04em;
  text-transform: capitalize;
}

.upload-status-ready,
.upload-status-published,
.upload-status-approved {
  border-color: color-mix(in srgb, var(--theme-status-green) 50%, var(--line));
  color: var(--theme-status-green);
}

.upload-status-failed,
.upload-status-rejected,
.upload-status-revoked {
  border-color: color-mix(in srgb, var(--danger) 52%, var(--line));
  color: var(--danger);
}

.upload-status-pending_review,
.upload-status-under_review,
.upload-status-changes_requested,
.upload-status-scheduled {
  border-color: color-mix(in srgb, var(--warning) 55%, var(--line));
  color: var(--warning);
}

.upload-form-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.8rem;
}

.upload-form-grid label,
.upload-batch-fields label,
.upload-combobox-field,
.series-request-form > fieldset > label,
.request-action-reason label {
  display: grid;
  min-width: 0;
  gap: 0.38rem;
  color: var(--text-soft);
  font-size: 0.76rem;
  font-weight: 750;
}

.upload-form-grid :is(input, select, textarea),
.upload-batch-fields :is(input, select, textarea),
.series-request-form :is(input, select, textarea),
.request-action-reason :is(input, select, textarea),
.upload-filter-row select,
.upload-center-mobile-nav select {
  width: 100%;
  min-height: 42px;
  padding: 0.65rem 0.72rem;
  border: 1px solid var(--line);
  border-radius: 9px;
  color: var(--text);
  background: var(--bg-soft);
}

.upload-form-grid textarea,
.series-request-form textarea {
  resize: vertical;
}

.upload-form-grid small,
.upload-combobox-field > small,
.series-request-form small {
  color: var(--muted);
  font-weight: 500;
  line-height: 1.4;
}

.upload-combobox-field > span {
  color: var(--text-soft);
}

.upload-combobox-field .admin-combobox {
  position: relative;
  min-width: 0;
}

.upload-combobox-field .admin-combobox > input {
  width: 100%;
}

.upload-combobox-field .admin-combobox-list {
  position: absolute;
  z-index: 40;
  top: calc(100% + 4px);
  right: 0;
  left: 0;
  display: grid;
  max-height: 240px;
  overflow-y: auto;
  padding: 8px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: var(--surface-2);
}

.upload-combobox-field .admin-combobox-list button {
  display: grid;
  min-height: 40px;
  gap: 4px;
  justify-items: start;
  padding: 8px 12px;
  border: 0;
  border-radius: 8px;
  color: var(--text);
  background: transparent;
  text-align: left;
}

.upload-combobox-field .admin-combobox-list button:is(:hover, :focus-visible, .is-active),
.upload-combobox-field .admin-combobox-list button[aria-selected="true"] {
  background: color-mix(in srgb, var(--accent) 14%, transparent);
}

.upload-combobox-field .admin-combobox-list small,
.upload-combobox-field .admin-combobox-empty {
  color: var(--muted);
  font-size: 0.72rem;
}

.upload-combobox-field .admin-combobox-empty {
  padding: 12px;
}

.upload-field-wide {
  grid-column: 1 / -1;
}

.upload-check {
  display: flex !important;
  min-height: 42px;
  flex-direction: row !important;
  gap: 0.55rem !important;
  align-items: center;
  color: var(--text-soft);
  font-size: 0.78rem;
  font-weight: 650;
}

.upload-check input {
  width: 17px !important;
  min-height: 17px !important;
  flex: 0 0 auto;
}

.upload-composer {
  display: grid;
  gap: 0.85rem;
}

.upload-composer-card,
.series-request-form > fieldset {
  min-width: 0;
  margin: 0;
  padding: 1rem;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
}

.upload-card-heading {
  display: flex;
  gap: 0.75rem;
  align-items: center;
  margin-bottom: 0.9rem;
}

.upload-card-heading > span {
  display: grid;
  width: 30px;
  height: 30px;
  flex: 0 0 auto;
  place-items: center;
  border-radius: 50%;
  color: var(--accent-ink);
  background: var(--accent);
  font-size: 0.78rem;
  font-weight: 900;
}

.upload-card-heading strong,
.upload-card-heading small {
  display: block;
}

.upload-card-heading small {
  margin-top: 0.15rem;
  color: var(--muted);
  font-size: 0.7rem;
}

.upload-credits summary {
  cursor: pointer;
}

.upload-credits > div {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.65rem;
  margin-top: 0.75rem;
}

.upload-dropzone {
  display: grid;
  min-height: 170px;
  place-items: center;
  align-content: center;
  gap: 0.35rem;
  padding: 1.2rem;
  border: 1px dashed var(--line-strong);
  border-radius: 12px;
  color: var(--text-soft);
  background: var(--bg-soft);
  text-align: center;
  cursor: pointer;
}

.upload-dropzone:hover {
  border-color: var(--accent);
}

.upload-dropzone svg {
  color: var(--accent);
}

.upload-dropzone span {
  color: var(--muted);
  font-size: 0.72rem;
}

.upload-dropzone input {
  max-width: min(100%, 420px);
  margin-top: 0.5rem;
}

.upload-local-pages,
.upload-server-pages {
  display: grid;
  gap: 0.75rem;
  margin-top: 0.9rem;
}

.upload-local-pages h4,
.upload-server-pages h4 {
  margin: 0;
  font-size: 0.82rem;
}

.upload-local-pages ol,
.upload-server-pages ol {
  display: grid;
  gap: 0.4rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.upload-local-pages li,
.upload-server-pages li {
  display: grid;
  grid-template-columns: 28px 52px minmax(120px, 1fr) repeat(3, 34px);
  gap: 0.5rem;
  align-items: center;
  padding: 0.5rem;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: var(--surface-2);
}

.upload-local-pages li > span,
.upload-server-pages li > span {
  display: grid;
  width: 25px;
  height: 25px;
  place-items: center;
  border-radius: 7px;
  color: var(--muted);
  background: var(--surface);
  font-size: 0.68rem;
}

.upload-local-pages img,
.upload-server-pages img {
  width: 46px;
  height: 60px;
  border-radius: 6px;
  object-fit: cover;
}

.upload-local-pages strong,
.upload-local-pages small,
.upload-server-pages strong,
.upload-server-pages small {
  display: block;
  min-width: 0;
}

.upload-local-pages strong,
.upload-server-pages strong {
  overflow: hidden;
  font-size: 0.74rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.upload-local-pages small,
.upload-server-pages small {
  margin-top: 0.18rem;
  color: var(--muted);
  font-size: 0.66rem;
}

.upload-local-pages button,
.upload-server-pages button {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 8px;
  color: var(--text-soft);
  background: var(--surface);
  cursor: pointer;
}

.upload-local-pages button:disabled,
.upload-server-pages button:disabled {
  opacity: 0.38;
  cursor: not-allowed;
}

.upload-progress {
  display: grid;
  gap: 0.45rem;
  margin-top: 0.9rem;
}

.upload-progress > div {
  height: 8px;
  overflow: hidden;
  border-radius: 99px;
  background: var(--surface-3);
}

.upload-progress > div span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--brand-gradient);
  transition: width 180ms ease;
}

.upload-progress strong {
  color: var(--muted);
  font-size: 0.7rem;
}

.upload-batch-table {
  display: grid;
  gap: 0.65rem;
}

.upload-batch-table > article {
  min-width: 0;
  padding: 0.8rem;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: var(--surface-2);
}

.upload-batch-table header {
  display: flex;
  gap: 0.6rem;
  align-items: center;
  margin-bottom: 0.7rem;
}

.upload-batch-table header > span {
  display: grid;
  width: 25px;
  height: 25px;
  place-items: center;
  border-radius: 7px;
  color: var(--accent);
  background: var(--surface);
  font-size: 0.68rem;
}

.upload-batch-table header strong,
.upload-batch-table header small {
  display: block;
}

.upload-batch-table header small {
  color: var(--muted);
  font-size: 0.67rem;
}

.upload-batch-fields {
  display: grid;
  grid-template-columns: repeat(5, minmax(100px, 1fr));
  gap: 0.55rem;
  overflow-x: auto;
  padding-bottom: 0.2rem;
}

.upload-final-review dl,
.request-detail dl,
.upload-rights-list dl {
  display: flex;
  flex-wrap: wrap;
  gap: 0.55rem;
  margin: 0 0 0.8rem;
}

.upload-final-review dl div,
.request-detail dl div,
.upload-rights-list dl div {
  min-width: 100px;
  padding: 0.55rem 0.65rem;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: var(--surface-2);
}

.upload-final-review dt,
.request-detail dt,
.upload-rights-list dt {
  color: var(--muted);
  font-size: 0.64rem;
  text-transform: uppercase;
}

.upload-final-review dd,
.request-detail dd,
.upload-rights-list dd {
  margin: 0.22rem 0 0;
  font-size: 0.78rem;
  font-weight: 750;
}

.upload-action-bar {
  display: flex;
  gap: 0.65rem;
  align-items: center;
  justify-content: space-between;
  padding: 0.75rem 0 0;
}

.upload-action-bar .button,
.upload-final-review .button {
  display: inline-flex;
  gap: 0.45rem;
  align-items: center;
  justify-content: center;
}

.upload-series-grid,
.upload-rights-list,
.upload-method-list {
  display: grid;
  gap: 0.65rem;
}

.upload-series-grid article,
.upload-rights-list article,
.upload-method-list article {
  display: grid;
  grid-template-columns: 38px minmax(160px, 1fr) auto auto;
  gap: 0.75rem;
  align-items: center;
  padding: 0.8rem;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: var(--surface);
}

.upload-series-grid article > svg,
.upload-rights-list article > svg,
.upload-method-list article > svg {
  color: var(--accent);
}

.upload-series-grid article strong,
.upload-series-grid article small,
.upload-rights-list article strong,
.upload-rights-list article small {
  display: block;
}

.upload-series-grid article small,
.upload-rights-list article small {
  color: var(--muted);
}

.upload-series-grid article > span,
.upload-method-list article > span {
  color: var(--muted);
  font-size: 0.7rem;
  font-weight: 750;
}

.upload-method-list article {
  grid-template-columns: 32px minmax(0, 1fr) auto;
}

.upload-method-list article p {
  margin: 0.2rem 0 0;
  color: var(--muted);
  line-height: 1.45;
}

.upload-method-list article:not(.is-supported) {
  opacity: 0.74;
}

.upload-rule-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.65rem;
  margin-top: 0.8rem;
}

.upload-rule-grid article {
  padding: 0.9rem;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: var(--surface-2);
}

.upload-rule-grid strong,
.upload-rule-grid span {
  display: block;
}

.upload-rule-grid strong {
  font-size: 1.2rem;
}

.upload-rule-grid span {
  margin-top: 0.18rem;
  color: var(--muted);
  font-size: 0.7rem;
}

.upload-rules-copy {
  display: grid;
  gap: 0.55rem;
  margin: 1rem 0 0;
  padding-left: 1.25rem;
  color: var(--text-soft);
  line-height: 1.55;
}

.series-request-form {
  display: grid;
  gap: 0.8rem;
}

.series-request-form fieldset {
  display: grid;
  gap: 0.8rem;
}

.series-request-form fieldset:disabled {
  opacity: 0.68;
}

.series-request-form legend {
  padding: 0 0.4rem;
  color: var(--accent);
  font-size: 0.72rem;
  font-weight: 850;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.request-media-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.7rem;
}

.request-media-grid label {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 0.55rem;
  align-items: center;
  padding: 0.75rem;
  border: 1px dashed var(--line-strong);
  border-radius: 10px;
}

.request-media-grid label > svg {
  color: var(--accent);
}

.request-media-grid label strong,
.request-media-grid label small {
  display: block;
}

.request-media-grid label small {
  color: var(--muted);
}

.request-media-grid input,
.request-media-grid img {
  grid-column: 1 / -1;
}

.request-media-grid img {
  width: 96px;
  aspect-ratio: 2 / 3;
  border-radius: 8px;
  object-fit: cover;
}

.upload-helper {
  margin: 0;
  color: var(--muted);
  font-size: 0.72rem;
  line-height: 1.5;
}

.request-import-workspace,
.request-import-preview {
  display: grid;
  gap: 0.8rem;
  padding: 0.9rem;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: var(--surface-2);
}

.request-import-workspace {
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
}

.request-import-workspace > div {
  display: grid;
  gap: 0.22rem;
}

.request-import-workspace strong {
  font-size: 0.82rem;
}

.request-import-preview > header,
.request-import-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.65rem;
}

.request-import-preview > header > div {
  display: grid;
  gap: 0.18rem;
}

.request-import-preview > header span,
.request-import-preview > header small,
.request-import-actions small {
  color: var(--muted);
  font-size: 0.68rem;
}

.request-import-preview h3 {
  margin: 0;
  font: 750 1rem/1.3 var(--font-display);
}

.request-import-fields {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.55rem;
}

.request-import-fields label {
  display: flex;
  min-width: 0;
  align-items: flex-start;
  gap: 0.55rem;
  padding: 0.65rem;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: var(--surface);
  cursor: pointer;
}

.request-import-fields input {
  width: 17px !important;
  min-height: 17px !important;
  flex: 0 0 auto;
}

.request-import-fields label > span {
  display: grid;
  min-width: 0;
  gap: 0.18rem;
}

.request-import-fields strong {
  font-size: 0.72rem;
}

.request-import-fields small {
  display: -webkit-box;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
  overflow-wrap: anywhere;
}

.request-import-actions small {
  max-width: 48rem;
  line-height: 1.5;
}

.upload-filter-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.55rem;
  align-items: end;
  margin-bottom: 0.8rem;
}

.upload-filter-row label {
  display: grid;
  gap: 0.3rem;
}

.upload-filter-row :is(span, small) {
  color: var(--muted);
  font-size: 0.68rem;
}

.request-list-layout {
  display: grid;
  grid-template-columns: minmax(260px, 0.85fr) minmax(300px, 1.15fr);
  gap: 0.8rem;
  align-items: start;
}

.request-record-list {
  display: grid;
  gap: 0.45rem;
}

.request-record-list > button {
  display: grid;
  grid-template-columns: 36px minmax(0, 1fr) auto;
  gap: 0.65rem;
  align-items: center;
  padding: 0.7rem;
  border: 1px solid var(--line);
  border-radius: 10px;
  color: var(--text);
  background: var(--surface);
  text-align: left;
  cursor: pointer;
}

.request-record-list > button:hover,
.request-record-list > button.is-selected {
  border-color: var(--accent);
}

.request-record-list > button > span {
  display: grid;
  width: 36px;
  height: 36px;
  place-items: center;
  border-radius: 9px;
  color: var(--accent);
  background: var(--surface-2);
}

.request-record-list strong,
.request-record-list small {
  display: block;
}

.request-record-list small {
  margin-top: 0.18rem;
  color: var(--muted);
  font-size: 0.67rem;
}

.request-detail {
  min-width: 0;
  padding: 1rem;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--surface);
}

.request-detail > div:first-child {
  display: flex;
  flex-wrap: wrap;
  gap: 0.55rem;
  align-items: center;
  margin-bottom: 0.75rem;
}

.request-detail h3 {
  width: 100%;
  margin: 0;
}

.request-detail > p {
  color: var(--text-soft);
  line-height: 1.55;
}

.request-detail > img {
  width: 110px;
  margin: 0 0 0.8rem;
  border-radius: 9px;
  aspect-ratio: 2 / 3;
  object-fit: cover;
}

.request-detail > section {
  display: grid;
  gap: 0.55rem;
  margin: 0.8rem 0;
}

.request-detail > section h4 {
  margin: 0;
}

.request-detail > section article {
  padding: 0.7rem;
  border-left: 3px solid var(--accent);
  border-radius: 0 9px 9px 0;
  background: var(--surface-2);
}

.request-detail > section article p {
  margin: 0.3rem 0;
  line-height: 1.5;
}

.request-detail > section article small {
  color: var(--muted);
}

.request-action-reason {
  display: grid;
  gap: 0.55rem;
  margin-top: 0.8rem;
}

@media (max-width: 1100px) {
  .upload-center-workspace {
    grid-template-columns: 195px minmax(0, 1fr);
  }

  .upload-metric-grid,
  .upload-rule-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .upload-form-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .upload-batch-fields {
    grid-template-columns: repeat(3, minmax(150px, 1fr));
  }

  .upload-job-list > article {
    grid-template-columns: 38px minmax(0, 1fr) auto;
  }

  .upload-job-list > article :is(time, .button) {
    grid-column: 2 / -1;
  }
}

@media (max-width: 820px) {
  .upload-center-workspace {
    display: block;
    min-height: 0;
  }

  .upload-center-nav {
    display: none;
  }

  .upload-center-main {
    padding: 1rem;
  }

  .upload-center-mobile-nav {
    display: grid;
    gap: 0.35rem;
    margin-bottom: 1rem;
    color: var(--muted);
    font-size: 0.7rem;
    font-weight: 750;
  }

  .upload-primary-actions,
  .request-list-layout {
    grid-template-columns: 1fr;
  }

  .upload-series-grid article,
  .upload-rights-list article {
    grid-template-columns: 34px minmax(0, 1fr);
  }

  .upload-series-grid article > :is(span, a),
  .upload-rights-list article > :is(dl, .upload-status) {
    grid-column: 2;
  }

  .upload-batch-fields {
    grid-template-columns: repeat(2, minmax(145px, 1fr));
  }
}

@media (max-width: 600px) {
  .upload-section-heading {
    display: grid;
  }

  .upload-section-heading > :is(a, button) {
    width: 100%;
    justify-content: center;
  }

  .upload-metric-grid,
  .upload-primary-actions,
  .upload-form-grid,
  .upload-rule-grid,
  .request-media-grid,
  .request-import-fields {
    grid-template-columns: 1fr;
  }

  .request-import-workspace {
    grid-template-columns: 1fr;
  }

  .request-import-workspace > button,
  .request-import-actions > button {
    width: 100%;
    justify-content: center;
  }

  .upload-field-wide {
    grid-column: auto;
  }

  .upload-batch-fields {
    grid-template-columns: 1fr;
    overflow: visible;
  }

  .upload-local-pages li,
  .upload-server-pages li {
    grid-template-columns: 28px 44px minmax(0, 1fr);
  }

  .upload-local-pages li > button,
  .upload-server-pages li > button {
    grid-row: 2;
  }

  .upload-local-pages li > button:first-of-type,
  .upload-server-pages li > button:first-of-type {
    grid-column: 2;
  }

  .upload-action-bar {
    align-items: stretch;
    flex-direction: column-reverse;
  }

  .upload-action-bar > :is(button, a) {
    width: 100%;
  }

  .upload-job-list > article {
    grid-template-columns: 36px minmax(0, 1fr);
  }

  .upload-job-list > article > :is(.upload-status, time, .button) {
    grid-column: 2;
  }

  .request-record-list > button {
    grid-template-columns: 34px minmax(0, 1fr);
  }

  .request-record-list .upload-status {
    grid-column: 2;
  }
}

/* v1.2.1 public experience refresh */
.trending-rail,
.teams-carousel {
  scrollbar-width: none;
}

.trending-rail::-webkit-scrollbar,
.teams-carousel::-webkit-scrollbar {
  display: none;
}

.site-header {
  height: 78px;
}

.site-header-inner {
  gap: clamp(22px, 3vw, 48px);
}

.brand-logo-image {
  width: auto;
  max-width: 168px;
  height: 38px;
  object-fit: contain;
}

.header-actions {
  gap: 10px;
}

.header-search,
.header-notifications {
  display: grid;
  width: 48px;
  min-width: 48px;
  height: 48px;
  min-height: 48px;
  place-items: center;
  padding: 0;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--surface);
  color: var(--text-soft);
}

.header-search:hover,
.header-notifications:hover,
.header-notifications[aria-current="page"] {
  border-color: color-mix(in srgb, var(--accent) 58%, var(--line));
  background: color-mix(in srgb, var(--accent) 10%, var(--surface));
  color: var(--accent);
}

.header-search span,
.header-search kbd {
  display: none;
}

.header-notifications {
  position: relative;
}

.header-notifications > span {
  position: absolute;
  top: -5px;
  right: -5px;
  display: grid;
  min-width: 19px;
  height: 19px;
  place-items: center;
  padding-inline: 4px;
  border: 2px solid var(--header);
  border-radius: 999px;
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 9px;
  font-weight: 850;
