  height: 46px;
}

.header-menu-profile > div {
  display: grid;
  min-width: 0;
  gap: 2px;
}

.header-menu-profile strong,
.header-menu-profile small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.header-menu-profile strong {
  font-size: 13px;
}

.header-menu-profile small {
  color: var(--muted);
  font-size: 10px;
}

.header-menu-profile em {
  width: fit-content;
  margin-top: 3px;
  padding: 3px 7px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--accent) 12%, transparent);
