  font-size: 11px;
}

.new-series-cover,
.latest-cover,
.catalog-card-cover,
.public-team-series-cover {
  box-shadow: 0 14px 34px color-mix(in srgb, var(--shadow) 62%, transparent);
}

.new-series-cover img,
.latest-cover img,
.catalog-card-cover img,
.public-team-series-cover img {
  object-position: center top;
}

.teams-carousel {
  grid-auto-columns: min(34rem, 82vw);
  gap: 1.15rem;
  padding:
    1.4rem
    max(0px, calc((100% - min(34rem, 82vw)) / 2))
    1.8rem;
  scroll-padding-inline:
    max(0px, calc((100% - min(34rem, 82vw)) / 2));
}

.teams-carousel.is-single {
  grid-auto-columns: min(34rem, 82vw);
}

.team-carousel-card {
  min-height: 0;
  overflow: hidden;
  scroll-snap-align: center;
  opacity: 0.58;
  transform: scale(0.94);
  transform-origin: center;
  transition:
    opacity 180ms ease,
    transform 180ms ease,
    border-color 180ms ease,
    box-shadow 180ms ease;
}

.team-carousel-card[data-active="true"] {
  border-color: color-mix(in srgb, var(--accent) 52%, var(--line));
  box-shadow: 0 26px 68px color-mix(in srgb, var(--shadow) 82%, transparent);
  opacity: 1;
  transform: scale(1);
}

.team-carousel-banner {
  height: auto;
  aspect-ratio: 3 / 1;
}

.team-carousel-banner > span {
  display: block;
  width: 100%;
  height: 100%;
  background:
    radial-gradient(circle at 50% 10%, color-mix(in srgb, var(--accent) 24%, transparent), transparent 48%),
    linear-gradient(135deg, var(--surface-3), var(--surface));
}

.team-carousel-logo {
  position: relative;
  z-index: 2;
  top: auto;
  left: auto;
  display: block;
  width: 5.8rem;
  height: 5.8rem;
  margin: -2.9rem auto 0;
  padding: 0.3rem;
  border-width: 4px;
  border-radius: 1.35rem;
  box-shadow: 0 12px 28px color-mix(in srgb, var(--shadow) 72%, transparent);
}

.team-carousel-card > div {
  justify-items: center;
  padding: 0.9rem 1.5rem 1.5rem;
  text-align: center;
}

.team-carousel-card p {
  max-width: 44ch;
}

.team-carousel-card a {
  margin-top: 0.3rem;
}

.teams-carousel-dots {
  display: flex;
  min-height: 24px;
  align-items: center;
  justify-content: center;
  gap: 7px;
}

.teams-carousel-dots button {
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: var(--line-strong);
  cursor: pointer;
  transition:
    width 160ms ease,
    background 160ms ease;
}

.teams-carousel-dots button[aria-pressed="true"] {
  width: 28px;
  background: var(--accent);
}

.editors-pick-card {
  grid-template-columns: minmax(350px, 0.88fr) minmax(0, 1.12fr);
  gap: clamp(42px, 6vw, 88px);
  min-height: 630px;
  padding: clamp(34px, 5vw, 72px);
  overflow: hidden;
  background:
    radial-gradient(circle at 20% 30%, color-mix(in srgb, var(--accent) 10%, transparent), transparent 32rem),
    linear-gradient(145deg, var(--surface), color-mix(in srgb, var(--bg-soft) 78%, var(--surface)));
}

.editors-pick-visual {
  position: relative;
  z-index: 1;
  display: grid;
  justify-items: center;
  min-width: 0;
}

.editors-pick-cover-stage {
  position: relative;
  display: grid;
  width: min(380px, 100%);
  min-height: 520px;
  place-items: center;
  touch-action: pan-y;
}

.editors-pick-cover {
  z-index: 3;
  width: min(300px, 82%);
  border-radius: 18px;
  transform: none;
  animation: editors-pick-in 140ms ease both;
}

.editors-pick-cover-back {
  position: absolute;
  z-index: 1;
  width: min(252px, 68%);
  aspect-ratio: 2 / 3;
  border: 1px solid color-mix(in srgb, white 10%, var(--line));
  border-radius: 16px;
  object-fit: cover;
  filter: saturate(0.72) brightness(0.72);
  opacity: 0.58;
}

.editors-pick-cover-back-left {
  left: 0;
  transform: translateX(-18%) rotate(-6deg) scale(0.94);
}

.editors-pick-cover-back-right {
  right: 0;
  transform: translateX(18%) rotate(6deg) scale(0.94);
}

.editors-pick-controls {
  position: absolute;
  z-index: 4;
  right: -7px;
  left: -7px;
  justify-content: space-between;
  pointer-events: none;
}

.editors-pick-controls button {
  width: 48px;
  height: 48px;
  border-color: color-mix(in srgb, var(--accent) 30%, var(--line));
  background: color-mix(in srgb, var(--surface) 92%, transparent);
  box-shadow: 0 12px 32px var(--shadow);
  pointer-events: auto;
  backdrop-filter: blur(14px);
}

.editors-pick-dots button[aria-pressed="true"] {
  width: 28px;
  background: var(--accent);
}

.editors-pick-copy {
  animation: editors-pick-in 140ms ease both;
}

.editors-pick-copy h3 {
  max-width: 14ch;
  font-size: clamp(38px, 4.6vw, 68px);
}

.editors-pick-teaser {
  color: var(--text) !important;
  font-size: 15px !important;
  font-weight: 680;
}

.editors-pick-state {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.editors-pick-state :is(span, em) {
  padding: 5px 9px;
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--text-soft);
  font-size: 9px;
  font-style: normal;
  font-weight: 760;
}

.editors-pick-state em {
  border-color: color-mix(in srgb, var(--accent) 44%, var(--line));
  color: var(--accent);
}

.editors-pick-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 5px;
}

.editors-pick-actions .button {
  min-width: 150px;
  min-height: 48px;
}

@keyframes editors-pick-in {
  from {
    opacity: 0;
    transform: translateY(5px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.title-actions {
  display: grid;
  width: min(100%, 560px);
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.title-actions .series-secondary-action {
  width: 100%;
  min-height: 50px;
  justify-content: center;
  padding-inline: 16px;
  font-size: 13px;
}

.title-actions .series-secondary-action svg {
  flex: 0 0 auto;
}

.latest-page > .page-wrap {
  width: min(1320px, calc(100vw - 64px));
}

.latest-grid {
  gap: 22px;
}

.latest-card {
  min-height: 210px;
  grid-template-columns: 126px minmax(0, 1fr);
  padding: 16px;
  border-radius: 17px;
}

.latest-pagination {
  flex-wrap: wrap;
}

.latest-pagination > span {
  background: transparent;
}

.reader-chapter-layer {
  position: fixed;
  z-index: 100;
  inset: 0;
}

.reader-chapter-scrim {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  background: rgba(1, 7, 14, 0.62);
  cursor: default;
  backdrop-filter: blur(3px);
}

.reader-chapter-drawer {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  display: grid;
  width: min(430px, calc(100vw - 20px));
  grid-template-rows: auto minmax(0, 1fr) auto;
  border-left: 1px solid #2c455b;
  background: #081525;
  color: #eff7fc;
  box-shadow: -28px 0 80px rgba(0, 0, 0, 0.48);
  animation: reader-drawer-in 150ms ease both;
}

.reader-chapter-drawer > header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 24px 20px 18px;
  border-bottom: 1px solid #20384d;
}

.reader-chapter-drawer > header > div {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.reader-chapter-drawer > header span {
  color: #6fbef6;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.reader-chapter-drawer h2,
.reader-chapter-drawer p {
  margin: 0;
}

.reader-chapter-drawer h2 {
  overflow: hidden;
  font-size: 20px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.reader-chapter-drawer p {
  color: #8da6b8;
  font-size: 10px;
}

.reader-chapter-drawer > header > button {
  display: grid;
  width: 40px;
  height: 40px;
  flex: 0 0 auto;
  place-items: center;
  border: 1px solid #294860;
  border-radius: 50%;
  background: #10243a;
  color: #eff7fc;
  cursor: pointer;
}

.reader-chapter-list {
  overflow-y: auto;
  padding: 10px;
  overscroll-behavior: contain;
}

.reader-chapter-list > a {
  display: grid;
  min-height: 67px;
  grid-template-columns: 34px minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  border: 1px solid transparent;
  border-radius: 12px;
  color: #bdd0dc;
}

.reader-chapter-list > a:hover {
  background: #10243a;
}

.reader-chapter-list > a.is-current {
  border-color: #317bb0;
  background: #102b43;
  color: #fff;
}

.reader-chapter-list > a > span {
  display: grid;
  width: 32px;
  height: 32px;
  place-items: center;
  border-radius: 9px;
  background: #152b3e;
  color: #6fbef6;
}

.reader-chapter-list > a > div {
  display: grid;
  min-width: 0;
  gap: 4px;
}

.reader-chapter-list strong {
  overflow: hidden;
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.reader-chapter-list small {
  color: #819aad;
  font-size: 9px;
}

.reader-chapter-list em {
  padding: 4px 7px;
  border-radius: 999px;
  background: #2d9be7;
  color: #041523;
  font-size: 8px;
  font-style: normal;
  font-weight: 800;
}

.reader-chapter-list-state {
  display: grid;
  min-height: 260px;
  place-content: center;
  justify-items: center;
  gap: 8px;
  padding: 24px;
  color: #8da6b8;
  text-align: center;
  font-size: 10px;
}

.reader-chapter-list-state strong {
  color: #eff7fc;
  font-size: 13px;
}

.reader-chapter-list-state button {
  min-height: 38px;
  margin-top: 5px;
  padding-inline: 13px;
  border: 1px solid #317bb0;
  border-radius: 10px;
  background: #102b43;
  color: #eff7fc;
}

.reader-chapter-drawer > footer {
  display: grid;
  gap: 6px;
  padding: 12px;
  border-top: 1px solid #20384d;
}

.reader-chapter-drawer > footer a {
  display: flex;
  min-height: 42px;
  align-items: center;
  gap: 9px;
  padding-inline: 12px;
  border-radius: 10px;
  color: #bdd0dc;
  font-size: 10px;
  font-weight: 690;
}

.reader-chapter-drawer > footer a:hover {
  background: #10243a;
  color: #fff;
}

@keyframes reader-drawer-in {
  from {
    opacity: 0;
    transform: translateX(24px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

.reader-chapter-complete {
  display: grid;
  width: min(920px, calc(100% - 32px));
  gap: 22px;
  margin: 18px auto 90px;
  padding: 24px;
  border: 1px solid #293c4d;
  border-radius: 18px;
  background: #0d1b29;
  color: #eff7fc;
}

.reader-chapter-complete > div {
  display: flex;
  align-items: center;
  gap: 12px;
}

.reader-chapter-complete > div > svg {
  color: #39a9ff;
}

.reader-chapter-complete > div > span {
  display: grid;
  gap: 3px;
}

.reader-chapter-complete small {
  color: var(--theme-mid-tone);
  font-size: 10px;
}

.reader-chapter-navigation {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.reader-chapter-navigation > :is(a, span) {
  display: flex;
  min-height: 68px;
  align-items: center;
  gap: 12px;
  padding: 11px 15px;
  border: 1px solid var(--theme-accent-l3);
  border-radius: 14px;
  background: var(--theme-accent);
  color: var(--theme-text-color);
}

.reader-chapter-navigation > :is(a, span):last-child {
  justify-content: flex-end;
  text-align: right;
}

.reader-chapter-navigation > a:hover {
  border-color: var(--theme-primary);
  background: var(--theme-accent-l1);
}

.reader-chapter-navigation > span[aria-disabled="true"] {
  opacity: 0.42;
}

.reader-chapter-navigation > :is(a, span) > span {
  display: grid;
  gap: 3px;
}

.reader-chapter-navigation small {
  color: var(--theme-mid-tone);
  font-size: 9px;
  font-weight: 650;
  text-transform: uppercase;
}

.reader-chapter-navigation strong {
  font-size: 11px;
}

.public-team-page {
