.notifications-page {
  min-height: calc(100dvh - 78px);
  padding: 48px 0 110px;
}

.notifications-page-inner {
  width: min(1120px, calc(100vw - 64px));
}

.notifications-page-head {
  display: grid;
  grid-template-columns: 52px minmax(0, 1fr);
  align-items: start;
  gap: 22px;
  padding-bottom: 34px;
}

.notifications-page-head h1,
.notifications-page-head p {
  margin: 0;
}

.notifications-page-head h1 {
  margin-top: 5px;
  font-size: clamp(40px, 6vw, 72px);
  letter-spacing: -0.06em;
}

.notifications-page-head > div > p:last-child {
  margin-top: 8px;
  color: var(--muted);
}

.notifications-back {
  display: grid;
  width: 48px;
  height: 48px;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: var(--surface);
  color: var(--text);
  cursor: pointer;
}

.notifications-category-tabs {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 8px;
  padding: 8px;
  border: 1px solid var(--line);
  border-radius: 17px;
  background: var(--surface);
}

.notifications-category-tabs button {
  display: flex;
  min-height: 54px;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 0 14px;
  border: 1px solid transparent;
  border-radius: 12px;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
  font-size: 12px;
  font-weight: 720;
}

.notifications-category-tabs button:hover {
  color: var(--text);
}

.notifications-category-tabs button[aria-selected="true"] {
  border-color: color-mix(in srgb, var(--accent) 62%, var(--line));
  background: var(--accent);
  color: var(--accent-ink);
  box-shadow: 0 8px 24px color-mix(in srgb, var(--accent) 24%, transparent);
}

.notifications-panel {
  min-height: 520px;
  padding-top: 34px;
  outline: 0;
}

.notifications-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 20px;
}

.notifications-state-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.notifications-state-chips button,
.notifications-mark-all {
  display: inline-flex;
  min-height: 42px;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 0 15px;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: var(--surface);
  color: var(--text-soft);
  cursor: pointer;
  font-size: 11px;
  font-weight: 700;
}

.notifications-state-chips button[aria-pressed="true"] {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 10%, var(--surface));
  color: var(--accent);
}

.notifications-state-chips button > span {
  display: grid;
  min-width: 19px;
  height: 19px;
  place-items: center;
  padding-inline: 4px;
  border-radius: 999px;
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 8px;
}

.notifications-mark-all:disabled,
.notification-read-toggle:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}

.notifications-list {
  display: grid;
  gap: 10px;
}

.notification-card {
  position: relative;
  display: grid;
  min-height: 108px;
  grid-template-columns: 48px minmax(0, 1fr) auto;
  align-items: center;
  gap: 15px;
  padding: 16px 18px;
  border: 1px solid var(--line);
  border-radius: 15px;
  background: var(--surface);
  transition:
    border-color 150ms ease,
    background 150ms ease;
}

.notification-card.is-unread {
  border-color: color-mix(in srgb, var(--accent) 42%, var(--line));
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--accent) 8%, var(--surface)), var(--surface) 38%);
}

.notification-card.is-unread::before {
  position: absolute;
  top: 17px;
  bottom: 17px;
  left: 0;
  width: 3px;
  border-radius: 0 99px 99px 0;
  background: var(--accent);
  content: "";
}

.notification-card.is-read {
  opacity: 0.76;
}

.notification-card-icon {
  display: grid;
  width: 46px;
  height: 46px;
  place-items: center;
  border-radius: 13px;
  background: color-mix(in srgb, var(--accent) 11%, var(--surface-2));
  color: var(--accent);
}

.notification-card-icon.is-announcements {
  background: color-mix(in srgb, var(--warning) 12%, var(--surface-2));
  color: var(--warning);
}

.notification-card-icon.is-social {
  background: color-mix(in srgb, var(--theme-status-purple) 13%, var(--surface-2));
  color: var(--theme-status-purple);
}

.notification-card-copy {
  display: grid;
  min-width: 0;
  gap: 6px;
}

.notification-card-copy > :is(a, div) {
  display: grid;
  gap: 4px;
  min-width: 0;
  color: inherit;
}

.notification-card-copy strong {
  color: var(--text);
  font-size: 13px;
}

.notification-card-copy p {
  overflow: hidden;
  margin: 0;
  color: var(--text-soft);
  font-size: 11px;
  line-height: 1.5;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.notification-card-meta {
  display: flex;
  align-items: center;
  gap: 8px;
}

.notification-card-meta small,
.notification-card-meta i,
.notification-card-meta time {
  color: var(--muted);
  font-size: 8px;
  font-style: normal;
}

.notification-card-meta small {
  color: var(--accent);
  font-weight: 800;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.notification-card-meta i {
  padding: 3px 6px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--accent) 12%, transparent);
  color: var(--accent);
}

.notification-card-meta time {
  margin-left: auto;
}

.notification-read-toggle {
  min-height: 38px;
  padding: 0 12px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--surface-2);
  color: var(--text-soft);
  cursor: pointer;
  font-size: 9px;
  font-weight: 680;
}

.notifications-action-error {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
  padding: 11px 13px;
  border: 1px solid color-mix(in srgb, var(--danger) 42%, var(--line));
  border-radius: 11px;
  background: color-mix(in srgb, var(--danger) 8%, var(--surface));
  color: var(--danger);
  font-size: 10px;
}

.notifications-action-error button {
  color: inherit;
  cursor: pointer;
  font-weight: 730;
}

.notifications-loading,
.notifications-error,
.notifications-empty,
.notifications-auth-state {
  display: grid;
  min-height: 430px;
  place-content: center;
  justify-items: center;
  gap: 10px;
  padding: 30px;
  border: 1px solid var(--line);
  border-radius: 17px;
  background: var(--surface);
  color: var(--muted);
  text-align: center;
}

.notifications-loading > div {
  display: grid;
  width: min(520px, 75vw);
  gap: 8px;
  margin-top: 14px;
}

.notifications-loading i {
  display: block;
  height: 52px;
  border-radius: 12px;
  background: var(--surface-2);
}

.notifications-error strong,
.notifications-empty strong,
.notifications-auth-state h2 {
  margin: 0;
  color: var(--text);
}

.notifications-error p,
.notifications-empty p,
.notifications-auth-state p {
  max-width: 50ch;
  margin: 0;
  line-height: 1.6;
}

.notifications-error button,
.notifications-empty > button {
  display: inline-flex;
  min-height: 40px;
  align-items: center;
  gap: 7px;
  margin-top: 5px;
  padding: 0 14px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--surface-2);
  color: var(--text);
  cursor: pointer;
}

.notifications-empty-icon {
  display: grid;
  width: 58px;
  height: 58px;
  place-items: center;
  border-radius: 17px;
  background: color-mix(in srgb, var(--accent) 10%, var(--surface-2));
  color: var(--accent);
}

.notifications-pagination {
  display: grid;
  grid-template-columns: auto 1fr auto auto;
  align-items: center;
  gap: 10px;
  margin-top: 24px;
}

.notifications-pagination > span {
  justify-self: center;
  color: var(--muted);
  font-size: 10px;
}

.notifications-pagination > div {
  display: flex;
  gap: 5px;
}

.notifications-pagination button {
  display: inline-flex;
  min-width: 38px;
  min-height: 38px;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 0 11px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--surface);
  color: var(--text-soft);
  cursor: pointer;
  font-size: 9px;
}

.notifications-pagination button[aria-current="page"] {
  border-color: var(--accent);
  background: var(--accent);
  color: var(--accent-ink);
}

.notifications-pagination button:disabled {
  cursor: not-allowed;
  opacity: 0.42;
}

@media (max-width: 760px) {
  .notifications-page {
    min-height: calc(100dvh - 68px);
    padding-top: 28px;
  }

  .notifications-page-inner {
    width: min(100% - 28px, 1120px);
  }

  .notifications-page-head {
    grid-template-columns: 44px minmax(0, 1fr);
    gap: 14px;
    padding-bottom: 24px;
  }

  .notifications-back {
    width: 42px;
    height: 42px;
  }

  .notifications-page-head h1 {
    font-size: 38px;
  }

  .notifications-page-head .eyebrow {
    display: none;
  }

  .notifications-page-head > div > p:last-child {
    font-size: 11px;
  }

  .notifications-category-tabs {
    display: flex;
    overflow-x: auto;
    justify-content: flex-start;
    scrollbar-width: none;
  }

  .notifications-category-tabs::-webkit-scrollbar {
    display: none;
  }

  .notifications-category-tabs button {
    min-width: max-content;
    min-height: 50px;
  }

  .notifications-toolbar {
    align-items: stretch;
    flex-direction: column;
  }

  .notifications-mark-all {
    width: 100%;
  }

  .notification-card {
    grid-template-columns: 42px minmax(0, 1fr);
    align-items: start;
    padding: 14px;
  }

  .notification-card-icon {
    width: 40px;
    height: 40px;
  }

  .notification-read-toggle {
    grid-column: 2;
    justify-self: start;
  }

  .notification-card-copy p {
    display: -webkit-box;
    overflow: hidden;
    white-space: normal;
    -webkit-box-orient: vertical;
    -webkit-line-clamp: 2;
  }

  .notification-card-meta {
    flex-wrap: wrap;
  }

  .notification-card-meta time {
    margin-left: 0;
  }

  .notifications-pagination {
    grid-template-columns: 1fr 1fr;
  }

  .notifications-pagination > span,
  .notifications-pagination > div {
    grid-column: 1 / -1;
    justify-self: center;
  }

  .notifications-pagination > span {
    grid-row: 1;
  }

  .notifications-pagination > div {
    grid-row: 2;
  }

  .notifications-pagination > button:first-child {
    grid-column: 1;
    grid-row: 3;
  }

  .notifications-pagination > button:last-child {
    grid-column: 2;
    grid-row: 3;
  }
}

/* v1.2.2 featured discovery and protected-workspace refinement */
.featured-slider {
  position: relative;
  min-height: clamp(600px, 72vw, 740px);
  overflow: hidden;
  border-bottom: 1px solid var(--line);
  background: #050d18;
  isolation: isolate;
}

.featured-slider-backdrop,
.featured-slider-shade {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.featured-slider-backdrop {
  z-index: -3;
  object-fit: cover;
  filter: blur(32px) saturate(0.72);
  opacity: 0.3;
  transform: scale(1.12);
}

.featured-slider-shade {
  z-index: -2;
  background:
    radial-gradient(circle at 34% 42%, color-mix(in srgb, var(--accent) 14%, transparent), transparent 32rem),
    linear-gradient(90deg, rgba(5, 13, 24, 0.15), rgba(5, 13, 24, 0.92) 76%),
    linear-gradient(180deg, rgba(5, 13, 24, 0.05), #050d18 97%);
}

.featured-slider-inner {
  display: grid;
  min-height: inherit;
  grid-template-columns: minmax(500px, 1.16fr) minmax(310px, 0.84fr);
  align-items: center;
  gap: clamp(40px, 6vw, 88px);
  padding-block: clamp(42px, 6vw, 72px);
}

.featured-slider-stage {
  position: relative;
  display: grid;
  min-width: 0;
  min-height: 500px;
  grid-template-columns: minmax(120px, 0.72fr) minmax(230px, 1fr) minmax(120px, 0.72fr);
  align-items: center;
  justify-items: center;
  gap: 12px;
  perspective: 1200px;
  touch-action: pan-y;
}

.featured-main-card,
.featured-side-card {
  position: relative;
  display: grid;
  overflow: hidden;
  place-items: center;
  padding: 0;
  border: 1px solid color-mix(in srgb, white 12%, var(--line));
  background: var(--surface);
  box-shadow: 0 28px 68px rgba(0, 0, 0, 0.44);
  transition:
    transform 260ms cubic-bezier(0.2, 0.8, 0.2, 1),
    opacity 260ms ease,
    filter 260ms ease;
}

.featured-main-card {
  z-index: 3;
  width: min(300px, 100%);
  aspect-ratio: 2 / 3;
  border-radius: 18px;
  animation: featured-card-enter 360ms cubic-bezier(0.16, 1, 0.3, 1) both;
}

.featured-main-card:hover {
  transform: translateY(-6px) scale(1.015);
}

.featured-main-card > img,
.featured-side-card > img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.featured-main-card > span {
  position: absolute;
  top: 11px;
  left: 11px;
  display: inline-flex;
  min-height: 28px;
  align-items: center;
  gap: 5px;
  padding: 0 9px;
  border-radius: 8px;
  background: rgba(4, 11, 20, 0.86);
  color: #f4c850;
  font-size: 10px;
  font-weight: 850;
  backdrop-filter: blur(10px);
}

.featured-side-card {
  width: min(220px, 100%);
  aspect-ratio: 2 / 3;
  border-radius: 15px;
  opacity: 0.48;
  filter: saturate(0.62) brightness(0.72);
  cursor: pointer;
}

.featured-side-card-left {
  transform: translateX(24%) rotateY(12deg) scale(0.9);
}

.featured-side-card-right {
  transform: translateX(-24%) rotateY(-12deg) scale(0.9);
}

.featured-side-card:hover {
  opacity: 0.78;
  filter: saturate(0.86) brightness(0.88);
}

.featured-slider-arrows {
  position: absolute;
  z-index: 5;
  right: 1%;
  left: 1%;
  display: flex;
  justify-content: space-between;
  pointer-events: none;
}

.featured-slider-arrows button {
  display: grid;
  width: 48px;
  height: 48px;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--accent) 35%, var(--line));
  border-radius: 50%;
  background: rgba(7, 17, 31, 0.76);
  color: #f4f8fc;
  box-shadow: 0 12px 34px rgba(0, 0, 0, 0.35);
  cursor: pointer;
  pointer-events: auto;
  backdrop-filter: blur(16px);
}

.featured-slider-copy,
.featured-slider-fallback-copy {
  display: grid;
  align-content: center;
  justify-items: start;
  gap: 17px;
  color: #f4f8fc;
  animation: featured-copy-enter 380ms cubic-bezier(0.16, 1, 0.3, 1) both;
}

.featured-slider-copy > div:first-child {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
}

.featured-slider-copy > div:first-child > span:not(.series-type-badge) {
  padding: 6px 9px;
  border: 1px solid color-mix(in srgb, var(--accent) 30%, var(--line));
  border-radius: 999px;
  color: #c5d2dd;
  font-size: 9px;
  font-weight: 760;
}

.featured-slider-copy h1,
.featured-slider-copy p,
.featured-slider-fallback-copy h1,
.featured-slider-fallback-copy p {
  margin: 0;
}

.featured-slider-copy h1,
.featured-slider-fallback-copy h1 {
  max-width: 12ch;
  font-size: clamp(42px, 5.5vw, 74px);
  letter-spacing: -0.065em;
  line-height: 0.96;
  text-wrap: balance;
}

.featured-slider-copy p {
  display: -webkit-box;
  max-width: 48ch;
  overflow: hidden;
  color: #c5d2dd;
  font-size: 15px;
  line-height: 1.65;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
}

.featured-slider-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.featured-slider-actions .button {
  min-height: 50px;
}

.featured-slider-actions .button-secondary {
  border-color: rgba(244, 248, 252, 0.28);
  background: rgba(244, 248, 252, 0.12);
  color: #f4f8fc;
  backdrop-filter: blur(14px);
}

.featured-slider-actions .button-secondary:hover {
  border-color: rgba(244, 248, 252, 0.48);
  background: rgba(244, 248, 252, 0.19);
}

.featured-slider-dots {
  display: flex;
  min-height: 22px;
  align-items: center;
  gap: 7px;
}

.featured-slider-dots button {
  width: 7px;
  height: 7px;
  padding: 0;
  border: 0;
  border-radius: 999px;
  background: var(--theme-progress-track);
  cursor: pointer;
  transition:
    width 180ms ease,
    background 180ms ease;
}

.featured-slider-dots button[aria-pressed="true"] {
  width: 30px;
  background: var(--theme-progress-fill);
}

.featured-slider-fallback-copy {
  min-height: inherit;
}

@keyframes featured-card-enter {
  from {
    opacity: 0.35;
    transform: translateY(12px) scale(0.96);
  }
}

@keyframes featured-copy-enter {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
}

.editors-pick-section {
  width: min(860px, calc(100vw - 64px));
  padding-block: clamp(36px, 5vw, 58px);
}

.editors-pick-card {
  grid-template-columns: 1fr;
  gap: 18px;
  min-height: 0;
  padding: clamp(22px, 4vw, 36px);
}

.editors-pick-cover-stage {
  width: min(430px, 100%);
  min-height: 326px;
}

.editors-pick-cover {
  width: min(196px, 52%);
  border-radius: 14px;
  animation-duration: 320ms;
  animation-timing-function: cubic-bezier(0.16, 1, 0.3, 1);
}

.editors-pick-cover-back {
  width: min(170px, 44%);
  border-radius: 12px;
}

.editors-pick-cover-back-left {
  left: 7%;
}

.editors-pick-cover-back-right {
  right: 7%;
}

.editors-pick-copy {
  justify-items: center;
  gap: 10px;
  padding-top: 18px;
  border-top: 1px solid var(--line);
  text-align: center;
  animation-duration: 320ms;
  animation-timing-function: cubic-bezier(0.16, 1, 0.3, 1);
}

.editors-pick-copy h3 {
  max-width: 18ch;
  font-size: clamp(30px, 4.2vw, 46px);
}

.editors-pick-copy > p:not(.editors-pick-teaser) {
  display: -webkit-box;
  max-width: 60ch;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.editors-pick-chips,
.editors-pick-state,
.editors-pick-meta,
.editors-pick-actions {
  justify-content: center;
}

.community-highlight-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
}

.community-highlight-card {
  position: relative;
  grid-template-columns: 42px minmax(0, 1fr) 64px;
  min-height: 136px;
  gap: 12px;
  padding: 15px;
  border-color: color-mix(in srgb, var(--accent) 18%, var(--line));
  background:
    radial-gradient(circle at 100% 0%, color-mix(in srgb, var(--accent) 8%, transparent), transparent 44%),
    var(--surface);
}

.community-highlight-avatar {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  align-self: start;
  border: 1px solid color-mix(in srgb, var(--accent) 44%, var(--line));
  border-radius: 13px;
  background: color-mix(in srgb, var(--accent) 12%, var(--surface-2));
  color: var(--accent);
  font-size: 14px;
  font-weight: 800;
}

.community-highlight-cover {
  width: 64px;
  align-self: stretch;
  border-radius: 10px;
}

.community-highlight-copy {
  align-self: stretch;
  align-content: start;
  gap: 8px;
}

.community-highlight-source {
  display: flex;
  min-width: 0;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
}

.community-highlight-source strong {
  overflow: hidden;
  color: var(--text);
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.community-highlight-source em {
  padding: 3px 6px;
  border-radius: 6px;
  background: color-mix(in srgb, var(--accent) 10%, var(--surface-2));
  color: var(--accent);
  font-size: 9px;
  font-style: normal;
  font-weight: 720;
}

.community-highlight-copy q {
  display: -webkit-box;
  overflow: hidden;
  color: var(--text-soft);
  font-size: 12px;
  font-weight: 560;
  line-height: 1.48;
  quotes: none;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.community-highlight-meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 9px;
  color: var(--muted);
  font-size: 9px;
}

.community-highlight-meta > span {
  display: inline-flex;
  align-items: center;
  gap: 3px;
}

.community-highlight-meta > strong {
  color: var(--text);
  font-size: 10px;
}

.workspace-site-shell .ops-shell {
  width: min(1460px, calc(100vw - 48px));
  min-height: 780px;
  margin: 28px auto 72px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 20px;
  box-shadow: 0 30px 90px color-mix(in srgb, var(--shadow) 58%, transparent);
}

.workspace-site-shell .ops-main {
  min-width: 0;
  background:
    radial-gradient(circle at 100% 0, color-mix(in srgb, var(--accent) 7%, transparent), transparent 34rem),
    var(--bg);
}

.workspace-series-request-entry {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 18px;
  padding: clamp(20px, 3vw, 30px);
  border: 1px solid color-mix(in srgb, var(--accent) 38%, var(--line));
  border-radius: calc(var(--radius) + 2px);
  background:
    radial-gradient(circle at 100% 0%, color-mix(in srgb, var(--accent) 15%, transparent), transparent 42%),
    var(--surface);
}

.workspace-series-request-entry > div {
  display: grid;
  gap: 7px;
}

.workspace-series-request-entry :is(h3, p) {
  margin: 0;
}

.workspace-series-request-entry span {
  color: var(--accent);
  font-size: 10px;
  font-weight: 760;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.workspace-series-request-entry p {
  max-width: 62ch;
  color: var(--text-soft);
  line-height: 1.55;
}

.ops-header {
  min-height: 104px;
  padding: 22px clamp(22px, 3vw, 42px);
  border-bottom: 1px solid var(--line);
  background: color-mix(in srgb, var(--bg) 88%, transparent);
  backdrop-filter: blur(18px);
}

.ops-header h1 {
  font-size: clamp(32px, 4vw, 52px);
  letter-spacing: -0.05em;
}

.ops-main > .control-panel,
.ops-main > .appearance-workspace,
.ops-main > .reaction-library-panel {
  margin: clamp(18px, 3vw, 34px);
}

.ops-main :is(input, select, textarea) {
  min-height: 46px;
  border-color: color-mix(in srgb, var(--line) 88%, transparent);
  border-radius: 11px;
  background: color-mix(in srgb, var(--bg-soft) 92%, transparent);
  transition:
    border-color 160ms ease,
    box-shadow 160ms ease,
    background 160ms ease;
}

.ops-main :is(input, select, textarea):focus {
  border-color: var(--accent);
  background: var(--bg-soft);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 13%, transparent);
}

.upload-center-main {
  padding: clamp(18px, 3vw, 34px);
}

.upload-section-heading h2 {
  font-size: clamp(25px, 3vw, 38px);
  letter-spacing: -0.035em;
}

.upload-primary-actions a,
.upload-metric-grid article,
.upload-composer-card,
.series-request-form > fieldset {
  transition:
    transform 170ms ease,
    border-color 170ms ease,
    background 170ms ease;
}

.upload-primary-actions a:hover {
  border-color: color-mix(in srgb, var(--accent) 62%, var(--line));
  background: color-mix(in srgb, var(--accent) 7%, var(--surface));
  transform: translateY(-3px);
}

@media (max-width: 980px) {
  .featured-slider-inner {
    grid-template-columns: 1fr;
    gap: 22px;
    padding-block: 34px 46px;
  }

  .featured-slider-stage {
    min-height: 430px;
    grid-template-columns: minmax(90px, 0.62fr) minmax(220px, 1fr) minmax(90px, 0.62fr);
  }

  .featured-main-card {
    width: min(270px, 100%);
  }

  .featured-side-card {
    width: min(188px, 100%);
  }

  .featured-slider-copy {
    justify-items: center;
    text-align: center;
  }

  .featured-slider-copy h1 {
    max-width: 16ch;
  }

  .featured-slider-copy > div,
  .featured-slider-actions,
  .featured-slider-dots {
    justify-content: center;
  }
}

@media (max-width: 820px) {
  .featured-slider {
    min-height: 0;
  }

  .featured-slider-inner {
    width: 100%;
    padding: 26px 0 42px;
  }

  .featured-slider-stage {
    min-height: 370px;
    grid-template-columns: 17vw minmax(210px, 58vw) 17vw;
    gap: 0;
    overflow: hidden;
  }

  .featured-main-card {
    width: min(234px, 58vw);
    border-radius: 15px;
  }

  .featured-side-card {
    width: min(182px, 46vw);
    border-radius: 13px;
  }

  .featured-side-card-left {
    justify-self: end;
    transform: translateX(42%) scale(0.84);
  }

  .featured-side-card-right {
    justify-self: start;
    transform: translateX(-42%) scale(0.84);
  }

  .featured-slider-arrows {
    right: 8px;
    left: 8px;
  }

  .featured-slider-arrows button {
    width: 43px;
    height: 43px;
  }

  .featured-slider-copy {
    width: min(100% - 36px, 620px);
    margin-inline: auto;
  }

  .featured-slider-copy h1 {
    font-size: clamp(32px, 9vw, 48px);
  }

  .featured-slider-copy p {
    font-size: 13px;
    -webkit-line-clamp: 2;
  }

  .editors-pick-section {
    width: min(100% - 28px, 860px);
  }

  .editors-pick-card {
    gap: 12px;
    padding: 18px 14px 22px;
  }

  .editors-pick-cover-stage {
    width: min(340px, 82vw);
    min-height: 280px;
  }

  .editors-pick-cover {
    width: min(166px, 53%);
  }

  .editors-pick-cover-back {
    width: min(144px, 44%);
    opacity: 0.44;
  }

  .editors-pick-copy {
    justify-items: center;
    text-align: center;
  }

  .editors-pick-copy h3 {
    font-size: clamp(26px, 8vw, 36px);
  }

  .community-highlight-grid {
    grid-template-columns: 1fr;
  }

  .workspace-site-shell .ops-shell {
    width: 100%;
    min-height: 0;
    margin: 0 0 56px;
    border-inline: 0;
    border-radius: 0;
    box-shadow: none;
  }

  .ops-main > .control-panel,
  .ops-main > .appearance-workspace,
  .ops-main > .reaction-library-panel {
    margin: 14px;
  }

  .workspace-series-request-entry {
    align-items: stretch;
    flex-direction: column;
  }
}

@media (max-width: 520px) {
  .featured-slider-stage {
    min-height: 332px;
  }

  .featured-main-card {
    width: min(208px, 58vw);
  }

  .featured-slider-copy {
    gap: 12px;
  }

  .featured-slider-actions {
    display: grid;
    width: 100%;
  }

  .featured-slider-actions .button,
  .workspace-series-request-entry .button {
    width: 100%;
  }

  .editors-pick-cover-stage {
    min-height: 264px;
  }

  .editors-pick-cover {
    width: min(158px, 53%);
  }

  .editors-pick-cover-back {
    width: min(138px, 44%);
  }

  .editors-pick-copy > p:not(.editors-pick-teaser),
  .editors-pick-meta {
    display: none;
  }

  .community-highlight-card {
    grid-template-columns: 38px minmax(0, 1fr) 54px;
    min-height: 118px;
    padding: 12px;
  }

  .community-highlight-avatar {
    width: 38px;
    height: 38px;
  }

  .community-highlight-cover {
    width: 54px;
  }
}

/* Version 28 — desktop editorial, Gifts, Shards, and Roulette */

.editors-pick-desktop-detail {
  display: none;
}

.new-series-cover .new-series-badges {
  position: absolute;
  z-index: 3;
  right: 8px;
  bottom: 8px;
  left: 8px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 5px;
  pointer-events: none;
}

.new-series-cover .new-series-badges :is(.series-type-badge, .series-status-badge) {
  min-height: 21px;
  padding-inline: 6px;
  border-color: rgba(255, 255, 255, 0.34);
  background: rgba(4, 11, 20, 0.78);
  color: #fff;
  font-size: 7.5px;
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.28);
  backdrop-filter: blur(10px);
}

.search-preview-card .series-type-badge {
  width: max-content;
  min-height: 21px;
  gap: 4px;
  padding-inline: 7px;
  font-size: 8px;
  letter-spacing: 0.035em;
}

.wallet-chip-multi {
  min-width: min(330px, 100%);
}

.store-hero .wallet-chip-multi > span {
  color: var(--text-soft);
}

.store-hero .wallet-chip-multi > span b {
  color: var(--text);
  font-size: 18px;
  letter-spacing: -0.025em;
}

.store-hero .wallet-chip-multi > span:nth-child(2) {
  grid-column: 1;
}

.store-hero .wallet-chip-multi > svg:last-child {
  grid-row: 1 / span 2;
}

.gift-store {
  display: grid;
  gap: 26px;
  padding-block: 32px 80px;
}

.gift-store-heading {
  display: grid;
  max-width: 780px;
  gap: 7px;
}

.gift-store-heading h2,
.gift-store-heading p {
  margin: 0;
}

.gift-store-heading h2 {
  color: var(--text);
  font-size: clamp(30px, 4vw, 52px);
  letter-spacing: -0.055em;
  line-height: 1;
}

.gift-store-heading > p:last-child {
  max-width: 66ch;
  color: var(--muted);
  line-height: 1.65;
}

.gift-store-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
}

.gift-purchase-card {
  position: relative;
  display: grid;
  align-content: start;
  gap: 17px;
  overflow: hidden;
  padding: clamp(22px, 3vw, 34px);
  border: 1px solid color-mix(in srgb, var(--accent) 30%, var(--line));
  border-radius: 24px;
  background:
    radial-gradient(circle at 100% 0%, color-mix(in srgb, var(--accent) 15%, transparent), transparent 38%),
    var(--surface);
  box-shadow: 0 26px 70px color-mix(in srgb, var(--shadow) 70%, transparent);
}

.team-support-card {
  border-color: color-mix(in srgb, #ff688c 30%, var(--line));
  background:
    radial-gradient(circle at 100% 0%, color-mix(in srgb, #ff688c 12%, transparent), transparent 38%),
    var(--surface);
}

.gift-card-icon {
  display: grid;
  width: 52px;
  height: 52px;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--accent) 42%, var(--line));
  border-radius: 16px;
  background: color-mix(in srgb, var(--accent) 12%, var(--surface-2));
  color: var(--accent);
}

.gift-purchase-card h3,
.gift-purchase-card p {
  margin: 0;
}

.gift-purchase-card h3 {
  margin-block: 4px 7px;
  font-size: clamp(22px, 2.7vw, 32px);
  letter-spacing: -0.04em;
}

.gift-purchase-card > div > p:last-child {
  color: var(--muted);
  line-height: 1.55;
}

.gift-purchase-card > label,
.gift-redeem-card > label {
  display: grid;
  gap: 7px;
  color: var(--text-soft);
  font-size: 11px;
  font-weight: 800;
}

.gift-purchase-card :is(input, textarea, select),
.gift-redeem-card input {
  width: 100%;
  min-height: 44px;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: 11px;
  outline: 0;
  background: var(--surface-2);
  color: var(--text);
  font: inherit;
}

.gift-purchase-card textarea {
  min-height: 82px;
  resize: vertical;
}

.gift-purchase-card :is(input, textarea, select):focus,
.gift-redeem-card input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 12%, transparent);
}

.gift-purchase-card > .button {
  width: 100%;
}

.support-pack-options {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 7px;
}

.support-pack-options button {
  display: inline-flex;
  min-height: 39px;
  align-items: center;
  justify-content: center;
  gap: 5px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--surface-2);
  color: var(--text-soft);
  font-size: 10px;
  font-weight: 850;
  cursor: pointer;
}

.support-pack-options button[aria-pressed="true"] {
  border-color: color-mix(in srgb, var(--theme-primary) 55%, var(--line));
  background: color-mix(in srgb, var(--theme-primary) 12%, var(--surface));
  color: var(--theme-primary);
}

.gift-code-result {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  padding: 13px;
  border: 1px solid color-mix(in srgb, var(--success) 48%, var(--line));
  border-radius: 13px;
  background: color-mix(in srgb, var(--success) 8%, var(--surface-2));
  color: var(--success);
}

.gift-code-result > div {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.gift-code-result code {
  overflow: hidden;
  color: var(--text);
  font-size: clamp(12px, 1.5vw, 15px);
  font-weight: 900;
  letter-spacing: 0.08em;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.gift-code-result button,
.gift-card-history article > button {
  display: inline-flex;
  min-height: 36px;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding-inline: 10px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: var(--surface);
  color: var(--text);
  font-size: 10px;
  font-weight: 800;
  cursor: pointer;
}

.gift-store-signin,
.roulette-signin {
  display: grid;
  justify-items: center;
  gap: 12px;
  padding: clamp(34px, 8vw, 90px);
  border: 1px solid var(--line);
  border-radius: 24px;
  background: var(--surface);
  text-align: center;
}

.gift-store-signin h2,
.gift-store-signin p,
.roulette-signin h1,
.roulette-signin p {
  margin: 0;
}

.roulette-page {
  display: grid;
  gap: 22px;
  padding-block: clamp(32px, 6vw, 72px) 90px;
}

.roulette-hero {
  display: grid;
  min-height: 610px;
  grid-template-columns: minmax(0, 0.86fr) minmax(470px, 1.14fr);
  align-items: center;
  gap: clamp(30px, 6vw, 96px);
  overflow: hidden;
  padding: clamp(28px, 5vw, 68px);
  border: 1px solid color-mix(in srgb, var(--accent) 38%, var(--line));
  border-radius: 30px;
  background:
    radial-gradient(circle at 80% 20%, color-mix(in srgb, var(--accent) 20%, transparent), transparent 36%),
    radial-gradient(circle at 15% 95%, color-mix(in srgb, #8d5dff 15%, transparent), transparent 35%),
    var(--surface);
  box-shadow: 0 38px 100px color-mix(in srgb, var(--shadow) 82%, transparent);
}

.roulette-copy {
  display: grid;
  align-content: center;
  gap: 16px;
}

.roulette-copy h1,
.roulette-copy p {
  margin: 0;
}

.roulette-copy h1 {
  max-width: 8ch;
  font-size: clamp(46px, 7vw, 86px);
  letter-spacing: -0.075em;
  line-height: 0.9;
}

.roulette-copy > p:not(.eyebrow) {
  max-width: 55ch;
  color: var(--muted);
  line-height: 1.65;
}

.roulette-balances {
  display: flex;
  flex-wrap: wrap;
  gap: 9px;
}

.roulette-balances > span {
  display: inline-flex;
  min-height: 40px;
  align-items: center;
  gap: 6px;
  padding-inline: 12px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--surface-2);
  color: var(--muted);
  font-size: 10px;
}

.roulette-balances strong {
  color: var(--text);
  font-size: 13px;
}

.roulette-spin-button {
  width: min(100%, 330px);
  min-height: 52px;
}

.roulette-cooldown {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--muted);
}

.roulette-stage {
  position: relative;
  display: grid;
  min-height: 520px;
  place-items: center;
}

.roulette-pointer {
  position: absolute;
  z-index: 4;
  top: 3px;
  left: 50%;
  width: 0;
  height: 0;
  border-top: 34px solid var(--text);
  border-right: 18px solid transparent;
  border-left: 18px solid transparent;
  filter: drop-shadow(0 7px 12px rgba(0, 0, 0, 0.3));
  transform: translateX(-50%);
}

.roulette-wheel {
  position: relative;
  width: min(500px, 42vw);
  aspect-ratio: 1;
  border: 10px solid color-mix(in srgb, var(--text) 90%, var(--surface));
  border-radius: 50%;
  background:
    radial-gradient(circle, var(--surface) 0 17%, transparent 17.5%),
    repeating-conic-gradient(
      from -18deg,
      color-mix(in srgb, var(--accent) 86%, #127cff) 0deg 36deg,
      color-mix(in srgb, #8d5dff 86%, var(--accent)) 36deg 72deg,
      color-mix(in srgb, #ff6587 84%, var(--accent)) 72deg 108deg
    );
  box-shadow:
    0 0 0 8px color-mix(in srgb, var(--accent) 24%, transparent),
    0 35px 80px rgba(0, 0, 0, 0.35);
  transform: rotate(var(--roulette-rotation));
  transition: transform 1.8s cubic-bezier(0.08, 0.72, 0.08, 1);
}

.roulette-segment-label {
  --segment-angle: calc(360deg / var(--roulette-count));
  position: absolute;
  top: 50%;
  left: 50%;
  display: flex;
  width: 42%;
  align-items: center;
  justify-content: flex-end;
  gap: 5px;
  color: #fff;
  font-size: clamp(8px, 1vw, 12px);
  font-weight: 900;
  text-align: right;
  text-shadow: 0 1px 4px rgba(0, 0, 0, 0.55);
  transform:
    translateY(-50%)
    rotate(calc(var(--segment-angle) * var(--segment-index)))
    translateX(13%);
  transform-origin: 0 50%;
}

.roulette-hub {
  position: absolute;
  z-index: 2;
  top: 50%;
  left: 50%;
  display: grid;
  width: 25%;
  aspect-ratio: 1;
  place-items: center;
  border: 7px solid color-mix(in srgb, var(--text) 88%, var(--surface));
  border-radius: 50%;
  background: var(--surface);
  color: var(--accent);
  transform: translate(-50%, -50%);
}

.roulette-result {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 17px 20px;
  border: 1px solid color-mix(in srgb, var(--success) 42%, var(--line));
  border-radius: 15px;
  background: color-mix(in srgb, var(--success) 8%, var(--surface));
  color: var(--success);
}

.roulette-result > div {
  display: grid;
  gap: 3px;
}

.roulette-result span {
  color: var(--text-soft);
  font-size: 11px;
}

.roulette-history {
  display: grid;
  gap: 14px;
  padding: clamp(22px, 4vw, 34px);
  border: 1px solid var(--line);
  border-radius: 22px;
  background: var(--surface);
}

.roulette-history header h2,
.roulette-history header p {
  margin: 0;
}

.roulette-history header p {
  margin-top: 4px;
  color: var(--muted);
}

.roulette-history > div {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 9px;
}

.roulette-history article {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 10px;
  padding: 13px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--surface-2);
}

.roulette-history article > span {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  border-radius: 10px;
  background: color-mix(in srgb, var(--accent) 12%, var(--surface));
  color: var(--accent);
}

.roulette-history time {
  grid-column: 2;
  color: var(--muted);
  font-size: 9px;
}

.wallet-balance-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.wallet-balance-grid .wallet-hero {
  min-width: 0;
}

.wallet-hero-shards {
  background:
    radial-gradient(circle at 90% 0%, color-mix(in srgb, #8d5dff 18%, transparent), transparent 48%),
    var(--surface);
}

.gift-cards-account {
  display: grid;
  gap: 18px;
}

.gift-redeem-card {
  display: grid;
  grid-template-columns: minmax(220px, 1fr) minmax(220px, 1fr) auto;
  align-items: end;
  gap: 13px;
  padding: 20px;
  border: 1px solid color-mix(in srgb, var(--accent) 30%, var(--line));
  border-radius: 17px;
  background: color-mix(in srgb, var(--accent) 5%, var(--surface));
}

.gift-redeem-card > div {
  display: flex;
  align-items: center;
  gap: 10px;
}

.gift-redeem-card > div > span {
  display: grid;
  gap: 3px;
  color: var(--muted);
  font-size: 10px;
}

.gift-redeem-card > div strong {
  color: var(--text);
  font-size: 13px;
}

.gift-redeem-card > p {
  grid-column: 1 / -1;
  margin: 0;
  color: var(--text-soft);
  font-size: 11px;
}

.gift-card-history {
  display: grid;
  gap: 10px;
}

.gift-card-history > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.gift-card-history > header h3 {
  margin: 0;
}

.gift-card-history > header a {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  color: var(--accent);
  font-size: 11px;
  font-weight: 800;
}

.gift-card-history article {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto auto auto;
  align-items: center;
  gap: 12px;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: var(--surface-2);
}

.gift-history-icon {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  border-radius: 11px;
  background: color-mix(in srgb, var(--accent) 12%, var(--surface));
  color: var(--accent);
}

.gift-card-history article > div {
  display: grid;
  gap: 3px;
}

.gift-card-history code {
  color: var(--text);
  font-weight: 900;
  letter-spacing: 0.06em;
}

.gift-card-history article p,
.gift-card-history article small {
  margin: 0;
  color: var(--muted);
  font-size: 9px;
}

.gift-card-history article > em {
  padding: 5px 8px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--danger) 9%, var(--surface));
  color: var(--danger);
  font-size: 9px;
  font-style: normal;
  font-weight: 850;
}

.gift-card-history article > em[data-valid="true"] {
  background: color-mix(in srgb, var(--success) 10%, var(--surface));
  color: var(--success);
}

.reward-settings-panel {
  display: grid;
  gap: 18px;
  margin-top: 18px;
  padding: clamp(20px, 3vw, 30px);
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--surface);
}

.reward-settings-panel > header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
}

.reward-settings-panel > header h2,
.reward-settings-panel > header p {
  margin: 0;
}

.reward-settings-panel > header h2 {
  margin-block: 6px;
}

.reward-settings-panel > header p {
  max-width: 70ch;
  color: var(--muted);
}

.reward-settings-content {
  display: grid;
  gap: 12px;
  min-inline-size: 0;
  margin: 0;
  padding: 0;
  border: 0;
}

.reward-settings-content > details {
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--surface-2);
}

.reward-settings-content summary {
  padding: 16px 18px;
  color: var(--text);
  font-weight: 850;
  cursor: pointer;
}

.reward-settings-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 13px;
  padding: 4px 18px 18px;
}

.reward-settings-grid label,
.roulette-admin-toolbar label,
.roulette-admin-list label {
  display: grid;
  gap: 6px;
  color: var(--text-soft);
  font-size: 10px;
  font-weight: 800;
}

.reward-settings-panel :is(input, select) {
  width: 100%;
  min-height: 40px;
  padding: 8px 10px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: var(--surface);
  color: var(--text);
}

.roulette-admin-toolbar {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 12px;
  padding: 4px 18px 12px;
}

.roulette-admin-toolbar button {
  display: inline-flex;
  min-height: 40px;
  align-items: center;
  gap: 6px;
  padding-inline: 13px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: var(--surface);
  color: var(--text);
  font-weight: 800;
  cursor: pointer;
}

.roulette-admin-list {
  display: grid;
  gap: 8px;
  padding: 0 18px 18px;
}

.roulette-admin-list article {
  display: grid;
  grid-template-columns: minmax(150px, 1.2fr) minmax(105px, 0.7fr) minmax(100px, 0.8fr) 90px auto auto;
  align-items: end;
  gap: 9px;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: var(--surface);
}

.roulette-admin-list article > button {
  display: grid;
  width: 40px;
  height: 40px;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: var(--surface-2);
  color: var(--danger);
  cursor: pointer;
}

@media (min-width: 981px) {
