/* Version 30 — recipient, discovery, reading continuity, and operations polish */

:root {
  --success: var(--theme-status-green);
}

.gift-recipient-fieldset {
  display: grid;
  min-width: 0;
  gap: 11px;
  margin: 0;
  padding: 0;
  border: 0;
}

.gift-recipient-fieldset legend,
.gift-recipient-fieldset label > span {
  margin-bottom: 7px;
  color: var(--text-soft);
  font-size: 10px;
  font-weight: 760;
}

.gift-recipient-tabs {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 7px;
  padding: 4px;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: var(--bg-soft);
}

.gift-recipient-tabs button {
  display: inline-flex;
  min-height: 40px;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 0 10px;
  border: 1px solid transparent;
  border-radius: 9px;
  background: transparent;
  color: var(--muted);
  font-size: 10px;
  font-weight: 760;
  cursor: pointer;
  transition:
    border-color 180ms ease,
    background 180ms ease,
    color 180ms ease;
}

.gift-recipient-tabs button[aria-pressed="true"] {
  border-color: color-mix(in srgb, var(--accent) 44%, var(--line));
  background: color-mix(in srgb, var(--accent) 11%, var(--surface));
  color: var(--text);
}

.gift-recipient-tabs button:disabled {
  cursor: not-allowed;
  opacity: 0.46;
}

.gift-recipient-fieldset > label {
  display: grid;
}

.gift-recipient-fieldset > small {
  color: var(--muted);
  font-size: 9px;
  line-height: 1.55;
}

.gift-series-options {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 7px;
  max-height: 190px;
  overflow: auto;
  padding: 8px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--bg-soft);
}

.gift-series-options label {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 8px;
  padding: 8px;
  border-radius: 8px;
  background: color-mix(in srgb, var(--surface) 84%, transparent);
}

.gift-series-options input {
  flex: 0 0 auto;
}

.gift-series-options span {
  overflow: hidden;
  color: var(--text);
  text-overflow: ellipsis;
  white-space: nowrap;
}

@media (max-width: 620px) {
  .gift-series-options {
    grid-template-columns: 1fr;
  }
}

.continue-reading-section {
  display: grid;
  gap: 17px;
  padding-block: clamp(44px, 6vw, 78px);
}

.continue-reading-heading,
.continue-reading-actions,
.continue-reading-actions > div {
  display: flex;
  align-items: center;
}

.continue-reading-heading {
  justify-content: space-between;
  gap: 22px;
}

.continue-reading-heading > div:first-child {
  display: grid;
  gap: 5px;
}

.continue-reading-heading :is(h2, p) {
  margin: 0;
}

.continue-reading-heading h2 {
  font-size: clamp(28px, 3.5vw, 43px);
  letter-spacing: -0.055em;
  line-height: 1;
}

.continue-reading-heading > div:first-child > p:last-child {
  color: var(--muted);
  font-size: 11px;
}

.continue-reading-heading .continue-reading-preference-error {
  color: var(--danger);
  font-size: 9px;
}

.continue-reading-actions {
  gap: 13px;
}

.continue-reading-actions > div {
  gap: 4px;
  padding: 4px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--surface);
}

.continue-reading-actions button {
  display: grid;
  width: 36px;
  height: 34px;
  place-items: center;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--muted);
  cursor: pointer;
}

.continue-reading-actions button[aria-pressed="true"] {
  background: var(--surface-3);
  color: var(--accent);
}

.continue-reading-actions button:disabled {
  cursor: wait;
  opacity: 0.55;
}

.continue-reading-actions > a {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: var(--accent);
  font-size: 11px;
  font-weight: 780;
}

.continue-reading-list,
.continue-reading-loading {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 9px;
}

.continue-reading-item {
  position: relative;
  display: grid;
  min-width: 0;
  grid-template-columns: 58px minmax(0, 1fr) 38px;
  align-items: center;
  gap: 13px;
  padding: 9px 11px 9px 9px;
  border: 1px solid color-mix(in srgb, var(--line) 88%, transparent);
  border-radius: 14px;
  background: color-mix(in srgb, var(--surface) 92%, transparent);
  color: var(--text);
  transition:
    border-color 180ms ease,
    background 180ms ease,
    transform 180ms ease;
}

.continue-reading-item:hover,
.continue-reading-item:focus-visible {
  border-color: color-mix(in srgb, var(--accent) 45%, var(--line));
  background: var(--surface-2);
  transform: translateY(-2px);
}

.continue-reading-cover {
  display: grid;
  width: 58px;
  aspect-ratio: 2 / 3;
  place-items: center;
  overflow: hidden;
  border-radius: 9px;
  background: var(--surface-3);
  color: var(--accent);
}

.continue-reading-cover img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center top;
}

.continue-reading-copy {
  display: grid;
  min-width: 0;
  gap: 4px;
}

.continue-reading-copy > strong,
.continue-reading-copy > small,
.continue-reading-copy > span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.continue-reading-copy > strong {
  font-size: 12px;
}

.continue-reading-copy > small {
  color: var(--text-soft);
  font-size: 10px;
}

.continue-reading-copy > span {
  color: var(--muted);
  font-size: 9px;
}

.continue-reading-progress {
  display: block;
  width: 100%;
  height: 4px;
  overflow: hidden;
  margin-top: 3px;
  border-radius: 999px;
  background: var(--theme-progress-track);
}

.continue-reading-progress > b {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--theme-progress-fill);
}

.continue-reading-resume {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--accent) 34%, var(--line));
  border-radius: 11px;
  background: color-mix(in srgb, var(--accent) 10%, var(--surface));
  color: var(--accent);
}

.continue-reading-guest,
.continue-reading-state {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 13px;
  min-height: 88px;
  padding: 17px 19px;
  border: 1px solid var(--line);
  border-radius: 15px;
  background: var(--surface);
}

.continue-reading-guest > span,
.continue-reading-state > svg {
  display: grid;
  width: 40px;
  height: 40px;
  place-items: center;
  border-radius: 12px;
  background: color-mix(in srgb, var(--accent) 11%, var(--surface-2));
  color: var(--accent);
}

.continue-reading-guest > div,
.continue-reading-state > div {
  display: grid;
  gap: 3px;
}

.continue-reading-guest :is(p, strong),
.continue-reading-state :is(span, strong) {
  margin: 0;
}

.continue-reading-guest p,
.continue-reading-state span {
  color: var(--muted);
  font-size: 10px;
}

.continue-reading-state > :is(button, a) {
  min-height: 38px;
  padding: 0 12px;
  border: 1px solid var(--line-strong);
  border-radius: 10px;
  background: var(--surface-2);
  color: var(--text);
  font-size: 10px;
  font-weight: 760;
  cursor: pointer;
}

.continue-reading-loading > span {
  display: grid;
  min-height: 104px;
  grid-template-columns: 58px minmax(0, 1fr);
  grid-template-rows: repeat(3, 12px);
  align-content: center;
  gap: 9px 13px;
  padding: 9px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--surface);
}

.continue-reading-loading i {
  grid-row: 1 / -1;
  width: 58px;
  aspect-ratio: 2 / 3;
  border-radius: 9px;
}



.continue-reading-section.is-shelf .continue-reading-list {
  display: grid;
  grid-auto-columns: minmax(166px, 198px);
  grid-auto-flow: column;
  grid-template-columns: none;
  overflow-x: auto;
  padding: 2px 2px 10px;
  scroll-snap-type: x proximity;
  scrollbar-width: thin;
}

.continue-reading-section.is-shelf .continue-reading-item {
  grid-template-columns: 1fr;
  align-content: start;
  gap: 9px;
  padding: 8px;
  scroll-snap-align: start;
}

.continue-reading-section.is-shelf .continue-reading-cover {
  width: 100%;
}

.continue-reading-section.is-shelf .continue-reading-resume {
  position: absolute;
  right: 15px;
  bottom: 17px;
}

.continue-reading-section.is-shelf .continue-reading-copy {
  min-height: 92px;
  padding: 2px 46px 3px 3px;
