/* Browse's single-choice filters use the same Library listbox primitive. */
.compact-single-select {
  position: relative;
  display: grid;
  min-width: 0;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: end;
  gap: .35rem;
}

.compact-single-select > label {
  display: block;
  min-width: 0;
}

.compact-single-select .unified-single-select-trigger {
  padding-right: 2rem;
}

.compact-single-active-count {
  position: absolute;
  z-index: 1;
  top: .38rem;
  right: 2.15rem;
  display: grid;
  min-width: 1.15rem;
  height: 1.15rem;
  place-items: center;
  border-radius: 999px;
  color: var(--theme-button-accent-alternate);
  background: var(--theme-button-accent);
  font-size: .62rem;
  pointer-events: none;
