  outline-offset: 2px;
}

body:has(.browse-desktop-filter-bar) .browse-desktop-filter-bar > .compact-single-select {
  flex: 1 1 0;
}

.catalog-filter-grid > .compact-single-select {
  width: 100%;
}

.featured-card-banner:not(.featured-card-fallback),
.featured-outer-card {
