.ops-sidebar-head {
  display: flex;
  min-width: 0;
  align-items: center;
  justify-content: space-between;
  gap: 9px;
}

.ops-sidebar-head > .brand {
  min-width: 0;
  margin: 0 6px;
}

.ops-sidebar-collapse {
  display: grid;
  width: 38px;
  height: 38px;
  flex: 0 0 auto;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: var(--surface);
  color: var(--text-soft);
  cursor: pointer;
  transition:
    border-color 180ms ease,
    background 180ms ease,
    color 180ms ease,
    transform 180ms ease;
}

.ops-sidebar-collapse:hover,
.ops-sidebar-collapse:focus-visible {
  border-color: color-mix(in srgb, var(--accent) 42%, var(--line));
  background: var(--surface-2);
  color: var(--accent);
}

.ops-sidebar nav :is(a, button) > span.ops-nav-label {
  display: block;
  min-width: 0;
  height: auto;
  margin: 0;
  overflow: hidden;
  border-radius: 0;
  background: transparent;
  color: inherit;
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ops-sidebar nav .ops-nav-group-toggle > span {
  display: block;
  min-width: 0;
  height: auto;
  margin: 0;
  overflow: hidden;
  border-radius: 0;
  background: transparent;
  color: inherit;
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ops-grouped-nav {
  gap: 9px;
  padding-right: 3px;
  scrollbar-color: color-mix(in srgb, var(--line-strong) 72%, transparent)
    transparent;
  scrollbar-gutter: stable;
  scrollbar-width: thin;
}

.ops-nav-group-toggle {
  min-height: 32px !important;
  padding-inline: 10px !important;
  font-size: 9px !important;
  letter-spacing: 0.055em;
}

.ops-nav-group-items {
  gap: 3px;
}

.ops-nav-group-items > a {
  position: relative;
  min-height: 43px;
  gap: 11px;
  padding: 0 11px;
  border: 1px solid transparent;
  border-radius: 11px;
}

.ops-nav-group-items > a[aria-current="page"] {
  border-color: color-mix(in srgb, var(--accent) 24%, var(--line));
  background: color-mix(in srgb, var(--accent) 9%, var(--surface));
}

.ops-nav-group-items > a[aria-current="page"]::before {
  position: absolute;
  top: 10px;
  bottom: 10px;
  left: -1px;
  width: 3px;
  border-radius: 0 4px 4px 0;
  background: var(--accent);
  content: "";
}

@media (min-width: 901px) {
  .ops-shell {
    grid-template-columns: 276px minmax(0, 1fr);
    transition: grid-template-columns 220ms cubic-bezier(0.2, 0.8, 0.2, 1);
  }

  .ops-shell.is-sidebar-collapsed {
    grid-template-columns: 78px minmax(0, 1fr);
  }

  .ops-shell.is-sidebar-collapsed .ops-sidebar {
    padding-inline: 10px;
  }

  .ops-shell.is-sidebar-collapsed .ops-sidebar-head {
    display: grid;
    justify-items: center;
  }

  .ops-shell.is-sidebar-collapsed .ops-sidebar-head .brand {
    margin: 0;
  }

  .ops-shell.is-sidebar-collapsed
    .ops-sidebar-head
    .brand
    > span:last-child,
  .ops-shell.is-sidebar-collapsed .ops-workspace > div,
  .ops-shell.is-sidebar-collapsed .ops-nav-group-toggle,
  .ops-shell.is-sidebar-collapsed .ops-nav-label,
  .ops-shell.is-sidebar-collapsed .ops-session-actions span,
  .ops-shell.is-sidebar-collapsed .ops-user > div {
    display: none;
  }

  .ops-shell.is-sidebar-collapsed .ops-sidebar-collapse {
    transform: rotate(180deg);
  }

  .ops-shell.is-sidebar-collapsed .ops-workspace {
    grid-template-columns: 1fr;
    padding: 7px;
  }

  .ops-shell.is-sidebar-collapsed .ops-workspace > span,
  .ops-shell.is-sidebar-collapsed .ops-user > span {
    margin-inline: auto;
  }

  .ops-shell.is-sidebar-collapsed .ops-nav-group-items > a,
  .ops-shell.is-sidebar-collapsed .ops-session-actions a {
    justify-content: center;
    padding: 0;
  }

  .ops-shell.is-sidebar-collapsed .ops-nav-group {
    gap: 0;
  }

  .ops-shell.is-sidebar-collapsed .ops-user {
    grid-template-columns: 1fr;
    padding-inline: 0;
  }
}

@media (max-width: 900px) {
  .ops-sidebar-collapse {
    display: none;
  }

  .ops-sidebar-head {
    justify-content: center;
  }
}

.roulette-page {
  gap: 16px;
  padding-block: clamp(28px, 5vw, 58px) 78px;
}

.roulette-hero {
  min-height: 0;
  grid-template-columns: minmax(320px, 0.9fr) minmax(430px, 1.1fr);
  align-items: stretch;
  gap: clamp(24px, 4vw, 56px);
  padding: clamp(26px, 4vw, 48px);
  border-color: color-mix(in srgb, var(--accent) 26%, var(--line));
  border-radius: 25px;
  background:
    radial-gradient(
      circle at 88% 8%,
      color-mix(in srgb, var(--accent) 16%, transparent),
      transparent 34%
    ),
    linear-gradient(
      135deg,
      color-mix(in srgb, var(--surface) 96%, var(--accent)),
      var(--surface)
    );
  box-shadow: 0 30px 85px color-mix(in srgb, var(--bg) 72%, transparent);
}

.roulette-copy {
  align-content: start;
  gap: 14px;
}

.roulette-copy h1 {
  max-width: 11ch;
  font-size: clamp(42px, 5vw, 68px);
  letter-spacing: -0.065em;
  line-height: 0.94;
}

.roulette-copy > p:not(.eyebrow) {
  max-width: 52ch;
  font-size: 11px;
  line-height: 1.65;
}

.roulette-balances > span {
  min-height: 38px;
  border-radius: 11px;
  background: var(--surface-2);
  font-size: 9px;
}

.roulette-balances strong {
  font-variant-numeric: tabular-nums;
}

.roulette-reward-list {
  display: grid;
  min-height: 0;
  gap: 9px;
  overflow: hidden;
  padding: 13px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: color-mix(in srgb, var(--surface-2) 86%, transparent);
}

.roulette-reward-list > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.roulette-reward-list > header strong {
  font-size: 11px;
}

.roulette-reward-list > header span {
  display: grid;
  min-width: 24px;
  height: 22px;
  place-items: center;
  border-radius: 7px;
  background: color-mix(in srgb, var(--accent) 13%, var(--surface));
  color: var(--accent);
  font-size: 9px;
  font-weight: 800;
}

.roulette-reward-list ul {
  display: grid;
  max-height: 184px;
  gap: 2px;
  overflow-y: auto;
  margin: 0;
  padding: 0 3px 0 0;
  list-style: none;
  scrollbar-width: thin;
}

.roulette-reward-list li {
  display: grid;
  grid-template-columns: 25px minmax(0, 1fr) auto;
  align-items: center;
  gap: 9px;
  min-height: 32px;
  padding: 4px 6px;
  border-radius: 8px;
}

.roulette-reward-list li:nth-child(odd) {
  background: color-mix(in srgb, var(--surface-3) 52%, transparent);
}

.roulette-reward-list li > span {
  display: grid;
  width: 23px;
  height: 23px;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--accent) 28%, var(--line));
  border-radius: 7px;
  color: var(--accent);
  font-size: 8px;
  font-weight: 850;
}

.roulette-reward-list li > strong {
  overflow: hidden;
  font-size: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.roulette-reward-list li > small,
.roulette-reward-list > p {
  margin: 0;
  color: var(--muted);
  font-size: 9px;
}

.roulette-spin-button {
  width: 100%;
  max-width: none;
}

.roulette-stage-card {
  display: grid;
  min-width: 0;
  align-content: center;
  gap: 12px;
  padding: clamp(18px, 3vw, 28px);
  border: 1px solid var(--line);
  border-radius: 21px;
  background: color-mix(in srgb, var(--surface-2) 86%, transparent);
  box-shadow: inset 0 1px color-mix(in srgb, white 5%, transparent);
}

.roulette-stage-card > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.roulette-stage-card > header span {
  color: var(--muted);
  font-size: 9px;
  font-weight: 760;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.roulette-stage-card > header strong {
  color: var(--accent);
  font-size: 10px;
}

.roulette-stage-card > p {
  margin: 0;
  color: var(--muted);
  font-size: 9px;
  text-align: center;
}

.roulette-stage {
  min-height: 0;
  padding-block: 12px 3px;
}

.roulette-pointer {
  top: 0;
  width: 34px;
  height: 38px;
  border: 0;
  background: var(--text);
  clip-path: polygon(0 0, 100% 0, 50% 100%);
  filter: drop-shadow(0 7px 12px color-mix(in srgb, var(--bg) 70%, transparent));
}

.roulette-wheel {
  width: min(430px, 35vw);
  border: 8px solid color-mix(in srgb, var(--text) 82%, var(--surface));
  background:
    radial-gradient(
      circle,
      var(--surface) 0 18%,
      transparent 18.5%
    ),
    repeating-conic-gradient(
      from -90deg,
      color-mix(in srgb, var(--accent) 63%, var(--surface-3))
        0
        calc(var(--roulette-slice) - 1.5deg),
      color-mix(in srgb, var(--line-strong) 80%, var(--surface))
        calc(var(--roulette-slice) - 1.5deg)
        var(--roulette-slice)
    );
  box-shadow:
    0 0 0 7px color-mix(in srgb, var(--accent) 17%, transparent),
    0 28px 66px color-mix(in srgb, var(--bg) 72%, transparent);
}

.roulette-segment-label {
  width: 39%;
  justify-content: flex-end;
  gap: 3px;
  color: var(--text);
  font-size: clamp(7px, 0.8vw, 10px);
  text-shadow: 0 1px 5px color-mix(in srgb, var(--bg) 72%, transparent);
  transform:
    translateY(-50%)
    rotate(
      calc(
        -90deg + (var(--roulette-slice) * var(--segment-index)) +
          (var(--roulette-slice) / 2)
      )
    )
    translateX(18%);
}

.roulette-segment-label strong {
  font-variant-numeric: tabular-nums;
}

.roulette-segment-label small {
  color: color-mix(in srgb, var(--text) 78%, var(--accent));
  font-size: 8px;
  font-weight: 900;
}

.roulette-hub {
  border-color: color-mix(in srgb, var(--text) 82%, var(--surface));
  background: var(--surface);
  box-shadow: 0 0 0 5px color-mix(in srgb, var(--accent) 14%, transparent);
}

.roulette-history {
  gap: 9px;
  padding: 20px;
  border-radius: 17px;
}

.roulette-history > div {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0;
}

.roulette-history article {
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 11px;
  padding: 10px 4px;
  border: 0;
  border-bottom: 1px solid var(--line);
  border-radius: 0;
  background: transparent;
}

.roulette-history article:last-child {
  border-bottom: 0;
}

.roulette-history time {
  grid-column: auto;
  font-variant-numeric: tabular-nums;
}

@media (max-width: 980px) {
  .roulette-hero {
    grid-template-columns: 1fr;
  }

  .roulette-copy {
    justify-items: stretch;
    text-align: left;
  }

  .roulette-copy h1 {
    max-width: 12ch;
  }

  .roulette-wheel {
    width: min(430px, 70vw);
  }
}

