  min-height: 340px;
  place-content: center;
  justify-items: center;
  gap: 8px;
}

.support-admin-empty-detail strong {
  color: var(--text);
}

.roulette-page {
  width: min(100% - 32px, 1240px);
}

.roulette-hero {
  min-height: 0;
  grid-template-columns: minmax(0, 0.9fr) minmax(360px, 1.1fr);
  gap: clamp(20px, 4vw, 54px);
  padding: clamp(22px, 4vw, 48px);
  border-color: color-mix(in srgb, var(--accent) 35%, var(--line));
  background:
    radial-gradient(circle at 82% 14%, color-mix(in srgb, var(--accent) 16%, transparent), transparent 34%),
    linear-gradient(145deg, var(--surface), color-mix(in srgb, var(--surface-strong) 92%, #061b2e));
}

.roulette-copy h1 {
  max-width: 11ch;
  font-size: clamp(38px, 5vw, 68px);
  line-height: 0.96;
}

.roulette-spin-actions {
  display: grid;
  gap: 9px;
  width: 100%;
}

.roulette-paid-spin-button {
  min-height: 48px;
  justify-content: center;
  border-color: color-mix(in srgb, var(--accent) 48%, var(--line));
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 8%, var(--surface-strong));
}

.roulette-stage-card {
  align-self: center;
  border-color: color-mix(in srgb, var(--accent) 32%, var(--line));
  background:
    linear-gradient(160deg, color-mix(in srgb, var(--accent) 9%, var(--surface-strong)), var(--surface));
}

.roulette-stage {
  min-height: 0;
  padding: 16px 0 6px;
}

.roulette-wheel {
  width: clamp(280px, 34vw, 420px);
  border-color: color-mix(in srgb, var(--accent) 45%, #d8efff);
  background:
    repeating-conic-gradient(
      from -90deg,
      color-mix(in srgb, var(--accent) 82%, #0c426e) 0 var(--roulette-slice),
      color-mix(in srgb, var(--accent) 52%, #071b31) var(--roulette-slice)
        calc(var(--roulette-slice) * 2)
    );
  box-shadow:
    0 18px 48px rgb(0 0 0 / 32%),
    0 0 0 6px color-mix(in srgb, var(--accent) 10%, transparent);
}

.roulette-hub {
  border-color: color-mix(in srgb, var(--accent) 40%, #fff);
  color: #dff6ff;
  background: #071a2e;
}

.roulette-history article > span:not(:first-child) {
  color: var(--muted);
  font-size: 11px;
}

.analytics-chart-card {
  overflow: hidden;
}

.analytics-chart-scroll {
  width: 100%;
  overflow-x: auto;
  padding: 8px 0 4px;
  scrollbar-color: var(--accent) transparent;
}

.analytics-line-chart {
  width: max(100%, 720px);
  min-height: 300px;
}

.analytics-line-chart text {
  fill: var(--muted);
  font-size: 11px;
}

.analytics-line-chart :is(.views-line, .starts-line) {
  stroke-width: 3;
}

.analytics-line-chart :is(.views-point, .starts-point) {
  stroke: var(--surface);
  stroke-width: 2;
}

.analytics-line-chart .views-point {
  fill: var(--accent);
}

.analytics-line-chart .starts-point {
  fill: #ffc768;
}

.analytics-data-fallback {
  margin-top: 10px;
  border-top: 1px solid var(--line);
}

.analytics-data-fallback summary {
  cursor: pointer;
  padding: 12px 0;
  color: var(--accent);
  font-weight: 750;
}

.analytics-data-fallback > div {
  max-height: 320px;
  overflow: auto;
}

.analytics-data-fallback table {
  width: 100%;
  border-collapse: collapse;
  font-variant-numeric: tabular-nums;
}

.analytics-data-fallback :is(th, td) {
  padding: 9px 10px;
  border-bottom: 1px solid var(--line);
  text-align: right;
}

.analytics-data-fallback :is(th, td):first-child {
  text-align: left;
}

