/* Reader-facing progress, featured metadata, and home rhythm */

.home-main > section {
  padding-block: clamp(22px, 2.2vw, 28px);
}

.featured-main-card > span.featured-main-details {
  min-height: 50%;
  gap: 7px;
}

.featured-main-alternatives {
  display: -webkit-box;
  max-width: 100%;
  overflow: hidden;
  color: rgba(255, 255, 255, 0.7);
  font-size: 10px;
  font-weight: 560;
  line-height: 1.35;
  text-wrap: pretty;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.featured-main-meta {
  display: flex;
  min-width: 0;
  align-items: center;
  flex-wrap: wrap;
  gap: 7px 11px;
  color: rgba(255, 255, 255, 0.82);
  font-size: 10px;
  font-variant-numeric: tabular-nums;
}

.featured-main-meta > span:not(.series-status-badge) {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  white-space: nowrap;
}

.featured-main-meta > span:not(.series-status-badge) svg {
  color: color-mix(in srgb, var(--accent) 78%, white);
}

.library-record-chapter-count,
.continue-reading-chapter-count {
  color: color-mix(in srgb, var(--accent) 72%, var(--text)) !important;
  font-variant-numeric: tabular-nums;
  font-weight: 750;
}

:is(.continue-reading-progress, .library-record-progress) {
  --reading-progress-fill: var(--theme-progress-fill);
}
:is(.continue-reading-progress, .library-record-progress)[data-progress-tone="starting"] {
  --reading-progress-fill: var(--theme-progress-starting);
}
:is(.continue-reading-progress, .library-record-progress)[data-progress-tone="building"] {
  --reading-progress-fill: var(--theme-progress-building);
}
:is(.continue-reading-progress, .library-record-progress)[data-progress-tone="halfway"] {
  --reading-progress-fill: var(--theme-progress-halfway);
}
:is(.continue-reading-progress, .library-record-progress)[data-progress-tone="strong"] {
  --reading-progress-fill: var(--theme-progress-strong);
}
:is(.continue-reading-progress, .library-record-progress)[data-progress-tone="nearly"] {
  --reading-progress-fill: var(--theme-progress-nearly);
}
:is(.continue-reading-progress, .library-record-progress)[data-progress-tone="complete"] {
  --reading-progress-fill: var(--theme-progress-complete);
}

.continue-reading-progress > b,
.library-record-progress > i {
  background: var(--reading-progress-fill);
  transition:
    width 220ms ease,
    background-color 220ms ease;
}

@media (max-width: 760px) {
  .home-main > section {
    padding-block: 18px;
  }

  .featured-main-card > span.featured-main-details {
    min-height: 58%;
    gap: 5px;
    padding: 58px 12px 12px;
  }

  .featured-main-alternatives {
    font-size: 9px;
    -webkit-line-clamp: 1;
  }

  .featured-main-meta {
    gap: 6px 8px;
    font-size: 9px;
  }

  .featured-main-meta .series-status-badge {
    min-height: 21px;
    gap: 4px;
    padding-inline: 6px;
    font-size: 8px;
  }
}

@media (max-width: 700px) {
  .library-records.is-compact
    .library-record-copy
    > .library-record-chapter-count,
  .library-records.is-list
    .library-record-copy
    > .library-record-chapter-count,
  .library-records.is-list .library-record-progress {
    display: block;
  }

  .library-records.is-compact
    .library-record-copy
    > .library-record-activity,
  .library-records.is-list
