    transform 160ms ease;
}

.public-profile-record-card:hover {
  border-color: color-mix(in srgb, var(--accent) 50%, var(--line));
  background: color-mix(in srgb, var(--accent) 6%, var(--surface-2));
  transform: translateY(-2px);
}

.public-profile-record-cover {
  display: grid;
  width: 4rem;
  aspect-ratio: 2 / 3;
  place-items: center;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--line-strong) 72%, transparent);
  border-radius: 0.65rem;
  background: var(--surface-3);
}

.public-profile-record-cover > :is(img, .public-reading-cover-placeholder) {
  width: 100%;
  height: 100%;
  border-radius: inherit;
  object-fit: cover;
}

.public-profile-record-copy {
  display: grid;
  min-width: 0;
  gap: 0.32rem;
}

.public-profile-record-copy > strong {
  overflow-wrap: anywhere;
  font-size: 0.93rem;
  line-height: 1.3;
}

.public-profile-record-copy > small {
  overflow-wrap: anywhere;
  color: var(--muted);
  font-size: 0.72rem;
  line-height: 1.4;
  white-space: normal;
}

.public-profile-record-label {
  display: inline-flex;
  width: max-content;
  max-width: 100%;
  align-items: center;
  gap: 0.3rem;
  overflow: hidden;
  color: var(--accent);
  font-size: 0.65rem;
  font-weight: 760;
  line-height: 1.2;
  text-overflow: ellipsis;
  text-transform: capitalize;
  white-space: nowrap;
}

.public-profile-record-action {
  display: grid;
  width: 2.15rem;
  height: 2.15rem;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: var(--surface);
  color: var(--muted);
}

.public-profile-record-card:hover .public-profile-record-action {
  border-color: color-mix(in srgb, var(--accent) 40%, var(--line));
  color: var(--accent);
}

.public-profile-record-copy > :is(strong, small) {
  overflow-wrap: anywhere;
  white-space: normal;
}

.public-profile-comments article {
  display: grid;
  grid-template-columns: 4.25rem minmax(0, 1fr);
  align-items: stretch;
  gap: 0.85rem;
  padding: 0.75rem;
}

.public-profile-comment-cover {
  display: grid;
  width: 4.25rem;
  aspect-ratio: 2 / 3;
  place-items: center;
  align-self: start;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--line-strong) 72%, transparent);
  border-radius: 0.65rem;
  background: var(--surface-3);
}

.public-profile-comment-cover > :is(img, .public-reading-cover-placeholder) {
  width: 100%;
  height: 100%;
  border-radius: inherit;
  object-fit: cover;
}

.public-profile-comment-copy {
  display: grid;
  align-content: start;
  gap: 0.48rem;
}

.public-profile-comment-title {
  display: grid;
  min-width: 0;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: start;
  gap: 0.4rem;
}

.public-profile-comment-title > svg {
  margin-top: 0.08rem;
  color: var(--accent);
}

.public-profile-comment-title > a {
  line-height: 1.35;
}

.public-profile-comment-copy > p,
.public-profile-comment-spoiler p {
  margin: 0;
  color: var(--text-soft);
  font-size: 0.86rem;
  line-height: 1.55;
  white-space: pre-wrap;
}

.public-profile-comment-copy > small {
  display: block;
  color: var(--muted);
  font-size: 0.68rem;
  line-height: 1.45;
}

.public-profile-comment-title > a,
.public-profile-comment-copy > p,
.public-profile-comment-copy > small,
.public-profile-comment-spoiler p {
  overflow-wrap: anywhere;
}

.public-profile-comment-title > a,
.public-profile-comment-copy > small {
  white-space: normal;
}

.public-profile-comment-spoiler {
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--warning) 34%, var(--line));
  border-radius: 0.65rem;
  background: color-mix(in srgb, var(--warning) 6%, var(--surface));
}

.public-profile-comment-spoiler summary {
  padding: 0.6rem 0.7rem;
  color: var(--warning);
  cursor: pointer;
  font-size: 0.74rem;
  font-weight: 760;
}

.public-profile-comment-spoiler summary:focus-visible {
  outline-offset: -3px;
}

.public-profile-comment-spoiler[open] summary {
  border-bottom: 1px solid color-mix(in srgb, var(--warning) 22%, var(--line));
}

.public-profile-comment-spoiler p {
  padding: 0.65rem 0.7rem;
}

@media (max-width: 760px) {
  .public-profile-identity,
  .public-profile-content {
    width: min(1440px, calc(100% - 28px));
  }

  .public-profile-panel {
    width: 100%;
    padding: 1rem;
    border-radius: 0.95rem;
  }

  .public-profile-section-heading {
    display: grid;
