    gap: 0.75rem;
  }

  .public-profile-section-heading h2 {
    font-size: clamp(1.65rem, 8vw, 2.15rem);
    line-height: 1;
  }

  .public-profile-section-heading p {
    margin-top: 0.55rem;
    font-size: 0.78rem;
    line-height: 1.5;
  }

  .public-profile-rail-controls button {
    width: 2.4rem;
    height: 2.4rem;
  }

  .public-profile-series-grid {
    grid-auto-columns: min(45vw, 10.25rem);
    gap: 0.65rem;
  }

  .public-profile-record-list {
    grid-template-columns: 1fr;
    gap: 0.65rem;
  }

  .public-profile-record-card {
    min-height: 6.65rem;
    grid-template-columns: 3.65rem minmax(0, 1fr) 1.95rem;
    gap: 0.65rem;
    padding: 0.65rem;
  }

  .public-profile-record-cover {
    width: 3.65rem;
  }

  .public-profile-record-action {
    width: 1.95rem;
    height: 1.95rem;
  }

  .public-profile-comments article {
    grid-template-columns: 3.5rem minmax(0, 1fr);
    gap: 0.7rem;
    padding: 0.65rem;
  }

  .public-profile-comment-cover {
    width: 3.5rem;
  }

  .public-profile-comment-title > a {
    font-size: 0.88rem;
  }

  .public-profile-comment-copy > p,
  .public-profile-comment-spoiler p {
    font-size: 0.8rem;
  }
}

@media (max-width: 380px) {
  .public-profile-identity,
  .public-profile-content {
    width: min(1440px, calc(100% - 20px));
  }

  .public-profile-panel {
    padding: 0.8rem;
  }

  .public-profile-series-grid {
    grid-auto-columns: min(52vw, 9.5rem);
  }

  .public-profile-record-card {
    grid-template-columns: 3.35rem minmax(0, 1fr) 1.8rem;
    gap: 0.55rem;
    padding: 0.55rem;
  }

  .public-profile-record-cover {
    width: 3.35rem;
  }

  .public-profile-record-action {
    width: 1.8rem;
    height: 1.8rem;
  }

  .public-profile-comments article {
    grid-template-columns: 3.25rem minmax(0, 1fr);
    gap: 0.55rem;
    padding: 0.55rem;
  }

  .public-profile-comment-cover {
    width: 3.25rem;
  }
}

/* Version 37: unified system feedback and administrative polish */
.system-notification-region {
  position: fixed;
  z-index: 420;
  top: max(18px, env(safe-area-inset-top));
  right: max(18px, env(safe-area-inset-right));
  display: grid;
  width: min(390px, calc(100vw - 28px));
  gap: 10px;
  pointer-events: none;
}

.system-notification {
  --notice-color: var(--theme-indication-blue);
  position: relative;
  display: grid;
  min-width: 0;
  grid-template-columns: 42px minmax(0, 1fr) 30px;
  align-items: start;
  gap: 11px;
  overflow: hidden;
  padding: 15px 13px 16px 14px;
  border: 1px solid color-mix(in srgb, var(--notice-color) 46%, var(--theme-accent-l3));
  border-radius: 13px;
  color: var(--theme-text-color);
  background:
    linear-gradient(
      105deg,
      color-mix(in srgb, var(--notice-color) 10%, transparent),
      transparent 48%
    ),
    var(--theme-accent);
  box-shadow:
    0 18px 48px rgb(0 0 0 / 38%),
    inset 3px 0 0 var(--notice-color);
  pointer-events: auto;
  animation: system-notification-enter 240ms cubic-bezier(0.2, 0.8, 0.2, 1)
    both;
}

.system-notification-success {
  --notice-color: var(--theme-status-green);
}

.system-notification-info {
  --notice-color: var(--theme-indication-blue);
}

.system-notification-warning {
  --notice-color: var(--theme-status-yellow);
}

.system-notification-error {
  --notice-color: var(--theme-danger);
}

.system-notification-icon {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--notice-color) 52%, transparent);
  border-radius: 10px;
  color: var(--notice-color);
  background: color-mix(in srgb, var(--notice-color) 13%, var(--theme-accent-l1));
}

.system-notification-copy {
  display: grid;
  min-width: 0;
  gap: 3px;
  padding-top: 1px;
}

.system-notification-copy strong {
  color: var(--theme-text-color);
  font-size: 13px;
  font-weight: 780;
  letter-spacing: -0.01em;
}

.system-notification-copy p {
  margin: 0;
  color: var(--theme-mid-tone);
  font-size: 11px;
  line-height: 1.52;
  overflow-wrap: anywhere;
}

.system-notification > button {
  display: grid;
  width: 28px;
  height: 28px;
  place-items: center;
  padding: 0;
  border: 0;
  border-radius: 7px;
  color: var(--theme-mid-tone);
  background: transparent;
  cursor: pointer;
}

.system-notification > button:hover,
.system-notification > button:focus-visible {
  color: var(--theme-text-color);
  background: var(--theme-accent-l1);
}

.system-notification > button:focus-visible {
  outline: 2px solid var(--notice-color);
  outline-offset: 2px;
}

.system-notification-progress {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  height: 2px;
  background: var(--notice-color);
  transform-origin: left;
  animation: system-notification-progress
    var(--system-notification-duration, 5400ms) linear both;
}

@keyframes system-notification-enter {
  from {
    opacity: 0;
    transform: translate3d(calc(100% + 24px), 0, 0);
  }
  to {
    opacity: 1;
    transform: translate3d(0, 0, 0);
  }
}

@keyframes system-notification-progress {
  from {
    transform: scaleX(1);
  }
  to {
    transform: scaleX(0);
  }
}

.footer-group > div > :is(a, .footer-inline-action) {
  display: block;
  width: max-content;
  max-width: 100%;
  margin: 0;
  padding: 0;
  border: 0;
  color: var(--muted);
  background: transparent;
  cursor: pointer;
  font: inherit;
  font-size: 12px;
  line-height: 1.45;
  text-align: start;
}

.footer-group > div > :is(a, .footer-inline-action):is(:hover, :focus-visible) {
  color: var(--accent);
}

.footer-inline-action:focus-visible {
  border-radius: 3px;
  outline: 2px solid var(--accent);
  outline-offset: 4px;
}

.admin-field-error {
  color: var(--danger);
  font-size: 10px;
  line-height: 1.45;
}

.site-configuration-panel [aria-invalid="true"] {
  border-color: var(--danger) !important;
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--danger) 14%, transparent);
}

.user-admin-list {
