.user-role-chips label[data-role="MANAGER"] {
  --role-color: #64cce7;
}

.user-role-chips label[data-role="MODERATOR"] {
  --role-color: #f39aaa;
}

.user-role-chips label[data-role="TEAM_LEADER"] {
  --role-color: #6bd5aa;
}

.user-role-chips label[data-role="UPLOADER"] {
  --role-color: #f3ad73;
}

.user-role-chips label[data-role="USER"] {
  --role-color: #a9b9c8;
}

[data-theme="light"] .user-role-chips label[data-role="OWNER"] {
