}

[data-theme="light"] .user-role-chips label[data-role="MANAGER"] {
  --role-color: #006b85;
}

[data-theme="light"] .user-role-chips label[data-role="MODERATOR"] {
  --role-color: #9b3347;
}

[data-theme="light"] .user-role-chips label[data-role="TEAM_LEADER"] {
  --role-color: #006c4c;
}

[data-theme="light"] .user-role-chips label[data-role="UPLOADER"] {
  --role-color: #914900;
}

[data-theme="light"] .user-role-chips label[data-role="USER"] {
  --role-color: #3d5568;
}

.user-role-chips label[data-selected="true"] {
  border-color: color-mix(in srgb, var(--role-color) 68%, var(--line));
  color: var(--role-color);
  background: color-mix(in srgb, var(--role-color) 12%, var(--surface));
}

.user-role-chips label:focus-within {
  outline: 2px solid var(--role-color);
  outline-offset: 2px;
}

.user-role-chips input {
  accent-color: var(--role-color);
}

.balance-adjustment-editor {
  display: grid;
  gap: 16px;
  margin: 4px 0 18px;
  padding: clamp(16px, 2.2vw, 22px);
  border: 1px solid color-mix(in srgb, var(--accent) 42%, var(--line));
  border-radius: 16px;
  outline: 0;
  background:
    radial-gradient(
      circle at 95% 0,
      color-mix(in srgb, var(--accent) 10%, transparent),
      transparent 24rem
    ),
    var(--surface);
  box-shadow: 0 16px 36px color-mix(in srgb, var(--shadow) 72%, transparent);
}

.balance-adjustment-editor:focus-visible {
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 18%, transparent);
}

.balance-adjustment-editor > header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}

.balance-adjustment-editor > header > div {
  display: grid;
  gap: 4px;
}

.balance-adjustment-editor > header span {
  color: var(--accent);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.balance-adjustment-editor > header h3 {
  margin: 0;
  font-size: clamp(19px, 2.4vw, 25px);
  letter-spacing: -0.025em;
}

.balance-adjustment-editor > header p {
  max-width: 70ch;
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.55;
}

.balance-adjustment-editor > header > button {
  display: grid;
  width: 34px;
  height: 34px;
  flex: 0 0 auto;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 9px;
  color: var(--muted);
  background: var(--surface-2);
  cursor: pointer;
}

.balance-adjustment-panels {
