  width: 100%;
  min-height: 76px;
  grid-template-columns: 42px minmax(0, 1fr) auto 20px;
  align-items: center;
  gap: 11px;
  padding: 12px;
  border: 0;
  color: var(--text);
  background: transparent;
  cursor: pointer;
  text-align: start;
