}

.balance-currency-toggle > span:not(.balance-currency-icon) {
  display: grid;
  min-width: 0;
  gap: 2px;
}

.balance-currency-toggle small {
  color: var(--muted);
  font-size: 9px;
}

.balance-currency-toggle strong {
  overflow: hidden;
  font-size: 13px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.balance-currency-icon {
  display: grid;
  width: 40px;
  height: 40px;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--balance-color) 42%, var(--line));
  border-radius: 10px;
  color: var(--balance-color);
