  gap: 2px 12px;
  padding: 10px 12px;
  border: 1px solid color-mix(in srgb, var(--balance-color) 34%, var(--line));
  border-radius: 9px;
  background: color-mix(in srgb, var(--balance-color) 7%, var(--surface-2));
}

.balance-projection span,
.balance-projection small {
  color: var(--muted);
