  border-radius: 9px;
}

@media (max-width: 760px) {
  .system-notification-region {
    top: max(10px, env(safe-area-inset-top));
    right: max(10px, env(safe-area-inset-right));
    width: min(390px, calc(100vw - 20px));
  }

  .balance-adjustment-panels {
    grid-template-columns: 1fr;
  }

  .balance-currency-form {
    grid-template-columns: 1fr 1fr;
  }

  .balance-adjustment-reason,
  .balance-projection,
  .balance-currency-form > .button {
    grid-column: 1 / -1;
  }

  .discussion-settings-actions {
    display: grid;
    width: 100%;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .discussion-settings-actions button {
    justify-content: center;
  }

  .discussion-limit-card > header {
    align-items: flex-start;
    flex-direction: column;
  }
}

@media (max-width: 520px) {
  .system-notification {
    grid-template-columns: 38px minmax(0, 1fr) 28px;
    gap: 9px;
    padding: 12px 10px 14px 12px;
  }

  .system-notification-icon {
    width: 36px;
    height: 36px;
  }

  .user-role-chips {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .user-role-chips label {
    width: 100%;
    min-height: 36px;
  }

  .balance-adjustment-editor > header {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
  }

  .balance-currency-toggle {
    grid-template-columns: 40px minmax(0, 1fr) 18px;
  }

  .balance-currency-current {
    grid-column: 2;
    justify-items: start;
  }

  .balance-currency-toggle > svg {
    grid-row: 1 / 3;
    grid-column: 3;
  }

  .balance-currency-form {
    grid-template-columns: 1fr;
  }

  .balance-currency-form > * {
    grid-column: 1 !important;
  }

  .discussion-feature-card {
    grid-template-columns: 40px minmax(0, 1fr);
  }

  .discussion-policy-toggle {
    grid-column: 1 / -1;
    justify-content: center;
  }

  .discussion-limit-grid {
    grid-template-columns: 1fr;
  }

  .admin-team-picker > .admin-team-row {
    grid-template-columns: minmax(0, 1fr) 36px;
  }

  .admin-team-primary {
    grid-column: 1;
  }

  .admin-team-row > button {
    grid-row: 1 / 3;
    grid-column: 2;
  }

  .admin-entity-input-row {
    grid-template-columns: 1fr;
  }

  .admin-entity-input-row > .button {
    width: 100%;
  }
}

@media (max-width: 390px) {
  .user-role-chips {
    grid-template-columns: 1fr;
  }

  .discussion-settings-actions {
    grid-template-columns: 1fr;
  }
}

@media (prefers-reduced-motion: reduce) {
  .system-notification,
  .system-notification-progress,
  .balance-currency-toggle > svg {
    animation: none;
    transition: none;
  }
}

/* Version 38: multi-release series, moderated galleries, and continuity UI */
.language-flag {
  display: inline-flex;
  min-width: 0;
  align-items: center;
  gap: 6px;
  color: inherit;
  font-size: 11px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: 0.04em;
}

.language-flag img {
  display: block;
  width: 20px;
  height: 15px;
  flex: 0 0 auto;
  border: 1px solid rgb(255 255 255 / 0.22);
  border-radius: 2px;
  object-fit: cover;
}

.series-type-badge .language-flag {
  min-width: 20px;
}

.series-details {
  grid-template-columns: minmax(0, 1.2fr) minmax(320px, 0.8fr);
}

.title-content {
