  padding-block: 10px 34px;
}

.series-gallery-section {
  min-width: 0;
  scroll-margin-top: 90px;
  padding: clamp(18px, 2.4vw, 28px);
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background:
    linear-gradient(140deg, color-mix(in srgb, var(--theme-indication-blue) 8%, transparent), transparent 44%),
    var(--surface);
}

.series-gallery-section > header {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 12px;
}

.series-gallery-heading-copy {
  display: grid;
  min-width: 0;
  gap: 3px;
}

.series-gallery-heading-copy :is(h2, p) {
  margin: 0;
}

.series-gallery-heading-copy h2 {
  font-size: clamp(24px, 2.4vw, 34px);
  line-height: 1.05;
}

.series-gallery-heading-copy p {
  max-width: 720px;
