  font-size: 13px;
  font-weight: 500;
  line-height: 1.55;
}

.series-gallery-toggle {
  display: inline-flex;
  min-width: 86px;
  min-height: 42px;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 8px 13px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--surface-2);
  color: var(--text);
  cursor: pointer;
}

.series-gallery-toggle:is(:hover, :focus-visible) {
  border-color: color-mix(in srgb, var(--accent) 64%, var(--line));
  color: var(--accent);
}

.series-gallery-toggle:focus-visible {
  outline: 3px solid color-mix(in srgb, var(--accent) 22%, transparent);
  outline-offset: 2px;
}

.series-gallery-toggle-state {
  display: inline-flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 7px;
  color: var(--text-soft);
  font-size: 11px;
  font-weight: 750;
}

.series-gallery-toggle-state svg {
  transition: transform 180ms ease;
}

.series-gallery-toggle[aria-expanded="true"] .series-gallery-toggle-state svg {
  transform: rotate(180deg);
}

.series-gallery-add {
  min-width: max-content;
  min-height: 42px;
}

.series-gallery-content {
  margin-top: 18px;
}

.series-gallery-content[hidden] {
  display: none;
}

.series-gallery-rail {
  display: grid;
  min-width: 0;
  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
  grid-auto-flow: dense;
  gap: 14px;
}

.series-gallery-card {
  position: relative;
  display: block;
  min-width: 0;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 12px;
  color: #fff;
  background: var(--surface-2);
  isolation: isolate;
}

.series-gallery-art .series-gallery-card.is-landscape {
  grid-column: span 2;
  aspect-ratio: 16 / 9;
}

.series-gallery-art .series-gallery-card.is-portrait,
.series-gallery-cover .series-gallery-card {
