  width: 100%;
  height: 100%;
  object-fit: cover;
}

.chapter-variant-copy {
  display: grid;
  min-width: 0;
  gap: 6px;
}

.chapter-variant-copy > strong {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 8px;
  overflow: hidden;
  font-size: 13px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.chapter-variant-copy > strong > .language-flag {
  flex: 0 0 auto;
}

.chapter-variant-copy > small {
  display: flex;
  min-width: 0;
  flex-wrap: wrap;
  gap: 4px 10px;
  color: var(--muted);
  font-size: 10px;
}

.chapter-variant-copy > small > span:not(:last-child)::after,
.chapter-variant-copy > small > time::after {
  content: "·";
  margin-left: 10px;
  color: var(--line-strong);
}

.chapter-variant-row .chapter-access {
  justify-self: end;
  white-space: nowrap;
}

.chapter-variant-row .chapter-read {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
  color: var(--text-soft);
  font-size: 11px;
  font-weight: 750;
  white-space: nowrap;
}

.media-picker-backdrop {
  z-index: 210;
}

.media-picker-backdrop :is(.comment-gif-picker, .emoji-picker) {
  position: relative !important;
  inset: auto !important;
  display: grid;
  width: min(720px, 100%);
  max-width: 100%;
  max-height: calc(100dvh - 36px);
  margin: 0 !important;
  overflow: hidden;
  transform: none !important;
  border: 1px solid var(--line-strong);
  border-radius: 18px;
  background: var(--surface);
  box-shadow: 0 28px 90px rgb(0 0 0 / 0.5) !important;
}

.media-picker-backdrop :is(.comment-gif-picker, .emoji-picker) > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 16px 18px;
  border-bottom: 1px solid var(--line);
}

.media-picker-backdrop :is(.comment-gif-picker, .emoji-picker) > header > div {
  display: grid;
  gap: 2px;
}

.media-picker-backdrop :is(.comment-gif-picker, .emoji-picker) > header span {
  color: var(--muted);
  font-size: 10px;
}

.media-picker-backdrop :is(.comment-gif-picker, .emoji-picker) > header button {
  display: grid;
  width: 36px;
  height: 36px;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 9px;
  color: var(--text);
  background: var(--surface-2);
}

.comment-gif-filters,
.emoji-picker-filters {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(170px, 0.34fr);
  gap: 10px;
  padding: 13px 18px;
  border-bottom: 1px solid var(--line);
}

.comment-gif-filters :is(input, select),
.emoji-picker-filters :is(input, select) {
  width: 100%;
  min-width: 0;
  min-height: 42px;
}

.emoji-catalog-grid {
  display: grid;
  min-height: 220px;
  max-height: min(52dvh, 520px);
  padding: 14px 18px;
  overflow: auto;
  grid-template-columns: repeat(10, minmax(42px, 1fr));
  align-content: start;
  gap: 6px;
}

.emoji-catalog-grid button {
  display: grid;
  min-width: 0;
  aspect-ratio: 1;
  place-items: center;
  border: 1px solid transparent;
  border-radius: 9px;
  background: var(--surface-2);
  font-size: 23px;
  line-height: 1;
}

.emoji-catalog-grid button:hover,
.emoji-catalog-grid button:focus-visible {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--theme-primary) 12%, var(--surface-2));
}

.emoji-picker-status,
.comment-gif-empty {
  display: flex;
  min-height: 220px;
  align-items: center;
  justify-content: center;
  gap: 8px;
  margin: 0;
  color: var(--muted);
}

.emoji-picker > footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 18px;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 10px;
}

.emoji-picker > footer button {
  min-height: 34px;
  padding: 0 12px;
  border: 1px solid var(--line);
  border-radius: 8px;
  color: var(--text);
  background: var(--surface-2);
  font: inherit;
  font-weight: 700;
}

.comment-gif-grid {
  min-height: 220px;
  max-height: min(52dvh, 520px);
  padding: 14px 18px 18px;
  overflow: auto;
}

.reader-chapter-navigation > button {
  display: flex;
  min-width: 0;
  flex: 1;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: 11px;
  color: var(--text);
  background: var(--surface);
  font: inherit;
  text-align: left;
}

.reader-continuity-layer {
  z-index: 230;
}

.reader-continuity-scrim {
  position: fixed;
  inset: 0;
  border: 0;
  background: transparent;
}

.reader-continuity-dialog {
  position: relative;
  z-index: 1;
  display: grid;
  width: min(680px, 100%);
  max-height: calc(100dvh - 36px);
  gap: 15px;
  padding: clamp(18px, 3vw, 28px);
  overflow: auto;
  border: 1px solid var(--line-strong);
  border-radius: 18px;
  background: var(--surface);
  box-shadow: 0 30px 100px rgb(0 0 0 / 0.52);
}

.reader-continuity-dialog > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
}

.reader-continuity-dialog > header span {
  color: var(--accent);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.reader-continuity-dialog h2 {
  margin: 4px 0 0;
  font-size: 25px;
}

.reader-continuity-dialog > header button {
  display: grid;
  width: 38px;
  height: 38px;
  flex: 0 0 auto;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 10px;
  color: var(--text);
  background: var(--surface-2);
}

.reader-continuity-dialog > p {
  margin: 0;
  color: var(--text-soft);
  font-size: 13px;
  line-height: 1.6;
}

.reader-continuity-options {
  display: grid;
  gap: 8px;
}

.reader-continuity-options a {
  display: grid;
  min-width: 0;
  grid-template-columns: auto minmax(0, 1fr) auto auto;
  align-items: center;
  gap: 12px;
  padding: 13px;
  border: 1px solid var(--line);
  border-radius: 11px;
  color: var(--text);
  background: var(--surface-2);
}

.reader-continuity-options a:hover,
.reader-continuity-options a:focus-visible {
  border-color: var(--accent);
}

.reader-continuity-options a > span {
  display: grid;
  min-width: 0;
  gap: 3px;
}

.reader-continuity-options :is(strong, small) {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.reader-continuity-options strong {
  font-size: 12px;
}

.reader-continuity-options small,
.reader-continuity-options em {
  color: var(--muted);
  font-size: 10px;
  font-style: normal;
}

.reader-continuity-dialog > footer {
  display: flex;
  justify-content: flex-end;
}

.admin-gallery-moderation {
  margin-bottom: 18px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: var(--surface);
}

.admin-gallery-moderation > summary {
  display: flex;
  min-height: 52px;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 0 16px;
  cursor: pointer;
}

.admin-gallery-moderation > summary > span {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
  font-weight: 750;
}

.admin-gallery-moderation > summary > strong {
  padding: 5px 8px;
  border-radius: 999px;
  color: var(--accent);
  background: color-mix(in srgb, var(--theme-indication-blue) 10%, transparent);
  font-size: 10px;
}

.admin-gallery-moderation > :not(summary) {
  margin-inline: 16px;
}

.admin-gallery-queue {
  display: grid;
  gap: 10px;
  padding-bottom: 16px;
}

.admin-gallery-queue > article {
  display: grid;
  min-width: 0;
  grid-template-columns: 110px minmax(0, 1fr) auto;
  align-items: center;
  gap: 14px;
  padding: 11px;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: var(--surface-2);
}

.admin-gallery-queue > article > img {
  width: 110px;
  height: 74px;
  border-radius: 8px;
  object-fit: cover;
}

.admin-gallery-queue > article > div:nth-child(2) {
  display: grid;
  min-width: 0;
  gap: 3px;
}

.admin-gallery-queue article span,
.admin-gallery-queue article small {
  color: var(--muted);
  font-size: 10px;
}

.admin-gallery-queue article strong {
  font-size: 13px;
}

.admin-gallery-queue article p {
  margin: 0;
  color: var(--text-soft);
  font-size: 11px;
}

.admin-gallery-actions {
  display: flex;
  gap: 8px;
}

.admin-gallery-actions .button,
.admin-gallery-rejection .button {
  min-height: 38px;
  font-size: 11px;
}

.admin-gallery-rejection {
  display: grid;
  width: min(300px, 100%);
  gap: 8px;
}

.admin-gallery-rejection label {
  display: grid;
  gap: 5px;
}

.admin-gallery-rejection textarea {
  min-height: 72px;
  resize: vertical;
}

@media (max-width: 960px) {
  .series-details {
    grid-template-columns: 1fr;
  }

  .series-gallery-rail {
    grid-template-columns: repeat(auto-fill, minmax(132px, 1fr));
  }

  .chapter-variant-row {
    grid-template-columns: 48px minmax(0, 1fr) minmax(80px, auto);
  }

  .chapter-variant-row .chapter-read {
    display: none;
  }

  .emoji-catalog-grid {
    grid-template-columns: repeat(8, minmax(40px, 1fr));
  }

  .admin-gallery-queue > article {
    grid-template-columns: 94px minmax(0, 1fr);
  }

  .admin-gallery-queue > article > img {
    width: 94px;
    height: 68px;
  }

  .admin-gallery-actions,
  .admin-gallery-rejection {
    grid-column: 1 / -1;
    width: 100%;
  }
}

@media (max-width: 700px) {
  .series-jump {
    overflow-x: auto;
    overscroll-behavior-inline: contain;
    scrollbar-width: none;
  }

  .series-jump::-webkit-scrollbar {
    display: none;
  }

  .series-gallery-section {
    padding: 16px;
  }

  .series-gallery-section > header {
    align-items: stretch;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 13px;
  }

  .series-gallery-heading-copy {
    grid-column: 1 / -1;
  }

  .series-gallery-toggle {
    width: 100%;
  }

  .series-gallery-add {
    width: 100%;
    justify-content: center;
  }

  .series-gallery-rail {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px;
  }

  .series-gallery-art .series-gallery-card.is-landscape {
    grid-column: 1 / -1;
  }

  .series-gallery-submissions {
    align-items: stretch;
    flex-direction: column;
  }

  .series-gallery-submissions > div {
    justify-content: flex-start;
  }

  .chapter-action-bar {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .chapter-action-bar .button {
    width: 100%;
    justify-content: center;
  }

  .chapter-action-bar .chapter-upload-action {
    grid-column: 1 / -1;
    margin-left: 0;
  }

  .chapter-action-bar .report-link {
    grid-column: 1 / -1;
    justify-content: center;
  }

  .chapter-release-group > header {
    grid-template-columns: 48px minmax(0, 1fr);
    padding-inline: 11px;
  }

  .chapter-variant-row {
    grid-template-columns: 42px minmax(0, 1fr);
    gap: 9px;
    padding: 11px;
  }

  .chapter-variant-visual {
    width: 40px;
    height: 40px;
  }

  .chapter-variant-copy > strong {
    align-items: flex-start;
    flex-wrap: wrap;
    white-space: normal;
  }

  .chapter-variant-copy > small {
    line-height: 1.45;
  }

  .chapter-variant-row .chapter-access {
    grid-column: 2;
    justify-self: start;
    margin-top: 1px;
  }

  .gallery-submit-fields,
  .comment-gif-filters,
  .emoji-picker-filters {
    grid-template-columns: 1fr;
  }

  .gallery-submit-fields label {
    grid-column: 1 !important;
  }

  .gallery-submit-dialog > footer {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .gallery-submit-dialog > footer p {
    grid-column: 1 / -1;
  }

  .gallery-submit-dialog > footer .button {
    width: 100%;
    justify-content: center;
  }

  .emoji-catalog-grid {
    grid-template-columns: repeat(6, minmax(38px, 1fr));
  }

  .reader-continuity-options a {
    grid-template-columns: auto minmax(0, 1fr) auto;
  }

  .reader-continuity-options a > em {
    grid-column: 2;
  }

  .reader-continuity-options a > svg {
    grid-row: 1 / 3;
    grid-column: 3;
  }
}

@media (max-width: 430px) {
  .gallery-dialog-backdrop,
  .media-picker-backdrop,
  .reader-continuity-layer {
    padding:
      max(8px, env(safe-area-inset-top))
      max(8px, env(safe-area-inset-right))
      max(8px, env(safe-area-inset-bottom))
      max(8px, env(safe-area-inset-left));
  }

  .gallery-submit-dialog,
  .media-picker-backdrop :is(.comment-gif-picker, .emoji-picker),
  .reader-continuity-dialog {
    max-height: calc(100dvh - 16px);
    border-radius: 14px;
  }

  .gallery-submit-dialog {
    padding: 15px;
  }

  .series-gallery-rail {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .chapter-action-bar {
    grid-template-columns: 1fr;
  }

  .chapter-action-bar > * {
    grid-column: 1 !important;
  }

  .chapter-release-group > header > div {
    align-items: flex-start;
    flex-direction: column;
    gap: 2px;
  }

  .chapter-variant-copy > small > span:not(:last-child)::after,
  .chapter-variant-copy > small > time::after {
    content: none;
  }

  .emoji-catalog-grid {
    grid-template-columns: repeat(5, minmax(40px, 1fr));
    padding-inline: 12px;
  }

  .media-picker-backdrop :is(.comment-gif-picker, .emoji-picker) > header,
  .comment-gif-filters,
  .emoji-picker-filters {
    padding-inline: 13px;
  }

  .admin-gallery-queue > article {
    grid-template-columns: 76px minmax(0, 1fr);
    padding: 9px;
  }

  .admin-gallery-queue > article > img {
    width: 76px;
    height: 62px;
  }

  .admin-gallery-actions {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .admin-gallery-actions .button {
    width: 100%;
    justify-content: center;
  }

  .reader-continuity-dialog {
    padding: 16px;
  }
}

@media (min-width: 1800px) {
  .series-gallery-rail {
    grid-template-columns: repeat(auto-fill, minmax(170px, 1fr));
  }

  .chapter-variant-row {
    grid-template-columns: 54px minmax(0, 1fr) minmax(110px, auto) 110px;
  }
}

/* Version 39 · team-first multi-upload queue */
.upload-team-step {
  display: grid;
  width: min(100%, 940px);
  min-width: 0;
  gap: 18px;
  margin-inline: auto;
  padding: clamp(18px, 3vw, 30px);
  border: 1px solid var(--line);
  border-radius: 18px;
  background:
    linear-gradient(
      135deg,
      color-mix(in srgb, var(--accent) 8%, transparent),
      transparent 48%
    ),
    var(--surface);
}

.upload-team-step-copy {
  display: grid;
  gap: 5px;
}

.upload-team-step-copy > span {
  color: var(--accent);
  font-size: 12px;
  font-weight: 850;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.upload-team-step-copy :is(h3, p) {
  margin: 0;
}

.upload-team-step-copy h3 {
  font-size: clamp(22px, 3vw, 32px);
  letter-spacing: -0.035em;
}

.upload-team-step-copy p {
  max-width: 64ch;
  color: var(--muted);
  font-size: 14px;
  line-height: 1.6;
}

.upload-team-search {
  display: grid;
  min-width: 0;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 10px;
  padding-inline: 14px;
  border: 1px solid var(--line);
  border-radius: 12px;
  color: var(--muted);
  background: var(--bg-soft);
}

.upload-team-search:focus-within {
  border-color: color-mix(in srgb, var(--accent) 70%, var(--line));
  box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 13%, transparent);
}

.upload-team-search input {
  width: 100%;
  min-width: 0;
  min-height: 48px;
  padding: 0;
  border: 0;
  outline: 0;
  background: transparent;
}

.upload-team-options {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.upload-team-options > label {
  display: grid;
  min-width: 0;
  min-height: 76px;
  grid-template-columns: 42px minmax(0, 1fr) 28px;
  align-items: center;
  gap: 11px;
  padding: 12px;
  border: 1px solid var(--line);
  border-radius: 13px;
  color: var(--text);
  background: var(--surface-2);
  text-align: left;
  cursor: pointer;
}

.upload-team-options > label:hover,
.upload-team-options > label:focus-within,
.upload-team-options > label.is-selected {
  border-color: color-mix(in srgb, var(--accent) 66%, var(--line));
  background: color-mix(in srgb, var(--accent) 8%, var(--surface-2));
}

.upload-team-options > label:focus-within {
  outline: 3px solid color-mix(in srgb, var(--accent) 22%, transparent);
  outline-offset: 2px;
}

.upload-team-native-radio {
  position: absolute;
  width: 1px !important;
  min-width: 1px !important;
  height: 1px !important;
  min-height: 1px !important;
  margin: 0;
  opacity: 0;
}

.upload-team-option-icon {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--accent) 35%, var(--line));
  border-radius: 50%;
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 10%, var(--surface));
}

.upload-team-options > label strong,
.upload-team-options > label small {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.upload-team-options > label strong {
  font-size: 14px;
}

.upload-team-options > label small {
  margin-top: 3px;
  color: var(--muted);
  font-size: 11px;
}

.upload-team-option-check {
  display: grid;
  width: 26px;
  height: 26px;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 50%;
  color: var(--accent-ink);
  background: var(--surface);
}

.upload-team-options > label.is-selected .upload-team-option-check {
  border-color: var(--accent);
  background: var(--accent);
}

.upload-team-step-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.upload-resume-state {
  min-height: 260px;
}

.upload-resume-state > svg {
  color: var(--accent);
}

.upload-quick-settings {
  display: grid;
  min-width: 0;
  gap: 14px;
}

.upload-active-team {
  display: grid;
  min-width: 0;
  grid-template-columns: 42px minmax(0, 1fr) auto;
  align-items: center;
  gap: 11px;
  padding: 11px 12px;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: var(--bg-soft);
}

.upload-active-team :is(strong, small) {
  display: block;
}

.upload-active-team small {
  color: var(--muted);
  font-size: 11px;
}

.upload-active-team strong {
  margin-top: 2px;
  font-size: 14px;
}

.upload-active-team .button {
  min-height: 38px;
}

.upload-quick-grid {
  display: grid;
  min-width: 0;
  grid-template-columns: minmax(220px, 1.35fr) minmax(170px, 0.8fr) minmax(190px, 0.9fr);
  gap: 10px;
}

.upload-quick-grid > :is(label, div) {
  display: grid;
  min-width: 0;
  align-content: start;
  gap: 7px;
}

.upload-quick-grid > label > span,
.upload-quick-grid > .upload-combobox-field > span,
.upload-quick-format > span,
.upload-batch-price > span {
  color: var(--muted);
  font-size: 11px;
  font-weight: 750;
}

.upload-quick-grid :is(select, input) {
  width: 100%;
  min-width: 0;
  min-height: 44px;
}

.upload-quick-format {
  min-height: 72px;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: var(--surface-2);
}

.upload-quick-format strong {
  font-size: 13px;
}

.upload-quick-format small {
  color: var(--muted);
  font-size: 10px;
  line-height: 1.45;
}

.upload-batch-paid-panel {
  display: grid;
  min-width: 0;
  grid-template-columns: minmax(240px, 1fr) auto minmax(140px, 0.38fr);
  align-items: center;
  gap: 14px;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: 13px;
  background: color-mix(in srgb, var(--accent) 4%, var(--surface-2));
}

.upload-batch-paid-panel > div {
  display: grid;
  min-width: 0;
  grid-template-columns: 38px minmax(0, 1fr);
  align-items: center;
  gap: 10px;
}

.upload-batch-paid-panel > div :is(strong, small) {
  display: block;
}

.upload-batch-paid-panel > div strong {
  font-size: 14px;
}

.upload-batch-paid-panel > div small {
  margin-top: 2px;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.45;
}

.upload-paid-icon {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  overflow: hidden;
  border-radius: 50%;
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 12%, var(--surface));
}

.upload-paid-icon img {
  width: 24px;
  height: 24px;
  object-fit: contain;
}

.upload-switch,
.upload-queue-paid-toggle {
  display: inline-grid;
  min-width: 0;
  grid-template-columns: 38px minmax(0, auto);
  align-items: center;
  gap: 8px;
  cursor: pointer;
}

.upload-switch input,
.upload-queue-paid-toggle input {
  position: absolute;
  width: 1px;
  height: 1px;
  opacity: 0;
}

.upload-switch > span,
.upload-queue-paid-toggle > span {
  position: relative;
  display: block;
  width: 38px;
  height: 22px;
  border: 1px solid var(--line-strong);
  border-radius: 99px;
  background: var(--surface-3);
  transition: 160ms ease;
}

.upload-switch > span::after,
.upload-queue-paid-toggle > span::after {
  position: absolute;
  top: 3px;
  left: 3px;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: var(--muted);
  content: "";
  transition: transform 160ms ease, background 160ms ease;
}

.upload-switch input:checked + span,
.upload-queue-paid-toggle input:checked + span {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 35%, var(--surface-3));
}

.upload-switch input:checked + span::after,
.upload-queue-paid-toggle input:checked + span::after {
  transform: translateX(16px);
  background: var(--accent);
}

.upload-switch input:focus-visible + span,
.upload-queue-paid-toggle input:focus-visible + span {
  outline: 3px solid color-mix(in srgb, var(--accent) 22%, transparent);
  outline-offset: 2px;
}

.upload-switch input:disabled + span,
.upload-queue-paid-toggle input:disabled + span {
  opacity: 0.48;
}

.upload-switch b,
.upload-queue-paid-toggle b {
  min-width: 0;
  color: var(--text-soft);
  font-size: 11px;
  white-space: nowrap;
}

.upload-batch-price {
  display: grid;
  min-width: 0;
  gap: 6px;
}

.upload-batch-price input {
  width: 100%;
  min-width: 0;
  min-height: 42px;
}

.upload-batch-dropzone {
  display: grid;
  min-width: 0;
  min-height: 300px;
  place-items: center;
  align-content: center;
  gap: 10px;
  padding: clamp(18px, 4vw, 34px);
  border: 1px dashed var(--line-strong);
  border-radius: 16px;
  background:
    radial-gradient(
      circle at 100% 0%,
      color-mix(in srgb, var(--accent) 9%, transparent),
      transparent 34%
    ),
    var(--bg-soft);
  text-align: center;
  transition: border-color 160ms ease, background 160ms ease;
}

.upload-batch-dropzone.is-dragging {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 9%, var(--bg-soft));
}

.upload-batch-dropzone[aria-busy="true"] {
  cursor: progress;
  opacity: 0.72;
}

.upload-batch-drop-icon {
  display: grid;
  width: 64px;
  height: 64px;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 18px;
  color: var(--accent);
  background: var(--surface-2);
}

.upload-batch-dropzone > strong {
  margin-top: 4px;
  font-size: clamp(18px, 2.2vw, 25px);
  letter-spacing: -0.025em;
}

.upload-batch-dropzone > p {
  max-width: 680px;
  margin: 0;
  color: var(--muted);
  font-size: 13px;
  line-height: 1.55;
}

.upload-source-chips,
.upload-batch-drop-actions {
  display: flex;
  min-width: 0;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

.upload-source-chips span {
  padding: 5px 10px;
  border: 1px solid var(--line);
  border-radius: 99px;
  color: var(--text-soft);
  background: var(--surface-2);
  font-size: 10px;
  font-weight: 750;
}

.upload-batch-drop-actions {
  margin-top: 6px;
}

.upload-batch-drop-actions .button {
  min-height: 42px;
}

.upload-batch-dropzone > input.upload-native-file {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  opacity: 0;
  pointer-events: none;
}

.upload-queue-summary {
  display: grid;
  width: 100%;
  min-width: 0;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
  margin: 14px 0 0;
}

.upload-queue-summary > div {
  display: flex;
  min-width: 0;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 12px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background: var(--surface-2);
}

.upload-queue-summary :is(dt, dd) {
  min-width: 0;
  margin: 0;
  font-size: 11px;
}

.upload-queue-summary dt {
  color: var(--muted);
}

.upload-queue-summary dd {
  overflow: hidden;
  color: var(--text);
  font-weight: 800;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.upload-batch-table > article {
  padding: 14px;
}

.upload-batch-table > article > header {
  display: grid;
  min-width: 0;
  grid-template-columns: 30px minmax(0, 1fr) auto;
  gap: 10px;
  margin-bottom: 0;
}

.upload-batch-table > article > header > div {
  min-width: 0;
}

.upload-queue-paid-toggle {
  justify-self: end;
}

.upload-queue-access-controls {
  display: grid;
  min-width: 0;
  justify-items: end;
  gap: 7px;
}

.upload-queue-access-controls .upload-queue-paid-toggle {
  justify-self: stretch;
}

.upload-queue-details {
  margin-top: 12px;
  border-top: 1px solid var(--line);
}

.upload-queue-details > summary {
  width: max-content;
  max-width: 100%;
  padding-block: 12px 2px;
  color: var(--accent);
  font-size: 11px;
  font-weight: 800;
  cursor: pointer;
}

.upload-queue-details > .upload-form-grid {
  margin-top: 12px;
}

.upload-batch-table > article > header strong,
.upload-batch-table > article > header small,
.upload-queue-paid-toggle b {
  overflow-wrap: anywhere;
}

.upload-page-preview-note,
.upload-review-warning {
  margin: 10px 0 0;
  padding: 9px 11px;
  border: 1px solid var(--line);
  border-radius: 10px;
  color: var(--muted);
  background: var(--bg-soft);
  font-size: 11px;
  line-height: 1.55;
}

.upload-page-disclosure {
  min-width: 0;
  overflow: clip;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: var(--surface-2);
}

.upload-page-disclosure + .upload-page-disclosure {
  margin-top: 10px;
}

.upload-page-disclosure > summary {
  display: grid;
  min-width: 0;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  padding: 12px 14px;
  color: var(--text);
  cursor: pointer;
  list-style: none;
}

.upload-page-disclosure > summary::-webkit-details-marker {
  display: none;
}

.upload-page-disclosure > summary::after {
  grid-column: 2;
  grid-row: 1 / span 2;
  color: var(--muted);
  content: "+";
  font-size: 20px;
  line-height: 1;
}

.upload-page-disclosure[open] > summary::after {
  content: "−";
}

.upload-page-disclosure > summary span,
.upload-page-disclosure > summary small {
  min-width: 0;
  overflow-wrap: anywhere;
}

.upload-page-disclosure > summary span {
  font-size: 13px;
  font-weight: 800;
}

.upload-page-disclosure > summary small {
  color: var(--muted);
  font-size: 11px;
}

.upload-page-disclosure > ol {
  margin-top: 0;
  padding: 0 12px 12px;
}

.upload-page-pagination {
  display: flex;
  min-width: 0;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 0 12px 12px;
}

.upload-page-pagination button {
  display: inline-flex;
  width: auto;
  height: auto;
  min-height: 36px;
  align-items: center;
  justify-content: center;
  gap: 6px;
  padding: 7px 10px;
  border: 1px solid var(--line);
  border-radius: 9px;
  color: var(--text-soft);
  background: var(--surface);
  font-size: 11px;
  font-weight: 800;
}

.upload-page-pagination span {
  color: var(--muted);
  font-size: 11px;
  text-align: center;
}

.upload-final-review > .button {
  width: 100%;
  min-width: 0;
  justify-content: center;
  overflow-wrap: anywhere;
  text-align: center;
  white-space: normal;
}

.upload-review-warning {
  border-color: color-mix(in srgb, var(--warning) 48%, var(--line));
  color: var(--text-soft);
  background: color-mix(in srgb, var(--warning) 7%, var(--bg-soft));
}

.upload-team-empty {
  min-height: 180px;
}

@container (max-width: 900px) {
  .upload-quick-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .upload-quick-format {
    grid-column: 1 / -1;
  }

  .upload-batch-paid-panel {
    grid-template-columns: minmax(0, 1fr) auto;
  }

  .upload-batch-price {
    grid-column: 1 / -1;
  }
}

@container (max-width: 700px) {
  .upload-team-options,
  .upload-quick-grid,
  .upload-queue-summary {
    grid-template-columns: 1fr;
  }

  .upload-active-team {
    grid-template-columns: 42px minmax(0, 1fr);
  }

  .upload-active-team .button {
    grid-column: 1 / -1;
  }

  .upload-batch-paid-panel {
    grid-template-columns: minmax(0, 1fr);
  }

  .upload-batch-paid-panel > :is(div, .upload-switch, .upload-batch-price) {
    grid-column: 1;
  }

  .upload-batch-paid-panel > .upload-switch {
    justify-self: start;
  }

  .upload-batch-table > article > header {
    grid-template-columns: 30px minmax(0, 1fr);
  }

  .upload-queue-paid-toggle {
    grid-column: 1 / -1;
    justify-self: stretch;
    padding: 10px;
    border: 1px solid var(--line);
    border-radius: 10px;
    background: var(--surface);
  }

  .upload-queue-access-controls {
    grid-column: 1 / -1;
    justify-items: stretch;
  }

  .upload-queue-paid-toggle b {
    white-space: normal;
  }

  .upload-batch-drop-actions {
    display: grid;
    width: 100%;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .upload-batch-drop-actions .button {
    width: 100%;
    min-width: 0;
    justify-content: center;
  }
}

@media (max-width: 430px) {
  .title-actions {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .title-actions .series-secondary-action {
    width: 100%;
    min-width: 0;
  }
}

@container (max-width: 430px) {
  .upload-team-step,
  .upload-composer-card {
    padding: 14px;
  }

  .upload-team-step-actions,
  .upload-batch-drop-actions {
    display: grid;
    width: 100%;
    grid-template-columns: 1fr;
  }

  .upload-team-step-actions .button,
  .upload-batch-drop-actions .button {
    width: 100%;
    justify-content: center;
  }

  .upload-team-options > label {
    grid-template-columns: 38px minmax(0, 1fr) 26px;
    padding-inline: 10px;
  }

  .upload-team-option-icon {
    width: 38px;
    height: 38px;
  }

  .upload-batch-dropzone {
    min-height: 260px;
    padding: 18px 12px;
  }

  .upload-batch-table > article {
    padding: 11px;
  }

  .upload-page-pagination {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .upload-page-pagination span {
    grid-column: 1 / -1;
    grid-row: 1;
  }

  .upload-page-pagination button {
    width: 100%;
    min-width: 0;
  }
}

/* Version 40 · publishing identity, chapter disclosures, reports and galleries */
.chapter-details-toggle,
.chapter-group-toggle {
  display: inline-flex;
  min-height: 42px;
  align-items: center;
  justify-content: center;
  gap: 7px;
  border: 1px solid var(--line);
  border-radius: 10px;
  color: var(--text-soft);
  background: var(--surface-2);
  font: inherit;
  font-size: 12px;
  font-weight: 750;
  cursor: pointer;
}

.chapter-details-toggle:is(:hover, :focus-visible),
.chapter-group-toggle:is(:hover, :focus-visible) {
  border-color: color-mix(in srgb, var(--accent) 64%, var(--line));
  color: var(--accent);
}

.chapter-details-toggle:focus-visible,
.chapter-group-toggle:focus-visible,
.chapter-release-compact > button:focus-visible {
  outline: 3px solid color-mix(in srgb, var(--accent) 22%, transparent);
  outline-offset: 2px;
}

.chapter-release-group > header {
  grid-template-columns: 56px minmax(0, 1fr) 38px;
}

.chapter-release-group > header > div {
  align-items: center;
}

.chapter-group-toggle {
  width: 38px;
  min-height: 38px;
  padding: 0;
}

.chapter-group-toggle svg {
  transform: rotate(180deg);
}

.chapter-language-counts {
  display: inline-flex;
  min-width: 0;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
}

.chapter-language-counts > span {
  display: inline-flex;
  min-height: 27px;
  align-items: center;
  gap: 5px;
  padding: 4px 7px;
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--text-soft);
  background: var(--bg-soft);
}

.chapter-language-counts b {
  font-size: 10px;
  line-height: 1;
}

.chapter-variant-row {
  text-decoration: none;
}

.chapter-variant-row:hover {
  background: color-mix(in srgb, var(--theme-indication-blue) 5.5%, transparent);
}

.chapter-variant-visual,
.chapter-variant-title,
.chapter-variant-copy small a,
.chapter-read {
  text-decoration: none;
}

.chapter-variant-title {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 8px;
  overflow: hidden;
  color: var(--text);
  font-size: 13px;
  font-weight: 800;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.chapter-variant-title > span:not(.language-flag) {
  overflow: hidden;
  text-overflow: ellipsis;
}

.chapter-variant-title:is(:hover, :focus-visible),
.chapter-variant-copy small a:is(:hover, :focus-visible) {
  color: var(--accent);
}

.chapter-variant-title:focus-visible,
.chapter-variant-copy small a:focus-visible,
.chapter-read:focus-visible,
.chapter-variant-visual:focus-visible {
  border-radius: 5px;
  outline: 2px solid color-mix(in srgb, var(--accent) 58%, transparent);
  outline-offset: 2px;
}

.chapter-variant-copy > small a {
  color: var(--text-soft);
  font-weight: 700;
}

.chapter-release-compact {
  overflow: visible;
}

.chapter-release-compact > button {
  display: grid;
  width: 100%;
  min-width: 0;
  min-height: 82px;
  grid-template-columns: 58px minmax(0, 1fr) auto 22px;
  align-items: center;
  gap: 13px;
  padding: 11px 14px;
  border: 0;
  border-radius: 12px;
  color: var(--text);
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--theme-primary) 8%, transparent), transparent 62%),
    var(--surface);
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.chapter-release-compact > button:is(:hover, :focus-visible) {
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--theme-primary) 14%, transparent), transparent 72%),
    var(--surface-2);
}

.chapter-compact-thumbnail {
  display: grid;
  width: 58px;
  height: 58px;
  overflow: hidden;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 10px;
  color: var(--muted);
  background: var(--surface-2);
}

.chapter-compact-thumbnail img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.chapter-compact-copy {
  display: grid;
  min-width: 0;
  gap: 4px;
}

.chapter-compact-copy strong,
.chapter-compact-copy small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.chapter-compact-copy strong {
  font-size: 14px;
}

.chapter-compact-copy small {
  color: var(--muted);
  font-size: 11px;
}

.chapter-release-compact > button > svg {
  color: var(--muted);
}

.chapter-action-bar .report-link.button-danger {
  padding-inline: 16px;
  border-color: color-mix(in srgb, var(--danger) 78%, var(--line)) !important;
  color: var(--theme-contrast-l1) !important;
  background: color-mix(in srgb, var(--danger) 78%, var(--theme-danger-l2));
  font-size: 12px;
  font-weight: 800;
}

.chapter-action-bar .report-link.button-danger:is(:hover, :focus-visible) {
  background: color-mix(in srgb, var(--danger) 88%, var(--theme-danger-l2));
  box-shadow: 0 8px 24px color-mix(in srgb, var(--danger) 22%, transparent);
}

.series-report-backdrop {
  position: fixed;
  inset: 0;
  z-index: 230;
  display: grid;
  overflow: auto;
  place-items: center;
  padding:
    max(18px, env(safe-area-inset-top))
    max(18px, env(safe-area-inset-right))
    max(18px, env(safe-area-inset-bottom))
    max(18px, env(safe-area-inset-left));
  background: rgb(2 8 16 / 0.82);
  backdrop-filter: blur(9px);
}

.series-report-dialog {
  display: grid;
  width: min(620px, 100%);
  max-height: calc(100dvh - 36px);
  gap: 16px;
  padding: clamp(18px, 3vw, 28px);
  overflow: auto;
  border: 1px solid color-mix(in srgb, var(--danger) 42%, var(--line));
  border-radius: 18px;
  background:
    linear-gradient(
      145deg,
      color-mix(in srgb, var(--danger) 8%, transparent),
      transparent 42%
    ),
    var(--surface);
  box-shadow: 0 28px 90px rgb(0 0 0 / 0.5);
}

.series-report-dialog > header {
  display: grid;
  grid-template-columns: 46px minmax(0, 1fr) 40px;
  align-items: center;
  gap: 12px;
}

.series-report-dialog > header :is(span, h2),
.series-report-dialog > p {
  margin: 0;
}

.series-report-dialog > header > div > span {
  color: var(--danger);
  font-size: 11px;
  font-weight: 850;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.series-report-dialog h2 {
  margin-top: 3px !important;
  font-size: clamp(21px, 3vw, 28px);
  line-height: 1.15;
}

.series-report-icon,
.series-report-dialog > header > button {
  display: grid;
  width: 40px;
  height: 40px;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--danger) 34%, var(--line));
  border-radius: 11px;
  color: var(--danger);
  background: color-mix(in srgb, var(--danger) 9%, var(--surface-2));
}

.series-report-icon {
  width: 46px;
  height: 46px;
}

.series-report-dialog > header > button {
  cursor: pointer;
}

.series-report-dialog > p {
  color: var(--muted);
  font-size: 13px;
  line-height: 1.6;
}

.series-report-dialog > label {
  display: grid;
  min-width: 0;
  gap: 7px;
}

.series-report-dialog > label > span {
  color: var(--text-soft);
  font-size: 12px;
  font-weight: 750;
}

.series-report-dialog :is(select, textarea) {
  width: 100%;
  min-width: 0;
}

.series-report-dialog textarea {
  min-height: 142px;
  resize: vertical;
}

.series-report-dialog label small {
  justify-self: end;
  color: var(--muted);
  font-size: 10px;
}

.series-report-critical-note,
.series-report-error {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  padding: 11px 13px;
  border: 1px solid color-mix(in srgb, var(--danger) 42%, var(--line));
  border-radius: 10px;
  color: color-mix(in srgb, var(--danger) 64%, white);
  background: color-mix(in srgb, var(--danger) 8%, var(--surface-2));
  font-size: 12px;
  line-height: 1.55;
}

.series-report-error svg {
  flex: 0 0 auto;
}

.series-report-dialog > footer {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  padding-top: 3px;
}

.series-galleries {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  align-items: start;
}

.series-gallery-error,
.series-gallery-submissions {
  grid-column: 1 / -1;
}

.series-gallery-card {
  padding: 0;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.series-cover-badges {
  position: absolute;
  inset: 9px 9px auto;
  z-index: 2;
  display: flex;
  min-width: 0;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
  pointer-events: none;
}

.series-cover-type-badge,
.series-cover-language-badge {
  display: inline-flex;
  min-height: 27px;
