/* Version 48.3 — home discovery, release feed, and notification polish. */

.home-announcement-slider.v46-announcement-list {
  display: block;
  overflow: visible;
  margin: 0 0 1.2rem;
  padding: 0;
  scrollbar-width: none;
}

.home-announcement-slider.v46-announcement-list > article {
  grid-template-columns: auto minmax(0, 1fr) auto auto;
  min-height: 7rem;
  padding: 1rem 1.1rem;
  animation: announcement-slide-enter 220ms ease both;
}

.home-announcement-slider.v46-announcement-list > article > div:not(.announcement-slider-arrows) {
  align-content: center;
}

.home-announcement-slider .announcement-slider-arrows {
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

.home-announcement-slider .announcement-slider-arrows button {
  display: grid;
  width: 2.65rem;
  height: 2.65rem;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--announcement-tone) 34%, var(--line));
  border-radius: 999px;
  background: color-mix(in srgb, var(--announcement-tone) 8%, var(--surface));
  color: var(--announcement-tone);
}

.home-announcement-slider .announcement-slider-arrows button:hover,
.home-announcement-slider .announcement-slider-arrows button:focus-visible {
  border-color: var(--announcement-tone);
  background: color-mix(in srgb, var(--announcement-tone) 16%, var(--surface));
}

.home-announcement-slider > .announcement-slider-dots {
  margin-block-start: 0.65rem;
}

@keyframes announcement-slide-enter {
  from {
    opacity: 0.48;
    transform: translateY(5px);
  }
}

.hot-this-week {
  display: grid;
  gap: 1.15rem;
}

.hot-week-heading,
.hot-week-heading > div,
.hot-week-heading > div > div,
.hot-week-heading > a {
  display: flex;
  align-items: center;
}

.hot-week-heading {
  justify-content: space-between;
  gap: 1rem;
  padding-bottom: 0.9rem;
  border-bottom: 1px solid var(--line);
}

.hot-week-heading > div {
  min-width: 0;
  gap: 0.75rem;
}

.hot-week-heading > div > span {
  display: grid;
  width: 2.7rem;
  height: 2.7rem;
  flex: 0 0 auto;
  place-items: center;
  border: 1px solid color-mix(in srgb, #ff7547 36%, var(--line));
  border-radius: 0.85rem;
  background: color-mix(in srgb, #ff7547 12%, var(--surface));
  color: #ff7547;
}

.hot-week-heading > div > div {
  align-items: flex-start;
  flex-direction: column;
  gap: 0.2rem;
}

.hot-week-heading h2,
.hot-week-heading p {
  margin: 0;
}

.hot-week-heading h2 {
  font-size: clamp(1.35rem, 2.4vw, 2rem);
}

.hot-week-heading p {
  color: var(--muted);
  font-size: 0.84rem;
}

.hot-week-heading > a,
.hot-week-read {
  justify-content: center;
  gap: 0.35rem;
  color: var(--accent);
  font-size: 0.78rem;
  font-weight: 800;
}

.hot-week-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.9rem;
}

.hot-week-card {
  position: relative;
  display: grid;
  min-width: 0;
  grid-template-columns: 4.65rem minmax(0, 1fr);
  gap: 0.85rem;
  padding: 0.9rem;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 1rem;
  background: linear-gradient(145deg, var(--surface), color-mix(in srgb, var(--bg-soft) 70%, var(--surface)));
  transition: border-color 160ms ease, transform 160ms ease, box-shadow 160ms ease;
}

.hot-week-card:hover,
.hot-week-card:focus-within {
  border-color: color-mix(in srgb, #ff7547 42%, var(--line));
  box-shadow: 0 14px 34px color-mix(in srgb, var(--shadow) 58%, transparent);
  transform: translateY(-2px);
}

.hot-week-rank {
  position: absolute;
  z-index: 2;
  top: 0.55rem;
  left: 0.55rem;
  display: grid;
  width: 1.65rem;
  height: 1.65rem;
  place-items: center;
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 0.5rem;
  background: #e85b32;
  color: #fff;
  box-shadow: 0 6px 16px rgba(0, 0, 0, 0.28);
  font-size: 0.72rem;
  font-weight: 900;
}

.hot-week-rank.rank-1 { background: #d79c18; }
.hot-week-rank.rank-2 { background: #7a8797; }
.hot-week-rank.rank-3 { background: #a86831; }

.hot-week-cover,
.hot-week-cover > :is(img, span) {
  display: block;
  width: 100%;
  height: 100%;
}

.hot-week-cover {
  min-height: 6.9rem;
  overflow: hidden;
  border-radius: 0.7rem;
  background: var(--surface-2);
}

.hot-week-cover img {
  object-fit: cover;
}

.hot-week-cover-fallback {
  display: grid !important;
  place-items: center;
  color: var(--muted);
}

.hot-week-copy {
  display: grid;
  min-width: 0;
  align-content: start;
  gap: 0.45rem;
}

.hot-week-copy h3 {
  display: -webkit-box;
  overflow: hidden;
  margin: 0;
  color: var(--text);
  font-size: 0.92rem;
  line-height: 1.3;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.hot-week-metrics,
.hot-week-genres {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem 0.65rem;
}

.hot-week-metrics small {
  display: inline-flex;
