.hot-week-state button {
  display: inline-flex;
  min-height: 2.5rem;
  align-items: center;
  gap: 0.35rem;
  margin-top: 0.35rem;
  padding: 0 0.75rem;
  border: 1px solid var(--line);
  border-radius: 0.7rem;
  background: var(--surface-2);
  color: var(--text);
}

.hot-week-grid.is-loading > span {
