.latest-release-table :is(th, td):nth-child(1) { width: 39%; }
.latest-release-table :is(th, td):nth-child(2) { width: 27%; }
.latest-release-table :is(th, td):nth-child(3) { width: 21%; }
.latest-release-table :is(th, td):nth-child(4) { width: 13%; }
