  min-width: 0;
  align-items: center;
}

.latest-feed-series { gap: 0.7rem; }
.latest-feed-cover {
  display: grid;
  width: 2.5rem;
  aspect-ratio: 2 / 3;
  flex: 0 0 auto;
  place-items: center;
  overflow: hidden;
  border-radius: 0.42rem;
  background: var(--surface-2);
  color: var(--muted);
