.latest-feed-cover img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.latest-feed-series > span:last-child,
.latest-feed-chapter > span:nth-child(2) {
  display: grid;
  min-width: 0;
  gap: 0.18rem;
}

.latest-feed-series strong,
.latest-feed-chapter strong,
.latest-feed-series small,
.latest-feed-chapter small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.latest-feed-series strong,
.latest-feed-chapter strong {
  color: var(--text);
  font-size: 0.78rem;
}

.latest-feed-series small,
.latest-feed-chapter small,
.latest-release-table time,
.latest-feed-team {
  color: var(--muted);
  font-size: 0.67rem;
}

.latest-feed-chapter { gap: 0.45rem; }
.latest-feed-chapter > .chapter-status-badge { margin-left: auto; }
.latest-feed-team { gap: 0.45rem; }
.latest-feed-team a { color: var(--text-soft); }

.latest-chapters li.is-paid {
  border-color: color-mix(in srgb, var(--theme-status-yellow) 34%, var(--line));
  background: linear-gradient(90deg, color-mix(in srgb, var(--theme-status-yellow) 12%, var(--surface-2)), var(--surface-2));
  box-shadow: inset 3px 0 0 var(--theme-status-yellow);
}

.latest-chapters li.is-paid:hover {
  box-shadow: inset 3px 0 0 var(--theme-status-yellow), 0 8px 22px color-mix(in srgb, var(--theme-status-yellow) 12%, transparent);
}

.teams-heading-actions {
  display: flex;
  align-items: center;
  gap: 0.55rem;
}

.public-teams .teams-carousel {
  grid-auto-columns: calc((100% - 2rem) / 3);
  align-items: stretch;
  gap: 1rem;
  padding: 0.15rem 0 0.6rem;
  scroll-padding-inline: 0;
}

.public-teams .teams-carousel.is-single {
  grid-auto-columns: min(100%, 30rem);
  justify-content: center;
}

.public-teams .team-carousel-card {
  display: grid;
  min-height: 100%;
  grid-template-rows: auto auto 1fr;
  scroll-snap-align: start;
  opacity: 1;
  transform: none;
}

.public-teams .team-carousel-card[data-active="true"] {
  border-color: color-mix(in srgb, var(--accent) 38%, var(--line));
  box-shadow: 0 14px 34px color-mix(in srgb, var(--shadow) 56%, transparent);
  transform: none;
}

.public-teams .team-carousel-logo {
  width: 4.8rem;
  height: 4.8rem;
  margin-top: -2.4rem;
}

.public-teams .team-carousel-card > div {
  width: 100%;
  align-content: start;
  grid-template-rows: auto minmax(3rem, auto) auto auto 1fr;
  padding: 0.7rem 1rem 1rem;
}

.public-teams .team-carousel-card > div > .team-card-action {
  align-self: end;
  justify-self: stretch;
  justify-content: center;
  min-height: 2.65rem;
  margin-top: 0.2rem;
  border: 1px solid color-mix(in srgb, var(--accent) 38%, var(--line));
  border-radius: 0.7rem;
  background: color-mix(in srgb, var(--accent) 8%, var(--surface));
}

.public-teams .team-public-metrics {
  justify-content: center;
  gap: 0.45rem 0.7rem;
}

.notification-artwork {
  display: grid;
  flex: 0 0 auto;
  place-items: center;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 0.65rem;
  background: color-mix(in srgb, var(--accent) 10%, var(--surface-2));
  color: var(--accent);
}

.notification-artwork img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
}

.header-notification-menu {
  width: min(430px, calc(100vw - 24px));
}

.header-notification-menu > header {
  align-items: flex-start;
}

.header-notification-mark-all,
.header-notification-mark-one {
  border: 0;
  background: transparent;
  color: var(--accent);
  cursor: pointer;
  font-size: 0.64rem;
  font-weight: 800;
}

.header-notification-mark-all {
  display: inline-flex;
  min-height: 2.25rem;
  align-items: center;
  gap: 0.3rem;
  padding: 0 0.55rem;
  border: 1px solid color-mix(in srgb, var(--accent) 30%, var(--line));
  border-radius: 0.65rem;
  background: color-mix(in srgb, var(--accent) 7%, var(--surface));
}

.header-notification-mark-all:disabled,
.header-notification-mark-one:disabled {
  cursor: not-allowed;
  opacity: 0.45;
}

.header-notification-action-error {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.45rem;
  padding: 0.6rem 0.75rem;
  border-bottom: 1px solid color-mix(in srgb, var(--danger) 34%, var(--line));
  background: color-mix(in srgb, var(--danger) 8%, var(--surface));
  color: var(--danger);
  font-size: 0.64rem;
}

.header-notification-action-error button {
  color: inherit;
  font-weight: 800;
}

.header-notification-list > li {
  display: grid;
  min-width: 0;
  border-bottom: 1px solid color-mix(in srgb, var(--line) 72%, transparent);
}

.header-notification-list > li.is-unread {
  background: linear-gradient(90deg, color-mix(in srgb, var(--accent) 9%, var(--surface)), var(--surface));
  box-shadow: inset 3px 0 0 var(--accent);
}

.header-notification-item {
  grid-template-columns: 3rem minmax(0, 1fr);
  gap: 0.75rem;
  padding: 0.75rem 0.85rem 0.45rem;
  border-bottom: 0;
  background: transparent;
}

.header-notification-item:hover,
.header-notification-item:focus-visible {
  background: color-mix(in srgb, var(--accent) 5%, transparent);
}

.header-notification-item > span.header-notification-artwork:first-child {
  width: 3rem;
  height: auto;
  aspect-ratio: 2 / 3;
}

.header-notification-item > span:last-child {
  align-content: center;
  gap: 0.18rem;
}

.header-notification-item em {
  width: fit-content;
  padding: 0.15rem 0.35rem;
  border-radius: 999px;
  background: color-mix(in srgb, var(--accent) 11%, transparent);
  color: var(--accent);
  font-size: 0.52rem;
  font-style: normal;
  font-weight: 850;
  letter-spacing: 0.055em;
  text-transform: uppercase;
}

.header-notification-item strong {
  font-size: 0.73rem;
}

.header-notification-item small {
  display: -webkit-box;
  overflow: hidden;
  white-space: normal;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.header-notification-mark-one,
.header-notification-read-state {
  justify-self: end;
  margin: 0 0.85rem 0.55rem;
}

.header-notification-mark-one {
  min-height: 1.9rem;
  padding: 0 0.55rem;
  border: 1px solid color-mix(in srgb, var(--accent) 32%, var(--line));
  border-radius: 999px;
}

.header-notification-read-state {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  color: var(--muted);
  font-size: 0.58rem;
}

.notification-card {
  grid-template-columns: 3.4rem minmax(0, 1fr) auto;
}

.notification-card-artwork {
  width: 3.4rem;
  aspect-ratio: 2 / 3;
}

@media (max-width: 1024px) {
  .hot-week-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .public-teams .teams-carousel {
    grid-auto-columns: calc((100% - 1rem) / 2);
  }
  .public-teams .teams-carousel.is-single {
    grid-auto-columns: min(100%, 30rem);
  }
}

@media (max-width: 780px) {
  .home-announcement-slider.v46-announcement-list > article {
    grid-template-columns: auto minmax(0, 1fr) auto;
  }

  .home-announcement-slider.v46-announcement-list > article > a {
    grid-column: 2;
  }

  .home-announcement-slider .announcement-slider-arrows {
    grid-column: 3;
    grid-row: 1 / span 2;
    flex-direction: column;
  }

  .latest-release-table,
  .latest-release-table tbody {
    display: block;
  }

  .latest-release-table thead {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0 0 0 0);
    clip-path: inset(50%);
    white-space: nowrap;
  }

  .latest-release-table tbody {
    display: grid;
    gap: 0.65rem;
    padding: 0.65rem;
  }

  .latest-release-table tbody tr {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 0.65rem 1rem;
    padding: 0.75rem;
    border: 1px solid var(--line);
    border-radius: 0.8rem;
    background: var(--surface);
  }

  .latest-release-table tbody tr.is-paid {
    border-color: color-mix(in srgb, var(--theme-status-yellow) 38%, var(--line));
    background: color-mix(in srgb, var(--theme-status-yellow) 7%, var(--surface));
    box-shadow: inset 3px 0 0 var(--theme-status-yellow);
  }

  .latest-release-table tbody tr > :is(th, td) {
    display: grid;
    width: auto;
    gap: 0.3rem;
    padding: 0;
    border: 0;
    background: transparent !important;
  }

  .latest-release-table tbody tr > :is(th, td)::before {
    color: var(--muted);
    content: attr(data-label);
    font-size: 0.55rem;
    font-weight: 850;
    letter-spacing: 0.07em;
    text-transform: uppercase;
  }

  .latest-release-table tbody tr > :nth-child(1),
  .latest-release-table tbody tr > :nth-child(2) {
    grid-column: 1 / -1;
  }

  .latest-release-table tbody tr > :nth-child(4) {
    justify-items: end;
    text-align: right;
  }
}

@media (max-width: 680px) {
  .hot-week-heading {
    align-items: flex-start;
    flex-direction: column;
  }

  .hot-week-grid { grid-template-columns: 1fr; }
  .hot-week-card { grid-template-columns: 4.2rem minmax(0, 1fr); }
  .hot-week-cover { min-height: 6.2rem; }

  .teams-heading {
    align-items: flex-start;
  }

  .teams-heading-actions {
    width: 100%;
    flex-wrap: wrap;
  }

  .teams-heading-actions > a {
    margin-left: auto;
  }

  .public-teams .teams-carousel,
  .public-teams .teams-carousel.is-single {
    grid-auto-columns: 100%;
  }

  .header-notification-menu {
    position: fixed;
    top: 76px;
    right: 8px;
    left: 8px;
    width: auto;
    max-height: calc(100dvh - 92px);
  }

  .notification-card {
    grid-template-columns: 2.8rem minmax(0, 1fr);
  }

  .notification-card-artwork {
    width: 2.8rem;
  }

  .notification-read-toggle {
    grid-column: 2;
    justify-self: start;
  }
}

@media (max-width: 520px) {
  .home-announcement-slider.v46-announcement-list > article {
    grid-template-columns: auto minmax(0, 1fr);
    gap: 0.7rem;
  }

  .home-announcement-slider.v46-announcement-list > article > a,
  .home-announcement-slider .announcement-slider-arrows {
    grid-column: 1 / -1;
  }

  .home-announcement-slider .announcement-slider-arrows {
    grid-row: auto;
    flex-direction: row;
    justify-content: flex-end;
  }

  .home-announcement-slider.v46-announcement-list > article > a {
    min-height: 2.5rem;
    justify-content: flex-start;
  }

  .hot-week-heading > a { min-height: 2.75rem; }
}

@media (prefers-reduced-motion: reduce) {
  .home-announcement-slider.v46-announcement-list > article,
  .hot-week-grid.is-loading > span {
    animation: none;
  }

  .hot-week-card { transition: none; }
}

.v481-pin-limit-warning {
  grid-column: 1 / -1;
  margin: 0;
  padding: 0.6rem 0.75rem;
  border: 1px solid color-mix(in srgb, var(--danger) 38%, var(--line));
  border-radius: 0.65rem;
  background: color-mix(in srgb, var(--danger) 8%, var(--surface));
  color: var(--danger);
  font-weight: 750;
}

/* Version 48.3.1 — user-selectable Latest Updates layouts. */
.latest-layout-switch {
  flex: 0 0 auto;
  padding: 0.2rem;
}

.latest-layout-switch > button {
  inline-size: 2.25rem;
  block-size: 2.25rem;
}

.latest-feed-chapter > span:first-child {
  display: grid;
  min-width: 0;
  gap: 0.18rem;
}

@media (max-width: 760px) {
  .latest-layout-switch {
    gap: 0.12rem;
    padding: 0.14rem;
  }

  .latest-layout-switch > button {
    inline-size: 2rem;
    block-size: 2rem;
  }
}

/* Version 48.6.0 — final responsive authority for campaigns, chapter UX, and discovery rails. */

/* The campaign is a composed editorial card on desktop instead of a full-art
   layer with copy floating over it. Keeping the two areas independent also
   lets long campaign copy scroll without moving the close control. */
.event-campaign-backdrop {
  place-items: center !important;
  padding:
    max(1rem, env(safe-area-inset-top))
    max(1rem, env(safe-area-inset-right))
    max(1rem, env(safe-area-inset-bottom))
    max(1rem, env(safe-area-inset-left)) !important;
}

.event-campaign-modal.floating-home-ad {
  display: grid !important;
  width: min(68rem, calc(100vw - 2rem)) !important;
  height: min(44rem, calc(100dvh - 2rem)) !important;
  min-height: 0 !important;
  max-height: calc(100dvh - 2rem) !important;
  grid-template-columns: minmax(0, 1.02fr) minmax(25rem, .98fr);
  overflow: hidden !important;
  border-radius: 1.25rem !important;
  background: #07111c !important;
  box-shadow:
    0 2.5rem 7.5rem rgb(0 0 0 / 72%),
    inset 0 0 0 1px rgb(255 255 255 / 4%) !important;
}

.event-campaign-modal.floating-home-ad .event-campaign-visual {
  position: relative;
  isolation: isolate;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  background: #0a1827;
}

.event-campaign-modal.floating-home-ad .event-campaign-art,
.event-campaign-modal.floating-home-ad .event-campaign-shade {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.event-campaign-modal.floating-home-ad .event-campaign-art {
  z-index: 0;
  object-fit: cover;
  object-position: center;
}

.event-campaign-modal.floating-home-ad .event-campaign-placeholder {
  display: grid;
  place-items: center;
}

.event-campaign-modal.floating-home-ad .event-campaign-shade {
  z-index: 1;
  background:
    linear-gradient(0deg, rgb(3 10 18 / 52%), transparent 52%),
    linear-gradient(90deg, transparent 70%, rgb(3 10 18 / 16%));
  pointer-events: none;
}

.event-campaign-eyebrow {
  position: absolute;
  z-index: 3;
  top: 1.25rem;
  left: 1.25rem;
  display: inline-flex;
  min-height: 2.25rem;
  align-items: center;
  gap: .55rem;
  padding: .45rem .8rem;
  border: 1px solid rgb(139 207 255 / 42%);
  border-radius: .35rem;
  background: rgb(4 19 32 / 78%);
  color: #b8e2ff;
  font-size: .69rem;
  font-weight: 850;
  letter-spacing: .16em;
  text-transform: uppercase;
  backdrop-filter: blur(.75rem);
}

.event-campaign-eyebrow::before {
  width: .42rem;
  height: .42rem;
  border-radius: 50%;
  background: #9ed8ff;
  box-shadow: 0 0 .8rem rgb(96 189 255 / 78%);
  content: "";
}

.event-campaign-modal.floating-home-ad .event-campaign-close {
  position: absolute !important;
  z-index: 4;
  inset: 1.25rem 1.25rem auto auto !important;
  width: 2.75rem !important;
  height: 2.75rem !important;
  border: 1px solid rgb(255 255 255 / 52%);
  border-radius: .45rem;
  background: rgb(3 10 18 / 78%);
  color: #fff;
  backdrop-filter: blur(.75rem);
}

.event-campaign-modal.floating-home-ad .event-campaign-close:is(:hover, :focus-visible) {
  border-color: #fff;
  background: rgb(18 40 61 / 92%);
}

.event-campaign-modal.floating-home-ad .event-campaign-content {
  position: relative;
  z-index: 2;
  display: flex;
  width: auto;
  min-width: 0;
  min-height: 0;
  flex-direction: column;
  justify-content: flex-start;
  align-items: stretch;
  gap: 1.15rem;
  overflow-y: auto;
  padding: clamp(1.75rem, 3vw, 3rem);
  color: #f3f8fc;
  background:
    radial-gradient(circle at 100% 0, rgb(50 145 211 / 10%), transparent 35%),
    #07111c;
  overscroll-behavior: contain;
}

.event-campaign-copy {
  display: grid;
  gap: .8rem;
}

.event-campaign-modal.floating-home-ad .event-campaign-copy h2 {
  max-width: 13ch;
  margin: 0;
  font-size: clamp(2.25rem, 4vw, 4.2rem);
  line-height: .96;
  letter-spacing: -.055em;
}

.event-campaign-modal.floating-home-ad .event-campaign-copy p {
  max-width: 54ch;
  margin: 0;
  color: rgb(219 233 244 / 72%);
  font-size: .9rem;
  line-height: 1.65;
}

.event-campaign-modal.floating-home-ad .event-campaign-info {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: .65rem;
}

.event-campaign-modal.floating-home-ad .event-campaign-info article {
  min-height: 4.15rem;
  padding: .65rem;
  border-color: rgb(132 199 244 / 17%);
  border-radius: .75rem;
  background: rgb(12 31 49 / 68%);
}

.event-campaign-modal.floating-home-ad .event-campaign-info article > span {
  border: 1px solid rgb(112 192 247 / 18%);
  background: rgb(62 147 212 / 13%);
  color: #aadaff;
}

.event-campaign-modal.floating-home-ad .event-campaign-info article strong {
  color: #f3f8fc;
  font-size: .79rem;
}

.event-campaign-modal.floating-home-ad .event-campaign-info article small {
  color: rgb(219 233 244 / 55%);
  font-size: .68rem;
}

.event-campaign-footer {
  display: grid;
  gap: .85rem;
  margin-top: auto;
  padding-top: .2rem;
}

.event-campaign-modal.floating-home-ad .event-campaign-action {
  display: grid;
  width: 100%;
  min-height: 3.4rem;
  grid-template-columns: auto minmax(0, 1fr) auto;
  justify-content: stretch;
  padding-inline: 1.15rem;
  border: 1px solid rgb(204 235 255 / 30%);
  border-radius: .55rem;
  background: linear-gradient(180deg, #8ac8ff, #4b91eb);
  color: #061321;
  box-shadow: 0 .9rem 2.3rem rgb(40 136 226 / 22%);
  font-size: .88rem;
  font-weight: 900;
  letter-spacing: .06em;
  text-transform: uppercase;
}

.event-campaign-modal.floating-home-ad .event-campaign-action:is(:hover, :focus-visible) {
  filter: brightness(1.08);
}

.event-campaign-modal.floating-home-ad .event-campaign-dismiss {
  justify-self: center;
  min-height: 1.75rem;
  color: rgb(219 233 244 / 58%);
  font-size: .73rem;
}

/* Reaction heading deliberately inherits the exact comments-header typography.
   The interaction surface follows the six-item Hive arrangement. */
.chapter-reaction-placement {
  display: grid;
  width: 100%;
  gap: 0;
  margin-bottom: clamp(2rem, 5vw, 4rem);
}

.chapter-reactions-header {
  width: 100%;
  margin-bottom: 1rem;
}

.chapter-reaction-placement .chapter-reactions-box {
  width: 100%;
  margin: 0;
  padding: clamp(1.15rem, 2.4vw, 2rem);
  border: 1px solid color-mix(in srgb, var(--line) 76%, transparent);
  border-radius: 1.1rem;
  background: color-mix(in srgb, var(--theme-main-background) 80%, var(--surface));
  box-shadow: inset 0 1px 0 rgb(255 255 255 / 3%);
}

.chapter-reactions-box .chapter-reaction-options {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: clamp(.45rem, 1.4vw, 1rem);
  margin: 0;
  overflow: visible;
}

.chapter-reactions-box .chapter-reaction-options > button {
  display: grid;
  min-width: 0;
  min-height: 9.25rem;
  grid-template-rows: 3.8rem 2rem auto;
  place-items: center;
  gap: .4rem;
  padding: .75rem .35rem;
  border: 1px solid transparent;
  border-radius: .85rem;
  background: transparent;
  color: inherit;
}

.chapter-reactions-box .chapter-reaction-options > button:is(:hover, :focus-visible),
.chapter-reactions-box .chapter-reaction-options > button[aria-pressed="true"] {
  border-color: color-mix(in srgb, var(--accent) 42%, var(--line));
  background: color-mix(in srgb, var(--accent) 8%, transparent);
}

.chapter-reaction-icon {
  display: grid;
  width: 3.65rem;
  height: 3.65rem;
  place-items: center;
  border-radius: 50%;
  font-family: "Apple Color Emoji", "Segoe UI Emoji", sans-serif;
  font-size: 2.8rem !important;
  line-height: 1;
  filter: drop-shadow(0 .4rem .7rem rgb(0 0 0 / 28%));
}

.chapter-reaction-icon[data-reaction="upvote"] {
  background: linear-gradient(145deg, #6d9bff, #4168d7);
  color: #fff;
}

.chapter-reaction-icon[data-reaction="heart"] {
  background: linear-gradient(145deg, #ff6d8c, #d94268);
  color: #fff;
}

.chapter-reaction-icon > svg {
  width: 2rem;
  height: 2rem;
}

.chapter-reactions-box .chapter-reaction-options > button small {
  display: grid;
  min-width: 2rem;
  height: 2rem;
  place-items: center;
  padding-inline: .45rem;
  border-radius: 999px;
  background: rgb(255 255 255 / 3%);
  color: var(--text);
  font-size: .94rem;
  font-variant-numeric: tabular-nums;
  font-weight: 640;
}

.chapter-reactions-box .chapter-reaction-options > button strong {
  max-width: 100%;
  color: var(--muted);
  font-size: .78rem;
  font-weight: 570;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.chapter-reactions-box.is-status {
  min-height: 9rem;
  place-content: center;
  justify-items: center;
}

/* Compact sort popover, readable search, and a stable three-cell group header. */
.chapter-heading .chapter-sort-menu {
  position: relative;
  display: block;
  min-width: 0;
  height: 40px;
  overflow: visible;
}

.chapter-sort-menu > summary {
  display: flex;
  width: 100%;
  height: 100%;
  align-items: center;
  justify-content: space-between;
  gap: .45rem;
  padding: 0 .7rem;
  list-style: none;
  color: var(--text-soft);
  cursor: pointer;
  font-size: .76rem;
  font-weight: 800;
}

.chapter-sort-menu > summary::-webkit-details-marker {
  display: none;
}

.chapter-sort-menu > summary > span {
  display: grid;
  width: 1.55rem;
  height: 1.55rem;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--accent) 34%, var(--line));
  border-radius: .4rem;
  background: color-mix(in srgb, var(--accent) 8%, transparent);
  color: var(--accent);
}

.chapter-sort-menu > summary > svg {
  position: static;
  flex: 0 0 auto;
  transition: transform 150ms ease;
}

.chapter-sort-menu[open] > summary > svg {
  transform: rotate(180deg);
}

.chapter-sort-menu > div {
  position: absolute;
  z-index: 35;
  top: calc(100% + .4rem);
  left: 0;
  display: grid;
  width: max(8.75rem, 100%);
  gap: .2rem;
  padding: .4rem;
  border: 1px solid var(--line);
  border-radius: .7rem;
  background: var(--surface-strong);
  box-shadow: 0 1rem 2.5rem rgb(0 8 20 / 55%);
}

.chapter-sort-menu > div > button {
  min-height: 2.25rem;
  padding: 0 .65rem;
  border: 0;
  border-radius: .45rem;
  background: transparent;
  color: var(--text-soft);
  text-align: left;
  font-size: .75rem;
}

.chapter-sort-menu > div > button:is(:hover, :focus-visible),
.chapter-sort-menu > div > button[aria-pressed="true"] {
  background: color-mix(in srgb, var(--accent) 13%, transparent);
  color: var(--text);
}

.chapter-heading .chapter-tools .chapter-search input {
  font-size: max(12px, .78rem) !important;
}

.chapter-release-group > header {
  grid-template-columns: minmax(0, 1fr) 38px 38px !important;
}

.chapter-group-read-state {
  display: grid;
  width: 2.25rem;
  height: 2.25rem;
  place-items: center;
  justify-self: center;
  border: 1px solid var(--line);
  border-radius: .65rem;
  background: color-mix(in srgb, var(--surface-2) 84%, transparent);
  color: var(--muted) !important;
}

.chapter-group-read-state.is-read {
