/* Version 48.7.0 — release-first discovery, centered editorial motion, and
   final phone parity for the supplied Latest Updates reference. */

@property --v487-gold-angle {
  syntax: "<angle>";
  initial-value: 0deg;
  inherits: false;
}

.latest-style-toggle {
  display: grid;
  inline-size: 2.75rem;
  min-inline-size: 2.75rem;
  block-size: 2.75rem;
  min-block-size: 2.75rem;
  flex: 0 0 2.75rem;
  place-items: center;
  padding: 0;
  border: 1px solid var(--line);
  border-radius: var(--site-button-radius, var(--radius-small));
  background: var(--surface);
  color: var(--text-soft);
  cursor: pointer;
}

.latest-style-toggle:is(:hover, :focus-visible) {
  border-color: color-mix(in srgb, var(--accent) 55%, var(--line));
  color: var(--accent);
}

/* Style one: only the paid release itself receives the moving gold edge. */
.latest-chapters li {
  position: relative;
  isolation: isolate;
  padding: .42rem .5rem;
}

.latest-chapters li.is-paid {
  margin-block: .22rem;
  overflow: hidden;
  border: 0;
  border-radius: .58rem;
  background: color-mix(in srgb, var(--theme-status-yellow) 8%, var(--surface-2));
  box-shadow: none;
}

.latest-chapters li.is-paid > * {
  position: relative;
  z-index: 1;
}

.latest-chapters li.is-paid::after {
  position: absolute;
  z-index: 2;
  inset: 0;
  padding: 1.5px;
  border-radius: inherit;
  background: conic-gradient(
    from var(--v487-gold-angle),
    transparent 0 55%,
    #fff1a6 63%,
    #dca51d 74%,
    transparent 84%
  );
  content: "";
  pointer-events: none;
  -webkit-mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  animation: v487-gold-orbit 2.7s linear infinite;
}

@keyframes v487-gold-orbit {
  to { --v487-gold-angle: 360deg; }
}

/* Style two: a five-column desktop release table with a dedicated status. */
.latest-release-table :is(th, td):nth-child(1) { width: 32%; }
.latest-release-table :is(th, td):nth-child(2) { width: 25%; }
.latest-release-table :is(th, td):nth-child(3) { width: 18%; }
.latest-release-table :is(th, td):nth-child(4) { width: 12%; }
.latest-release-table :is(th, td):nth-child(5) { width: 13%; }

.latest-release-table time,
.latest-feed-status {
  display: inline-flex;
  align-items: center;
  gap: .35rem;
}

.latest-feed-status .chapter-status-badge {
  min-width: 4.25rem;
  justify-content: center;
  margin: 0;
}

.latest-release-table tbody tr.is-paid > :first-child {
  box-shadow: none;
}

.latest-pagination.is-home {
  width: min(100%, 25rem);
  min-height: 4.6rem;
  gap: 1rem;
  margin: 1rem auto 0;
  padding: .7rem 1rem;
  border: 1px solid var(--line);
  border-radius: 1rem;
  background: color-mix(in srgb, #05080b 82%, var(--surface));
}

.latest-pagination.is-home > button {
  display: grid;
  width: 2.8rem;
  min-width: 2.8rem;
  height: 2.8rem;
  min-height: 2.8rem;
  place-items: center;
  padding: 0;
  border: 1px solid var(--line);
  border-radius: .72rem;
  background: transparent;
}

.latest-pagination.is-home > .latest-page-dots {
  display: flex;
  min-width: 0;
  min-height: 1rem;
  align-items: center;
  justify-content: center;
  gap: .48rem;
