/* Version 48.8.0 — ranked light language, violet editorial treatment,
   release clarity, and configurable campaign palettes. */
@property --v488-orbit-angle {
  syntax: "<angle>";
  initial-value: 0deg;
  inherits: false;
}

@keyframes v488-orbit {
  to { --v488-orbit-angle: 360deg; }
}

@keyframes v488-soft-pulse {
  0%, 100% { opacity: .45; filter: brightness(.88); }
  50% { opacity: 1; filter: brightness(1.2); }
}

/* Latest Updates exposes two explicit, mutually exclusive choices. */
.latest-style-choices {
  display: inline-flex;
  align-items: center;
  gap: .18rem;
  padding: .18rem;
  border: 1px solid var(--line);
  border-radius: calc(var(--site-button-radius, var(--radius-small)) + .18rem);
  background: color-mix(in srgb, var(--surface) 88%, transparent);
}

.latest-style-choices .latest-style-toggle {
  inline-size: 2.35rem;
  min-inline-size: 2.35rem;
  block-size: 2.35rem;
  min-block-size: 2.35rem;
  flex-basis: 2.35rem;
  border-color: transparent;
  background: transparent;
}

.latest-style-choices .latest-style-toggle[aria-pressed="true"] {
  border-color: color-mix(in srgb, var(--accent) 72%, var(--line));
  background: color-mix(in srgb, var(--accent) 18%, var(--surface));
  color: var(--accent);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent) 28%, transparent);
}

.latest-updates-block[data-latest-style="classic"] .latest-card {
  grid-template-columns: 94px minmax(0, 1fr);
}

.latest-updates-block[data-latest-style="classic"] .latest-cover {
  min-width: 0;
}

.latest-updates-block[data-latest-style="classic"] .latest-chapter-identity > span:nth-child(2) {
  min-width: 0;
  overflow: visible;
  text-overflow: clip;
  white-space: normal;
  overflow-wrap: anywhere;
}

.latest-feed-series,
.latest-feed-chapter,
.latest-feed-series > span:last-child,
.latest-feed-chapter > span:first-child {
  min-width: 0;
  overflow: visible;
}

.latest-feed-series strong,
.latest-feed-chapter strong,
.latest-feed-chapter small {
  max-width: none;
  overflow: visible;
  text-overflow: clip;
  white-space: normal;
  overflow-wrap: anywhere;
  -webkit-box-orient: initial;
  -webkit-line-clamp: unset;
}

.latest-feed-status .chapter-status-badge {
  min-width: 4.6rem;
  min-height: 2rem;
  justify-content: center;
  padding: .36rem .72rem;
  white-space: nowrap;
}

/* The older weekly boxes remain intact; only their podium edge moves. */
.hot-week-card.is-top-1 { --hot-rank-a: #fff1a6; --hot-rank-b: #dca51d; }
.hot-week-card.is-top-2 { --hot-rank-a: #f4fbff; --hot-rank-b: #9eafc1; }
.hot-week-card.is-top-3 { --hot-rank-a: #ffd0a0; --hot-rank-b: #b66d32; }

.hot-week-card:is(.is-top-1, .is-top-2, .is-top-3) {
  position: relative;
  isolation: isolate;
  overflow: hidden;
}

.hot-week-card:is(.is-top-1, .is-top-2, .is-top-3)::before {
  content: none !important;
}

.hot-week-card:is(.is-top-1, .is-top-2, .is-top-3)::after {
  position: absolute !important;
  z-index: 5 !important;
  inset: 0 !important;
  width: auto !important;
  height: auto !important;
  padding: 2px !important;
  border: 0 !important;
  border-radius: inherit !important;
  background: conic-gradient(from var(--v488-orbit-angle), transparent 0 56%, var(--hot-rank-a) 64%, var(--hot-rank-b) 74%, transparent 84%) !important;
  box-shadow: none !important;
  content: "" !important;
  pointer-events: none;
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  animation: v488-orbit 3s linear infinite !important;
}

/* Violet editorial world: strongest at the frame, softer on inner surfaces. */
.editors-pick-section {
  position: relative;
  padding-block: clamp(1.2rem, 3vw, 2.4rem);
