  min-height: 20rem;
  border: 1px solid color-mix(in srgb, var(--ranking-gold) 18%, var(--line));
  border-radius: 1.7rem 1.7rem 1.35rem 1.35rem;
  background: linear-gradient(160deg, color-mix(in srgb, var(--surface-strong) 92%, #071226 8%), color-mix(in srgb, var(--surface) 85%, #160d24 15%));
  box-shadow: 0 1.2rem 2.8rem rgb(8 17 36 / 18%), inset 0 1px rgb(255 255 255 / 9%);
  list-style: none;
}

.user-leaderboard .user-ranking-podium-card.is-rank-1 {
  min-height: 22rem;
  border-color: color-mix(in srgb, var(--ranking-gold) 55%, var(--line));
  box-shadow: 0 1.35rem 3.2rem color-mix(in srgb, var(--ranking-gold) 18%, transparent), 0 1.2rem 2.8rem rgb(8 17 36 / 18%), inset 0 1px rgb(255 255 255 / 12%);
}

.user-leaderboard .user-ranking-podium-card > a {
  display: grid;
  min-height: 20rem !important;
  grid-template-columns: 1fr !important;
  align-content: start;
  justify-items: center;
  gap: 0.7rem;
  padding: 2.1rem 1rem 1rem !important;
  color: inherit;
  text-align: center;
}

.user-leaderboard .user-ranking-podium-card.is-rank-1 > a {
  min-height: 22rem !important;
  padding-top: 2.4rem !important;
}

.user-ranking-place {
  position: absolute;
  top: -1.25rem;
  left: 50%;
  display: grid;
  width: 3.35rem;
  height: 3.35rem;
  place-items: center;
  border: 1px solid color-mix(in srgb, var(--ranking-gold) 25%, var(--line));
  border-radius: 999px;
  color: var(--muted);
  background: color-mix(in srgb, var(--surface-strong) 85%, transparent);
  box-shadow: 0 0.7rem 1.5rem rgb(8 17 36 / 22%);
  transform: translateX(-50%);
}

.user-ranking-place svg {
  position: absolute;
  width: 1.1rem;
  height: 1.1rem;
  opacity: 0.24;
}

.user-ranking-place strong {
  position: relative;
  z-index: 1;
  font-family: var(--font-geist-mono), monospace;
  font-size: 1.1rem;
  font-weight: 850;
}

.user-leaderboard .is-rank-1 .user-ranking-place {
  width: 3.7rem;
  height: 3.7rem;
  border-color: color-mix(in srgb, var(--ranking-gold) 55%, var(--line));
  color: var(--ranking-gold);
  background: color-mix(in srgb, var(--ranking-gold) 17%, var(--surface-strong));
}

.user-leaderboard .is-rank-2 .user-ranking-place {
  color: #b9c8dc;
  background: color-mix(in srgb, #b9c8dc 13%, var(--surface-strong));
}

.user-leaderboard .is-rank-3 .user-ranking-place {
  color: #d69670;
  background: color-mix(in srgb, #d69670 13%, var(--surface-strong));
}

.user-ranking-avatar {
  display: grid;
  width: 3.2rem;
  height: 3.2rem;
  flex: 0 0 auto;
  place-items: center;
  overflow: hidden;
  border: 1px solid color-mix(in srgb, var(--accent) 34%, var(--line));
  border-radius: 1rem;
  color: var(--accent);
  background: color-mix(in srgb, var(--accent) 9%, var(--surface-strong));
  font-size: 0.9rem;
  font-weight: 850;
}

.user-ranking-avatar.is-featured {
  width: clamp(4.8rem, 9vw, 6rem);
  height: clamp(4.8rem, 9vw, 6rem);
  border-color: color-mix(in srgb, var(--ranking-gold) 56%, var(--line));
  border-radius: 1.35rem;
  color: var(--ranking-gold);
  background: color-mix(in srgb, var(--ranking-gold) 10%, var(--surface-strong));
  box-shadow: 0 0 0 0.2rem color-mix(in srgb, var(--ranking-gold) 10%, transparent), 0 0.7rem 1.4rem rgb(8 17 36 / 25%);
}

.user-ranking-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.user-ranking-podium-name {
  max-width: 100%;
  overflow: hidden;
  color: var(--text);
  font-size: clamp(0.9rem, 1.8vw, 1.18rem);
  font-weight: 850;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.user-ranking-tier {
  display: inline-flex;
  min-height: 1.65rem;
  align-items: center;
  padding: 0 0.65rem;
  border: 1px solid color-mix(in srgb, var(--ranking-gold) 45%, transparent);
  border-radius: 999px;
  color: var(--ranking-gold-soft);
  background: color-mix(in srgb, var(--ranking-gold) 15%, transparent);
  font-size: 0.62rem;
  font-weight: 850;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.user-ranking-podium-metrics {
  display: grid;
  width: 100%;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.3rem;
  margin-top: auto;
  padding-top: 0.7rem;
  border-top: 1px solid rgb(255 255 255 / 10%);
}

.user-leaderboard .user-ranking-metric {
  display: grid;
  min-width: 0;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  justify-content: center;
  gap: 0.28rem;
  color: var(--muted);
  font-variant-numeric: tabular-nums;
  text-align: left;
}

.user-leaderboard .user-ranking-metric svg {
  width: 1rem;
  height: 1rem;
  color: var(--ranking-blue);
}

.user-leaderboard .user-ranking-metric.is-accent svg,
.user-leaderboard .user-ranking-metric.is-accent strong {
  color: var(--ranking-gold);
}

.user-ranking-metric > span {
  display: grid;
  min-width: 0;
  gap: 0.05rem;
}

.user-ranking-metric strong,
.user-ranking-metric small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.user-ranking-metric strong {
  color: var(--text-soft);
  font-size: 0.77rem;
  font-weight: 850;
}

.user-ranking-metric small {
  color: var(--muted);
  font-size: 0.52rem;
  font-weight: 750;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.user-ranking-list {
  max-width: 920px;
  margin: 0 auto;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 1.65rem;
  background: var(--ranking-panel);
  box-shadow: 0 1.4rem 3.3rem rgb(8 17 36 / 11%);
}

.user-ranking-list-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 1rem;
  padding: 1.1rem 1.25rem 0.9rem;
  border-bottom: 1px solid var(--line);
}

.user-ranking-list-heading h2 {
  margin: 0.2rem 0 0;
  color: var(--text);
  font-size: 1.15rem;
}

.user-ranking-list-labels {
  display: grid;
  width: min(52%, 22rem);
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.7rem;
  color: var(--muted);
  font-size: 0.56rem;
  font-weight: 850;
  letter-spacing: 0.08em;
  text-align: right;
  text-transform: uppercase;
}

.user-leaderboard .user-ranking-list > ol {
  margin: 0;
  padding: 0;
  list-style: none;
}

.user-leaderboard .user-ranking-list-row {
  border-top: 1px solid var(--line);
  list-style: none;
}

.user-leaderboard .user-ranking-list-row:first-child {
  border-top: 0;
}

.user-leaderboard .user-ranking-list-row.is-viewer {
  background: color-mix(in srgb, var(--accent) 8%, transparent);
  box-shadow: inset 3px 0 var(--accent);
}

.user-leaderboard .user-ranking-list-row > a {
  display: grid;
  min-height: 5.8rem !important;
  grid-template-columns: 2.6rem 3.2rem minmax(0, 1fr) minmax(19rem, 0.72fr) !important;
  align-items: center;
  gap: 0.85rem;
  padding: 0.75rem 1.25rem !important;
  color: inherit;
}

.user-ranking-row-rank {
  color: var(--muted);
  font-family: var(--font-geist-mono), monospace;
  font-size: 0.9rem;
  font-weight: 850;
  text-align: center;
}

.user-ranking-row-person {
  display: grid;
  min-width: 0;
  gap: 0.18rem;
}

.user-ranking-row-person strong,
.user-ranking-row-person small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.user-ranking-row-person strong {
  color: var(--text);
  font-size: 0.95rem;
}

.user-ranking-row-person small {
  color: var(--muted);
  font-size: 0.62rem;
}

.user-ranking-row-metrics {
  display: grid;
  min-width: 0;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.75rem;
}

.user-ranking-row-metrics .user-ranking-metric {
  justify-content: end;
}

.user-ranking-ellipsis {
  display: grid;
  min-height: 3rem;
  place-items: center;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 1.1rem;
  letter-spacing: 0.35em;
  list-style: none;
}

@media (max-width: 760px) {
  .user-ranking-hero {
    padding-top: 0;
  }

  .user-ranking-controls {
    align-items: stretch;
    flex-direction: column;
    margin-bottom: 0.8rem;
  }

  .user-ranking-periods {
    width: 100%;
  }

  .user-ranking-periods button {
    flex: 1;
    padding-inline: 0.35rem;
  }

  .user-leaderboard .user-ranking-podium > ol {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.7rem;
    padding-inline: 0;
  }

  .user-leaderboard .user-ranking-podium-card,
  .user-leaderboard .user-ranking-podium-card.is-rank-1 {
    min-height: 19rem;
  }

  .user-leaderboard .user-ranking-podium-card > a,
  .user-leaderboard .user-ranking-podium-card.is-rank-1 > a {
    min-height: 19rem !important;
    padding: 2rem 0.65rem 0.8rem !important;
  }

  .user-leaderboard .user-ranking-podium-card.is-rank-1 {
    grid-column: 1 / -1;
    grid-row: 1;
  }

  .user-leaderboard .user-ranking-podium-card.is-rank-2 {
    grid-column: 1;
    grid-row: 2;
  }

  .user-leaderboard .user-ranking-podium-card.is-rank-3 {
    grid-column: 2;
    grid-row: 2;
  }

  .user-ranking-list-heading {
    align-items: start;
    flex-direction: column;
    padding: 1rem;
  }

  .user-ranking-list-labels {
    display: none;
  }

  .user-leaderboard .user-ranking-list-row > a {
    min-height: 0 !important;
    grid-template-columns: 2rem 2.8rem minmax(0, 1fr) !important;
    gap: 0.65rem;
    padding: 0.8rem 0.9rem !important;
  }

  .user-ranking-row-metrics {
    grid-column: 1 / -1;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 0.35rem;
    padding-top: 0.2rem;
  }

  .user-ranking-row-metrics .user-ranking-metric {
    justify-content: start;
    padding: 0.45rem;
    border: 1px solid var(--line);
    border-radius: 0.65rem;
    background: var(--surface-2);
  }

  .user-ranking-row-metrics .user-ranking-metric strong {
    font-size: 0.68rem;
  }

  .user-ranking-row-metrics .user-ranking-metric small {
    font-size: 0.48rem;
  }
}

@media (max-width: 430px) {
  .user-ranking-hero h1 {
    font-size: 2rem;
  }

  .user-ranking-hero p {
    font-size: 0.73rem;
  }

  .user-ranking-podium-name {
    font-size: 0.82rem;
  }

  .user-ranking-tier {
    font-size: 0.52rem;
  }

  .user-ranking-metric {
    gap: 0.18rem !important;
  }

  .user-ranking-metric svg {
    width: 0.85rem !important;
    height: 0.85rem !important;
  }

  .user-ranking-metric strong {
    font-size: 0.62rem;
  }
}

/* v49.5.0: Asura-inspired ranking + Browse presentation */
body:has(.user-leaderboard),
body:has(.catalog-toolbar) {
  background: var(--theme-main-background);
}

.user-leaderboard {
  --bg: var(--theme-main-background);
  --bg-soft: var(--theme-accent);
  --surface: var(--theme-accent);
  --surface-2: var(--theme-accent-l1);
  --surface-strong: var(--theme-accent-l2);
  --text: var(--theme-text-color);
  --text-soft: color-mix(in srgb, var(--theme-text-color) 82%, var(--theme-main-background));
  --muted: var(--theme-mid-tone);
  --line: var(--theme-accent-l3);
  --line-strong: var(--theme-accent-l4);
  --accent: var(--theme-primary);
  --shadow: color-mix(in srgb, var(--theme-main-background) 82%, transparent);
  --ranking-gold: #ffc34d;
  --ranking-gold-soft: #ffe3a1;
  --ranking-blue: #55baff;
  --ranking-ink: #111b2a;
  width: 100%;
  max-width: 1120px;
  margin-inline: auto;
  color: var(--text);
}

.user-leaderboard .user-ranking-hero {
  max-width: 840px;
  padding: 0.6rem 0 2rem;
}

.user-leaderboard .user-ranking-hero-mark {
  width: 4.7rem;
  height: 4.7rem;
  border-color: color-mix(in srgb, var(--ranking-gold) 62%, var(--line));
  border-radius: 1.25rem;
  color: var(--ranking-gold);
  background: color-mix(in srgb, var(--ranking-gold) 11%, var(--surface));
  box-shadow: 0 0 1.8rem color-mix(in srgb, var(--ranking-gold) 17%, transparent);
}

.user-leaderboard .user-ranking-hero h1 {
  color: var(--text);
  font-size: clamp(2.35rem, 5vw, 4.4rem);
  letter-spacing: -0.06em;
}

.user-leaderboard .user-ranking-hero p {
  color: var(--muted);
  font-size: clamp(0.82rem, 1.55vw, 1.05rem);
}

.user-leaderboard .user-ranking-controls {
  max-width: 920px;
  margin-bottom: 1.35rem;
  padding: 1rem 1.15rem;
  border-color: var(--line);
  border-radius: 1.2rem;
  background: var(--surface);
  box-shadow: inset 0 1px rgb(255 255 255 / 4%);
}

.user-leaderboard .user-ranking-kicker {
  color: var(--muted);
}

.user-leaderboard .user-ranking-controls-copy > strong,
.user-leaderboard .user-ranking-list-heading h2 {
  color: var(--text);
}

.user-leaderboard .user-ranking-periods {
  border-color: var(--line);
  border-radius: 0.85rem;
  background: var(--surface-2);
}

.user-leaderboard .user-ranking-periods button {
  color: var(--muted);
}

.user-leaderboard .user-ranking-periods button[aria-pressed="true"] {
  color: var(--ranking-ink);
  background: var(--ranking-gold);
}

.user-leaderboard .user-ranking-podium > ol {
  gap: 1rem;
  padding-inline: 0;
}

.user-leaderboard .user-ranking-podium-card {
  border-color: var(--line);
  border-radius: 1.35rem;
  background: linear-gradient(160deg, #112b49, #0d2139);
  box-shadow: 0 1.25rem 2.8rem rgb(0 5 15 / 25%), inset 0 1px rgb(255 255 255 / 7%);
}

.user-leaderboard .user-ranking-podium-card.is-rank-1 {
  border-color: color-mix(in srgb, var(--ranking-gold) 60%, var(--line));
  background: linear-gradient(160deg, #183454, #102541);
  box-shadow: 0 1.35rem 3rem color-mix(in srgb, var(--ranking-gold) 11%, transparent), 0 1.2rem 2.5rem rgb(0 5 15 / 26%), inset 0 1px rgb(255 255 255 / 9%);
}

.user-leaderboard .user-ranking-podium-card > a,
.user-leaderboard .user-ranking-podium-card.is-rank-1 > a {
  color: var(--text);
}

.user-leaderboard .user-ranking-place {
  border-color: color-mix(in srgb, var(--ranking-gold) 45%, var(--line));
  color: var(--ranking-gold);
  background: #1a3854;
  box-shadow: 0 0.7rem 1.5rem rgb(0 5 15 / 35%);
}

.user-leaderboard .is-rank-2 .user-ranking-place {
  color: #c9d6e5;
}

.user-leaderboard .is-rank-3 .user-ranking-place {
  color: #e19a6b;
}

.user-leaderboard .user-ranking-avatar {
  border-color: color-mix(in srgb, var(--ranking-blue) 55%, var(--line));
  color: var(--ranking-blue);
  background: #20446e;
}

.user-leaderboard .user-ranking-avatar.is-featured {
  border-color: color-mix(in srgb, var(--ranking-gold) 62%, var(--line));
  color: var(--ranking-gold);
  background: #29445c;
  box-shadow: 0 0 0 0.2rem color-mix(in srgb, var(--ranking-gold) 12%, transparent), 0 0.65rem 1.2rem rgb(0 5 15 / 32%);
}

.user-leaderboard .user-ranking-podium-name,
.user-leaderboard .user-ranking-row-person strong {
  color: var(--text);
}

.user-leaderboard .user-ranking-tier {
  border-color: color-mix(in srgb, var(--ranking-gold) 63%, transparent);
  color: var(--ranking-gold-soft);
  background: color-mix(in srgb, var(--ranking-gold) 14%, transparent);
}

.user-leaderboard .user-ranking-podium-metrics {
  border-color: var(--line);
}

.user-leaderboard .user-ranking-metric svg,
.user-leaderboard .user-ranking-metric strong {
  color: var(--ranking-blue);
}

.user-leaderboard .user-ranking-metric.is-accent svg,
.user-leaderboard .user-ranking-metric.is-accent strong {
  color: var(--ranking-gold);
}

.user-leaderboard .user-ranking-metric small,
.user-leaderboard .user-ranking-row-rank,
.user-leaderboard .user-ranking-row-person small {
  color: var(--muted);
}

.user-leaderboard .user-ranking-list {
  border-color: var(--line);
  border-radius: 1.35rem;
  background: #0b1e35;
  box-shadow: 0 1.5rem 3rem rgb(0 5 15 / 22%);
}

.user-leaderboard .user-ranking-list-heading,
.user-leaderboard .user-ranking-list-row {
  border-color: var(--line);
}

.user-leaderboard .user-ranking-list-labels {
  width: min(18%, 7rem);
  grid-template-columns: 1fr;
  justify-items: end;
}

.user-leaderboard .user-ranking-list-row.is-viewer {
  background: color-mix(in srgb, var(--ranking-blue) 9%, transparent);
  box-shadow: inset 3px 0 var(--ranking-blue);
}

.user-leaderboard .user-ranking-ellipsis {
  border-color: var(--line);
  color: var(--muted);
}

/* Browse header, filter surface, and results */
body:has(.catalog-toolbar) {
  --browse-bg: var(--bg);
  --browse-panel: var(--theme-accent);
  --browse-panel-2: var(--theme-accent-l1);
  --browse-card: var(--theme-accent);
  --browse-purple: var(--accent);
  --browse-text: var(--theme-text-color);
  --browse-muted: var(--theme-mid-tone);
  --browse-line: var(--theme-accent-l3);
}

body:has(.catalog-toolbar) .page-main {
  min-height: calc(100dvh - 72px);
  padding-top: clamp(2.2rem, 5vw, 5rem);
}

body:has(.catalog-toolbar) .browse-intro {
  max-width: none;
  margin-bottom: 0;
  padding: 1.35rem 1.35rem 1rem;
  border: 1px solid var(--browse-line);
  border-bottom: 0;
  border-radius: 1.4rem 1.4rem 0 0;
  background: linear-gradient(145deg, var(--theme-accent-l2), var(--theme-accent) 72%, var(--theme-main-background));
}

.browse-intro-heading {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 1rem;
}

body:has(.catalog-toolbar) .browse-intro .eyebrow {
  margin-bottom: 0.3rem;
  color: var(--accent);
}

body:has(.catalog-toolbar) .browse-intro h1 {
  display: flex;
  align-items: center;
  gap: 0.65rem;
  color: var(--browse-text);
  font-size: clamp(1.65rem, 3.2vw, 2.8rem);
  letter-spacing: -0.055em;
}

.browse-count {
  display: inline-grid;
  min-width: 2.5rem;
  min-height: 2rem;
  place-items: center;
  padding: 0 0.6rem;
  border-radius: 0.55rem;
  color: var(--theme-contrast-l1);
  background: color-mix(in srgb, var(--browse-purple) 35%, var(--browse-panel-2));
  font-size: 0.8em;
  letter-spacing: -0.02em;
}

body:has(.catalog-toolbar) .browse-intro-note {
  max-width: 20rem;
  margin: 0;
  color: var(--browse-muted);
  font-size: 0.78rem;
  text-align: right;
}

body:has(.catalog-toolbar) .catalog-toolbar {
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 0.75rem;
  padding: 0 1.35rem 1.35rem;
  border: 1px solid var(--browse-line);
  border-top: 0;
  border-radius: 0 0 1.4rem 1.4rem;
  background: linear-gradient(145deg, var(--theme-accent-l2), var(--theme-accent) 72%, var(--theme-main-background));
}

body:has(.catalog-toolbar) .catalog-search,
body:has(.catalog-toolbar) .filter-button,
body:has(.catalog-toolbar) .catalog-desktop-filters > label,
body:has(.catalog-toolbar) .catalog-desktop-filters > details {
  min-height: 3.05rem;
  border-color: var(--browse-line);
  border-radius: 0.72rem;
  color: var(--browse-text);
  background: var(--browse-panel-2);
}

body:has(.catalog-toolbar) .catalog-search {
  padding-inline: 0.9rem;
}

body:has(.catalog-toolbar) .catalog-search svg {
  color: var(--browse-muted);
}

body:has(.catalog-toolbar) .catalog-search input {
  color: var(--browse-text);
  font-size: 0.9rem;
}

body:has(.catalog-toolbar) .catalog-search input::placeholder {
  color: var(--browse-muted);
}

.catalog-desktop-filters {
  display: flex;
  min-width: 0;
  align-items: stretch;
  gap: 0.55rem;
}

body:has(.catalog-toolbar) .catalog-desktop-filters > details,
body:has(.catalog-toolbar) .catalog-desktop-filters > label {
  min-width: 9rem;
}

body:has(.catalog-toolbar) .filter-button {
  justify-content: center;
  padding-inline: 1.1rem;
  color: var(--theme-button-accent-alternate);
  background: var(--theme-button-accent);
  cursor: pointer;
  font-weight: 800;
}

body:has(.catalog-toolbar) .filter-button svg {
  color: var(--theme-button-accent-alternate);
}

body:has(.catalog-toolbar) .catalog-summary {
  padding: 1rem 0.1rem;
}

body:has(.catalog-toolbar) .catalog-results.catalog-grid {
  display: grid;
