/* Unified site dropdowns and Library listbox controls. */
select {
  appearance: none;
  color-scheme: dark;
  border: 1px solid var(--line);
  border-radius: var(--site-button-radius, var(--radius-small));
  background-color: var(--surface);
  background-image: linear-gradient(45deg, transparent 50%, var(--muted) 50%), linear-gradient(135deg, var(--muted) 50%, transparent 50%);
  background-position: calc(100% - 1rem) 50%, calc(100% - .68rem) 50%;
  background-repeat: no-repeat;
  background-size: .34rem .34rem, .34rem .34rem;
  color: var(--text);
}

select:focus-visible {
  border-color: var(--accent);
  outline: 2px solid color-mix(in srgb, var(--accent) 32%, transparent);
  outline-offset: 2px;
}

.library-dropdown-field {
  position: relative;
  display: grid;
  min-width: 12rem;
  gap: .4rem;
  color: var(--muted);
  font-size: .7rem;
  font-weight: 750;
}

.unified-single-select {
  position: relative;
  display: inline-block;
  width: 100%;
  min-width: 0;
  vertical-align: middle;
}

.unified-single-select-native {
  position: absolute !important;
  width: 1px !important;
  height: 1px !important;
  overflow: hidden !important;
  clip: rect(0 0 0 0) !important;
  clip-path: inset(50%) !important;
  margin: -1px !important;
  padding: 0 !important;
  border: 0 !important;
  opacity: 0 !important;
  pointer-events: none !important;
  white-space: nowrap !important;
}

.unified-single-select-trigger {
  display: flex;
  width: 100%;
  min-height: 2.75rem;
  box-sizing: border-box;
  align-items: center;
  justify-content: space-between;
  gap: .65rem;
  padding: .55rem .75rem;
  border: 1px solid color-mix(in srgb, var(--accent) 32%, var(--line));
  border-radius: var(--site-button-radius, var(--radius-small));
  background: color-mix(in srgb, var(--accent) 8%, var(--surface));
  color: var(--text);
  font: inherit;
  font-size: .82rem;
  font-weight: 700;
  text-align: start;
  cursor: pointer;
  transition: border-color .18s ease, background-color .18s ease, transform .16s ease;
}

.unified-single-select-trigger:hover,
.unified-single-select.is-open .unified-single-select-trigger,
.unified-single-select-trigger:focus-visible {
  border-color: var(--accent);
  background: color-mix(in srgb, var(--accent) 16%, var(--surface));
  outline: none;
}

.unified-single-select-trigger:active {
  transform: scale(.98);
}

.unified-single-select-trigger svg {
  flex: 0 0 auto;
  color: var(--accent);
  transition: transform .18s ease;
}

.unified-single-select.is-disabled .unified-single-select-trigger {
  border-color: var(--theme-disabled-border, var(--line));
  background: var(--theme-disabled-background, var(--surface));
  color: var(--theme-disabled-text, var(--muted));
  cursor: not-allowed;
  opacity: .68;
}

.unified-single-select.is-open .unified-single-select-trigger svg {
  transform: rotate(180deg);
}

.unified-single-select-menu {
  position: absolute;
  z-index: 1300;
  top: calc(100% + .4rem);
  right: 0;
  left: 0;
  display: grid;
  max-height: min(18rem, 42dvh);
  overflow-y: auto;
  padding: .35rem;
  border: 1px solid color-mix(in srgb, var(--accent) 38%, var(--line));
  border-radius: var(--site-card-radius, var(--radius));
  background: var(--surface-strong);
  box-shadow: 0 1rem 2.5rem rgb(0 0 0 / 32%);
}

.unified-single-select-menu button {
  display: flex;
  min-height: 2.45rem;
  align-items: center;
  justify-content: space-between;
  gap: .6rem;
  padding: .5rem .6rem;
  border: 1px solid transparent;
  border-radius: .55rem;
  background: transparent;
  color: var(--text);
  font: inherit;
  font-size: .8rem;
  text-align: start;
  cursor: pointer;
}

.unified-single-select-menu button:hover,
.unified-single-select-menu button:focus-visible,
.unified-single-select-menu button[aria-selected="true"] {
  border-color: color-mix(in srgb, var(--accent) 42%, var(--line));
  background: color-mix(in srgb, var(--accent) 14%, var(--surface));
  outline: none;
}

.unified-single-select-menu button[aria-selected="true"] {
  color: var(--accent);
}

.unified-single-select-menu button svg {
  flex: 0 0 auto;
}

.unified-single-select-menu button:disabled {
  color: var(--theme-disabled-text, var(--muted));
  cursor: not-allowed;
  opacity: .58;
}

.unified-single-select-group {
  display: block;
  padding: .65rem .6rem .3rem;
  color: var(--muted);
  font-size: .64rem;
  font-weight: 800;
  letter-spacing: .08em;
  text-transform: uppercase;
}

