  margin: 0;
  padding: 1rem 1.15rem;
  color: var(--theme-mid-tone);
  font-size: .75rem;
  line-height: 1.55;
}

.theme-library-list {
  display: grid;
  gap: .55rem;
  padding: 0 1.15rem 1.15rem;
}

.theme-library-list article {
  display: grid;
  grid-template-columns: 2.6rem minmax(0, 1fr) auto;
  align-items: center;
  gap: .75rem;
  padding: .72rem;
  border: 1px solid var(--theme-accent-l3);
  border-radius: .8rem;
  background: var(--theme-accent-l1);
}

.theme-library-list article.is-active {
  border-color: color-mix(in srgb, var(--theme-primary) 55%, var(--theme-accent-l3));
  box-shadow: inset 3px 0 var(--theme-primary);
}

.theme-library-swatch {
  width: 2.35rem;
  height: 2.35rem;
  border: 1px solid var(--theme-accent-l4);
  border-radius: 50%;
}

.theme-library-list article > div:nth-child(2) {
  display: grid;
  min-width: 0;
  gap: .2rem;
}

.theme-library-list article > div:nth-child(2) strong {
  overflow: hidden;
  color: var(--theme-text-color);
  font-size: .76rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.theme-library-list article > div:nth-child(2) small {
  color: var(--theme-mid-tone);
  font-size: .61rem;
  text-transform: capitalize;
}

.theme-library-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: .35rem;
}

.theme-library-actions button {
  display: inline-flex;
  min-height: 2rem;
  align-items: center;
  gap: .25rem;
  padding: .3rem .55rem;
  border: 1px solid var(--theme-accent-l4);
  border-radius: .55rem;
  color: var(--theme-text-color);
  background: var(--theme-accent-l2);
  font-size: .61rem;
  font-weight: 700;
}

.theme-library-actions button[aria-pressed="true"] {
  border-color: var(--theme-primary);
  color: var(--theme-primary);
}

.theme-library-actions button.is-danger {
  border-color: color-mix(in srgb, var(--theme-danger) 45%, var(--theme-accent-l4));
  color: var(--theme-danger);
}

.theme-library-empty {
  display: flex;
  align-items: center;
  gap: .65rem;
  margin: 0 1.15rem 1.15rem;
  padding: 1rem;
  border: 1px dashed var(--theme-accent-l4);
  border-radius: .8rem;
  color: var(--theme-mid-tone);
  background: var(--theme-accent-l1);
  font-size: .72rem;
}

.theme-library-empty svg {
  flex: 0 0 auto;
  color: var(--theme-primary);
}

.theme-builder-message {
  display: flex;
  align-items: center;
  gap: .55rem;
  margin: 0 1.15rem 1.15rem;
  padding: .72rem .8rem;
  border: 1px solid var(--theme-accent-l3);
  border-radius: .75rem;
  color: var(--theme-text-color);
  background: var(--theme-accent-l1);
  font-size: .72rem;
  line-height: 1.45;
}

.theme-builder-message.is-error {
  border-color: color-mix(in srgb, var(--theme-danger) 48%, var(--theme-accent-l3));
  color: var(--theme-danger);
  background: color-mix(in srgb, var(--theme-danger) 8%, var(--theme-accent));
}

.theme-builder-message.is-success {
  border-color: color-mix(in srgb, var(--theme-status-green) 42%, var(--theme-accent-l3));
  color: var(--theme-status-green);
}

.theme-builder-message button {
  margin-left: auto;
  color: inherit;
  cursor: pointer;
  text-decoration: underline;
}

.theme-import-card > p,
.theme-contrast-warning > p {
  margin: 0;
  padding: 1rem 1.15rem .75rem;
  color: var(--theme-mid-tone);
  font-size: .78rem;
  line-height: 1.6;
}

.theme-import-card textarea {
  display: block;
  width: calc(100% - 2.3rem);
  min-height: 8.5rem;
  margin: 0 1.15rem 1rem;
  padding: .8rem;
  resize: vertical;
  font-family: var(--font-geist-mono), monospace;
  font-size: .68rem;
  line-height: 1.55;
}

.theme-contrast-warning {
  border-color: color-mix(in srgb, var(--theme-status-yellow) 52%, var(--theme-accent-l3));
}

.theme-contrast-warning > header > svg {
  color: var(--theme-status-yellow);
}

.theme-contrast-warning ul {
  display: grid;
  gap: .45rem;
  margin: 0;
  padding: 0 1.15rem 1rem;
  list-style: none;
}

.theme-contrast-warning li {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  padding: .65rem .75rem;
  border-radius: .65rem;
  color: var(--theme-text-color);
  background: var(--theme-accent-l1);
  font-size: .7rem;
}

.theme-contrast-warning li span {
  color: var(--theme-status-yellow);
}

.theme-contrast-confirm {
  display: flex;
  align-items: center;
  gap: .6rem;
  margin: 0 1.15rem 1.15rem;
  color: var(--theme-text-color);
  font-size: .74rem;
  font-weight: 650;
}

.theme-contrast-confirm input {
  width: 1rem;
  height: 1rem;
  accent-color: var(--theme-primary);
}

.theme-token-groups-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 1rem 1.15rem;
}

.theme-token-groups-toolbar > div:first-child {
  display: grid;
  gap: .22rem;
}

.theme-token-groups-toolbar h2 {
  margin: 0;
  color: var(--theme-text-color);
  font-size: 1rem;
}

.theme-token-groups-toolbar p {
  max-width: 58ch;
  margin: 0;
  color: var(--theme-mid-tone);
  font-size: .69rem;
  line-height: 1.45;
}

.theme-token-group-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: .45rem;
}

.theme-token-group-actions .button {
  min-height: 2.35rem;
  padding-inline: .8rem;
  font-size: .67rem;
}

.theme-token-group:not(.is-open) > header {
  border-bottom: 0;
}

.theme-token-group-toggle {
  display: flex;
  min-width: 0;
  flex: 1 1 auto;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 0;
  border: 0;
  color: var(--theme-text-color);
  background: transparent;
  text-align: left;
  cursor: pointer;
}

.theme-token-group-toggle > span:first-child {
  display: grid;
  min-width: 0;
  gap: .22rem;
}

.theme-token-group-toggle h2 {
  margin: 0;
  color: var(--theme-text-color);
  font-size: 1rem;
}

.theme-token-group-toggle p {
  overflow: hidden;
  margin: 0;
  color: var(--theme-mid-tone);
  font-size: .66rem;
  line-height: 1.4;
  text-overflow: ellipsis;
}

.theme-token-group-toggle > strong {
  display: grid;
  width: 1.7rem;
  height: 1.7rem;
  flex: 0 0 auto;
  place-items: center;
  border: 1px solid var(--theme-accent-l3);
  border-radius: 50%;
  color: var(--theme-primary);
  background: color-mix(in srgb, var(--theme-primary) 10%, transparent);
  font-size: 1.05rem;
  line-height: 1;
}

.theme-token-group-toggle:is(:hover, :focus-visible) > strong {
  border-color: var(--theme-primary);
  box-shadow: 0 0 .75rem color-mix(in srgb, var(--theme-primary) 24%, transparent);
}

.theme-token-group-count {
  flex: 0 0 auto;
}

.theme-token-list {
  display: grid;
}

.theme-token-row {
  display: grid;
  min-height: 4.45rem;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 1rem;
  padding: .72rem 1.15rem;
  border-bottom: 1px solid var(--theme-accent-l2);
}

.theme-token-row:last-child {
  border-bottom: 0;
}

.theme-token-row > span:first-child {
  display: grid;
  min-width: 0;
  gap: .22rem;
}

.theme-token-row strong {
  color: var(--theme-text-color);
  font-size: .78rem;
}

.theme-token-row code {
  overflow: hidden;
  color: var(--theme-mid-tone);
  font-size: .59rem;
  text-overflow: ellipsis;
}

.theme-token-control {
  display: grid;
  grid-template-columns: 2.35rem 6.8rem;
  align-items: center;
  gap: .5rem;
}

.theme-color-picker {
  width: 2.35rem;
  height: 2.35rem;
  overflow: hidden;
  padding: .15rem;
  border: 1px solid var(--theme-accent-l4);
  border-radius: .62rem;
  background: var(--theme-accent-l1);
  cursor: pointer;
}

.theme-color-picker::-webkit-color-swatch-wrapper {
  padding: 0;
}

.theme-color-picker::-webkit-color-swatch {
  border: 0;
  border-radius: .4rem;
}

.theme-hex-input {
  width: 6.8rem;
  min-height: 2.35rem;
  padding: 0 .6rem;
  border: 1px solid var(--theme-accent-l3);
  border-radius: .62rem;
  outline: 0;
  color: var(--theme-text-color);
  background: var(--theme-accent-l1);
  font-family: var(--font-geist-mono), monospace;
  font-size: .69rem;
  text-transform: uppercase;
}

.theme-hex-input.is-invalid {
  border-color: var(--theme-danger);
}

.theme-token-control small {
  grid-column: 1 / -1;
  color: var(--theme-danger);
  font-size: .58rem;
}

.theme-builder-preview-column {
  position: sticky;
  top: 5.75rem;
}

.theme-preview-panel {
  display: grid;
  gap: 1rem;
  padding: 1rem;
  color: var(--theme-text-color);
  background: var(--theme-main-background);
}

.theme-preview-logo {
  display: flex;
  min-height: 3.2rem;
  align-items: center;
  gap: .7rem;
  padding: .65rem .75rem;
  border: 1px solid var(--theme-accent-l3);
  border-radius: .75rem;
  background: var(--theme-accent);
  color: var(--theme-mid-tone);
  font-size: .63rem;
  font-weight: 650;
}

.theme-preview-logo .theme-aware-logo {
  width: 2.5rem;
  height: 2.5rem;
  flex: 0 0 auto;
}

.theme-preview-tabs {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  padding: .24rem;
  border-radius: .72rem;
  background: var(--theme-accent-l1);
}

.theme-preview-tabs :is(button, span) {
  display: grid;
  min-height: 2.2rem;
  place-items: center;
  border-radius: .55rem;
  color: var(--theme-mid-tone);
  cursor: pointer;
  font-size: .67rem;
  font-weight: 700;
}

.theme-preview-tabs :is(button, span).is-active {
  color: var(--theme-text-color);
  background: var(--theme-accent-l2);
  box-shadow: inset 0 -2px var(--theme-primary);
}

.theme-preview-copy {
  display: grid;
  gap: .45rem;
  padding: 1rem;
  border: 1px solid var(--theme-accent-l3);
  border-radius: .85rem;
  background: var(--theme-accent);
}

.theme-preview-copy small {
  color: var(--theme-primary);
  font-size: .61rem;
  font-weight: 750;
  text-transform: uppercase;
}

.theme-preview-copy h3,
.theme-preview-copy p {
  margin: 0;
}

.theme-preview-copy h3 {
  font-size: 1rem;
  line-height: 1.25;
}

.theme-preview-copy p {
  color: var(--theme-mid-tone);
  font-size: .69rem;
  line-height: 1.55;
}

.theme-preview-copy a,
.theme-preview-copy > strong {
  width: fit-content;
  color: var(--theme-primary);
  font-size: .7rem;
  font-weight: 700;
}

.theme-preview-buttons {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: .5rem;
}

.theme-preview-button {
  display: grid;
  min-height: 2.4rem;
  place-items: center;
  border: 1px solid var(--theme-button-accent);
  border-radius: .65rem;
  color: var(--theme-button-accent-alternate);
  background: var(--theme-button-accent);
  font-size: .65rem;
  font-weight: 750;
}

.theme-preview-button.is-hover {
  border-color: var(--theme-primary-l1);
  background: var(--theme-primary-l1);
}

.theme-preview-button.is-active {
  border-color: var(--theme-primary-l2);
  background: var(--theme-primary-l2);
}

.theme-preview-button.is-alternate {
  border-color: var(--theme-accent-l4);
  color: var(--theme-text-color);
  background: var(--theme-accent-l2);
}

.theme-preview-button.is-danger {
  border-color: var(--theme-danger);
  color: var(--theme-contrast-l1);
  background: var(--theme-danger);
}

.theme-preview-button.is-danger-hover {
  border-color: var(--theme-danger-l1);
  color: var(--theme-contrast-l1);
  background: var(--theme-danger-l1);
}

.theme-preview-button.is-danger-active {
  border-color: var(--theme-danger-l2);
  color: var(--theme-contrast-l1);
  background: var(--theme-danger-l2);
}

.theme-preview-surface-states {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: .35rem;
}

.theme-preview-surface-states span {
  display: grid;
  min-height: 2.2rem;
  place-items: center;
  border: 1px solid var(--theme-accent-l3);
  border-radius: .55rem;
  color: var(--theme-text-color);
  font-size: .6rem;
  font-weight: 750;
}

.theme-preview-surface-states span:nth-child(1) { background: var(--theme-accent); }
.theme-preview-surface-states span:nth-child(2) { background: var(--theme-accent-hover); }
.theme-preview-surface-states span:nth-child(3) { background: var(--theme-accent-active); }

.theme-preview-levels {
  display: grid;
  grid-template-columns: 1fr;
  gap: .3rem;
}

.theme-preview-levels span {
  display: grid;
  min-height: 2.2rem;
  grid-template-columns: 2.25rem repeat(3, minmax(0, 1fr));
  align-items: stretch;
  border: 1px solid var(--theme-accent-l4);
  border-radius: .55rem;
  color: var(--theme-text-color);
  font-size: .6rem;
  font-weight: 750;
  overflow: hidden;
}

.theme-preview-levels strong,
.theme-preview-levels i {
  display: grid;
  min-width: 0;
  place-items: center;
  padding: .35rem .2rem;
  font-style: normal;
}

.theme-preview-levels strong { background: var(--theme-main-background); }
.theme-preview-levels span[data-level="1"] i:nth-of-type(1) { background: var(--theme-accent-l1); }
.theme-preview-levels span[data-level="1"] i:nth-of-type(2) { background: var(--theme-accent-l1-hover); }
.theme-preview-levels span[data-level="1"] i:nth-of-type(3) { background: var(--theme-accent-l1-active); }
.theme-preview-levels span[data-level="2"] i:nth-of-type(1) { background: var(--theme-accent-l2); }
.theme-preview-levels span[data-level="2"] i:nth-of-type(2) { background: var(--theme-accent-l2-hover); }
.theme-preview-levels span[data-level="2"] i:nth-of-type(3) { background: var(--theme-accent-l2-active); }
.theme-preview-levels span[data-level="3"] i:nth-of-type(1) { background: var(--theme-accent-l3); }
.theme-preview-levels span[data-level="3"] i:nth-of-type(2) { background: var(--theme-accent-l3-hover); }
.theme-preview-levels span[data-level="3"] i:nth-of-type(3) { background: var(--theme-accent-l3-active); }
.theme-preview-levels span[data-level="4"] i:nth-of-type(1) { background: var(--theme-accent-l4); }
.theme-preview-levels span[data-level="4"] i:nth-of-type(2) { background: var(--theme-accent-l4-hover); }
.theme-preview-levels span[data-level="4"] i:nth-of-type(3) { background: var(--theme-accent-l4-active); }
.theme-preview-levels span[data-level="5"] i:nth-of-type(1) { background: var(--theme-accent-l5); }
.theme-preview-levels span[data-level="5"] i:nth-of-type(2) { background: var(--theme-accent-l5-hover); }
.theme-preview-levels span[data-level="5"] i:nth-of-type(3) { background: var(--theme-accent-l5-active); }

.theme-preview-statuses {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: .4rem;
}

.theme-preview-statuses span {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: .45rem;
  color: var(--theme-mid-tone);
  font-size: .63rem;
}

.theme-preview-statuses i {
  width: .55rem;
  height: .55rem;
  flex: 0 0 auto;
  border-radius: 50%;
  background: var(--theme-status-grey);
}

.theme-preview-statuses [data-status="red"] i { background: var(--theme-status-red); }
.theme-preview-statuses [data-status="green"] i { background: var(--theme-status-green); }
.theme-preview-statuses [data-status="yellow"] i { background: var(--theme-status-yellow); }
.theme-preview-statuses [data-status="blue"] i { background: var(--theme-status-blue); }
.theme-preview-statuses [data-status="purple"] i { background: var(--theme-status-purple); }

.profile-theme-card > .button {
  align-self: center;
  justify-self: end;
}

@media (max-width: 1020px) {
  .theme-builder-layout {
    grid-template-columns: 1fr;
  }

  .theme-builder-preview-column {
    position: static;
    grid-row: 1;
  }

  .theme-preview-panel {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .theme-preview-tabs,
  .theme-preview-copy {
    grid-column: 1 / -1;
  }
}

@media (max-width: 680px) {
  .theme-builder-hero {
    grid-template-columns: 1fr;
    align-items: start;
  }

  .theme-builder-save-state {
    min-width: min(100%, 13rem);
  }

  .theme-builder-fields,
  .theme-preview-panel {
    grid-template-columns: 1fr;
  }

  .theme-builder-fields > label:last-child,
  .theme-preview-tabs,
  .theme-preview-copy {
    grid-column: auto;
  }

  .theme-token-row {
    grid-template-columns: 1fr;
  }

  .theme-token-control {
    grid-template-columns: 2.65rem minmax(0, 1fr);
  }

  .theme-hex-input {
    width: 100%;
  }

  .theme-builder-inline-control {
    grid-template-columns: 1fr;
  }

  .theme-builder-actions .button {
    width: 100%;
  }

  .theme-library-list article {
    grid-template-columns: 2.6rem minmax(0, 1fr);
  }

  .theme-library-actions {
    grid-column: 1 / -1;
    justify-content: stretch;
  }

  .theme-library-actions button {
    flex: 1 1 calc(50% - .35rem);
    justify-content: center;
  }

  .profile-theme-card > .button {
    justify-self: stretch;
  }
}

/* Major-page bridges: theme interface chrome while preserving cover art and reader paper modes. */
.series-status-badge.status-ongoing {
  border-color: color-mix(in srgb, var(--theme-status-green) 45%, var(--theme-accent-l3));
  color: var(--theme-status-green);
  background: color-mix(in srgb, var(--theme-status-green) 12%, var(--theme-accent));
}

.series-status-badge.status-completed {
  border-color: color-mix(in srgb, var(--theme-status-blue) 45%, var(--theme-accent-l3));
  color: var(--theme-status-blue);
  background: color-mix(in srgb, var(--theme-status-blue) 12%, var(--theme-accent));
}

.series-status-badge.status-paused {
  border-color: color-mix(in srgb, var(--theme-status-yellow) 45%, var(--theme-accent-l3));
  color: var(--theme-status-yellow);
  background: color-mix(in srgb, var(--theme-status-yellow) 12%, var(--theme-accent));
}

.series-status-badge.status-upcoming {
  border-color: color-mix(in srgb, var(--theme-status-purple) 45%, var(--theme-accent-l3));
  color: var(--theme-status-purple);
  background: color-mix(in srgb, var(--theme-status-purple) 12%, var(--theme-accent));
}

.series-status-badge.status-cancelled {
  border-color: color-mix(in srgb, var(--theme-status-red) 45%, var(--theme-accent-l3));
  color: var(--theme-status-red);
  background: color-mix(in srgb, var(--theme-status-red) 12%, var(--theme-accent));
}

body:has(.catalog-toolbar) .catalog-cover-bottom-badges .series-status-badge {
  color: var(--theme-contrast-l1) !important;
}

body:has(.catalog-toolbar) .catalog-cover-bottom-badges .series-status-badge.status-ongoing { background: color-mix(in srgb, var(--theme-status-green) 86%, var(--theme-main-background)) !important; }
body:has(.catalog-toolbar) .catalog-cover-bottom-badges .series-status-badge.status-completed { background: color-mix(in srgb, var(--theme-status-blue) 86%, var(--theme-main-background)) !important; }
body:has(.catalog-toolbar) .catalog-cover-bottom-badges .series-status-badge.status-paused { background: color-mix(in srgb, var(--theme-status-yellow) 86%, var(--theme-main-background)) !important; }
body:has(.catalog-toolbar) .catalog-cover-bottom-badges .series-status-badge.status-upcoming { background: color-mix(in srgb, var(--theme-status-purple) 86%, var(--theme-main-background)) !important; }
body:has(.catalog-toolbar) .catalog-cover-bottom-badges .series-status-badge.status-cancelled { background: color-mix(in srgb, var(--theme-status-red) 86%, var(--theme-main-background)) !important; }

.reader-chapter-scrim {
  background: color-mix(in srgb, var(--theme-main-background) 72%, transparent);
}

.reader-chapter-drawer {
  border-left-color: var(--theme-accent-l3);
  color: var(--theme-text-color);
  background: var(--theme-main-background);
  box-shadow: -1.75rem 0 5rem color-mix(in srgb, var(--theme-main-background) 64%, transparent);
}

.reader-chapter-drawer > :is(header, footer) {
  border-color: var(--theme-accent-l3);
}

.reader-chapter-drawer > header span,
.reader-chapter-drawer > header p > a,
.reader-chapter-list > :is(a, article) > span:first-child {
